        ["Kh\u{F4}ng l\u{1B0}u \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh \u{111}\u{E3} x\u{1EED} l\u{FD}"] = "Could not save the processed image",
        ["Kh\u{F4}ng x\u{1EED} l\u{FD} \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh n\u{E0}y"] = "Could not process this image",
