    function Icons.draw(parent, key, color, px, alpha)
        local spec = Icons.Shapes[key]
        if not spec then
            return nil
        end
        alpha = alpha or 0
        local holder = new("Frame", {
            Name = "Icon",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(px, px),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Parent = parent,
        })
        holder:SetAttribute("BoncutiIconKey", key)
        for _, item in ipairs(spec) do
            local kind, cx, cy, w, h, rot, round, thick = item[1], item[2], item[3], item[4], item[5], item[6], item[7], item[8]
            local shape = new("Frame", {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(cx, cy),
                Rotation = rot,
                BorderSizePixel = 0,
            })
            local least = math.min(w, h)
            if kind == "f" then
                shape.Size = UDim2.fromScale(w, h)
                shape.BackgroundColor3 = color
                shape.BackgroundTransparency = alpha
                if round > 0 then
                    new("UICorner", { CornerRadius = UDim.new(0, round * least * px), Parent = shape })
                end
            else
                shape.Size = UDim2.fromScale(w - 2 * thick, h - 2 * thick)
                shape.BackgroundTransparency = 1
                new("UIStroke", {
                    Color = color,
                    Transparency = alpha,
                    Thickness = math.max(thick * px, 1),
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                    Parent = shape,
                })
                if round >= 0.5 then
                    new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = shape })
                elseif round > 0 then
                    new("UICorner", { CornerRadius = UDim.new(0, math.max(round * least * px - thick * px, 0)), Parent = shape })
                end
            end
            shape.Parent = holder
        end
        return holder
    end

    function Icons.tint(holder, color, alpha)
