                return nil
            end

            local function decodeScan(scan)
                local comps = scan.comps
                local count = #comps
                local mcusPerLine, mcusPerColumn = frame.mcusPerLine, frame.mcusPerColumn
                local ss, se, ah, al = scan.ss, scan.se, scan.ah, scan.al
                local mode
                if not frame.progressive then
                    mode = "base"
                elseif ss == 0 then
                    mode = ah == 0 and "dcfirst" or "dcnext"
                else
                    mode = ah == 0 and "acfirst" or "acnext"
                end
                local eobrun = 0
                local acState, acNext = 0, 0

                local function block(comp, offset)
                    if mode == "base" then
                        local t = huff(comp.dc)
                        local diff = t == 0 and 0 or extend(t)
                        comp.pred = comp.pred + diff
                        wri16(comp.coef, offset, comp.pred)
                        local k = 1
                        local ac = comp.ac
                        while k < 64 do
                            local rs = huff(ac)
                            local s = band(rs, 15)
                            local r = rshift(rs, 4)
                            if s == 0 then
                                if r < 15 then
                                    break
                                end
                                k = k + 16
                            else
                                k = k + r
                                if k > 63 then
                                    break
                                end
                                wri16(comp.coef, offset + ZZ[k] * 2, extend(s))
                                k = k + 1
                            end
                        end
                    elseif mode == "dcfirst" then
                        local t = huff(comp.dc)
                        local diff = t == 0 and 0 or extend(t) * lshift(1, al)
                        comp.pred = comp.pred + diff
                        wri16(comp.coef, offset, comp.pred)
                    elseif mode == "dcnext" then
                        if receive(1) == 1 then
                            local value = rdi16(comp.coef, offset)
                            wri16(comp.coef, offset, bor(value, lshift(1, al)))
                        end
                    elseif mode == "acfirst" then
                        if eobrun > 0 then
                            eobrun = eobrun - 1
                            return
