                local expected
                if count == 1 then
                    expected = comps[1].bpl * comps[1].bpc
                else
                    expected = mcusPerLine * mcusPerColumn
                end
                local mcu = 0
                while mcu < expected do
                    local toRead = expected - mcu
                    if restartInterval > 0 and restartInterval < toRead then
