        local sfmt, slower, smatch = string.format, string.lower, string.match
        local sfind, sgsub, ssub, sbyte = string.find, string.gsub, string.sub, string.byte

        local ROOT = "boncuti/media"
        local VERSION = 13
        local KEEP = 4
        local LIMIT = 64 * 1024 * 1024
        local SIDE = 1022
        local FIT = 3840
        local DECODEPX = 36000000

        function Pic.reduce(img, k)
            if k <= 1 then
                return img
            end
            local ch, buf, step, bias = img.ch, img.buf, img.step, img.bias
            local nw, nh = max(img.w // k, 1), max(img.h // k, 1)
            local out = bcreate(nw * nh * ch)
            local area = k * k
            local half = area // 2
            for y = 0, nh - 1 do
                local dst = y * nw * ch
                for x = 0, nw - 1 do
                    if ch == 4 then
                        local sr, sg, sb, sa = 0, 0, 0, 0
                        for j = 0, k - 1 do
                            local at = (y * k + j) * step + bias + x * k * 4
                            for _ = 0, k - 1 do
                                local a = rdu8(buf, at + 3)
                                sr = sr + rdu8(buf, at) * a
                                sg = sg + rdu8(buf, at + 1) * a
                                sb = sb + rdu8(buf, at + 2) * a
                                sa = sa + a
                                at = at + 4
                            end
                        end
                        if sa > 0 then
                            local half2 = sa // 2
                            wru8(out, dst, (sr + half2) // sa)
                            wru8(out, dst + 1, (sg + half2) // sa)
                            wru8(out, dst + 2, (sb + half2) // sa)
                        end
                        wru8(out, dst + 3, (sa + half) // area)
                    else
                        for c = 0, ch - 1 do
                            local sum = 0
                            for j = 0, k - 1 do
                                local at = (y * k + j) * step + bias + x * k * ch + c
                                for _ = 0, k - 1 do
                                    sum = sum + rdu8(buf, at)
                                    at = at + ch
                                end
                            end
                            wru8(out, dst + c, (sum + half) // area)
                        end
                    end
                    dst = dst + ch
                end
                if y % 8 == 0 then
                    Pic.pace()
                end
            end
            return { w = nw, h = nh, ch = ch, buf = out, step = nw * ch, bias = 0 }
        end

        function Pic.crop(img, x0, y0, w, h)
            local ch = img.ch
            local rowLen = w * ch
            local raw = bcreate(h * (1 + rowLen))
            for r = 0, h - 1 do
                bcopy(raw, r * (1 + rowLen) + 1, img.buf, (y0 + r) * img.step + img.bias + x0 * ch, rowLen)
                if r % 64 == 63 then
                    Pic.pace()
                end
            end
            return Pic.encodePng(raw, w, h, ch)
        end

        function Pic.fit(img, side)
            local long = max(img.w, img.h)
            if long <= side then
                return img
            end
            local k = long // side
            if k >= 2 then
                img = Pic.reduce(img, k)
                long = max(img.w, img.h)
                if long <= side then
                    return img
                end
            end
            local w, h, ch = img.w, img.h, img.ch
            local scale = long / side
            local nw, nh = max(floor(w / scale + 0.5), 1), max(floor(h / scale + 0.5), 1)
            local buf, step, bias = img.buf, img.step, img.bias
            local out = bcreate(nw * nh * ch)
            local xa, xb, xf = {}, {}, {}
            for x = 0, nw - 1 do
                local fx = (x + 0.5) * w / nw - 0.5
                if fx < 0 then
                    fx = 0
                end
                local x0 = floor(fx)
                if x0 > w - 2 then
                    x0 = max(w - 2, 0)
                end
                local fr = fx - x0
                if fr > 1 then
                    fr = 1
                end
                xa[x] = x0 * ch
                xb[x] = min(x0 + 1, w - 1) * ch
                xf[x] = fr
            end
            for y = 0, nh - 1 do
                local fy = (y + 0.5) * h / nh - 0.5
                if fy < 0 then
                    fy = 0
                end
                local y0 = floor(fy)
                if y0 > h - 2 then
                    y0 = max(h - 2, 0)
                end
                local gy = fy - y0
                if gy > 1 then
                    gy = 1
                end
                local row0 = y0 * step + bias
                local row1 = min(y0 + 1, h - 1) * step + bias
                local dst = y * nw * ch
                for x = 0, nw - 1 do
                    local a, b, fr = xa[x], xb[x], xf[x]
                    local w00, w10, w01, w11 = (1 - fr) * (1 - gy), fr * (1 - gy), (1 - fr) * gy, fr * gy
                    if ch == 4 then
                        local a00, a10, a01, a11 = rdu8(buf, row0 + a + 3) * w00, rdu8(buf, row0 + b + 3) * w10, rdu8(buf, row1 + a + 3) * w01, rdu8(buf, row1 + b + 3) * w11
                        local sa = a00 + a10 + a01 + a11
                        if sa > 0 then
                            for c = 0, 2 do
                                local sum = rdu8(buf, row0 + a + c) * a00 + rdu8(buf, row0 + b + c) * a10 + rdu8(buf, row1 + a + c) * a01 + rdu8(buf, row1 + b + c) * a11
                                wru8(out, dst + c, floor(sum / sa + 0.5))
                            end
                        end
                        wru8(out, dst + 3, floor(sa + 0.5))
                    else
                        for c = 0, ch - 1 do
                            local sum = rdu8(buf, row0 + a + c) * w00 + rdu8(buf, row0 + b + c) * w10 + rdu8(buf, row1 + a + c) * w01 + rdu8(buf, row1 + b + c) * w11
                            wru8(out, dst + c, floor(sum + 0.5))
                        end
                    end
                    dst = dst + ch
                end
                if y % 8 == 0 then
                    Pic.pace()
                end
            end
            return { w = nw, h = nh, ch = ch, buf = out, step = nw * ch, bias = 0 }
        end

        local Http = game:GetService("HttpService")

        local function getter()
            if type(getcustomasset) == "function" then
                return getcustomasset
            end
            if type(getsynasset) == "function" then
                return getsynasset
            end
            return nil
        end

        local function hashText(value)
            local h1, h2 = 5381, 52711
            local len = #value
            local gap = max(1, len // 4096)
            for i = 1, len, gap do
                local b = string.byte(value, i)
                h1 = (h1 * 33 + b) % 4294967296
                h2 = (h2 * 131 + b + i) % 4294967296
            end
            return sfmt("%08x%08x%x", h1, h2, len)
        end

        local function exists(path)
            if type(isfile) ~= "function" then
                return false
            end
            local ok, found = pcall(isfile, path)
            return ok and found == true
        end

        local function ensure(path)
            if type(makefolder) ~= "function" then
                return
            end
            local acc
            for part in string.gmatch(path, "[^/]+") do
                acc = acc and (acc .. "/" .. part) or part
                pcall(function()
                    if type(isfolder) ~= "function" or not isfolder(acc) then
                        makefolder(acc)
                    end
                end)
            end
        end

        local function readJson(path)
            if type(readfile) ~= "function" or not exists(path) then
                return nil
            end
            local ok, text = pcall(readfile, path)
            if not ok or type(text) ~= "string" then
                return nil
            end
            local decoded, value = pcall(function()
                return Http:JSONDecode(text)
            end)
            if decoded and type(value) == "table" then
                return value
            end
            return nil
        end

        local function writeJson(path, value)
            pcall(function()
                writefile(path, Http:JSONEncode(value))
            end)
        end

        local function purge(dir)
            local manifest = readJson(dir .. "/m.json")
            local names = { "m.json" }
            if manifest and type(manifest.files) == "table" then
                for _, name in ipairs(manifest.files) do
                    names[#names + 1] = name
                end
            end
            if type(delfile) == "function" then
                for _, name in ipairs(names) do
                    pcall(delfile, dir .. "/" .. name)
                end
            end
            if type(delfolder) == "function" then
                pcall(delfolder, dir)
            end
        end

        local function touch(key)
            local index = readJson(ROOT .. "/index.json")
            local keys = index and type(index.keys) == "table" and index.keys or {}
            local out = {}
            for _, name in ipairs(keys) do
                if name ~= key then
                    out[#out + 1] = name
                end
            end
            out[#out + 1] = key
            while #out > KEEP do
                purge(ROOT .. "/" .. table.remove(out, 1))
            end
            writeJson(ROOT .. "/index.json", { keys = out })
        end

        local function describe(dir, manifest, asset)
            if type(manifest) ~= "table" or manifest.v ~= VERSION then
                return nil
            end
            for _, name in ipairs(manifest.files or {}) do
                if not exists(dir .. "/" .. name) then
                    return nil
                end
            end
            if manifest.kind == "single" then
                return { Kind = "single", W = manifest.w, H = manifest.h, Asset = asset(dir .. "/" .. manifest.file) }
            elseif manifest.kind == "tiles" then
                local tiles = {}
                for n, item in ipairs(manifest.tiles) do
                    tiles[n] = { X = item[1], Y = item[2], W = item[3], H = item[4], Asset = asset(dir .. "/" .. item[5]) }
                end
                return { Kind = "tiles", W = manifest.w, H = manifest.h, Cols = manifest.cols, Rows = manifest.rows, Tiles = tiles }
            elseif manifest.kind == "gif" then
                local frames, clock = {}, 0
                for n, item in ipairs(manifest.frames) do
                    frames[n] = { Asset = asset(dir .. "/" .. item[1]), Delay = item[2], Start = clock }
                    clock = clock + item[2]
                end
                return { Kind = "gif", W = manifest.w, H = manifest.h, Frames = frames, Total = max(clock, 0.05) }
            end
            return nil
        end

        local PROXY = "https://wsrv.nl/"
        local NOPAGE = "Link n\u{E0}y l\u{E0} trang web, kh\u{F4}ng t\u{EC}m th\u{1EA5}y \u{1EA3}nh trong trang"

        local function trimText(value)
            local out = sgsub(value, "^%s+", "")
            out = sgsub(out, "%s+$", "")
            return out
        end

        local function component(value)
            return (sgsub(value, "[^%w%-%._~]", function(c)
                return sfmt("%%%02X", sbyte(c))
            end))
        end

        local function dropClosers(url)
            while ssub(url, -1) == ")" do
                local _, opens = sgsub(url, "%(", "")
                local _, closes = sgsub(url, "%)", "")
                if closes > opens then
                    url = ssub(url, 1, -2)
                else
                    break
                end
            end
            return url
        end

        function Pic.cleanLink(source)
            local text = tostring(source or "")
            text = sgsub(text, "[\0-\8\11\12\14-\31\127]", "")
            text = sgsub(text, "\226\128[\139-\141]", "")
            text = sgsub(text, "\226\129\160", "")
            text = sgsub(text, "\239\187\191", "")
            text = trimText(text)
            if text == "" then
                return nil
            end
            local explicit = true
            local url = smatch(text, "^[Hh][Tt][Tt][Pp][Ss]?://[^%s]+$") or smatch(text, "[Hh][Tt][Tt][Pp][Ss]?://[^%s\"'<>]+")
            if not url then
                explicit = false
                local rest = smatch(text, "^//([^%s]+)$")
                if rest then
                    url = "https://" .. rest
                    explicit = true
                else
                    rest = smatch(text, "^(www%.[%w%-]+%.[^%s]+)$") or smatch(text, "^([%w%-]+%.[%w%-%.]+/[^%s]*)$")
                    if rest then
                        url = "https://" .. rest
                    end
                end
            end
            if not url then
                return nil
            end
            url = sgsub(url, "%[/.*$", "")
            url = sgsub(url, "#.*$", "")
            url = sgsub(url, "[\"'>%]%.,;:!%?]+$", "")
            url = dropClosers(url)
            url = sgsub(url, "&amp;", "&")
            url = sgsub(url, "&#38;", "&")
            url = sgsub(url, "&#x26;", "&")
            url = sgsub(url, "\\u0026", "&")
            url = sgsub(url, "\\/", "/")
            if #url < 10 then
                return nil
            end
            return url, explicit
        end

        function Pic.encodeLink(url)
            return (sgsub(url, "[^%w%-%._~:/%?#%[%]@!$&'()*+,;=%%]", function(c)
                return sfmt("%%%02X", sbyte(c))
            end))
        end

        local function splitUrl(rest)
            local path, query = smatch(rest, "^([^%?]*)%??(.*)$")
            return path, query
        end

        local function queryDrop(query, names)
            local out = {}
            for pair in string.gmatch(query, "[^&]+") do
                local key = smatch(pair, "^([^=]*)")
                if not names[key] then
                    out[#out + 1] = pair
                end
            end
            return out
        end

        local function withQuery(base, parts)
            if #parts == 0 then
                return base
            end
            return base .. "?" .. table.concat(parts, "&")
        end

        function Pic.variants(url)
            local list, seen = {}, {}
            local function add(value)
                if value and value ~= "" and not seen[value] then
                    seen[value] = true
                    list[#list + 1] = value
                end
            end
            local scheme = smatch(url, "^(https?)://")
            local host, rest = smatch(url, "^https?://([^/%?#]+)(.*)$")
            if not host then
                add(url)
                return list
            end
            host = slower(smatch(host, "^[^@]*@(.*)$") or host)
            host = smatch(host, "^([^:]+)") or host
            local path, query = splitUrl(rest)
            if path == "" then
                path = "/"
            end
            local function origin()
                return scheme .. "://" .. host
            end
            if host == "imgur.com" or host == "www.imgur.com" or host == "m.imgur.com" then
                local id = smatch(path, "^/(%w+)$")
                if id and id ~= "a" and id ~= "gallery" and id ~= "t" and id ~= "user" and id ~= "upload" then
                    add("https://i.imgur.com/" .. id .. ".png")
                    add("https://i.imgur.com/" .. id .. ".jpg")
                end
            elseif host == "i.imgur.com" then
                local id, ext = smatch(path, "^/(%w+)%.(%w+)$")
                if id then
                    local fixed = slower(ext)
                    if fixed == "gifv" or fixed == "mp4" or fixed == "webm" then
                        fixed = "gif"
                    elseif fixed == "webp" then
                        fixed = "png"
                    end
                    if (#id == 6 or #id == 8) and sfind("sbtmlhg", ssub(id, -1), 1, true) then
                        add("https://i.imgur.com/" .. ssub(id, 1, -2) .. "." .. fixed)
                    end
                    add("https://i.imgur.com/" .. id .. "." .. fixed)
                end
            elseif sfind(host, "giphy.com", 1, true) then
                local id = smatch(path, "^/media/(%w+)/[^/]+$")
                if not id and (smatch(path, "^/gifs/") or smatch(path, "^/stickers/") or smatch(path, "^/embed/")) then
                    local last = smatch(path, "/([^/]+)/?$") or ""
                    id = smatch(last, "(%w+)$")
                end
                if id then
                    add("https://i.giphy.com/media/" .. id .. "/giphy.gif")
                end
            elseif host == "www.dropbox.com" or host == "dropbox.com" then
                local parts = queryDrop(query, { dl = true, raw = true })
                parts[#parts + 1] = "dl=1"
                add(withQuery("https://www.dropbox.com" .. path, parts))
            elseif host == "drive.google.com" or host == "docs.google.com" then
                local id = smatch(path, "^/file/d/([%w_%-]+)") or smatch(query, "id=([%w_%-]+)")
                if id then
                    add("https://drive.google.com/uc?export=download&id=" .. id)
                    add("https://lh3.googleusercontent.com/d/" .. id .. "=s3840")
                end
            elseif host == "github.com" or host == "www.github.com" then
                local user, repo, tail = smatch(path, "^/([^/]+)/([^/]+)/blob/(.+)$")
                if not user then
                    user, repo, tail = smatch(path, "^/([^/]+)/([^/]+)/raw/(.+)$")
                end
                if user then
                    add("https://raw.githubusercontent.com/" .. user .. "/" .. repo .. "/" .. tail)
                end
            elseif host == "i.pinimg.com" then
                local fixed, n = sgsub(path, "^/%d+x%d*/", "/originals/")
                if n > 0 then
                    add(origin() .. fixed)
                end
            elseif host == "upload.wikimedia.org" then
                local head, hash, name = smatch(path, "^(/wikipedia/[%w_%-]+)/thumb/(%w/%w%w)/([^/]+)/[^/]+$")
                if head then
                    add(origin() .. head .. "/" .. hash .. "/" .. name)
                end
            elseif sfind(host, "wikimedia.org", 1, true) or sfind(host, "wikipedia.org", 1, true) then
                local name = smatch(path, "^/wiki/File:(.+)$")
                if name then
                    add(origin() .. "/wiki/Special:FilePath/" .. name)
                end
            elseif host == "images.unsplash.com" or host == "plus.unsplash.com" then
                local parts = queryDrop(query, { w = true, h = true, q = true, fit = true, crop = true, dpr = true, fm = true, auto = true, cs = true })
                parts[#parts + 1] = "w=3840"
                parts[#parts + 1] = "q=90"
                parts[#parts + 1] = "fm=jpg"
                parts[#parts + 1] = "fit=max"
                add(withQuery(origin() .. path, parts))
            elseif host == "images.pexels.com" then
                if query ~= "" then
                    add(origin() .. path)
                end
            elseif host == "preview.redd.it" then
                add("https://i.redd.it" .. path)
            elseif host == "pbs.twimg.com" then
                if sfind(query, "name=", 1, true) then
                    add(origin() .. path .. "?" .. (sgsub(query, "name=[^&]*", "name=4096x4096")))
                elseif smatch(path, "%.%a+:%a+$") then
                    add(origin() .. (sgsub(path, ":%a+$", ":orig")))
                elseif smatch(path, "/media/[%w_%-]+$") then
                    add(origin() .. path .. "?name=4096x4096")
                end
            elseif sfind(host, "googleusercontent.com", 1, true) or sfind(host, "ggpht.com", 1, true) then
                local fixed, n = sgsub(path, "=[swh]%d[%w%-]*$", "=s0")
                if n > 0 then
                    add(origin() .. fixed)
                end
            elseif host == "cdn.discordapp.com" or host == "media.discordapp.net" then
                local parts = queryDrop(query, { width = true, height = true, format = true, quality = true })
                if smatch(slower(path), "%.webp$") then
                    parts[#parts + 1] = "format=png"
                    add(withQuery("https://media.discordapp.net" .. path, parts))
                elseif sfind(query, "width=", 1, true) or sfind(query, "height=", 1, true) then
                    add(withQuery(origin() .. path, parts))
                end
            elseif sfind(host, ".media.tumblr.com", 1, true) then
                local fixed, n = sgsub(path, "/s%d+x%d+/", "/s2048x3072/")
                if n > 0 then
                    add(origin() .. fixed)
                end
            elseif host == "res.cloudinary.com" then
                local fixed, n = sgsub(path, "^(/[^/]+/image/upload/)[^/]+/(v%d+/)", "%1%2")
                if n > 0 then
                    add(origin() .. fixed .. (query ~= "" and ("?" .. query) or ""))
                end
            end
            add(url)
            return list
        end

        local ENTITY = { amp = "&", quot = '"', apos = "'", lt = "<", gt = ">" }

        local function unescape(value)
            value = sgsub(value, "&#[xX](%x+);", function(hex)
                local n = tonumber(hex, 16)
                return n and n < 128 and string.char(n) or ""
            end)
            value = sgsub(value, "&#(%d+);", function(dec)
                local n = tonumber(dec)
                return n and n < 128 and string.char(n) or ""
            end)
            value = sgsub(value, "&(%a+);", function(name)
                return ENTITY[name]
            end)
            return value
        end

        local function absolute(link, base)
            link = trimText(unescape(link))
            if link == "" or smatch(link, "^data:") then
                return nil
            end
            if smatch(link, "^https?://") then
                return link
            end
            if smatch(link, "^//") then
                return "https:" .. link
            end
            local origin = smatch(base, "^(https?://[^/%?#]+)")
            if not origin then
                return nil
            end
            if ssub(link, 1, 1) == "/" then
                return origin .. link
            end
            local dir = smatch(base, "^(https?://[^%?#]*/)") or (origin .. "/")
            return dir .. link
        end

        function Pic.pageImage(html, base)
            local head = ssub(html, 1, 400000)
            local found = {}
            for tag in string.gmatch(head, "<[Mm][Ee][Tt][Aa]%s[^>]*>") do
                local key = smatch(tag, "[Pp][Rr][Oo][Pp][Ee][Rr][Tt][Yy]%s*=%s*[\"']([^\"']+)[\"']") or smatch(tag, "[Nn][Aa][Mm][Ee]%s*=%s*[\"']([^\"']+)[\"']")
                local value = smatch(tag, "[Cc][Oo][Nn][Tt][Ee][Nn][Tt]%s*=%s*\"([^\"]*)\"") or smatch(tag, "[Cc][Oo][Nn][Tt][Ee][Nn][Tt]%s*=%s*'([^']*)'")
                if key and value and value ~= "" then
                    key = slower(key)
                    if not found[key] then
                        found[key] = value
                    end
                end
            end
            for _, name in ipairs({ "og:image:secure_url", "og:image:url", "og:image", "twitter:image:src", "twitter:image" }) do
                if found[name] then
                    local link = absolute(found[name], base)
                    if link then
                        return link
                    end
                end
            end
            local rel = smatch(head, "<[Ll][Ii][Nn][Kk][^>]-[Rr][Ee][Ll]%s*=%s*[\"']image_src[\"'][^>]-[Hh][Rr][Ee][Ff]%s*=%s*[\"']([^\"']+)[\"']")
            if rel then
                local link = absolute(rel, base)
                if link then
                    return link
                end
            end
            for tag in string.gmatch(head, "<[Ii][Mm][Gg]%s[^>]*>") do
                local src = smatch(tag, "[Ss][Rr][Cc]%s*=%s*[\"']([^\"']+)[\"']")
                if src then
                    local lowered = slower(src)
                    if (sfind(lowered, ".png", 1, true) or sfind(lowered, ".jpg", 1, true) or sfind(lowered, ".jpeg", 1, true) or sfind(lowered, ".gif", 1, true))
                        and not sfind(lowered, "favicon", 1, true) and not sfind(lowered, "sprite", 1, true) and not sfind(lowered, "logo", 1, true)
                        and not sfind(lowered, "avatar", 1, true) and not sfind(lowered, "emoji", 1, true) and not sfind(lowered, "pixel", 1, true) then
                        local link = absolute(src, base)
                        if link then
                            return link
                        end
                    end
                end
            end
            return nil
        end

        function Pic.looksLike(data)
            local lower = slower(ssub(data, 1, 1024))
            local trimmed = smatch(lower, "^%s*(.*)$") or lower
            if smatch(trimmed, "^<!doctype") or smatch(trimmed, "^<html") or sfind(lower, "<head", 1, true) or sfind(lower, "<body", 1, true) or sfind(lower, "<meta", 1, true) then
                return "html"
            end
            if smatch(trimmed, "^<svg") or (smatch(trimmed, "^<%?xml") and sfind(lower, "<svg", 1, true)) then
                return "svg"
            end
            local brand = ssub(data, 5, 12)
            if brand == "ftypavif" or brand == "ftypavis" then
                return "avif"
            end
            if smatch(brand, "^ftyphe[ioxv]") or brand == "ftypmif1" or brand == "ftypmsf1" then
                return "heic"
            end
            if ssub(data, 5, 8) == "ftyp" or ssub(data, 1, 4) == "\26\69\223\163" then
                return "video"
            end
            local head4 = ssub(data, 1, 4)
            if head4 == "II*\0" or head4 == "MM\0*" then
                return "tiff"
            end
            if head4 == "\0\0\1\0" then
                return "ico"
            end
            return nil
        end

        local function httpMessage(why)
            if why == "http404" or why == "http410" then
                return "Link \u{1EA3}nh kh\u{F4}ng t\u{1ED3}n t\u{1EA1}i (l\u{1ED7}i 404)"
            end
            if why == "http403" or why == "http401" then
                return "Trang ch\u{1EB7}n t\u{1EA3}i \u{1EA3}nh (l\u{1ED7}i 403)"
            end
            if why == "http429" then
                return "Trang \u{111}ang gi\u{1EDB}i h\u{1EA1}n l\u{1B0}\u{1EE3}t t\u{1EA3}i, th\u{1EED} l\u{1EA1}i sau"
            end
            return "Kh\u{F4}ng t\u{1EA3}i \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh t\u{1EEB} link"
        end

        local function fetchOne(env, url)
            if not env.Fetch then
                return nil
            end
            local ok, data, why = pcall(env.Fetch, url)
            if ok then
                return data, why
            end
            return nil
        end

        function Pic.convertRemote(url, other, data, env)
            local out = "jpg"
            if other == "png" or other == "bmp" or other == "tiff" or other == "ico" or other == "svg" then
                out = "png"
            elseif other == "gif" then
                out = "gif"
            elseif other == "webp" then
                local tag = ssub(data, 13, 16)
                if tag == "VP8L" then
                    out = "png"
                elseif tag == "VP8X" then
                    local flags = sbyte(data, 21) or 0
                    if bit32.band(flags, 2) ~= 0 then
                        out = "gif"
                    elseif bit32.band(flags, 16) ~= 0 then
                        out = "png"
                    end
                end
            end
            local limit = out == "gif" and 1280 or FIT
            local target = PROXY .. "?url=" .. component(url) .. "&output=" .. out .. "&q=95&w=" .. limit .. "&h=" .. limit .. "&fit=inside&we" .. (out == "gif" and "&n=-1" or "")
            local body = fetchOne(env, target)
            if type(body) ~= "string" then
                return nil
            end
            local kind, W, H = Pic.sniff(body)
            if kind == "png" or kind == "jpg" or kind == "gif" then
                return { Data = body, Kind = kind, W = W, H = H }
            end
            return nil
        end

        function Pic.acquire(link, env, status)
            local seen = {}
            local primary, secondary
            local function fail(url, message)
                if url == link then
                    primary = primary or message
                else
                    secondary = secondary or message
                end
            end
            local attempt
            function attempt(url, depth)
                if seen[url] then
                    return nil
                end
                seen[url] = true
                local data, why = fetchOne(env, url)
                if type(data) ~= "string" or #data == 0 then
                    fail(url, httpMessage(why))
                    return nil
                end
                local kind, W, H = Pic.sniff(data)
                if kind == "png" or kind == "jpg" or kind == "gif" then
                    return { Data = data, Kind = kind, W = W, H = H }
                end
                local other = kind or Pic.looksLike(data)
                if other == "html" then
                    if depth >= 2 then
                        fail(url, NOPAGE)
                        return nil
                    end
                    status("\u{110}ang \u{111}\u{1ECD}c trang\u{2026}")
                    local found = Pic.pageImage(data, url)
                    if not found then
                        fail(url, NOPAGE)
                        return nil
                    end
                    for _, candidate in ipairs(Pic.variants(Pic.encodeLink(found))) do
                        local got = attempt(candidate, depth + 1)
                        if got then
                            return got
                        end
                    end
                    fail(url, "Kh\u{F4}ng t\u{1EA3}i \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh trong trang n\u{E0}y")
                    return nil
                end
                if other == "webp" or other == "avif" or other == "heic" or other == "bmp" or other == "tiff" or other == "ico" or other == "svg" then
                    status("\u{110}ang chuy\u{1EC3}n \u{111}\u{1ECB}nh d\u{1EA1}ng\u{2026}")
                    local converted = Pic.convertRemote(url, other, data, env)
                    if converted then
                        return converted
                    end
                    fail(url, "Kh\u{F4}ng chuy\u{1EC3}n \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh WebP/AVIF sang PNG ho\u{1EB7}c JPG")
                    return nil
                end
                fail(url, "Link n\u{E0}y kh\u{F4}ng ph\u{1EA3}i \u{1EA3}nh \u{111}\u{1B0}\u{1EE3}c h\u{1ED7} tr\u{1EE3}")
                return nil
            end
            for _, candidate in ipairs(Pic.variants(link)) do
                local got = attempt(candidate, 0)
                if got then
                    return got
                end
            end
            return nil, primary or secondary or "Kh\u{F4}ng t\u{1EA3}i \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh t\u{1EEB} link"
        end

        local function extOf(kind)
            return kind == "jpg" and "jpg" or "png"
        end

        local function robloxId(lower)
            return smatch(lower, "roblox%.com/library/(%d+)")
                or smatch(lower, "roblox%.com/asset/?%?id=(%d+)")
                or smatch(lower, "roblox%.com/catalog/(%d+)")
                or smatch(lower, "roblox%.com/store/asset/(%d+)")
        end

        local function run(source, env, job, status)
            local asset = getter()
            source = trimText(source)
            local lower = slower(source)
            if smatch(source, "^%d+$") or smatch(lower, "^rbxassetid://%d+$") then
                return { Kind = "single", W = 0, H = 0, Asset = "rbxassetid://" .. smatch(source, "(%d+)$") }
            end
            if smatch(lower, "^rbxasset://") or smatch(lower, "^rbxthumb://") then
                return { Kind = "single", W = 0, H = 0, Asset = source }
            end
            local id = smatch(lower, "^https?://") and robloxId(lower)
            if id then
                return { Kind = "single", W = 0, H = 0, Asset = "rbxassetid://" .. id }
            end
            if not asset or type(writefile) ~= "function" or type(readfile) ~= "function" then
                return nil, "Executor kh\u{F4}ng h\u{1ED7} tr\u{1EE3} \u{1EA3}nh n\u{1EC1}n"
            end
            local last, top = 0, 0
            local label = "\u{110}ang x\u{1EED} l\u{FD} \u{1EA3}nh"
            local function report(p)
                if p > top then
                    top = p
                end
                local now = os.clock()
                if now - last > 0.2 then
                    last = now
                    status(sfmt("%s %d%%", label, floor(top * 100)))
                end
            end
            job.Progress = function(f)
                report(min(max(f, 0), 1) * 0.85)
            end

            local link, explicit = Pic.cleanLink(source)
            if link and not explicit and env.Find and env.Find(source) then
                link = nil
            end
            local key, data, path, kind, W, H
            local suffix = (env.Light and "l" or "") .. (env.Side and ("s" .. env.Side) or "")
            if link then
                link = Pic.encodeLink(link)
                key = "u" .. hashText(link) .. suffix
                local dir = ROOT .. "/" .. key
                local ready = describe(dir, readJson(dir .. "/m.json"), asset)
                if ready then
                    touch(key)
                    return ready
                end
                status("\u{110}ang t\u{1EA3}i \u{1EA3}nh\u{2026}")
                local got, failure = Pic.acquire(link, env, status)
                if not got then
                    return nil, failure
                end
                data, kind, W, H = got.Data, got.Kind, got.W, got.H
            else
                path = env.Find and env.Find(source)
                if not path then
                    if smatch(source, "^%a:[/\\]") or smatch(source, "^[/~]") or smatch(source, "^\\\\") then
                        return nil, "Executor ch\u{1EC9} \u{111}\u{1ECD}c file trong th\u{1B0} m\u{1EE5}c workspace"
                    end
                    return nil, "Kh\u{F4}ng t\u{EC}m th\u{1EA5}y file \u{1EA3}nh"
                end
                local ok, content = pcall(readfile, path)
                if not ok or type(content) ~= "string" then
                    return nil, "Kh\u{F4}ng t\u{EC}m th\u{1EA5}y file \u{1EA3}nh"
                end
                data = content
                key = "f" .. hashText(data) .. suffix
                local dir = ROOT .. "/" .. key
                local ready = describe(dir, readJson(dir .. "/m.json"), asset)
                if ready then
                    touch(key)
                    return ready
                end
                kind, W, H = Pic.sniff(data)
                if kind ~= "png" and kind ~= "jpg" and kind ~= "gif" then
                    local other = kind or Pic.looksLike(data)
                    if other == "webp" or other == "avif" or other == "heic" then
                        return nil, "File WebP/AVIF ch\u{1B0}a h\u{1ED7} tr\u{1EE3}, h\u{E3}y \u{111}\u{1ED5}i sang PNG ho\u{1EB7}c JPG"
                    end
                    return nil, "Ch\u{1EC9} h\u{1ED7} tr\u{1EE3} \u{1EA3}nh PNG, JPG ho\u{1EB7}c GIF"
                end
            end

            local oversize = #data > LIMIT or (W and H and W * H > DECODEPX)
            if oversize and link then
                status("\u{110}ang thu nh\u{1ECF} \u{1EA3}nh l\u{1EDB}n\u{2026}")
                local shrunk = Pic.convertRemote(link, kind, data, env)
                if shrunk then
                    data, kind, W, H = shrunk.Data, shrunk.Kind, shrunk.W, shrunk.H
                    oversize = #data > LIMIT or (W and H and W * H > DECODEPX)
                end
            end
            if #data > LIMIT then
                return nil, "\u{1EA2}nh qu\u{E1} l\u{1EDB}n (t\u{1ED1}i \u{111}a 64 MB)"
            end
            local dir = ROOT .. "/" .. key
            ensure(dir)

            local function direct(degraded)
                local file = path
                if not file then
                    file = dir .. "/o." .. extOf(kind)
                    writefile(file, data)
                    writeJson(dir .. "/m.json", { v = VERSION, kind = "single", w = W or 0, h = H or 0, file = "o." .. extOf(kind), files = { "o." .. extOf(kind) } })
                    touch(key)
                end
                return { Kind = "single", W = W or 0, H = H or 0, Asset = asset(file), Degraded = degraded or nil }
            end

            if oversize then
                return direct(true)
            end
            if kind ~= "gif" and ((W and H and W <= 1024 and H <= 1024) or env.Light) then
                return direct(false)
            end

            local manifest
            if kind == "gif" then
                if not W or not H then
                    return direct(true)
                end
                label = "\u{110}ang x\u{1EED} l\u{FD} GIF"
                job.Progress = function(f)
                    report(min(max(f, 0), 1) * 0.95)
                end
                local frames, files = {}, {}
                local outW, outH = 0, 0
                local result = Pic.gif(data, {
                    Side = env.Side or 1022,
                    MaxFrames = 90,
                    Budget = env.Pixels or 24000000,
                    Emit = function(canvas, delay, n, total, side)
                        local frame = { w = W, h = H, ch = 4, buf = canvas, step = W * 4, bias = 0 }
                        frame = Pic.fit(frame, side)
                        local name = sfmt("f%d.png", n)
                        writefile(dir .. "/" .. name, Pic.crop(frame, 0, 0, frame.w, frame.h))
                        frames[n] = { name, delay }
                        files[n] = name
                        outW, outH = frame.w, frame.h
                    end,
                })
                if not result or #files == 0 then
                    return direct(true)
                end
                if #files == 1 then
                    manifest = { v = VERSION, kind = "single", w = outW, h = outH, file = files[1], files = files }
                else
                    manifest = { v = VERSION, kind = "gif", w = outW, h = outH, frames = frames, files = files }
                end
            else
                local img, why
                if kind == "png" then
                    img, why = Pic.png(data)
                else
                    img, why = Pic.jpeg(data)
                end
                if not img then
                    if job.Dead then
                        error("cancelled", 0)
                    end
                    return direct(true)
                end
                data = nil
                img = Pic.fit(img, FIT)
                local w, h = img.w, img.h
                local cols, rows = ceil(w / SIDE), ceil(h / SIDE)
                local tw, th = ceil(w / cols), ceil(h / rows)
                local tiles, files = {}, {}
                local count = cols * rows
                local n = 0
                for r = 0, rows - 1 do
                    for c = 0, cols - 1 do
                        local x0, y0 = c * tw, r * th
                        local cw, ch = min(tw, w - x0), min(th, h - y0)
                        local ew = cw + ((x0 + cw < w) and 1 or 0)
                        local eh = ch + ((y0 + ch < h) and 1 or 0)
                        n = n + 1
                        local name = sfmt("t%d.png", n)
                        writefile(dir .. "/" .. name, Pic.crop(img, x0, y0, ew, eh))
                        tiles[n] = { x0, y0, ew, eh, name }
                        files[n] = name
                        report(0.85 + 0.15 * n / count)
                    end
                end
                if count == 1 then
                    manifest = { v = VERSION, kind = "single", w = w, h = h, file = files[1], files = files }
                else
                    manifest = { v = VERSION, kind = "tiles", w = w, h = h, cols = cols, rows = rows, tiles = tiles, files = files }
                end
            end
            writeJson(dir .. "/m.json", manifest)
            touch(key)
            local ready = describe(dir, manifest, asset)
            if not ready then
                return nil, "Kh\u{F4}ng l\u{1B0}u \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh \u{111}\u{E3} x\u{1EED} l\u{FD}"
            end
            return ready
        end

        function Pic.cancel(slot)
            local job = Pic.Slots[slot]
            if job then
                job.Dead = true
                Pic.Slots[slot] = nil
            end
        end

        function Pic.load(source, env)
            env = env or {}
            local slot = env.Slot or "ui"
            Pic.cancel(slot)
            local job = { Slot = slot }
            local thread = coroutine.running()
            Pic.Slots[slot] = job
            Pic.Jobs[thread] = job
            local ok, desc, failure = pcall(run, source, env, job, env.Status or function() end)
            Pic.Jobs[thread] = nil
            if Pic.Slots[slot] == job then
                Pic.Slots[slot] = nil
            end
            if not ok then
                if job.Dead then
                    return nil, "cancelled"
                end
                return nil, "Kh\u{F4}ng x\u{1EED} l\u{FD} \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh n\u{E0}y"
            end
            return desc, failure
        end
    end

    do
        local Surfaces = {}
        Fwd.surfaces = Surfaces

        function Fwd.surface(parent, name)
            local S = { Desc = nil, Frames = nil, Index = 1, T0 = os.clock(), Speed = 1, Gate = nil }
            local root = new("CanvasGroup", {
                Name = name or "Surface",
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                GroupTransparency = 1,
                Visible = false,
                Parent = parent,
            })
            local holder = new("Frame", {
                Name = "Content",
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Parent = root,
            })
            S.Root = root
            local stage

            local function layout()
                local desc = S.Desc
                if not stage or not desc or desc.Kind ~= "tiles" or (desc.H or 0) < 1 then
                    return
                end
                local size = root.AbsoluteSize
                local ca = (size.X > 0 and size.Y > 0) and size.X / size.Y or 1.6
                local ia = desc.W / desc.H
                if ia >= ca then
                    stage.Size = UDim2.fromScale(ia / ca, 1)
                else
                    stage.Size = UDim2.fromScale(1, ca / ia)
                end
            end
            root:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout)

            local function image(props)
                props.BackgroundTransparency = 1
                props.BorderSizePixel = 0
                return new("ImageLabel", props)
            end

            function S.Set(self, desc)
                if self.Desc == desc then
                    return
                end
                self.Desc = desc
                self.Frames = nil
                stage = nil
                for _, child in ipairs(holder:GetChildren()) do
                    child:Destroy()
                end
                if not desc then
                    return
                end
                if desc.Kind == "single" then
                    image({ Name = "Picture", Size = UDim2.fromScale(1, 1), Image = desc.Asset, ScaleType = Enum.ScaleType.Crop, Parent = holder })
                elseif desc.Kind == "tiles" then
                    stage = new("Frame", {
                        Name = "Stage",
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromScale(0.5, 0.5),
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        BorderSizePixel = 0,
                        Parent = holder,
                    })
                    for _, item in ipairs(desc.Tiles) do
                        image({
                            Name = "Tile",
                            Position = UDim2.fromScale(item.X / desc.W, item.Y / desc.H),
                            Size = UDim2.fromScale(item.W / desc.W, item.H / desc.H),
                            Image = item.Asset,
                            ScaleType = Enum.ScaleType.Stretch,
                            Parent = stage,
                        })
                    end
                    layout()
                elseif desc.Kind == "gif" then
                    local labels = {}
                    for n, item in ipairs(desc.Frames) do
                        labels[n] = image({
                            Name = "Frame",
                            Size = UDim2.fromScale(1, 1),
                            Image = item.Asset,
                            ScaleType = Enum.ScaleType.Crop,
                            Visible = n == 1,
                            Parent = holder,
                        })
                    end
                    self.Frames = labels
                    self.Index = 1
                    self.T0 = os.clock()
                    task.spawn(function()
                        pcall(function()
                            game:GetService("ContentProvider"):PreloadAsync(labels)
                        end)
                    end)
                end
            end

            Surfaces[#Surfaces + 1] = S
            return S
        end

        function Fwd.surfaceTick()
            local now = os.clock()
            for _, S in ipairs(Surfaces) do
                local desc = S.Desc
                if desc and desc.Kind == "gif" and S.Frames and S.Root.Visible and S.Root.GroupTransparency < 0.98 and (not S.Gate or S.Gate()) then
                    local frames = desc.Frames
                    local t = ((now - S.T0) * S.Speed) % desc.Total
                    local index = S.Index
                    local current = frames[index]
                    if not current or t < current.Start or t >= current.Start + current.Delay then
                        local lo, hi = 1, #frames
                        while lo < hi do
                            local mid = (lo + hi + 1) // 2
                            if frames[mid].Start <= t then
                                lo = mid
                            else
                                hi = mid - 1
                            end
                        end
                        index = lo
                    end
                    if index ~= S.Index then
                        local old = S.Frames[S.Index]
                        if old then
                            old.Visible = false
                        end
                        S.Frames[index].Visible = true
                        S.Index = index
                    end
                end
            end
        end
    end
end
local function text(props)
    local role = props.Role
    props.Role = nil
    props.BackgroundTransparency = 1
    props.BorderSizePixel = 0
    if type(props.Text) == "string" then
        props.Text = translate(props.Text)
    end
    if type(props.PlaceholderText) == "string" then
        props.PlaceholderText = translate(props.PlaceholderText)
    end
    props.FontFace = props.FontFace or Fonts.Medium
    props.TextSize = props.TextSize or 14
    local fixed = props.TextColor3
    local label = new("TextLabel", props)
    if not fixed then
        paint(label, "TextColor3", role or "Text")
    end
    if Fwd.icons.Map[label.Text] then
        Fwd.icons.watch(label)
    end
    return label
end

local function box(props)
    local class = props.Class or "Frame"
    local role = props.Role
    props.Class = nil
    props.Role = nil
    props.BorderSizePixel = 0
    local inst = new(class, props)
    if role then
        paint(inst, "BackgroundColor3", role)
    end
    return inst
end

local Glass = {}
local Search = { Index = {}, Open = false, Count = 0 }

function Search.Add(row, kind, title, desc, action)
    Search.Count = Search.Count + 1
    table.insert(Search.Index, {
        Row = row,
        Kind = kind,
        Title = title,
        Desc = desc,
        Action = action,
        Order = Search.Count,
    })
end

Glass.Rims = {}

function Glass.Edge(rim, frame)
    return new("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.12),
            NumberSequenceKeypoint.new(0.15, 0.42),
            NumberSequenceKeypoint.new(0.34, 0.8),
            NumberSequenceKeypoint.new(0.5, 0.92),
            NumberSequenceKeypoint.new(0.66, 0.8),
            NumberSequenceKeypoint.new(0.85, 0.42),
            NumberSequenceKeypoint.new(1, 0.12),
        }),
        Rotation = 45,
        Parent = rim,
    })
end

function Glass.Touch(button)
    if not button:IsA("GuiButton") then
        return nil
    end
    local radius = UDim.new(0, 10)
    for _, child in ipairs(button:GetChildren()) do
        if child:IsA("UICorner") then
            radius = child.CornerRadius
        end
    end
    local glow = new("Frame", {
        Name = "GlassTouch",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Static.White,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = button.ZIndex + 2,
        Parent = button,
    })
    new("UICorner", { CornerRadius = radius, Parent = glow })
    new("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.6),
            NumberSequenceKeypoint.new(0.5, 0.86),
            NumberSequenceKeypoint.new(1, 0.7),
        }),
        Rotation = 55,
        Parent = glow,
    })
    local function lit(on)
        tween(glow, on and 0.09 or 0.5, { BackgroundTransparency = on and 0 or 1 })
    end
    button.MouseButton1Down:Connect(function()
        lit(true)
    end)
    button.MouseButton1Up:Connect(function()
        lit(false)
    end)
    button.MouseLeave:Connect(function()
        lit(false)
    end)
    return glow
end

function Glass.Pane(button, tone)
    if button:GetAttribute("GlassPane") then
        return
    end
    button:SetAttribute("GlassPane", true)
    local radius = UDim.new(0, 10)
    for _, child in ipairs(button:GetChildren()) do
        if child:IsA("UICorner") then
            radius = child.CornerRadius
        end
    end
    if tone == "tint" then
        button.BackgroundTransparency = 0.34
    else
        button.BackgroundTransparency = math.max(button.BackgroundTransparency, 0.5)
        local frost = new("Frame", {
            Name = "GlassFrost",
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Static.White,
            BorderSizePixel = 0,
            ZIndex = button.ZIndex + 1,
            Parent = button,
        })
        new("UICorner", { CornerRadius = radius, Parent = frost })
        new("UIGradient", {
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.74),
                NumberSequenceKeypoint.new(1, 0.86),
            }),
            Rotation = 90,
            Parent = frost,
        })
    end
    local sheen = new("Frame", {
        Name = "GlassSheen",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        ZIndex = button.ZIndex + 1,
        Parent = button,
    })
    new("UICorner", { CornerRadius = radius, Parent = sheen })
    new("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.74),
            NumberSequenceKeypoint.new(0.45, 0.93),
            NumberSequenceKeypoint.new(1, 0.97),
        }),
        Rotation = 90,
        Parent = sheen,
    })
    local rim = new("Frame", {
        Name = "GlassRim",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = button.ZIndex + 1,
        Parent = button,
    })
    new("UICorner", { CornerRadius = radius, Parent = rim })
    local line = new("UIStroke", {
        Color = Static.White,
        Thickness = 1,
        Transparency = 0,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = rim,
    })
    Glass.Edge(line, rim)
    Glass.Touch(button)
end

function Glass.Skin(frame, transparency, tint)
    frame.BackgroundTransparency = transparency
    new("UIGradient", {
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Static.White),
            ColorSequenceKeypoint.new(0.42, rgb(238, 241, 250)),
            ColorSequenceKeypoint.new(1, tint or rgb(204, 210, 228)),
        }),
        Rotation = 90,
        Parent = frame,
    })
    local rim = new("UIStroke", {
        Color = Static.White,
        Thickness = 1.5,
        Transparency = 0,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = frame,
    })
    Glass.Edge(rim, frame)
    if frame.BackgroundTransparency < 0.8 then
        frame.BackgroundTransparency = frame.BackgroundTransparency + 0.06
    end
    return rim
end

function Glass.Band(parent, height)
    local band = new("Frame", {
        Name = "GlassBand",
        Size = UDim2.new(1, 0, 0, height),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        ZIndex = 0,
        Parent = parent,
    })
    new("UIGradient", {
        Transparency = NumberSequence.new(0.84, 1),
        Rotation = 90,
        Parent = band,
    })
    return band
end

function Glass.Rim(parent, radius)
    local rim = new("Frame", {
        Name = "GlassRim",
        Position = UDim2.fromOffset(2, 2),
        Size = UDim2.new(1, -4, 1, -4),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 30,
        Parent = parent,
    })
    new("UICorner", { CornerRadius = UDim.new(0, math.max(radius - 2, 2)), Parent = rim })
    local line = new("UIStroke", {
        Color = Static.White,
        Thickness = 1.6,
        Transparency = 0,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = rim,
    })
    local gradient = Glass.Edge(line, rim)
    Glass.InnerGradients = {}
    local rings = {
        { Inset = 3, Thick = 1.2, Edge = 0.9, Mid = 0.985 },
        { Inset = 6, Thick = 2, Edge = 0.92, Mid = 0.99 },
        { Inset = 11, Thick = 3.4, Edge = 0.96, Mid = 0.995 },
    }
    for index, ring in ipairs(rings) do
        local inner = new("Frame", {
            Name = index == 2 and "GlassInner" or "GlassBevel",
            Position = UDim2.fromOffset(ring.Inset, ring.Inset),
            Size = UDim2.new(1, -ring.Inset * 2, 1, -ring.Inset * 2),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 29,
            Parent = parent,
        })
        new("UICorner", { CornerRadius = UDim.new(0, math.max(radius - ring.Inset, 2)), Parent = inner })
        local innerLine = new("UIStroke", {
            Color = Static.White,
            Thickness = ring.Thick,
            Transparency = 0,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = inner,
        })
        new("UIGradient", {
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, ring.Edge),
                NumberSequenceKeypoint.new(0.3, ring.Mid),
                NumberSequenceKeypoint.new(0.7, ring.Mid),
                NumberSequenceKeypoint.new(1, ring.Edge),
            }),
            Rotation = 45,
            Parent = innerLine,
        })
    end
    return rim, gradient
end

function Glass.Mark(parent, size, fresh)
    local tile = new("Frame", {
        Name = "Mark",
        Size = UDim2.fromOffset(size, size),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        Parent = parent,
    })
    local radius = math.floor(size * 0.3)
    new("UICorner", { CornerRadius = UDim.new(0, radius), Parent = tile })
    new("UIGradient", {
        Color = fresh and ColorSequence.new({
            ColorSequenceKeypoint.new(0, rgb(98, 162, 255)),
            ColorSequenceKeypoint.new(0.5, rgb(104, 92, 240)),
            ColorSequenceKeypoint.new(1, rgb(58, 36, 140)),
        }) or ColorSequence.new(rgb(118, 192, 255), rgb(158, 100, 255)),
        Rotation = fresh and 55 or 38,
        Parent = tile,
    })
    new("UIStroke", {
        Color = Static.White,
        Thickness = 1,
        Transparency = 0.72,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = tile,
    })
    local gloss = new("Frame", {
        Position = UDim2.fromOffset(1, 1),
        Size = UDim2.new(1, -2, 0.52, 0),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        Parent = tile,
    })
    new("UICorner", { CornerRadius = UDim.new(0, math.max(radius - 1, 2)), Parent = gloss })
    new("UIGradient", {
        Transparency = NumberSequence.new(0.55, 1),
        Rotation = 90,
        Parent = gloss,
    })
    if fresh then
        local stemWidth = size * 0.12
        local stem = new("Frame", {
            Position = UDim2.fromOffset(size * 0.3, size * 0.17),
            Size = UDim2.fromOffset(stemWidth, size * 0.64),
            BackgroundColor3 = Static.White,
            BorderSizePixel = 0,
            Parent = tile,
        })
        new("UICorner", { CornerRadius = UDim.new(0, stemWidth / 2), Parent = stem })
        local bowl = new("Frame", {
            Position = UDim2.fromOffset(size * 0.42, size * 0.49),
            Size = UDim2.fromOffset(size * 0.2, size * 0.2),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Parent = tile,
        })
        new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = bowl })
        new("UIStroke", {
            Color = Static.White,
            Thickness = stemWidth,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = bowl,
        })
        local spark = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromOffset(size * 0.74, size * 0.25),
            Size = UDim2.fromOffset(size * 0.11, size * 0.11),
            BackgroundColor3 = rgb(120, 230, 255),
            BorderSizePixel = 0,
            Parent = tile,
        })
        new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = spark })
        return tile
    end
    local thickness = math.max(2, size * 0.075)
    local ring = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(size * 0.5, size * 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Parent = tile,
    })
    new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ring })
    new("UIStroke", {
        Color = Static.White,
        Thickness = thickness,
        Transparency = 0.35,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Parent = ring,
    })
    local core = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(size * 0.14, size * 0.14),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        Parent = tile,
    })
    new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = core })
    local orbit = size * 0.25 + thickness / 2
    local satellite = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, orbit * 0.7071, 0.5, -orbit * 0.7071),
        Size = UDim2.fromOffset(size * 0.17, size * 0.17),
        BackgroundColor3 = Static.White,
        BorderSizePixel = 0,
        Parent = tile,
    })
    new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = satellite })
    return tile
end

