        Activities.Clock = {
            Title = "\u{110}\u{1ED3}ng h\u{1ED3}",
            Color = Static.Gray,
            Value = value,
            Short = value,
        }
    else
        Activities.Clock = nil
    end
    refreshActivity()
end

