local Cross = {
    Enabled = false,
    Pref = false,
    Mood = "neutral",
    MoodUntil = 0,
    SpeakUntil = 0,
    Thinking = false,
    Acting = false,
    Lang = "vi",
    Chat = {},
    ChatVersion = 0,
    Shell = { Lines = {}, Version = 0, Width = 38, Live = nil },
    Bubble = { Full = "", Shown = "", Count = 0, Rate = 54 },
    Echo = "",
    Faces = {},
    Shells = {},
    MarkText = "",
    Pose = {},
    Target = {},
    Perm = { Ui = true, Body = true, Free = false, Key = true },
    Busy = 0,
    Idle = "neutral",
    Inputs = {},
    ShellHold = 0,
}

do
    local HEAD = rgb(17, 19, 27)
    local PINK = rgb(255, 112, 146)
    local DROP = rgb(120, 200, 255)
    local SHADE = rgb(6, 7, 10)
    local HEART = rgb(255, 96, 128)

    local NEUTRAL = {
        eyeW = 1, eyeH = 1, lidB = 0, lidT = 0, tilt = 0, browY = 0, browTilt = 0, browA = 0,
        smile = 0.35, mouthW = 0.34, open = 0, cheek = 0, shade = 0, heart = 0, sweat = 0,
        gx = 0, gy = 0, winkR = 0, markA = 0,
    }

    local MOODS = {
        neutral = {},
        happy = { lidB = 0.58, smile = 0.95, cheek = 0.55, mouthW = 0.38 },
        joy = { lidB = 0.62, smile = 1, cheek = 0.85, mouthW = 0.46, open = 0.38 },
        think = { gx = 0.9, gy = -0.9, smile = 0, browA = 0.85, browY = 0.6, browTilt = -8, mouthW = 0.2, eyeH = 0.92, mark = "\u{2026}" },
        sad = { lidT = 0.34, tilt = -17, smile = -0.85, browA = 0.9, browTilt = -15, browY = 0.1, mouthW = 0.26, eyeH = 0.95 },
        angry = { lidT = 0.36, tilt = 17, smile = -0.55, browA = 0.9, browTilt = 16, browY = -0.4, mouthW = 0.3 },
        surprised = { eyeW = 1.2, eyeH = 1.32, open = 0.85, mouthW = 0.2, browA = 0.9, browY = 1, smile = 0, mark = "!" },
        love = { lidB = 0.5, smile = 0.95, cheek = 0.95, heart = 1, mouthW = 0.38 },
        sleepy = { lidT = 0.62, smile = 0.1, mouthW = 0.2, browA = 0, mark = "z" },
        wink = { lidB = 0.15, winkR = 0.8, smile = 0.95, cheek = 0.4, mouthW = 0.4 },
        cool = { shade = 1, smile = 0.75, mouthW = 0.38 },
        sweat = { lidT = 0.2, smile = -0.4, sweat = 1, mouthW = 0.3, browA = 0.85, browTilt = 11 },
        confused = { gx = -0.7, smile = -0.2, browA = 0.9, browTilt = 13, mouthW = 0.22, mark = "?" },
        listen = { eyeW = 1.1, eyeH = 1.14, smile = 0.25, browA = 0.55, browY = 0.7 },
    }

    for key, value in pairs(NEUTRAL) do
        Cross.Pose[key] = value
        Cross.Target[key] = value
    end
    Cross.Pose.open = 0

    local blink = { Next = 2, Start = -10, Value = 0 }
    local wander = { Next = 1, X = 0, Y = 0, CX = 0, CY = 0 }
    local openSmooth = 0
    local clock = 0
    local lastAccent
    local glow = Static.White

    function Cross.setMood(name, hold)
        local def = MOODS[name] or MOODS.neutral
        Cross.Mood = MOODS[name] and name or "neutral"
        for key, value in pairs(NEUTRAL) do
            local target = def[key]
            Cross.Target[key] = target ~= nil and target or value
        end
        Cross.MarkText = def.mark or Cross.MarkText
        Cross.Target.markA = def.mark and 1 or 0
        Cross.MoodUntil = hold and hold > 0 and os.clock() + hold or 0
    end

    function Cross.speak(seconds)
        Cross.SpeakUntil = os.clock() + math.clamp(seconds, 0.6, 7)
    end

    local function prefix(source, count)
        local length = utf8.len(source)
        if not length then
            return string.sub(source, 1, count)
        end
        if count >= length then
            return source
        end
        if count <= 0 then
            return ""
        end
        return string.sub(source, 1, utf8.offset(source, count + 1) - 1)
    end
    Cross.prefix = prefix

    function Cross.length(source)
        return utf8.len(source) or #source
    end

    Cross.Grapheme = pcall(function()
        local probe = Instance.new("TextLabel")
        probe.MaxVisibleGraphemes = 1
        probe:Destroy()
    end)

    function Cross.clean(source, limit)
        source = tostring(source or "")
        source = string.gsub(source, "\226\128[\139-\143]", "")
        source = string.gsub(source, "\239\187\191", "")
        source = string.gsub(source, "\194\160", " ")
        source = string.gsub(source, "[%c]", " ")
        source = string.gsub(source, "%s+", " ")
        source = string.gsub(source, "^%s+", "")
        source = string.gsub(source, "%s+$", "")
        if limit and Cross.length(source) > limit then
            source = prefix(source, limit)
        end
        return source
    end

    Cross.Limit = 240

    local SAFE = {
        ["\226\134\146"] = ">",
        ["\226\134\144"] = "<",
        ["\226\134\145"] = "^",
        ["\226\134\147"] = "v",
        ["\226\150\182"] = ">",
        ["\226\156\147"] = "v",
        ["\226\156\148"] = "v",
        ["\226\151\143"] = "*",
    }

    function Cross.safe(source)
        source = tostring(source or "")
        return (string.gsub(source, "\226[\134\150\151\156][\128-\191]", function(found)
            return SAFE[found]
        end))
    end

    Cross.Guards = setmetatable({}, { __mode = "k" })

    function Cross.watchInput(field)
        local busy = false
        local state = { Text = field.Text, Window = 0, Set = nil }
        Cross.Guards[field] = state
        state.Set = function(value)
            state.Text = value
            busy = true
            pcall(function()
                field.Text = value
            end)
            busy = false
        end
        field:GetPropertyChangedSignal("Text"):Connect(function()
            if busy then
                return
            end
            local value = field.Text
            local leak = Cross.Leak
            if leak and os.clock() < leak.Until and #value == 1 and string.lower(value) == leak.Letter then
                Cross.Leak = nil
                state.Set("")
                return
            end
            local previous = state.Text
            if os.clock() < state.Window and Cross.length(previous) >= 2 and Cross.length(value) <= 1 and value ~= previous then
                local backspace = Cross.length(previous) == 2 and value == prefix(previous, 1)
                if not backspace then
                    local restored = previous .. value
                    if Cross.length(restored) > Cross.Limit then
                        restored = prefix(restored, Cross.Limit)
                    end
                    state.Set(restored)
                    return
                end
            end
            if Cross.length(value) > Cross.Limit then
                state.Set(prefix(value, Cross.Limit))
                return
            end
            state.Text = value
        end)
        field.FocusLost:Connect(function()
            state.Window = 0
        end)
    end

    function Cross.clearField(field)
        local state = Cross.Guards[field]
        state.Window = 0
        state.Set("")
    end

    function Cross.refocus(field)
        local held = false
        pcall(function()
            held = field:IsFocused()
        end)
        if held then
            return true
        end
        local state = Cross.Guards[field]
        if state then
            state.Window = os.clock() + 0.7
        end
        local ok = pcall(function()
            field:CaptureFocus()
        end)
        if ok then
            pcall(function()
                field.SelectionStart = -1
                field.CursorPosition = #field.Text + 1
            end)
        end
        return ok
    end

    function Cross.say(role, value)
        value = Cross.safe(value)
        local previous = Cross.Bubble.Entry
        if previous then
            previous.Shown = previous.Text
            previous.Visible = -1
        end
        local entry = { Role = role, Text = value, Shown = role == "cross" and "" or value, Visible = role == "cross" and 0 or -1, At = os.clock() }
        table.insert(Cross.Chat, entry)
        if #Cross.Chat > 60 then
            table.remove(Cross.Chat, 1)
        end
        Cross.ChatVersion = Cross.ChatVersion + 1
        if role == "cross" then
            Cross.Bubble.Full = value
            Cross.Bubble.Count = 0
            Cross.Bubble.Shown = ""
            Cross.Bubble.Entry = entry
            Cross.speak(Cross.length(value) / Cross.Bubble.Rate + 0.4)
        else
            Cross.Echo = value
        end
        return entry
    end

    local function hex(color)
        return string.format("%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
    end

    local function escape(source)
        source = string.gsub(source, "&", "&amp;")
        source = string.gsub(source, "<", "&lt;")
        source = string.gsub(source, ">", "&gt;")
        return source
    end
    Cross.escape = escape

    local COLORS = {
        prompt = "EEEDF0",
        cmd = "FFEB64",
        arg = "64DCE6",
        out = "C8D3E6",
        ok = "50FA7B",
        warn = "FFC46B",
        err = "FF6B6B",
        dim = "7C8CA8",
    }
    Cross.ShellColors = COLORS

    function Cross.renderLine(line, cursor)
        local parts = {}
        local left = line.Shown or math.huge
        for _, segment in ipairs(line.Segs) do
            if left <= 0 then
                break
            end
            local value = segment[1]
            local length = Cross.length(value)
            if length > left then
                value = prefix(value, left)
                left = 0
            else
                left = left - length
            end
            parts[#parts + 1] = string.format('<font color="#%s">%s</font>', segment[2], escape(value))
        end
        if cursor then
            parts[#parts + 1] = '<font color="#EEEDF0">_</font>'
        end
        return table.concat(parts)
    end

    function Cross.shellAdd(segments, typed)
        for _, segment in ipairs(segments) do
            if type(segment[1]) == "string" then
                segment[1] = Cross.safe(segment[1])
            end
        end
        local line = { Segs = segments, Shown = typed and 0 or nil }
        table.insert(Cross.Shell.Lines, line)
        if #Cross.Shell.Lines > 80 then
            table.remove(Cross.Shell.Lines, 1)
        end
        Cross.Shell.Version = Cross.Shell.Version + 1
        Cross.ShellHold = os.clock() + 7
        return line
    end

    function Cross.shellTouch()
        Cross.Shell.Version = Cross.Shell.Version + 1
    end

    function Cross.shellText(kind, value)
        local width = 34
        local color = COLORS[kind] or COLORS.out
        local first = true
        local words = {}
        for word in string.gmatch(value, "%S+") do
            words[#words + 1] = word
        end
        local current = ""
        local function flush()
            Cross.shellAdd({ { (first and "" or "  ") .. current, color } })
            first = false
            current = ""
        end
        for _, word in ipairs(words) do
            if current == "" then
                current = word
            elseif Cross.length(current) + 1 + Cross.length(word) > width then
                flush()
                current = word
            else
                current = current .. " " .. word
            end
        end
        if current ~= "" then
            flush()
        end
    end

    local TAGS = { ok = "ok", warn = "warn", err = "err", dim = "dim", out = "out" }

    function Cross.log(level, tag, value)
        local color = COLORS[TAGS[level] or "out"]
        local head = "[" .. tag .. "] "
        local width = Cross.Shell.Width
        local words = {}
        for word in string.gmatch(tostring(value), "%S+") do
            words[#words + 1] = word
        end
        local current, first = "", true
        local function flush()
            if first then
                Cross.shellAdd({ { head, COLORS.dim }, { current, color } })
            else
                Cross.shellAdd({ { string.rep(" ", Cross.length(head)), COLORS.dim }, { current, color } })
            end
            first = false
            current = ""
        end
        local limit = width - Cross.length(head)
        for _, word in ipairs(words) do
            while Cross.length(word) > limit do
                if current ~= "" then
                    flush()
                end
                current = Cross.prefix(word, limit)
                word = string.sub(word, #current + 1)
                flush()
            end
            if current == "" then
                current = word
            elseif Cross.length(current) + 1 + Cross.length(word) > limit then
                flush()
                current = word
            else
                current = current .. " " .. word
            end
        end
        if current ~= "" then
            flush()
        end
    end

    function Cross.setLive(segments)
        Cross.Shell.Live = segments
        Cross.Shell.Version = Cross.Shell.Version + 1
    end

    local function makeLabel(parent, props)
        props.BackgroundTransparency = 1
        props.BorderSizePixel = 0
        props.Parent = parent
        return new("TextLabel", props)
    end

    local codeFace = Fonts.Medium
    pcall(function()
        codeFace = Font.fromEnum(Enum.Font.Code)
    end)

    function Cross.buildShell(parent, props)
        local rows = props.Rows or 8
        local textSize = props.TextSize or 11
        local lineHeight = props.LineHeight or 14
        local frame = box({
            Name = "CrossShell",
            Position = props.Position,
            Size = props.Size,
            BackgroundColor3 = rgb(1, 36, 86),
            ClipsDescendants = true,
            ZIndex = props.ZIndex or 5,
            Parent = parent,
        })
        corner(props.Radius or 10, frame)
        stroke(frame, Static.White, 0.86, 1)
        local header = makeLabel(frame, {
            Name = "Header",
            Position = UDim2.fromOffset(10, 5),
            Size = UDim2.new(1, -20, 0, 14),
            Text = "Windows PowerShell \u{B7} cross@boncuti",
            FontFace = codeFace,
            TextSize = 10,
            TextColor3 = rgb(138, 160, 200),
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            ZIndex = (props.ZIndex or 5) + 1,
        })
        header:SetAttribute("BoncutiRaw", true)
        local labels = {}
        for index = 1, rows do
            local label = makeLabel(frame, {
                Name = "Line" .. index,
                Position = UDim2.fromOffset(10, 22 + (index - 1) * lineHeight),
                Size = UDim2.new(1, -20, 0, lineHeight),
                Text = "",
                FontFace = codeFace,
                TextSize = textSize,
                TextColor3 = rgb(238, 237, 240),
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                RichText = true,
                ZIndex = (props.ZIndex or 5) + 1,
            })
            label:SetAttribute("BoncutiRaw", true)
            labels[index] = label
        end
        local shell = { Frame = frame, Labels = labels, Rows = rows, Version = -1, Cursor = false, Active = props.Active }
        function shell.Refresh(force, cursor)
            if not force and shell.Version == Cross.Shell.Version and shell.Cursor == cursor then
                return
            end
            shell.Version = Cross.Shell.Version
            shell.Cursor = cursor
            local lines = Cross.Shell.Lines
            local live = Cross.Shell.Live
            local count = #lines
            local total = count + (live and 1 or 0)
            for index = 1, rows do
                local at = total - rows + index
                local label = labels[index]
                local value = ""
                if at >= 1 then
                    if at <= count then
                        value = Cross.renderLine(lines[at], cursor and at == total)
                    elseif live then
                        value = Cross.renderLine({ Segs = live })
                    end
                end
                if label.Text ~= value then
                    label.Text = value
                    local face = string.find(value, "[\128-\255]") and Fonts.Regular or codeFace
                    if label.FontFace ~= face then
                        label.FontFace = face
                    end
                end
            end
        end
        table.insert(Cross.Shells, shell)
        return shell
    end

    function Cross.buildFace(parent, size, position, props)
        props = props or {}
        local S = size
        local z = props.ZIndex or 3
        local root = new("Frame", {
            Name = "CrossFace",
            Position = position,
            Size = UDim2.fromOffset(S, S),
            BackgroundTransparency = 1,
            ZIndex = z,
            Parent = parent,
        })
        local head = box({
            Name = "Head",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = HEAD,
            ZIndex = z,
            Parent = root,
        })
        corner(S * 0.3, head)
        local scale = new("UIScale", { Parent = head })
        local rim = stroke(head, P.Accent, 0.4, 1.5)
        local face = { Root = root, Head = head, Scale = scale, Rim = rim, Eyes = {}, Brows = {}, Cheeks = {}, Hearts = {}, Lens = {}, Glints = {}, Active = props.Active, Size = S }

        for index = 1, 2 do
            local cheek = box({
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(S * 0.17, S * 0.09),
                BackgroundColor3 = PINK,
                BackgroundTransparency = 1,
                ZIndex = z + 1,
                Parent = head,
            })
            corner(S, cheek)
            face.Cheeks[index] = cheek
        end

        for index = 1, 2 do
            local eye = box({
                Name = "Eye" .. index,
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(S * 0.15, S * 0.2),
                BackgroundColor3 = Static.White,
                ClipsDescendants = true,
                ZIndex = z + 2,
                Parent = head,
            })
            local round = corner(S * 0.075, eye)
            local lidTop = box({
                AnchorPoint = Vector2.new(0.5, 1),
                Size = UDim2.fromOffset(S * 0.36, S * 0.2),
                BackgroundColor3 = HEAD,
                ZIndex = z + 3,
                Parent = eye,
            })
            local lidBottom = box({
                AnchorPoint = Vector2.new(0.5, 0),
                Size = UDim2.fromOffset(S * 0.26, S * 0.24),
                BackgroundColor3 = HEAD,
                ZIndex = z + 3,
                Parent = eye,
            })
            new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = lidBottom })
            face.Eyes[index] = { Eye = eye, Round = round, LidTop = lidTop, LidBottom = lidBottom }

            local brow = box({
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(S * 0.2, 3),
                BackgroundColor3 = Static.White,
                BackgroundTransparency = 1,
                ZIndex = z + 2,
                Parent = head,
            })
            corner(2, brow)
            face.Brows[index] = brow

            local lens = box({
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(S * 0.3, S * 0.15),
                BackgroundColor3 = SHADE,
