        sr = "xin loi", ib = "nhan tin", nt = "nhan tin", vl = "", vcl = "", dm = "", dkm = "", lol = "", haha = "", hihi = "", hehe = "", kkk = "",
        bt = "binh thuong", bth = "binh thuong", dep = "dep", cx = "cung", cg = "cung", cug = "cung",
