        hjhj = "", hix = "", uh = "u", uhm = "u", um = "u", uk = "u", ukm = "u",
        tgian = "thoi gian", tg = "thoi gian", sec = "giay", secs = "giay", seconds = "giay", second = "giay", sc = "giay",
        mins = "min", minute = "min", minutes = "min", hrs = "hour", hr = "hour", hours = "hour", ph = "phut",
        pct = "pct", percent = "pct",
    }

    local VNUM = { mot = 1, hai = 2, ba = 3, bon = 4, nam = 5, sau = 6, bay = 7, tam = 8, chin = 9, muoi = 10 }
    local ENUM = { one = 1, two = 2, three = 3, four = 4, five = 5, six = 6, seven = 7, eight = 8, nine = 9, ten = 10, once = 1, twice = 2, thrice = 3, couple = 2, few = 3 }
    local UNITS = {
        giay = "sec", s = "sec", phut = "min", min = "min", m = "min", p = "min", gio = "hour", h = "hour", hour = "hour", tieng = "hour",
        lan = "times", x = "times", times = "times", time = "times", buoc = "steps", step = "steps", steps = "steps", pct = "pct",
        bai = "track", song = "track", track = "track",
    }

    local function collapse(word)
        local out = {}
        local index = 1
        local length = #word
        while index <= length do
            local char = string.sub(word, index, index)
            local run = 1
            while string.sub(word, index + run, index + run) == char do
                run = run + 1
            end
            if run >= 3 and string.find(char, "%a") then
                out[#out + 1] = char
            else
                out[#out + 1] = string.rep(char, run)
            end
            index = index + run
        end
        return table.concat(out)
    end

    local function osa(a, b, limit)
        local la, lb = #a, #b
        if math.abs(la - lb) > limit then
            return limit + 1
        end
        local prev2, prev, cur = {}, {}, {}
        for j = 0, lb do
            prev[j] = j
        end
        for i = 1, la do
            cur[0] = i
            local best = i
            for j = 1, lb do
                local cost = string.byte(a, i) == string.byte(b, j) and 0 or 1
                local value = math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
                if i > 1 and j > 1 and string.byte(a, i) == string.byte(b, j - 1) and string.byte(a, i - 1) == string.byte(b, j) then
                    value = math.min(value, prev2[j - 2] + 1)
                end
                cur[j] = value
                if value < best then
                    best = value
                end
            end
            if best > limit then
                return limit + 1
            end
            prev2, prev, cur = prev, cur, prev2
            cur = cur or {}
        end
        return prev[lb]
    end
    M.distance = function(a, b)
        return osa(a, b, 8)
    end

    local function close(a, b)
        if a == b then
            return true
        end
        local n = #b
        if n <= 3 or #a <= 3 then
            return false
        end
        local limit = n >= 9 and 2 or 1
        return osa(a, b, limit) <= limit
    end
