    local LEX = {}
    for name, source in pairs(LEX_SRC) do
        local list = {}
        for phrase in string.gmatch(source, "[^|]+") do
            local words = {}
            for word in string.gmatch(phrase, "%S+") do
                words[#words + 1] = word
            end
            if #words > 0 then
                list[#list + 1] = words
            end
        end
        LEX[name] = list
    end

    local KNOWN, KCOUNT = {}, {}
    local function learn(spec)
        for word in string.gmatch(spec, "[%w_]+") do
            KNOWN[word] = true
            KCOUNT[word] = (KCOUNT[word] or 0) + 1
        end
    end
    M.learn = learn
    for _, source in pairs(LEX_SRC) do
        learn(source)
    end
    learn("cai nay kia con thang ong ba anh chi em co cau ban may tui toi minh chung ta nhung nhieu rat hoi kha lam that qua de so nhu neu thi ma nen vi boi do dang se da vua moi cung van chua het xong hoac hay tuy du khi luc sau truoc trong ngoai tren duoi giua canh ben gan xa day nao dau sao gi ai bao it tung cac mot hai ba bon nam sau bay tam chin muoi tram nghin trieu cho voi cua la va roi nua thoi nhe nha nhi a oi ne nay vay duoc khong xin xiu chut coi gium ho dum voi giup lam sao the nhin thay thich muon can biet noi hoi tra loi biet nghi")
    learn("the and but if then because as of at by for from in into on onto to up with without about over under again further once here there when where why how all any both each few more most other some such nor not only own same than too very can will just dont should now me my myself we our you your he him his she her its they them their what which who whom this that these those am is are was were be been being have has had does did doing would could ought let us please make turn set show tell give going get got want need like love hate know think see look come take put keep say said ask use used try little bit")
    local function transposedStart(a, b)
        return string.sub(a, 1, 1) == string.sub(b, 2, 2) and string.sub(a, 2, 2) == string.sub(b, 1, 1)
    end
    local function correct(token)
        if KNOWN[token] or #token <= 3 or string.find(token, "[%d_]") then
            return token
        end
        local limit = #token >= 9 and 2 or 1
        local best, bestD, bestC
        for word in pairs(KNOWN) do
            if #word >= 4 and math.abs(#word - #token) <= limit and not string.find(word, "_") then
                if string.sub(word, 1, 1) == string.sub(token, 1, 1) or transposedStart(token, word) then
                    local d = osa(token, word, limit)
                    if d <= limit then
                        local c = KCOUNT[word]
                        if not best or d < bestD or (d == bestD and c > bestC) or (d == bestD and c == bestC and word < best) then
                            best, bestD, bestC = word, d, c
                        end
                    end
                end
            end
        end
        return best or token
    end

    local cache = {}
    local function compile(spec)
        local direct = LEX[spec]
        if direct then
            return direct
        end
        local hit = cache[spec]
        if hit then
            return hit
        end
        learn(spec)
        local list = {}
        for phrase in string.gmatch(spec, "[^|]+") do
            local words = {}
            for word in string.gmatch(phrase, "%S+") do
                words[#words + 1] = word
            end
            if #words > 0 then
                list[#list + 1] = words
            end
        end
        cache[spec] = list
        return list
    end

    local function matchAt(tokens, used, start, words)
        for offset, word in ipairs(words) do
            local token = tokens[start + offset - 1]
            if token == nil or used[start + offset - 1] or token ~= word then
                return false
            end
        end
        return true
    end

    function M.find(clause, spec, consume)
        local list = compile(spec)
        local tokens, used = clause.tokens, clause.used
        local bestScore, bestStart, bestWords = 0, nil, nil
        for _, words in ipairs(list) do
            for start = 1, #tokens - #words + 1 do
                if matchAt(tokens, used, start, words) then
                    local score = 0
                    for offset, word in ipairs(words) do
                        score = score + 3 + #word * 0.1
                    end
                    if score > bestScore then
                        bestScore, bestStart, bestWords = score, start, words
                    end
                end
            end
        end
        if bestStart and consume then
            for offset = 1, #bestWords do
                used[bestStart + offset - 1] = true
            end
        end
        return bestStart ~= nil, bestScore, bestStart
    end

    function M.has(clause, spec, consume)
        return (M.find(clause, spec, consume))
    end

    function M.words(spec)
        local set = {}
        for _, words in ipairs(compile(spec)) do
            for _, word in ipairs(words) do
                set[word] = true
            end
        end
        return set
    end

    function M.exact(clause, spec)
        local list = compile(spec)
        local tokens, used = clause.tokens, clause.used
        for _, words in ipairs(list) do
            for start = 1, #tokens - #words + 1 do
                local ok = true
                for offset, word in ipairs(words) do
                    if tokens[start + offset - 1] ~= word or used[start + offset - 1] then
                        ok = false
                        break
                    end
                end
                if ok then
                    return true, start
                end
            end
        end
        return false
    end

    function M.count(clause, spec)
        local total = 0
        for _, words in ipairs(compile(spec)) do
            for start = 1, #clause.tokens - #words + 1 do
                if matchAt(clause.tokens, clause.used, start, words) then
                    total = total + 1
                end
            end
        end
        return total
    end

    function M.number(clause)
        local tokens = clause.tokens
        for index, token in ipairs(tokens) do
            local digits, suffix = string.match(token, "^(%d+_?%d*)(%a*)$")
            if digits then
                local value = tonumber((string.gsub(digits, "_", ".")))
                local unit = UNITS[suffix]
                if suffix ~= "" and not unit then
                    unit = nil
                end
                if not unit then
                    local nextToken = tokens[index + 1]
                    unit = nextToken and UNITS[nextToken]
                end
                return value, unit, index
            end
        end
        for index, token in ipairs(tokens) do
            local value = ENUM[token] or VNUM[token]
            if value then
                local nextToken = tokens[index + 1]
                local unit = nextToken and UNITS[nextToken]
                if unit or ENUM[token] then
                    return value, unit, index
                end
            end
        end
        return nil
    end

