    function M.analyze(source, previous)
        local text = lowered(source)
        local question = string.find(source, "?", 1, true) ~= nil
        local hasMarks = false
        for _, code in utf8.codes(text) do
            if FOLD[code] then
                hasMarks = true
                break
            end
        end
        text = string.gsub(text, "(%d)%.(%d)", "%1_%2")
        text = string.gsub(text, "%%", " pct ")
        local words = {}
        local cursor = 1
        for startPos, word, endPos in string.gmatch(text, "()([%w_\128-\255]+)()") do
            local between = string.sub(text, cursor, startPos - 1)
            if #words > 0 and string.find(between, "[,;%.!?\n]") then
                words[#words + 1] = "|"
            end
            words[#words + 1] = word
            cursor = endPos
        end
        local tokens = {}
        local rawSang = {}
        for _, word in ipairs(words) do
            if word == "|" then
                tokens[#tokens + 1] = "|"
            else
                if word == "sang" then
                    rawSang[#tokens + 1] = "plain"
                end
                local mark = MARK[word]
                local token = mark or collapse(folded(word))
                local slang = SLANG[token]
                if slang ~= nil and not mark then
                    for part in string.gmatch(slang, "%S+") do
                        tokens[#tokens + 1] = part
                    end
                elseif token ~= "" then
                    tokens[#tokens + 1] = token
                end
            end
        end
        for index, token in ipairs(tokens) do
            if token == "toi" then
                local nextToken = tokens[index + 1]
                if nextToken and (nextToken == "muon" or nextToken == "can" or nextToken == "se" or nextToken == "dang" or nextToken == "la" or nextToken == "co" or nextToken == "thich" or nextToken == "biet" or nextToken == "hoi" or nextToken == "da" or nextToken == "khong" or nextToken == "vua" or nextToken == "nghe" or nextToken == "dung" or nextToken == "nghi" or nextToken == "that") then
                    tokens[index] = "toi_me"
                end
            end
        end
        for index, token in ipairs(tokens) do
            if token ~= "|" then
                tokens[index] = correct(token)
            end
        end
        local PREP_NEXT = { trai = 1, phai = 1, tab = 1, tim = 1, hong = 1, cam = 1, xanh = 1, dai = 1, rung = 1, ca = 1, sakura = 1, toi = 1, den = 1, theme = 1, dark = 1, light = 1, ocean = 1, forest = 1, coffee = 1, midnight = 1, english = 1, tieng = 1, viet = 1, mau = 1, che = 1, giao = 1, mat = 1, blue = 1, green = 1, pink = 1, purple = 1, orange = 1, teal = 1, vua = 1, nho = 1, lon = 1, bai = 1, nhac = 1, nua = 1, ngoc = 1, nen = 1, am = 1, trang = 1 }
        for index, token in ipairs(tokens) do
            if token == "sang" and (rawSang[index] == "plain" and (hasMarks or PREP_NEXT[tokens[index + 1] or ""])) then
                tokens[index] = "sang_to"
            end
        end
        local NEG_VERBS = { bat = 1, tat = 1, mo = 1, choi = 1, phat = 1, di = 1, chay = 1, nhay = 1, lam = 1, cho = 1, doi = 1, chuyen = 1, an = 1, hien = 1, tang = 1, giam = 1, noi = 1, nghe = 1, tu = 1, dieu = 1, bam = 1, nhan = 1 }
        for index, token in ipairs(tokens) do
            if token == "dung" and NEG_VERBS[tokens[index + 1] or ""] then
                tokens[index] = "dung_neg"
            end
        end
        local viScore, enScore = hasMarks and 4 or 0, 0
        for _, token in ipairs(tokens) do
            if VI_HINT[token] == 1 then
                viScore = viScore + 1
            end
            if EN_HINT[token] == 1 then
                enScore = enScore + 1
            end
        end
        for _, word in ipairs(words) do
            if SLANG[word] and (word == "ko" or word == "dc" or word == "j" or word == "r" or word == "mk" or word == "vs") then
                viScore = viScore + 2
            end
        end
        local lang = previous or "vi"
        if viScore > enScore then
            lang = "vi"
        elseif enScore > viScore then
            lang = "en"
        end
        local clauses = {}
        local current = {}
        local function flush()
            if #current > 0 then
                clauses[#clauses + 1] = { tokens = current, used = {}, lang = lang }
                current = {}
            end
        end
        local index = 1
        while index <= #tokens do
            local token = tokens[index]
            local nextToken = tokens[index + 1]
            if token == "|" or token == "va" or token == "and" or token == "then" or token == "roi" or token == "xong" or token == "ma" or token == "sau" and nextToken == "do" or token == "also" or token == "afterwards" or token == "afterward" or token == "ngoai" and nextToken == "ra" or token == "dong" and nextToken == "thoi" then
                if token == "sau" and nextToken == "do" or token == "ngoai" and nextToken == "ra" or token == "dong" and nextToken == "thoi" then
                    index = index + 1
                end
                flush()
            else
                current[#current + 1] = token
            end
            index = index + 1
        end
        flush()
        local all = {}
        for _, token in ipairs(tokens) do
            if token ~= "|" then
                all[#all + 1] = token
            end
        end
        return { Lang = lang, Question = question, Tokens = all, Clauses = clauses, Raw = source, Marks = hasMarks, Vi = viScore, En = enScore }
    end

    function M.whole(analysis)
        return { tokens = analysis.Tokens, used = {}, lang = analysis.Lang }
    end

    for _, group in ipairs({ UNITS, VNUM, ENUM, VI_HINT, EN_HINT }) do
        for word in pairs(group) do
            learn(word)
        end
    end
    for _, value in pairs(SLANG) do
        learn(value)
    end
    for _, value in pairs(MARK) do
        learn(value)
    end
    M.VI_MARKS = VI_MARKS
    return M
end)()

