    K.Tabs = {
        Home = "home",
        Music = "music",
        AI = "cross",
        Inbox = "inbox",
        Tools = "tools",
        Settings = "settings",
        Test = "test",
        About = "about",
    }

    function K.byId(id)
        for _, topic in ipairs(K.Topics) do
            if topic.Id == id then
                return topic
            end
        end
    end

    function K.find(clause)
        local Nlu = Cross.Nlu
        local best, bestScore
        for _, topic in ipairs(K.Topics) do
            local found, score = Nlu.find(clause, topic.Keys)
            if found and (not bestScore or score > bestScore) then
                best, bestScore = topic, score
            end
        end
        return best, bestScore
    end

    function K.suggestions(lang)
        if lang == "en" then
            return { "it's hot, cool the UI down", "play music", "set speed to 60", "how do I use Anti AFK?", "play by yourself" }
        end
        return { "n\u{F3}ng qu\u{E1}, l\u{E0}m UI m\u{E1}t \u{111}i", "b\u{1EAD}t nh\u{1EA1}c", "\u{111}\u{1EB7}t t\u{1ED1}c \u{111}\u{1ED9} 60", "Anti AFK d\u{F9}ng sao?", "t\u{1EF1} ch\u{1A1}i \u{111}i" }
    end

    return K
end)()

