    local ADDRESS = { e = true, oi = true, cross = true, nay = true }

    local function fmtNumber(value)
        if value == math.floor(value) then
            return tostring(math.floor(value))
        end
        return string.format("%.1f", value)
    end

    local function pick(ctx, list)
        local seed = ctx.Env.seed or 0
        return list[(seed % #list) + 1]
    end

    local function T(ctx, vi, en)
        return ctx.Lang == "vi" and vi or en
    end

    local function themeName(ctx, index)
        return (ctx.Lang == "vi" and THEME_VI or THEME_EN)[index] or "?"
    end

    local function accentName(ctx, index)
        return (ctx.Lang == "vi" and ACCENT_VI or ACCENT_EN)[index] or "?"
    end

    local function clamp(value, low, high)
        return math.max(low, math.min(high, value))
    end

    local function snap(spec, value)
        value = clamp(value, spec.Min, spec.Max)
        return math.floor(value / spec.Step + 0.5) * spec.Step
    end

    local function step(ctx, op, fields)
        fields.Op = op
        ctx.Steps[#ctx.Steps + 1] = fields
        return fields
    end

    local function setCtl(ctx, key, value, sayVi, sayEn, shown)
        return step(ctx, "ctl", {
            Key = key,
            Value = value,
            Cmd = "Set-Setting",
            Args = string.format("%s=%s", key, shown or tostring(value)),
            Say = { sayVi, sayEn },
            Perm = "Ui",
        })
    end

    local function answer(ctx, vi, en, mood, hold)
        ctx.Answer = ctx.Answer and (ctx.Answer .. " " .. T(ctx, vi, en)) or T(ctx, vi, en)
        ctx.Mood = ctx.Mood or mood
        ctx.Hold = ctx.Hold or hold
    end

    local function intent(ctx, name)
        ctx.Intents[#ctx.Intents + 1] = name
    end

    local function strip(clause)
        local tokens = clause.tokens
        local first = tokens[1]
        local changed = false
        while first and ADDRESS[first] and #tokens > 1 do
            if first == "cross" then
                clause.addressed = true
            end
            table.remove(tokens, 1)
            first = tokens[1]
            changed = true
        end
        if #tokens == 1 and ADDRESS[tokens[1]] and tokens[1] == "cross" then
            clause.addressed = true
        end
        return changed
    end

    local function currentValue(ctx, key)
        local value = ctx.Env.get(key)
        if value == nil then
            local spec = CTL[key]
            if spec and spec.Kind == "slider" then
                value = spec.Min
            end
        end
        return value
    end

    local function describeValue(ctx, key, value)
        local spec = CTL[key]
        if spec.Kind == "toggle" then
            return value and T(ctx, "\u{111}ang b\u{1EAD}t", "on") or T(ctx, "\u{111}ang t\u{1EAF}t", "off")
        end
        if spec.Kind == "slider" then
            return fmtNumber(value) .. (spec.Unit or "")
        end
        if key == "theme" then
            return themeName(ctx, value)
        elseif key == "accent" then
            return accentName(ctx, value)
        elseif key == "scale" then
            return (ctx.Lang == "vi" and SCALE_VI or SCALE_EN)[value]
        elseif key == "language" then
            return value == 2 and "English" or "Ti\u{1EBF}ng Vi\u{1EC7}t"
        elseif key == "islandColor" then
            return (ctx.Lang == "vi" and ISLAND_VI or ISLAND_EN)[value] or tostring(value)
        end
        return tostring(value)
    end

    local function themeFromNames(c, consume)
        local list = {
            { 1, "t_dark" }, { 2, "t_light" }, { 3, "t_midnight" }, { 4, "t_ocean" }, { 5, "t_forest" }, { 6, "t_coffee" }, { 7, "t_sakura" },
        }
        local bestIndex, bestScore, strong = nil, 0, false
        for _, entry in ipairs(list) do
            local found, score = find(c, entry[2])
            if found and score > bestScore then
                bestIndex, bestScore = entry[1], score
                strong = entry[1] >= 3 or exact(c, "che do toi|dark mode|giao dien toi|che do sang|light mode|giao dien sang|night mode") or false
            end
        end
        if bestIndex and consume then
            find(c, list[bestIndex][2], true)
        end
        return bestIndex, strong
    end

    local function accentFromNames(c)
        local order = {
            { 3, "c_pink" }, { 2, "c_purple" }, { 4, "c_orange" }, { 5, "c_green" }, { 6, "c_teal" }, { 1, "c_blue" },
        }
        local bestIndex, bestScore = nil, 0
        for _, entry in ipairs(order) do
            local found, score = find(c, entry[2])
            if found and score > bestScore then
                bestIndex, bestScore = entry[1], score
            end
        end
        return bestIndex
    end

    local function negated(c)
        return has(c, "neg")
    end

    local function valueCue(c)
        return N.number(c) ~= nil or has(c, "up") or has(c, "down") or has(c, "max") or has(c, "min")
    end

    local I = {}

