    local FILL = { nua = true, dau = true, nha = true, nhe = true, nhi = true, ne = true, a = true, oi = true, di = true, luon = true, cu = true, ha = true, cross = true, e = true }
    local AGAIN_OK = N.words("again")
    for word in pairs(N.words("please")) do
        AGAIN_OK[word] = true
    end
    local AGAIN_FILL = { cross = true, e = true, oi = true, ne = true, a = true, ok = true, cai = true, do_that = true, no_it = true, it = true, that = true, this = true, the = true, same = true, thing = true, one = true, more = true, time = true, ["do"] = true, lam = true, thu = true, lan = true, mot = true, nua = true, lai = true, roi = true, minh = true, cho = true, giup = true }

    local function snip(text, limit)
        text = tostring(text or "")
        local length = utf8.len(text)
        if not length or length <= limit then
            return text
        end
        return string.sub(text, 1, utf8.offset(text, limit) - 1) .. "\u{2026}"
    end

    local function lastWhere(ctx, test, limit, maxAge)
        local list = ctx.Hist or {}
        local seen = 0
        for index = #list, 1, -1 do
            seen = seen + 1
            if limit and seen > limit then
                return nil
            end
            local turn = list[index]
            if (not maxAge or (turn.Age or 0) <= maxAge) and test(turn) then
                return turn, index
            end
        end
        return nil
    end

    local function accept(ctx, pending)
        if pending.Kind == "grant" then
            ctx.Assume = ctx.Assume or {}
            ctx.Assume[pending.Perm] = true
            step(ctx, "perm", { Name = pending.Perm, Value = true, Cmd = "Grant-Permission", Args = pending.Perm, Say = { "b\u{1EAD}t quy\u{1EC1}n " .. PERM_VI[pending.Perm], "enabled permission to " .. PERM_EN[pending.Perm] } })
            if pending.Perm == "Free" then
                ctx.Assume.Body = true
                if not ctx.Env.perm("Body") then
                    step(ctx, "perm", { Name = "Body", Value = true, Cmd = "Grant-Permission", Args = "Body", Say = { "b\u{1EAD}t quy\u{1EC1}n " .. PERM_VI.Body, "enabled permission to " .. PERM_EN.Body } })
                end
            end
            if pending.Replay then
                ctx.Replay = pending.Replay
            end
        elseif pending.Kind == "cool" then
            ctx.Replay = ctx.Lang == "vi" and "lam ui mat di" or "make the ui cool"
        elseif pending.Kind == "warm" then
            ctx.Replay = ctx.Lang == "vi" and "lam ui am ap" or "make the ui warm"
        elseif pending.Kind == "do" then
            ctx.Replay = pending.Replay
        end
    end

    function I.confirm(ctx, c)
        local pending = ctx.Env.pending()
        if not pending or #c.tokens > 5 or pending.Kind == "taskq" then
            return false
        end
        local allowed = { cross = true, e = true, nhe = true, nha = true, nhi = true, a = true, oi = true, di = true, luon = true, ne = true, please = true, ok = true, thanks = true, it = true, the = true, thing = true, do_ = true, lam = true, cho = true, phep = true, ["not"] = true, now = true, vay = true, thi = true, ["then"] = true, ["\u{111}i"] = true, qua = true, nua = true, roi = true }
        local yes = has(c, "yes")
        local no = has(c, "no") or negated(c)
        if not yes and not no then
            return false
        end
        for _, token in ipairs(c.tokens) do
            if not allowed[token] and not N.exact(c, "yes|no|neg") and false then
                return false
            end
        end
        local vocab = "yes|no|neg"
        for index, token in ipairs(c.tokens) do
            local ok = allowed[token]
            if not ok then
                local single = { tokens = { token }, used = {} }
                ok = N.has(single, vocab)
            end
            if not ok then
                return false
            end
        end
        intent(ctx, "confirm." .. pending.Kind)
        ctx.Env.clearPending()
        if no and not (yes and not negated(c)) then
            answer(ctx, "Ok, m\u{EC}nh b\u{1ECF} qua nh\u{E9}.", "Okay, I'll skip that.", "neutral")
            return true
        end
        accept(ctx, pending)
        return true
    end

    function I.undo(ctx, c)
        if not has(c, "undo") or has(c, "howto") then
            return false
        end
        intent(ctx, "ui.undo")
        step(ctx, "undo", { Cmd = "Undo-Change", Args = "", Say = { "ho\u{E0}n t\u{E1}c thay \u{111}\u{1ED5}i g\u{1EA7}n nh\u{1EA5}t", "undid the last change" } })
        return true
    end

    function I.who(ctx, c)
        if not has(c, "who") then
            return false
        end
        intent(ctx, "chat.identity")
        answer(ctx,
            "M\u{EC}nh l\u{E0} Cross, tr\u{1EE3} l\u{FD} AI s\u{1ED1}ng trong boncuti. M\u{EC}nh ch\u{1EC9}nh giao di\u{1EC7}n, \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{1EA1}c/h\u{1EB9}n gi\u{1EDD}/c\u{E0}i \u{111}\u{1EB7}t, gi\u{1EA3}i th\u{ED}ch c\u{E1}ch d\u{F9}ng v\u{E0} (khi b\u{1EA1}n cho ph\u{E9}p) \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t. M\u{EC}nh l\u{E0} b\u{1ED9} n\u{E3}o t\u{ED}ch h\u{1EE3}p s\u{1EB5}n trong script, kh\u{F4}ng ph\u{1EA3}i m\u{F4} h\u{EC}nh AI tr\u{EA}n m\u{1EA1}ng.",
            "I'm Cross, the AI assistant living inside boncuti. I tweak the interface, control music/timers/settings, explain how things work and, when you allow it, move your character. I'm a brain built into this script, not an online AI model.",
            "happy", 5)
        return true
    end

    function I.capabilities(ctx, c)
        if not has(c, "canw") or has(c, "howto") and not has(c, "what do") then
            return false
        end
        intent(ctx, "chat.capabilities")
        answer(ctx,
            "M\u{EC}nh l\u{E0}m \u{111}\u{1B0}\u{1EE3}c: \u{111}\u{1ED5}i giao di\u{1EC7}n/m\u{E0}u ('n\u{F3}ng qu\u{E1}, l\u{E0}m UI m\u{E1}t \u{111}i'), \u{111}\u{1ED5}i m\u{E0}u Dynamic Island, b\u{1EAD}t/t\u{1EAF}t m\u{1ECD}i c\u{F4}ng t\u{1EAF}c ('t\u{1EAF}t blur', '\u{111}\u{1EB7}t t\u{1ED1}c \u{111}\u{1ED9} 60'), nh\u{1EA1}c ('b\u{1EAD}t nh\u{1EA1}c', 'b\u{E0}i ti\u{1EBF}p'), h\u{1EB9}n gi\u{1EDD}/b\u{1EA5}m gi\u{1EDD}, m\u{1EDF} tab, gi\u{1EA3}i th\u{ED}ch c\u{E1}ch d\u{F9}ng ('Anti AFK d\u{F9}ng sao?'), \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t ('\u{111}i t\u{1EDB}i 3 gi\u{E2}y', 'nh\u{1EA3}y 2 l\u{1EA7}n'), t\u{1EF1} ch\u{1A1}i ('ch\u{1A1}i obby', '\u{111}\u{E1}nh qu\u{E1}i', 'nh\u{1EB7}t v\u{1EAD}t ph\u{1EA9}m', 'qu\u{E9}t map', 't\u{1EF1} ch\u{1A1}i \u{111}i') v\u{E0} ch\u{1EA1}y nhi\u{1EC7}m v\u{1EE5} n\u{1ED1}i ti\u{1EBF}p tr\u{EA}n m\u{1ECD}i c\u{F4}ng t\u{1EAF}c ('b\u{1EAD}t Anti AFK \u{111}\u{1EBF}n level 30 r\u{1ED3}i t\u{1EAF}t n\u{F3} v\u{E0} b\u{1EAD}t c\u{E1}i kh\u{E1}c') khi b\u{1EA1}n cho ph\u{E9}p. N\u{F3}i 'ho\u{E0}n t\u{E1}c' \u{111}\u{1EC3} tr\u{1EA3} l\u{1EA1}i.",
            "I can: change the look ('it's hot, cool the UI'), recolor Dynamic Island, toggle any switch ('blur off', 'set speed to 60'), control music ('play music', 'next song'), timers/stopwatch, open tabs, explain features ('how do I use Anti AFK?'), move your character ('walk forward 3 seconds', 'jump twice'), play on my own ('play the obby', 'fight mobs', 'collect items', 'scan the map', 'play by yourself') and run chained tasks over any toggle ('turn on Anti AFK until level 30 then turn it off and switch on something else') when you allow it. Say 'undo' to revert.",
            "wink", 6)
        return true
    end

    function I.howto(ctx, c)
        if not has(c, "howto") then
            return false
        end
        local topic, score = K.find(c)
        if not topic and (has(c, "this") or has(c, "itw")) then
            local recent = lastWhere(ctx, function(turn)
                return turn.Topic ~= nil
            end, 2, 300)
            if recent then
                topic = K.byId(recent.Topic)
            end
            if not topic then
                local tab = ctx.Env.tab()
                local id = K.Tabs[tab or ""]
                if ctx.Env.windowOpen() and id then
                    topic = K.byId(id)
                end
            end
        end
        if not topic then
            local key, value
            for _, target in ipairs(TARGETS) do
                if has(c, target[2]) then
                    key = target[1]
                    break
                end
            end
            if key then
                local spec = CTL[key]
                ctx.Key = key
                intent(ctx, "help.setting")
                answer(ctx,
                    string.format("'%s' n\u{1EB1}m trong c\u{E0}i \u{111}\u{1EB7}t c\u{1EE7}a m\u{EC}nh: b\u{1EA1}n c\u{F3} th\u{1EC3} t\u{1EF1} ch\u{1EC9}nh trong menu ho\u{1EB7}c nh\u{1EDD} m\u{EC}nh, v\u{ED} d\u{1EE5} 'b\u{1EAD}t %s' ho\u{1EB7}c '\u{111}\u{1EB7}t %s 50'. Hi\u{1EC7}n t\u{1EA1}i: %s.", spec.Vi, spec.Vi, spec.Vi, tostring(describeValue(ctx, key, currentValue(ctx, key)))),
                    string.format("'%s' is one of my settings: change it in the menu or just ask me, e.g. 'turn on %s' or 'set %s to 50'. Right now: %s.", spec.En, spec.En, spec.En, tostring(describeValue(ctx, key, currentValue(ctx, key)))),
                    "happy", 5)
                return true
            end
        end
        if topic then
            intent(ctx, "help." .. topic.Id)
            answer(ctx, topic.Vi, topic.En, "happy", 5)
            ctx.Topic = topic.Id
            return true
        end
        intent(ctx, "help.unknown")
        answer(ctx,
            "B\u{1EA1}n h\u{1ECF}i v\u{1EC1} ch\u{1EE9}c n\u{103}ng n\u{E0}o nh\u{1EC9}? M\u{EC}nh gi\u{1EA3}i th\u{ED}ch \u{111}\u{1B0}\u{1EE3}c c\u{E1}c tab (T\u{1ED5}ng quan, \u{C2}m nh\u{1EA1}c, Ti\u{1EC7}n \u{ED}ch, C\u{E0}i \u{111}\u{1EB7}t\u{2026}), Dynamic Island, giao di\u{1EC7}n, ph\u{ED}m t\u{1EAF}t, Anti AFK, t\u{E0}i kho\u{1EA3}n, Discord\u{2026} H\u{1ECF}i c\u{1EE5} th\u{1EC3} h\u{1A1}n nh\u{E9}.",
            "Which feature do you mean? I can explain the tabs (Overview, Music, Utilities, Settings\u{2026}), Dynamic Island, themes, shortcuts, Anti AFK, accounts, Discord\u{2026} Ask me something more specific.",
            "confused", 4)
        return true
    end

    function I.sys(ctx, c)
        if has(c, "howto") then
            return false
        end
        local asleep = ctx.Env.enabled ~= nil and not ctx.Env.enabled()
        if has(c, "cpon") or (asleep and has(c, "cwake") and #c.tokens <= 4) then
            find(c, "cpon", true)
            intent(ctx, "power.on")
            if not asleep then
                answer(ctx, "M\u{EC}nh \u{111}ang th\u{1EE9}c s\u{1EB5}n r\u{1ED3}i n\u{E8}!", "I'm already awake!", "wink", 3)
            end
            return true
        end
        if has(c, "cpoff") or (c.addressed and exact(c, "ngu_sleep|ngu_sleep di|di ngu_sleep|sleep|go to sleep|sleep now|go sleep")) then
            if has(c, "cpoff") then
                find(c, "cpoff", true)
            end
            intent(ctx, "power.off")
            step(ctx, "power", { Do = "off", Cmd = "Stop-Cross", Args = "", Say = { "t\u{1EAF}t Cross (n\u{F3}i 'b\u{1EAD}t cross' \u{111}\u{1EC3} g\u{1ECD}i m\u{EC}nh d\u{1EAD}y)", "turned Cross off (say 'turn on cross' to wake me)" } })
            ctx.Mood = "sleepy"
            ctx.Hold = 5
            return true
        end
        if has(c, "memoff") or has(c, "memon") then
            local want = not has(c, "memoff")
            find(c, want and "memon" or "memoff", true)
            intent(ctx, want and "memory.on" or "memory.off")
            local now = ctx.Env.remember ~= nil and ctx.Env.remember() or false
            if now == want then
                answer(ctx, want and "M\u{EC}nh \u{111}ang nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat s\u{1EB5}n r\u{1ED3}i n\u{E8}." or "M\u{EC}nh \u{111}ang t\u{1EAF}t nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat s\u{1EB5}n r\u{1ED3}i.", want and "I'm already remembering our chat." or "Chat memory is already off.", "wink", 3)
            else
                step(ctx, "memory", { Do = want and "on" or "off", Cmd = "Set-Memory", Args = want and "-On" or "-Off", Say = { want and "b\u{1EAD}t nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat" or "t\u{1EAF}t nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat v\u{E0} xo\u{E1} tr\u{ED} nh\u{1EDB}", want and "turned chat memory on" or "turned chat memory off and wiped it" } })
                ctx.Mood = want and "happy" or "wink"
            end
            return true
        end
        if has(c, "clearchat") then
            find(c, "clearchat", true)
            intent(ctx, "chat.clear")
            step(ctx, "memory", { Do = "chat", Cmd = "Clear-Chat", Args = "", Say = { "xo\u{E1} cu\u{1ED9}c tr\u{F2} chuy\u{1EC7}n", "cleared the chat" } })
            ctx.Forget = true
            ctx.Mood = "wink"
            return true
        end
        return false
    end

    function I.permission(ctx, c)
        local grant = has(c, "allow")
        local deny = has(c, "deny")
        local about = has(c, "perm")
        local free = has(c, "bfree")
        local body = has(c, "bchar") or has(c, "bmove") or has(c, "dieu khien|control|move|di chuyen")
        local ui = has(c, "ui") or has(c, "theme") or has(c, "cai dat|settings|chinh|edit|change|menu")
        local key = has(c, "goi cross|go cross|phim cross|cross key|trigger|phim tat|goi bang phim|bang phim|call with a key|call by key|by key|keyboard")
        if not (grant or deny or about) then
            return false
        end
        if has(c, "howto") then
            return false
        end
        if not (free or body or ui or key or about) then
            return false
        end
        local on = (grant and not negated(c)) or (about and has(c, "on") and not negated(c))
        local off = deny or (grant and negated(c)) or (about and (has(c, "off") or negated(c)))
        if not on and not off then
            if about and not grant then
                intent(ctx, "perm.status")
                local function state(name)
                    return ctx.Env.perm(name) and T(ctx, "b\u{1EAD}t", "on") or T(ctx, "t\u{1EAF}t", "off")
                end
                answer(ctx,
                    string.format("Quy\u{1EC1}n hi\u{1EC7}n t\u{1EA1}i: ch\u{1EC9}nh giao di\u{1EC7}n %s, \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t %s, t\u{1EF1} ch\u{1A1}i t\u{1EF1} do %s, g\u{1ECD}i b\u{1EB1}ng ph\u{ED}m %s. Mu\u{1ED1}n \u{111}\u{1ED5}i, n\u{F3}i 'cho ph\u{E9}p t\u{1EF1} ch\u{1A1}i' ho\u{1EB7}c 't\u{1EAF}t quy\u{1EC1}n \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t'.", state("Ui"), state("Body"), state("Free"), state("Key")),
                    string.format("Current permissions: edit the interface %s, control the character %s, free play %s, key trigger %s. To change one, say 'allow free play' or 'turn off the permission to control the character'.", state("Ui"), state("Body"), state("Free"), state("Key")),
                    "happy", 6)
                return true
            end
            return false
        end
        local name = free and "Free" or (key and "Key" or (body and "Body" or "Ui"))
        if name == "Free" and on and not off and not about then
            ctx.Env.clearPending()
            if ctx.Env.body().Free and ctx.Env.perm("Free") then
                intent(ctx, "body.free.already")
                answer(ctx, "M\u{EC}nh \u{111}ang t\u{1EF1} ch\u{1A1}i r\u{1ED3}i n\u{E8}! N\u{F3}i 'd\u{1EEB}ng' ho\u{1EB7}c b\u{1EA5}m ph\u{ED}m di chuy\u{1EC3}n l\u{E0} m\u{EC}nh nh\u{1B0}\u{1EDD}ng l\u{1EA1}i nh\u{E9}.", "I'm already playing on my own! Say 'stop' or press a movement key to take over.", "happy", 5)
                return true
            end
            intent(ctx, "body.free")
            ctx.Assume = ctx.Assume or {}
            ctx.Assume.Free = true
            ctx.Assume.Body = true
            for _, perm in ipairs({ "Free", "Body" }) do
                if not ctx.Env.perm(perm) then
                    step(ctx, "perm", { Name = perm, Value = true, Cmd = "Grant-Permission", Args = perm, Say = { "b\u{1EAD}t quy\u{1EC1}n " .. PERM_VI[perm], "enabled permission to " .. PERM_EN[perm] } })
                end
            end
            step(ctx, "body", { Do = "free", On = true, Cmd = "Start-Autoplay", Args = "-Mode Explore", Say = { "b\u{1EAF}t \u{111}\u{1EA7}u t\u{1EF1} ch\u{1A1}i t\u{1EF1} do", "started exploring on my own" }, Perm = "Free" })
            ctx.Mood = "joy"
            return true
        end
        intent(ctx, "perm." .. name)
        step(ctx, "perm", {
            Name = name,
            Value = on and not off,
            Cmd = on and not off and "Grant-Permission" or "Revoke-Permission",
            Args = name,
            Say = {
                (on and not off and "b\u{1EAD}t" or "t\u{1EAF}t") .. " quy\u{1EC1}n " .. PERM_VI[name],
                (on and not off and "enabled" or "disabled") .. " permission to " .. PERM_EN[name],
            },
        })
        if name == "Free" and on and not off then
            ctx.Assume = ctx.Assume or {}
            ctx.Assume.Body = true
            step(ctx, "perm", { Name = "Body", Value = true, Cmd = "Grant-Permission", Args = "Body", Say = { "b\u{1EAD}t quy\u{1EC1}n \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t", "enabled permission to control the character" } })
        end
        if on and not off then
            ctx.Mood = "happy"
        end
        return true
    end

    local function needPerm(ctx, name, replay)
        if ctx.Env.perm(name) or (ctx.Assume and ctx.Assume[name]) then
            return true
        end
        ctx.Denied = ctx.Denied or {}
        ctx.Denied[name] = true
        if not ctx.PendingSet then
            ctx.PendingSet = { Kind = "grant", Perm = name, Replay = replay or ctx.A.Raw }
        end
        return false
    end

    function I.free(ctx, c)
        if not has(c, "bfree") then
            return false
        end
        if has(c, "howto") then
            return false
        end
        find(c, "bfree", true)
        local state = ctx.Env.body()
        local pending = ctx.Env.pending()
        if has(c, "bstop") or has(c, "off") or negated(c) then
            intent(ctx, "body.free.stop")
            if state.Free or state.Active then
                step(ctx, "body", { Do = "stop", Cmd = "Stop-Autoplay", Args = "", Say = { "ng\u{1EEB}ng t\u{1EF1} ch\u{1A1}i", "stopped playing on my own" }, Perm = "Body" })
            else
                answer(ctx, "M\u{EC}nh \u{111}ang kh\u{F4}ng t\u{1EF1} ch\u{1A1}i m\u{E0}. Mu\u{1ED1}n th\u{EC} n\u{F3}i 't\u{1EF1} ch\u{1A1}i \u{111}i' nh\u{E9}!", "I'm not playing on my own right now. Say 'play by yourself' if you want me to!", "wink", 4)
            end
            return true
        end
        local pendingFree = pending and pending.Kind == "grant" and (pending.Perm == "Free" or pending.Perm == "Body")
        local consent = ctx.NoAsk or has(c, "grantw") or (pendingFree and has(c, "yes"))
        if ctx.NoAsk then
            ctx.NoAskUsed = true
        end
        if state.Free and ctx.Env.perm("Free") then
            intent(ctx, "body.free.already")
            answer(ctx, "M\u{EC}nh \u{111}ang t\u{1EF1} ch\u{1A1}i r\u{1ED3}i n\u{E8}! N\u{F3}i 'd\u{1EEB}ng' ho\u{1EB7}c b\u{1EA5}m ph\u{ED}m di chuy\u{1EC3}n l\u{E0} m\u{EC}nh nh\u{1B0}\u{1EDD}ng l\u{1EA1}i nh\u{E9}.", "I'm already playing on my own! Say 'stop' or press a movement key to take over.", "happy", 5)
            return true
        end
        intent(ctx, "body.free")
        if consent then
            if pendingFree then
                ctx.Env.clearPending()
            end
            ctx.Assume = ctx.Assume or {}
            ctx.Assume.Free = true
            ctx.Assume.Body = true
            for _, perm in ipairs({ "Free", "Body" }) do
                if not ctx.Env.perm(perm) then
                    step(ctx, "perm", { Name = perm, Value = true, Cmd = "Grant-Permission", Args = perm, Say = { "b\u{1EAD}t quy\u{1EC1}n " .. PERM_VI[perm], "enabled permission to " .. PERM_EN[perm] } })
                end
            end
        elseif not needPerm(ctx, "Free") then
            return true
        end
        step(ctx, "body", { Do = "free", On = true, Cmd = "Start-Autoplay", Args = "-Mode Explore", Say = { "b\u{1EAF}t \u{111}\u{1EA7}u t\u{1EF1} ch\u{1A1}i t\u{1EF1} do", "started exploring on my own" }, Perm = "Free" })
        ctx.Mood = "joy"
        return true
    end

    local DIR_WORDS = { fwd = "b_fwd", back = "b_back", left = "b_left", right = "b_right" }
    local DIR_VI = { fwd = "t\u{1EDB}i", back = "l\u{F9}i", left = "sang tr\u{E1}i", right = "sang ph\u{1EA3}i" }
    local DIR_EN = { fwd = "forward", back = "backward", left = "left", right = "right" }

    local function direction(c)
        for _, name in ipairs({ "back", "left", "right", "fwd" }) do
            if has(c, DIR_WORDS[name]) then
                return name
            end
        end
        local tokens = c.tokens
        for index, token in ipairs(tokens) do
            local before = tokens[index - 1]
            if before == "bam" or before == "nhan" or before == "press" or before == "hold" or before == "giu" or before == "key" or before == "phim" then
                if token == "w" then
                    return "fwd"
                elseif token == "s" then
                    return "back"
                elseif token == "a" then
                    return "left"
                elseif token == "d" then
                    return "right"
                end
            end
        end
        return nil
    end

    local function duration(c, default)
        local value, unit = N.number(c)
        if not value then
            return default
        end
        if unit == "min" then
            value = value * 60
        elseif unit == "steps" then
            value = value * 0.5
        elseif unit == "times" then
            return default
        end
        return clamp(value, 0.3, 30)
    end

    function I.body(ctx, c)
        local move = has(c, "bmove")
        local jump = has(c, "bjump")
        local spin = has(c, "bspin")
        local circle = has(c, "bcircle")
        local stop = has(c, "bstop")
        local dir = direction(c)
        local char = has(c, "bchar")
        local bodyState = ctx.Env.body()
        if has(c, "howto") or has(c, "timer") or has(c, "watch") or has(c, "mnoun") or has(c, "tabnoun") or has(c, "speedw") or has(c, "theme") then
            return false
        end
        if jump and (has(c, "ijump") or (has(c, "jumpw") and valueCue(c))) then
            return false
        end
        if stop and not move and not jump and not spin and not circle then
            if bodyState.Active or char or dir then
                intent(ctx, "body.stop")
                step(ctx, "body", { Do = "stop", Cmd = "Stop-Character", Args = "", Say = { "d\u{1EEB}ng nh\u{E2}n v\u{1EAD}t l\u{1EA1}i", "stopped the character" }, Perm = "Body" })
                return true
            end
            local playing = ctx.Env.music().Playing
            if playing and not has(c, "bchar") then
                intent(ctx, "music.pause")
                step(ctx, "music", { Do = "pause", Cmd = "Stop-Music", Args = "", Say = { "t\u{1EA1}m d\u{1EEB}ng nh\u{1EA1}c", "paused the music" } })
                ctx.Mood = "sleepy"
                ctx.Hold = 3
                return true
            end
            intent(ctx, "body.idle")
            answer(ctx, "M\u{EC}nh \u{111}ang \u{111}\u{1EE9}ng y\u{EA}n m\u{E0}, ch\u{1B0}a c\u{F3} g\u{EC} \u{111}\u{1EC3} d\u{1EEB}ng c\u{1EA3}.", "I'm already standing still, nothing to stop.", "wink", 3)
            return true
        end
        if circle then
            intent(ctx, "body.circle")
            if not needPerm(ctx, "Body") then
                return true
            end
            local seconds = duration(c, 6)
            step(ctx, "body", { Do = "circle", Seconds = seconds, Cmd = "Move-Character", Args = string.format("-Pattern Circle -Seconds %s", fmtNumber(seconds)), Say = { "ch\u{1EA1}y v\u{F2}ng tr\u{F2}n " .. fmtNumber(seconds) .. " gi\u{E2}y", "ran in a circle for " .. fmtNumber(seconds) .. "s" }, Perm = "Body" })
            return true
        end
        if spin then
            intent(ctx, "body.spin")
            if not needPerm(ctx, "Body") then
                return true
            end
            local sign = has(c, "b_left") and -1 or 1
            local value, unit = N.number(c)
            local angle = (value and not unit and value >= 10 and value <= 1440) and value or 360
            step(ctx, "body", { Do = "spin", Angle = angle * sign, Cmd = "Rotate-Character", Args = string.format("-Degrees %d", angle * sign), Say = { "xoay nh\u{E2}n v\u{1EAD}t " .. fmtNumber(angle) .. "\u{B0}", "spun the character " .. fmtNumber(angle) .. "\u{B0}" }, Perm = "Body" })
            return true
        end
        if jump and not (has(c, "jumpw") and not (has(c, "bjump"))) then
            intent(ctx, "body.jump")
            if not needPerm(ctx, "Body") then
                return true
            end
            local value, unit = N.number(c)
            local count = (value and (unit == "times" or unit == nil)) and clamp(math.floor(value), 1, 12) or 1
            step(ctx, "body", { Do = "jump", Count = count, Cmd = "Invoke-Jump", Args = string.format("-Count %d", count), Say = { "nh\u{1EA3}y " .. count .. " l\u{1EA7}n", "jumped " .. count .. (count == 1 and " time" or " times") }, Perm = "Body" })
            ctx.Mood = ctx.Mood or "joy"
            return true
        end
        if (move and (dir or char or bodyState.Active)) or (dir and #c.tokens <= 3) then
            intent(ctx, "body.move." .. (dir or "fwd"))
            if not needPerm(ctx, "Body") then
                return true
            end
            dir = dir or "fwd"
            local seconds = duration(c, 1.6)
            step(ctx, "body", { Do = "move", Dir = dir, Seconds = seconds, Cmd = "Move-Character", Args = string.format("-Direction %s -Seconds %s", dir, fmtNumber(seconds)), Say = { "\u{111}i " .. DIR_VI[dir] .. " " .. fmtNumber(seconds) .. " gi\u{E2}y", "walked " .. DIR_EN[dir] .. " for " .. fmtNumber(seconds) .. "s" }, Perm = "Body" })
            return true
        end
        if has(c, "chay|walk|run|go|move|nhich|di chuyen|sprint|di bo|chay bo") and not dir and #c.tokens <= 3 and not valueCue(c) and not has(c, "mnoun|timer|watch|theme|ui") then
            intent(ctx, "body.move.fwd")
            if not needPerm(ctx, "Body") then
                return true
            end
            step(ctx, "body", { Do = "move", Dir = "fwd", Seconds = 1.6, Cmd = "Move-Character", Args = "-Direction fwd -Seconds 1.6", Say = { "\u{111}i t\u{1EDB}i 1.6 gi\u{E2}y", "walked forward for 1.6s" }, Perm = "Body" })
            return true
        end
        return false
    end

    function I.timer(ctx, c)
        if has(c, "howto") then
            return false
        end
        if has(c, "watch") then
            local state = ctx.Env.watch()
            if has(c, "lap") and state.Active then
                intent(ctx, "watch.lap")
                step(ctx, "watch", { Do = "lap", Cmd = "Mark-Lap", Args = "", Say = { "\u{111}\u{E1}nh d\u{1EA5}u m\u{1ED9}t v\u{F2}ng", "marked a lap" } })
            elseif has(c, "reset") then
                intent(ctx, "watch.reset")
                step(ctx, "watch", { Do = "reset", Cmd = "Reset-Stopwatch", Args = "", Say = { "\u{111}\u{1EB7}t l\u{1EA1}i b\u{1EA5}m gi\u{1EDD}", "reset the stopwatch" } })
            else
                intent(ctx, "watch.toggle")
                local wantStop = has(c, "off") or has(c, "mpause") or negated(c)
                if wantStop and not state.Running then
                    answer(ctx, "B\u{1EA5}m gi\u{1EDD} \u{111}ang d\u{1EEB}ng s\u{1EB5}n r\u{1ED3}i.", "The stopwatch is already stopped.", "neutral")
                    return true
                end
                step(ctx, "watch", { Do = "toggle", Cmd = "Start-Stopwatch", Args = state.Running and "-Pause" or "", Say = { state.Running and "t\u{1EA1}m d\u{1EEB}ng b\u{1EA5}m gi\u{1EDD}" or "b\u{1EA5}m gi\u{1EDD} tr\u{EA}n \u{111}\u{1EA3}o", state.Running and "paused the stopwatch" or "started the stopwatch" } })
            end
            return true
        end
        if not has(c, "timer") then
            return false
        end
        local value, unit = N.number(c)
        if has(c, "off") or has(c, "no") or has(c, "undo") or has(c, "reset") or has(c, "bstop") then
            intent(ctx, "timer.stop")
            if not ctx.Env.timer() then
                answer(ctx, "Hi\u{1EC7}n kh\u{F4}ng c\u{F3} h\u{1EB9}n gi\u{1EDD} n\u{E0}o \u{111}ang ch\u{1EA1}y.", "There's no timer running right now.", "neutral")
                return true
            end
            step(ctx, "timer", { Do = "stop", Cmd = "Stop-Timer", Args = "", Say = { "d\u{1EEB}ng h\u{1EB9}n gi\u{1EDD}", "stopped the timer" } })
            return true
        end
        if value and ctx.Env.timer() and has(c, "up|them|add|extend|more|nua") then
            intent(ctx, "timer.extend")
            local seconds = unit == "min" and value * 60 or (unit == "hour" and value * 3600 or value)
            step(ctx, "timer", { Do = "extend", Seconds = seconds, Cmd = "Add-TimerTime", Args = string.format("-Seconds %d", seconds), Say = { "th\u{EA}m " .. fmtNumber(seconds) .. " gi\u{E2}y cho h\u{1EB9}n gi\u{1EDD}", "added " .. fmtNumber(seconds) .. "s to the timer" } })
            return true
        end
        if not value then
            intent(ctx, "timer.ask")
            answer(ctx, "H\u{1EB9}n gi\u{1EDD} bao l\u{E2}u? V\u{ED} d\u{1EE5}: 'h\u{1EB9}n gi\u{1EDD} 2 ph\u{FA}t' ho\u{1EB7}c 'h\u{1EB9}n gi\u{1EDD} 45 gi\u{E2}y'.", "How long should the timer be? For example: 'timer 2 minutes' or 'timer 45 seconds'.", "think", 4)
            return true
        end
        local seconds = value
        if unit == "min" then
            seconds = value * 60
        elseif unit == "hour" then
            seconds = value * 3600
        end
        seconds = clamp(math.floor(seconds + 0.5), 1, 3600 * 3)
        intent(ctx, "timer.start")
        local label
        if seconds >= 60 and seconds % 60 == 0 then
            label = T(ctx, string.format("%d ph\u{FA}t", seconds / 60), string.format("%d min", seconds / 60))
        else
            label = T(ctx, string.format("%d gi\u{E2}y", seconds), string.format("%ds", seconds))
        end
        step(ctx, "timer", { Do = "start", Seconds = seconds, Cmd = "Start-Timer", Args = string.format("-Seconds %d", seconds), Say = { "h\u{1EB9}n gi\u{1EDD} " .. (ctx.Lang == "vi" and label or string.format("%d gi\u{E2}y", seconds)), "set a " .. label .. " timer" } })
        return true
    end

    local function trackByName(ctx, c)
        local music = ctx.Env.music()
        local best, bestScore = nil, 0
        for index, name in ipairs(music.Names) do
            local folded = N.fold(name)
            local score = 0
            for word in string.gmatch(folded, "%a%a%a+") do
                for _, token in ipairs(c.tokens) do
                    if #token >= 3 and N.close(token, word) then
                        score = score + #word
                    end
                end
            end
            if score > bestScore then
                best, bestScore = index, score
            end
        end
        if bestScore >= 4 then
            return best
        end
        return nil
    end

    function I.music(ctx, c)
        if has(c, "howto") or has(c, "tabnoun") then
            return false
        end
        local music = ctx.Env.music()
        local noun = has(c, "mnoun")
        if has(c, "mquery") and not has(c, "mnext") then
            intent(ctx, "music.query")
            if music.Count == 0 then
                answer(ctx, "Ch\u{1B0}a c\u{F3} b\u{E0}i n\u{E0}o trong danh s\u{E1}ch.", "There are no tracks in the playlist yet.", "neutral")
            elseif music.Playing then
                answer(ctx, "\u{110}ang ph\u{E1}t: " .. music.Name .. ".", "Now playing: " .. music.Name .. ".", "happy", 5)
            else
                answer(ctx, "Nh\u{1EA1}c \u{111}ang t\u{1EA1}m d\u{1EEB}ng, b\u{E0}i hi\u{1EC7}n t\u{1EA1}i l\u{E0} " .. music.Name .. ". N\u{F3}i 'b\u{1EAD}t nh\u{1EA1}c' \u{111}\u{1EC3} ph\u{E1}t nh\u{E9}.", "Music is paused; the current track is " .. music.Name .. ". Say 'play music' to start.", "neutral", 4)
            end
            return true
        end
        local explicit = exact(c, "play|pause|resume|next|skip|prev|previous|stop")
        local number, unit = N.number(c)
        local byNumber = number and (unit == "track" or exact(c, "bai so|so|track|number|bai thu")) and number or nil
        local byName = noun and trackByName(ctx, c) or nil
        if not noun and not (explicit and (music.Playing or has(c, "mplay"))) and not byNumber then
            return false
        end
        if has(c, "mshuffle|mrepeat|mspatial|mbass|mtempo|musicisl|autonext") or (has(c, "mvol") and (valueCue(c) or has(c, "mute"))) then
            return false
        end
        if byNumber or byName then
            local index = byNumber and clamp(math.floor(byNumber), 1, math.max(music.Count, 1)) or byName
            intent(ctx, "music.select")
            step(ctx, "music", { Do = "select", Index = index, Cmd = "Play-Track", Args = string.format("-Index %d", index), Say = { "ph\u{E1}t b\u{E0}i s\u{1ED1} " .. index .. " (" .. (music.Names[index] or "?") .. ")", "played track " .. index .. " (" .. (music.Names[index] or "?") .. ")" } })
            ctx.Mood = "joy"
            return true
        end
        local prev = has(c, "mprev")
        local nextHit = has(c, "mnext")
        if prev and not nextHit then
            intent(ctx, "music.prev")
            step(ctx, "music", { Do = "prev", Cmd = "Skip-Track", Args = "-Direction Previous", Say = { "quay l\u{1EA1}i b\u{E0}i tr\u{1B0}\u{1EDB}c", "went back to the previous track" } })
            ctx.Mood = "joy"
            return true
        end
        if nextHit then
            intent(ctx, "music.next")
            step(ctx, "music", { Do = "next", Cmd = "Skip-Track", Args = "-Direction Next", Say = { "chuy\u{1EC3}n b\u{E0}i ti\u{1EBF}p theo", "skipped to the next track" } })
            ctx.Mood = "joy"
            return true
        end
        local pauseHit = has(c, "mpause") or has(c, "off") or negated(c)
        local playHit = has(c, "mplay") or has(c, "on")
        if pauseHit and not (playHit and not (has(c, "off") or has(c, "mpause"))) then
            intent(ctx, "music.pause")
            if not music.Playing then
                answer(ctx, "Nh\u{1EA1}c \u{111}ang t\u{1EAF}t s\u{1EB5}n r\u{1ED3}i.", "The music is already paused.", "neutral")
                return true
            end
            step(ctx, "music", { Do = "pause", Cmd = "Stop-Music", Args = "", Say = { "t\u{1EA1}m d\u{1EEB}ng nh\u{1EA1}c", "paused the music" } })
            ctx.Mood = "sleepy"
            ctx.Hold = 3
            return true
        end
        intent(ctx, "music.play")
        if music.Playing then
            answer(ctx, "Nh\u{1EA1}c \u{111}ang ph\u{E1}t r\u{1ED3}i: " .. music.Name .. ".", "Music is already playing: " .. music.Name .. ".", "happy", 3)
            return true
        end
        step(ctx, "music", { Do = "play", Cmd = "Start-Music", Args = "", Say = { "b\u{1EAD}t nh\u{1EA1}c", "started the music" } })
        ctx.Mood = "joy"
        ctx.Hold = 6
        return true
    end

    local function resolveTarget(c)
        local best, bestScore
        for _, target in ipairs(TARGETS) do
            local found, score = find(c, target[2])
            if found and (not bestScore or score > bestScore) then
                best, bestScore = target[1], score
            end
        end
        return best, bestScore
    end

    function I.setting(ctx, c, forced)
        if has(c, "howto") then
            return false
        end
        local key = forced or resolveTarget(c)
        if not key and has(c, "island|dynamic island|notch|pill|hon dao|thanh dao|cai dao") and (accentFromNames(c) or has(c, "i_black") or has(c, "i_follow")) then
            key = "islandColor"
        end
        if not key then
            return false
        end
        ctx.Key = key
        if has(c, "random") and (has(c, "theme") or has(c, "ui") or has(c, "accent")) then
            return false
        end
        if key == "clock" and (has(c, "ui") or has(c, "theme")) then
            return false
        end
        local spec = CTL[key]
        local current = currentValue(ctx, key)
        local name = T(ctx, spec.Vi, spec.En)
        if key == "musicVolume" and has(c, "soundw") and has(c, "giao dien|interface|ui") then
            key, spec = "volume", CTL.volume
            current = currentValue(ctx, key)
            name = T(ctx, spec.Vi, spec.En)
        end
        if key == "islandColor" then
            local index
            if has(c, "i_follow") then
                index = 1
            else
                local accent = accentFromNames(c)
                if accent then
                    index = accent + 2
                elseif has(c, "i_black") then
                    index = 2
                end
            end
            if not index then
                intent(ctx, "setting.query.islandColor")
                answer(ctx,
                    string.format("M\u{E0}u \u{111}\u{1EA3}o hi\u{1EC7}n l\u{E0} %s. N\u{F3}i '\u{111}\u{1ED5}i m\u{E0}u \u{111}\u{1EA3}o sang t\u{ED}m' (\u{110}en, Xanh d\u{1B0}\u{1A1}ng, T\u{ED}m, H\u{1ED3}ng, Cam, Xanh l\u{E1}, Ng\u{1ECD}c) ho\u{1EB7}c 'm\u{E0}u \u{111}\u{1EA3}o theo giao di\u{1EC7}n'.", describeValue(ctx, key, current)),
                    string.format("The island color is %s. Say 'make the island purple' (Black, Blue, Purple, Pink, Orange, Green, Teal) or 'island color follow the UI'.", describeValue(ctx, key, current)),
                    "neutral", 5)
                return true
            end
            intent(ctx, "setting.set.islandColor")
            if current == index then
                answer(ctx, "M\u{E0}u \u{111}\u{1EA3}o \u{111}\u{E3} l\u{E0} " .. ISLAND_VI[index] .. " r\u{1ED3}i.", "The island is already " .. ISLAND_EN[index] .. ".", "wink", 3)
                return true
            end
            setCtl(ctx, key, index, "\u{111}\u{1ED5}i m\u{E0}u \u{111}\u{1EA3}o sang " .. ISLAND_VI[index], "set the island color to " .. ISLAND_EN[index], ISLAND_EN[index])
            ctx.Mood = "wink"
            ctx.Hold = 5
            return true
        end
        if key == "scale" or key == "language" then
            local index
            if key == "scale" then
                for i, id in ipairs({ "s_small", "s_medium", "s_large" }) do
                    if has(c, id) then
                        index = i
                    end
                end
                if not index and has(c, "up") then
                    index = math.min((current or 2) + 1, 3)
                elseif not index and has(c, "down") then
                    index = math.max((current or 2) - 1, 1)
                end
            else
                if has(c, "l_en") then
                    index = 2
                elseif has(c, "l_vi") then
                    index = 1
                end
            end
            if not index then
                intent(ctx, "setting.query." .. key)
                answer(ctx, string.format("%s hi\u{1EC7}n l\u{E0} %s.", spec.Vi, describeValue(ctx, key, current)), string.format("The %s is currently %s.", spec.En, describeValue(ctx, key, current)), "neutral", 3)
                return true
            end
            intent(ctx, "setting.set." .. key)
            setCtl(ctx, key, index, string.format("\u{111}\u{1ED5}i %s sang %s", spec.Vi, (key == "scale" and SCALE_VI[index]) or (index == 2 and "English" or "Ti\u{1EBF}ng Vi\u{1EC7}t")), string.format("set the %s to %s", spec.En, (key == "scale" and SCALE_EN[index]) or (index == 2 and "English" or "Vietnamese")), (key == "scale" and SCALE_EN[index]) or (index == 2 and "en" or "vi"))
            ctx.Steps[#ctx.Steps].Value = index
            return true
        end
        if spec.Kind == "toggle" then
            local wantOff = has(c, "off") or has(c, "mute")
            local wantOn = has(c, "on")
            local flip = has(c, "set") and not wantOn and not wantOff
            local value
            if wantOff and wantOn then
                value = not exact(c, "tat|disable|off|turn off|dong|an|stop|hide|close") and true or false
            elseif wantOff then
                value = false
            elseif wantOn then
                value = true
            elseif flip then
                value = not current
            end
            if value ~= nil and negated(c) and wantOn and not wantOff then
                value = false
            end
            if spec.Invert and value ~= nil and not flip then
                value = not value
            end
            if value == nil then
                intent(ctx, "setting.query." .. key)
                answer(ctx, string.format("%s %s. N\u{F3}i 'b\u{1EAD}t' ho\u{1EB7}c 't\u{1EAF}t' n\u{1EBF}u mu\u{1ED1}n \u{111}\u{1ED5}i.", spec.Vi, describeValue(ctx, key, current)), string.format("%s is %s. Say 'turn on' or 'turn off' to change it.", spec.En, describeValue(ctx, key, current)), "neutral", 3)
                return true
            end
            intent(ctx, "setting.toggle." .. key)
            if value == (current and true or false) then
                if spec.Invert then
                    answer(ctx, string.format("B\u{F3}ng \u{111}\u{1ED5} \u{111}\u{E3} %s s\u{1EB5}n r\u{1ED3}i.", value and "t\u{1EAF}t" or "b\u{1EAD}t"), string.format("Shadows are already %s.", value and "off" or "on"), "wink", 3)
                else
                    answer(ctx, string.format("%s %s s\u{1EB5}n r\u{1ED3}i.", spec.Vi, value and "\u{111}\u{E3} b\u{1EAD}t" or "\u{111}\u{E3} t\u{1EAF}t"), string.format("%s is already %s.", spec.En, value and "on" or "off"), "wink", 3)
                end
                return true
            end
            if spec.Invert then
                setCtl(ctx, key, value, string.format("%s %s", value and "t\u{1EAF}t" or "b\u{1EAD}t", spec.Name[1]), string.format("turned shadows %s", value and "off" or "on"), tostring(value))
            else
                setCtl(ctx, key, value, string.format("%s %s", value and "b\u{1EAD}t" or "t\u{1EAF}t", spec.Vi), string.format("turned %s %s", value and "on" or "off", spec.En), tostring(value))
            end
            return true
        end
        local target
        local value, unit = N.number(c)
        if key == "clock" and not value then
            for _, preset in ipairs(CLOCK_PRESETS) do
                if has(c, preset[1]) then
                    target = preset[2]
                    break
                end
            end
        end
        if not target and value then
            if key == "musicVolume" or key == "volume" or key == "windowOpacity" then
                target = value
            elseif key == "tempo" then
                target = value > 3 and value / 100 or value
            elseif key == "clock" then
                target = unit == "hour" and value or value
            else
                target = value
            end
        end
        if not target and (has(c, "mute") and (key == "musicVolume" or key == "volume")) then
            target = 0
        end
        if not target and has(c, "max") then
            target = spec.Max
        elseif not target and has(c, "min") then
            target = spec.Min
        end
        local faster = has(c, "chay nhanh|di nhanh|tang toc|run fast|run faster|nhanh len|faster")
        local slower = has(c, "chay cham|di cham|giam toc|run slower|slower|cham lai")
        if not target and (has(c, "up") or faster) and not (has(c, "down") and not faster) then
            target = (current or spec.Min) + spec.Delta
        elseif not target and (has(c, "down") or slower) then
            target = (current or spec.Min) - spec.Delta
        end
        if not target then
            intent(ctx, "setting.query." .. key)
            answer(ctx, string.format("%s hi\u{1EC7}n l\u{E0} %s. B\u{1EA1}n mu\u{1ED1}n \u{111}\u{1ED5}i th\u{E0}nh bao nhi\u{EA}u? (%s\u{2013}%s)", spec.Vi, describeValue(ctx, key, current), fmtNumber(spec.Min), fmtNumber(spec.Max)), string.format("The %s is %s right now. What should I set it to? (%s\u{2013}%s)", spec.En, describeValue(ctx, key, current), fmtNumber(spec.Min), fmtNumber(spec.Max)), "think", 4)
            return true
        end
        target = snap(spec, target)
        intent(ctx, "setting.set." .. key)
        if current ~= nil and math.abs(current - target) < 1e-6 then
            answer(ctx, string.format("%s \u{111}\u{E3} l\u{E0} %s r\u{1ED3}i.", spec.Vi, fmtNumber(target) .. (spec.Unit or "")), string.format("The %s is already %s.", spec.En, fmtNumber(target) .. (spec.Unit or "")), "wink", 3)
            return true
        end
        local atEdge = target == spec.Max or target == spec.Min
        setCtl(ctx, key, target, string.format("\u{111}\u{1EB7}t %s th\u{E0}nh %s%s", spec.Vi, fmtNumber(target) .. (spec.Unit or ""), atEdge and " (m\u{1EE9}c gi\u{1EDB}i h\u{1EA1}n)" or ""), string.format("set the %s to %s%s", spec.En, fmtNumber(target) .. (spec.Unit or ""), atEdge and " (the limit)" or ""), fmtNumber(target))
        return true
    end

    local function cycleIndex(ctx, list)
        local theme, accent = ctx.Env.get("theme"), ctx.Env.get("accent")
        for index, pair in ipairs(list) do
            if pair[1] == theme and pair[2] == accent then
                return list[index % #list + 1], true
            end
        end
        return list[1], false
    end

    local function applyLook(ctx, pair, sayVi, sayEn)
        setCtl(ctx, "theme", pair[1], "\u{111}\u{1ED5}i giao di\u{1EC7}n sang " .. THEME_VI[pair[1]], "switched the theme to " .. THEME_EN[pair[1]], THEME_EN[pair[1]])
        setCtl(ctx, "accent", pair[2], "\u{111}\u{1ED5}i m\u{E0}u nh\u{1EA5}n sang " .. ACCENT_VI[pair[2]], "set the accent to " .. ACCENT_EN[pair[2]], ACCENT_EN[pair[2]])
        ctx.LookPair = pair
    end

    function I.theme(ctx, c)
        if has(c, "howto") then
            return false
        end
        local ui = has(c, "ui") or has(c, "theme") or has(c, "win")
        local hot = has(c, "hot")
        local cold = has(c, "cold")
        local coolwant = has(c, "coolwant")
        local warmwant = has(c, "warmwant") or (ctx.Lang == "vi" and exact(c, "am"))
        local nudge = has(c, "please") or has(c, "set") or has(c, "on") or has(c, "up") or exact(c, "lam|make|doi|change|cho|giup")
        local again = has(c, "hon nua|more|again|nua|further|even")
        if hot or coolwant then
            if hot and not (ui or coolwant or nudge) then
                intent(ctx, "mood.hot.offer")
                ctx.PendingSet = { Kind = "cool" }
                ctx.Mood = "sweat"
                ctx.Hold = 8
                answer(ctx,
                    pick(ctx, { "N\u{F3}ng th\u{1EAD}t \u{111}\u{1EA5}y! M\u{EC}nh \u{111}\u{1ED5}i UI sang t\u{F4}ng m\u{E1}t (\u{110}\u{1EA1}i d\u{1B0}\u{1A1}ng + m\u{E0}u Ng\u{1ECD}c) cho d\u{1ECB}u m\u{1EAF}t nh\u{E9}? N\u{F3}i 'ok' \u{111}\u{1EC3} m\u{EC}nh l\u{E0}m.", "Tr\u{1EDD}i n\u{F3}ng v\u{1EAD}y h\u{1EA3}! Mu\u{1ED1}n m\u{EC}nh l\u{E0}m UI nh\u{EC}n m\u{E1}t h\u{1A1}n kh\u{F4}ng? N\u{F3}i 'ok' l\u{E0} m\u{EC}nh \u{111}\u{1ED5}i li\u{1EC1}n." }),
                    pick(ctx, { "Ugh, that's hot! Want me to switch the UI to a cool tone (Ocean + Teal)? Say 'ok' and I'll do it.", "Sounds sweltering! Shall I make the UI look cooler? Just say 'ok'." }),
                    "sweat", 8)
                return true
            end
            intent(ctx, "theme.cool")
            local pair, repeated = cycleIndex(ctx, COOL)
            if not repeated and not (again and ctx.Env.get("theme") == 4) then
                pair = COOL[1]
            end
            applyLook(ctx, pair)
            ctx.PreMood = hot and "sweat" or nil
            ctx.Mood = "cool"
            ctx.Hold = 9
            ctx.Style = "cool"
            return true
        end
        if cold or warmwant then
            if cold and not (ui or warmwant or nudge) then
                intent(ctx, "mood.cold.offer")
                ctx.PendingSet = { Kind = "warm" }
                ctx.Mood = "sad"
                ctx.Hold = 8
                answer(ctx, "L\u{1EA1}nh h\u{1EA3}? M\u{EC}nh \u{111}\u{1ED5}i UI sang t\u{F4}ng \u{1EA5}m (C\u{E0} ph\u{EA} + m\u{E0}u Cam) cho \u{1EA5}m \u{E1}p nh\u{E9}? N\u{F3}i 'ok' \u{111}\u{1EC3} m\u{EC}nh l\u{E0}m.", "Feeling cold? Want me to switch the UI to a warm tone (Coffee + Orange)? Say 'ok' and I'll do it.", "sad", 8)
                return true
            end
            intent(ctx, "theme.warm")
            local pair, repeated = cycleIndex(ctx, WARM)
            if not repeated then
                pair = WARM[1]
            end
            applyLook(ctx, pair)
            ctx.Mood = "happy"
            ctx.Hold = 8
            ctx.Style = "warm"
            return true
        end
        if has(c, "random") and (ui or has(c, "theme") or has(c, "accent") or exact(c, "doi|change|make")) then
            intent(ctx, "theme.random")
            local theme = ctx.Env.random(7)
            local accent = ctx.Env.random(6)
            applyLook(ctx, { theme, accent })
            ctx.Style = "random"
            ctx.Mood = "wink"
            ctx.Hold = 6
            return true
        end
        local index, strong = themeFromNames(c, false)
        local view = { tokens = c.tokens, used = {} }
        for key, value in pairs(c.used) do
            view.used[key] = value
        end
        if index then
            themeFromNames(view, true)
        end
        local accentIndex
        if has(view, "accent") or has(view, "c_pink|c_purple|c_orange|c_green|c_teal|c_blue|c_red") then
            accentIndex = accentFromNames(view)
        end
        local did = false
        if index and (strong or ui or nudge or has(c, "gotow")) and not (has(c, "mnoun") and not ui) then
            intent(ctx, "theme.set")
            setCtl(ctx, "theme", index, "\u{111}\u{1ED5}i giao di\u{1EC7}n sang " .. THEME_VI[index], "switched the theme to " .. THEME_EN[index], THEME_EN[index])
            did = true
        end
        if accentIndex and (has(c, "accent") or nudge or ui or not index) then
            intent(ctx, "theme.accent")
            setCtl(ctx, "accent", accentIndex, "\u{111}\u{1ED5}i m\u{E0}u nh\u{1EA5}n sang " .. ACCENT_VI[accentIndex], "set the accent to " .. ACCENT_EN[accentIndex], ACCENT_EN[accentIndex])
            did = true
        end
        if did then
            ctx.Mood = "wink"
            ctx.Hold = 5
            return true
        end
        if has(c, "darkwant") and (ui or nudge) then
            local light = has(c, "lightwant")
            intent(ctx, light and "theme.light" or "theme.dark")
            local target = light and 2 or 1
            setCtl(ctx, "theme", target, "\u{111}\u{1ED5}i giao di\u{1EC7}n sang " .. THEME_VI[target], "switched the theme to " .. THEME_EN[target], THEME_EN[target])
            return true
        end
        if has(c, "lightwant") and (ui or nudge) then
            intent(ctx, "theme.light")
            setCtl(ctx, "theme", 2, "\u{111}\u{1ED5}i giao di\u{1EC7}n sang " .. THEME_VI[2], "switched the theme to " .. THEME_EN[2], THEME_EN[2])
            return true
        end
        if has(c, "choi mat|nhuc mat|choi|too bright|so bright|hurts my eyes|glare|ch\u{F3}i m\u{1EAF}t") then
            intent(ctx, "theme.dark")
            setCtl(ctx, "theme", 3, "\u{111}\u{1ED5}i giao di\u{1EC7}n sang " .. THEME_VI[3] .. " cho \u{111}\u{1EE1} ch\u{F3}i", "switched to the " .. THEME_EN[3] .. " theme to cut the glare", THEME_EN[3])
            ctx.Mood = "happy"
            ctx.Hold = 5
            return true
        end
        return false
    end

    function I.window(ctx, c)
        if has(c, "howto") then
            return false
        end
        local win = has(c, "win")
        if not win then
            return false
        end
        local open = has(c, "open") and not has(c, "close")
        local close = has(c, "close") and not has(c, "open")
        if has(c, "close") and has(c, "open") then
            close = exact(c, "dong|an|tat|hide|close|giau|dong lai|an di|tat di|thu nho|minimize")
            open = not close
        end
        if not open and not close then
            return false
        end
        if open and (has(c, "mnoun") or has(c, "timer") or has(c, "watch")) then
            return false
        end
        local isOpen = ctx.Env.windowOpen()
        if open and isOpen then
            intent(ctx, "window.open")
            answer(ctx, "C\u{1EED}a s\u{1ED5} \u{111}ang m\u{1EDF} s\u{1EB5}n r\u{1ED3}i n\u{E8}.", "The window is already open.", "wink", 3)
            return true
        end
        if close and not isOpen then
            intent(ctx, "window.close")
            answer(ctx, "C\u{1EED}a s\u{1ED5} \u{111}ang \u{1EA9}n s\u{1EB5}n r\u{1ED3}i. M\u{EC}nh v\u{1EAB}n \u{1EDF} \u{111}\u{E2}y tr\u{EA}n Dynamic Island nha.", "The window is already hidden. I'm still here on Dynamic Island.", "wink", 3)
            return true
        end
        intent(ctx, open and "window.open" or "window.close")
        step(ctx, "window", { Open = open, Cmd = open and "Show-Window" or "Hide-Window", Args = "", Say = { open and "m\u{1EDF} c\u{1EED}a s\u{1ED5}" or "\u{1EA9}n c\u{1EED}a s\u{1ED5}", open and "opened the window" or "hid the window" }, Perm = "Ui" })
        return true
    end

    function I.tab(ctx, c)
        if has(c, "howto") then
            return false
        end
        local list = {
            { "Home", "tab_home" }, { "Music", "tab_music" }, { "AI", "tab_ai" }, { "Inbox", "tab_inbox" }, { "Tools", "tab_tools" },
            { "Settings", "tab_settings" }, { "Test", "tab_test" }, { "About", "tab_about" },
        }
        local best, bestScore
        for _, entry in ipairs(list) do
            local found, score = find(c, entry[2])
            if found and (not bestScore or score > bestScore) then
                best, bestScore = entry[1], score
            end
        end
        if not best then
            return false
        end
        local noun = has(c, "tabnoun")
        local go = has(c, "gotow")
        if not noun and not (go and best ~= "Music" and best ~= "AI" and best ~= "Home") then
            return false
        end
        if not noun and not go then
            return false
        end
        intent(ctx, "ui.tab." .. best)
        if not ctx.Env.windowOpen() then
            step(ctx, "window", { Open = true, Cmd = "Show-Window", Args = "", Say = { "m\u{1EDF} c\u{1EED}a s\u{1ED5}", "opened the window" }, Perm = "Ui" })
        end
        step(ctx, "tab", { Name = best, Cmd = "Select-Tab", Args = '"' .. best .. '"', Say = { "chuy\u{1EC3}n sang tab " .. TAB_VI[best], "switched to the " .. TAB_EN[best] .. " tab" }, Perm = "Ui" })
        return true
    end

    function I.movediag(ctx, c)
        if not has(c, "movediag") then
            return false
        end
        find(c, "movediag", true)
        intent(ctx, "body.probe")
        if not needPerm(ctx, "Body") then
            return true
        end
        step(ctx, "body", { Do = "probe", Cmd = "Test-Movement", Args = "-Drivers 4", Say = { "b\u{1EAF}t \u{111}\u{1EA7}u th\u{1EED} t\u{1EEB}ng c\u{E1}ch \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t, k\u{1EBF}t qu\u{1EA3} hi\u{1EC7}n trong PowerShell v\u{E0} c\u{E1}ch n\u{E0}o ch\u{1EA1}y \u{111}\u{1B0}\u{1EE3}c m\u{EC}nh d\u{F9}ng lu\u{F4}n", "started testing each way to drive your character, the results show in PowerShell and I'll keep whichever works" }, Perm = "Body" })
        ctx.Mood = "think"
        return true
    end

    function I.status(ctx, c)
        if has(c, "timeq") then
            intent(ctx, "status.time")
            local stamp = ctx.Env.time()
            answer(ctx, "B\u{E2}y gi\u{1EDD} l\u{E0} " .. stamp .. ".", "It's " .. stamp .. " right now.", "happy", 3)
            return true
        end
        if has(c, "w_fps") and not has(c, "on") and not has(c, "off") then
            intent(ctx, "status.fps")
            local fps = ctx.Env.fps()
            answer(ctx, string.format("FPS hi\u{1EC7}n t\u{1EA1}i kho\u{1EA3}ng %d. %s", fps, fps >= 55 and "M\u{1B0}\u{1EE3}t nh\u{1B0} b\u{1A1}!" or (fps >= 30 and "C\u{169}ng \u{1ED5}n." or "H\u{1A1}i gi\u{1EAD}t; th\u{1EED} 't\u{1EAF}t b\u{F3}ng \u{111}\u{1ED5}' xem.")), string.format("Current FPS is about %d. %s", fps, fps >= 55 and "Smooth!" or (fps >= 30 and "Decent." or "A bit laggy; try 'shadows off'.")), fps >= 30 and "happy" or "sweat", 4)
            return true
        end
        if has(c, "w_ping") and not has(c, "on") and not has(c, "off") then
            intent(ctx, "status.ping")
            local ping = ctx.Env.ping()
            answer(ctx, string.format("Ping hi\u{1EC7}n kho\u{1EA3}ng %d ms.", ping), string.format("Ping is about %d ms right now.", ping), ping < 120 and "happy" or "sweat", 4)
            return true
        end
        if has(c, "whichtheme") or (has(c, "theme") and has(c, "dang dung|current|hien tai|nao|gi|which|what")) then
            intent(ctx, "status.theme")
            local theme, accent = ctx.Env.get("theme") or 1, ctx.Env.get("accent") or 1
            answer(ctx, string.format("\u{110}ang d\u{F9}ng giao di\u{1EC7}n %s v\u{1EDB}i m\u{E0}u nh\u{1EA5}n %s.", THEME_VI[theme], ACCENT_VI[accent]), string.format("You're on the %s theme with the %s accent.", THEME_EN[theme], ACCENT_EN[accent]), "happy", 4)
            return true
        end
        return false
    end

    local function memoryOff(ctx)
        return ctx.Env.remember ~= nil and not ctx.Env.remember()
    end

    function I.recall(ctx, c)
        local list = ctx.Hist or {}
        if has(c, "recforget") then
            intent(ctx, "memory.forget")
            step(ctx, "memory", { Do = "clear", Cmd = "Clear-Memory", Args = "", Say = { "xo\u{E1} tr\u{ED} nh\u{1EDB} cu\u{1ED9}c tr\u{F2} chuy\u{1EC7}n", "cleared the conversation memory" } })
            ctx.Forget = true
            ctx.Mood = "wink"
            return true
        end
        local you = has(c, "youw")
        if (has(c, "pastsay") or has(c, "pastdo") or has(c, "saywhat") or has(c, "recsum")) and memoryOff(ctx) then
            intent(ctx, "memory.off")
            answer(ctx, "M\u{EC}nh \u{111}ang t\u{1EAF}t ch\u{1EBF} \u{111}\u{1ED9} nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat n\u{EA}n kh\u{F4}ng xem l\u{1EA1}i \u{111}\u{1B0}\u{1EE3}c. N\u{F3}i 'b\u{1EAD}t nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat' \u{111}\u{1EC3} m\u{EC}nh nh\u{1EDB} l\u{1EA1}i nh\u{E9}.", "Chat history memory is switched off, so I can't look back. Say 'remember our chat' to turn it back on.", "think", 6)
            return true
        end
        if has(c, "pastsay") and not you then
            intent(ctx, "memory.user")
            local turn = list[#list]
            if not turn then
                answer(ctx, "M\u{EC}nh ch\u{1B0}a th\u{1EA5}y tin nh\u{1EAF}n n\u{E0}o tr\u{1B0}\u{1EDB}c \u{111}\u{F3} c\u{1EA3}.", "I haven't seen any earlier message yet.", "think", 4)
            else
                answer(ctx, string.format("L\u{FA}c n\u{E3}y b\u{1EA1}n n\u{F3}i: \"%s\".", snip(turn.Text, 120)), string.format("You said: \"%s\".", snip(turn.Text, 120)), "happy", 7)
            end
            return true
        end
        if has(c, "pastdo") then
            intent(ctx, "memory.did")
            local turn = lastWhere(ctx, function(item)
                return item.Did ~= nil and item.Did[1] ~= ""
            end, 8)
            if turn then
                answer(ctx, "M\u{EC}nh v\u{1EEB}a " .. turn.Did[1] .. ".", "I just " .. turn.Did[2] .. ".", "happy", 7)
            elseif list[#list] then
                answer(ctx, "L\u{FA}c n\u{E3}y m\u{EC}nh ch\u{1EC9} tr\u{1EA3} l\u{1EDD}i b\u{1EA1}n th\u{F4}i: \"" .. snip(list[#list].Said, 110) .. "\"", "Earlier I only replied to you: \"" .. snip(list[#list].Said, 110) .. "\"", "happy", 7)
            else
                answer(ctx, "M\u{EC}nh ch\u{1B0}a l\u{E0}m g\u{EC} c\u{1EA3}, m\u{1EDB}i b\u{1EAF}t \u{111}\u{1EA7}u th\u{F4}i!", "I haven't done anything yet, we just started!", "wink", 4)
            end
            return true
        end
        if has(c, "saywhat") or (has(c, "pastsay") and you) or (#c.tokens <= 3 and has(c, "ha|huh|gi co|sao co")) then
            intent(ctx, "memory.repeat")
            local turn = lastWhere(ctx, function(item)
                return item.Said ~= nil and item.Said ~= ""
            end, 6)
            if turn then
                answer(ctx, "M\u{EC}nh n\u{F3}i l\u{E0}: " .. snip(turn.Said, 220), "I said: " .. snip(turn.Said, 220), "happy", 8)
            else
                answer(ctx, "M\u{EC}nh ch\u{1B0}a n\u{F3}i g\u{EC} tr\u{1B0}\u{1EDB}c \u{111}\u{F3} c\u{1EA3}.", "I haven't said anything before this.", "think", 4)
            end
            return true
        end
        if has(c, "recsum") then
            intent(ctx, "memory.summary")
            if #list == 0 then
                answer(ctx, "M\u{EC}nh ch\u{1B0}a c\u{F3} g\u{EC} \u{111}\u{1EC3} nh\u{1EDB}, m\u{EC}nh m\u{1EDB}i b\u{1EAF}t \u{111}\u{1EA7}u n\u{F3}i chuy\u{1EC7}n v\u{1EDB}i b\u{1EA1}n th\u{F4}i.", "I have nothing to recall yet, we've only just started talking.", "wink", 5)
                return true
            end
            local lines = {}
            for index = math.max(1, #list - 4), #list do
                local turn = list[index]
                local note = turn.Did and turn.Did[1] ~= "" and ((ctx.Lang == "vi" and "m\u{EC}nh " or "I ") .. (ctx.Lang == "vi" and turn.Did[1] or turn.Did[2])) or ((ctx.Lang == "vi" and "m\u{EC}nh tr\u{1EA3} l\u{1EDD}i: " or "I replied: ") .. snip(turn.Said, 48))
                lines[#lines + 1] = "\u{2022} \"" .. snip(turn.Text, 40) .. "\" \u{2192} " .. note
            end
            answer(ctx, "M\u{EC}nh nh\u{1EDB} g\u{1EA7}n \u{111}\u{E2}y:\n" .. table.concat(lines, "\n"), "Here's what I remember lately:\n" .. table.concat(lines, "\n"), "happy", 10)
            return true
        end
        return false
    end

    function I.again(ctx, c)
        if #c.tokens > 6 or not has(c, "again") then
            return false
        end
        for _, token in ipairs(c.tokens) do
            if not AGAIN_OK[token] and not AGAIN_FILL[token] then
                return false
            end
        end
        intent(ctx, "memory.again")
        if memoryOff(ctx) then
            answer(ctx, "M\u{EC}nh \u{111}ang t\u{1EAF}t ch\u{1EBF} \u{111}\u{1ED9} nh\u{1EDB} l\u{1ECB}ch s\u{1EED} chat n\u{EA}n kh\u{F4}ng bi\u{1EBF}t l\u{1EB7}p l\u{1EA1}i g\u{EC}. B\u{1EA1}n n\u{F3}i l\u{1EA1}i l\u{1EC7}nh gi\u{FA}p m\u{EC}nh nh\u{E9}.", "Chat history memory is switched off, so I don't know what to repeat. Please say the command again.", "think", 6)
            return true
        end
        local turn = lastWhere(ctx, function(item)
            return item.Act ~= nil and item.Act ~= ""
        end, 8, 900)
        if not turn then
            answer(ctx, "M\u{EC}nh ch\u{1B0}a l\u{E0}m g\u{EC} \u{111}\u{1EC3} l\u{1EB7}p l\u{1EA1}i c\u{1EA3}. B\u{1EA1}n mu\u{1ED1}n m\u{EC}nh l\u{E0}m g\u{EC} n\u{E0}o?", "I haven't done anything to repeat yet. What should I do?", "think", 4)
            return true
        end
        ctx.Replay = turn.Act
        ctx.Carry = { Key = turn.Key, Topic = turn.Topic, Intents = turn.Intents }
        ctx.KeepLang = true
        ctx.Mood = "happy"
        return true
    end

    function I.follow(ctx, c)
        local count = #c.tokens
        local value, unit = N.number(c)
        local recent = lastWhere(ctx, function(turn)
            return turn.Key ~= nil or string.find(turn.Intents or "", "timer.ask", 1, true) ~= nil
        end, 2, 240)
        if recent and value and count <= 4 and string.find(recent.Intents or "", "timer.ask", 1, true) then
            intent(ctx, "memory.timer")
            local seconds = unit == "min" and value * 60 or (unit == "hour" and value * 3600 or value)
            seconds = clamp(math.floor(seconds + 0.5), 1, 3600 * 3)
            ctx.Replay = ctx.Lang == "vi" and ("hen gio " .. seconds .. " giay") or ("timer " .. seconds .. " seconds")
            return true
        end
        if recent and recent.Key and CTL[recent.Key] and count <= 6 and not has(c, "howto") then
            local cue = value ~= nil or has(c, "up") or has(c, "down") or has(c, "max") or has(c, "min") or has(c, "on") or has(c, "off") or has(c, "mute")
            if cue and (has(c, "itw") or count <= 4) then
                intent(ctx, "memory.setting")
                if I.setting(ctx, c, recent.Key) then
                    return true
                end
                ctx.Intents[#ctx.Intents] = nil
            end
        end
        if has(c, "moreq") or has(c, "tryit") then
            local topicTurn = lastWhere(ctx, function(turn)
                return turn.Topic ~= nil and TRY[turn.Topic] ~= nil
            end, 2, 300)
            if topicTurn then
                local try = TRY[topicTurn.Topic]
                local command = ctx.Lang == "vi" and try[1] or try[2]
                if has(c, "tryit") then
                    intent(ctx, "memory.try")
                    ctx.Replay = command
                    ctx.Mood = "joy"
                else
                    intent(ctx, "memory.more")
                    answer(ctx, "M\u{EC}nh k\u{1EC3} h\u{1EBF}t nh\u{1EEF}ng g\u{EC} m\u{EC}nh bi\u{1EBF}t v\u{1EC1} m\u{1EE5}c n\u{E0}y r\u{1ED3}i. Mu\u{1ED1}n th\u{1EED} lu\u{F4}n kh\u{F4}ng? N\u{F3}i 'ok' l\u{E0} m\u{EC}nh l\u{E0}m: '" .. command .. "'.", "That's everything I know about this one. Want to try it? Say 'ok' and I'll run: '" .. command .. "'.", "wink", 7)
                    ctx.PendingSet = { Kind = "do", Replay = command }
                end
                return true
            end
        end
        return false
    end

    local function afterName(raw)
        local patterns = { "[Tt]\u{EA}n [Tt]\u{F4}i [Ll]\u{E0}%s+([^,%.!%?]+)", "[Tt]\u{EA}n [Mm]\u{EC}nh [Ll]\u{E0}%s+([^,%.!%?]+)", "[Tt]\u{F4}i [Tt]\u{EA}n [Ll]\u{E0}%s+([^,%.!%?]+)", "[Mm]y [Nn]ame [Ii]s%s+([^,%.!%?]+)", "[Cc]all [Mm]e%s+([^,%.!%?]+)", "[Gg]\u{1ECD}i [Tt]\u{F4}i [Ll]\u{E0}%s+([^,%.!%?]+)", "[Gg]\u{1ECD}i [Mm]\u{EC}nh [Ll]\u{E0}%s+([^,%.!%?]+)" }
        for _, pattern in ipairs(patterns) do
            local value = string.match(raw, pattern)
            if value then
                value = string.gsub(value, "%s+$", "")
                if #value > 0 and #value <= 24 then
                    return value
                end
            end
        end
        return nil
    end

    function I.chat(ctx, c)
        if has(c, "name") then
            local value = afterName(ctx.A.Raw)
            if value then
                intent(ctx, "chat.name")
                ctx.Learn = { Name = value }
                answer(ctx, string.format("R\u{1EA5}t vui \u{111}\u{1B0}\u{1EE3}c g\u{1EB7}p %s! M\u{EC}nh nh\u{1EDB} t\u{EA}n b\u{1EA1}n trong phi\u{EA}n n\u{E0}y nh\u{E9}.", value), string.format("Nice to meet you, %s! I'll remember your name for this session.", value), "joy", 5)
                return true
            end
        end
        if has(c, "greet") then
            intent(ctx, "chat.greet")
            local who = ctx.Env.userName()
            local hour = tonumber(ctx.Env.hour()) or 12
            local part = hour < 11 and T(ctx, "bu\u{1ED5}i s\u{E1}ng", "morning") or (hour < 14 and T(ctx, "bu\u{1ED5}i tr\u{1B0}a", "afternoon") or (hour < 18 and T(ctx, "bu\u{1ED5}i chi\u{1EC1}u", "afternoon") or T(ctx, "bu\u{1ED5}i t\u{1ED1}i", "evening")))
            local name = who and (", " .. who) or ""
            answer(ctx,
                pick(ctx, { "Ch\u{E0}o " .. part .. name .. "! M\u{EC}nh l\u{E0} Cross, c\u{1EA7}n m\u{EC}nh gi\u{FA}p g\u{EC} n\u{E0}o?", "H\u{1EBF} l\u{F4}" .. name .. "! H\u{F4}m nay m\u{EC}nh gi\u{FA}p g\u{EC} \u{111}\u{1B0}\u{1EE3}c cho b\u{1EA1}n?", "M\u{EC}nh nghe n\u{E8}" .. name .. "! B\u{1EA1}n mu\u{1ED1}n l\u{E0}m g\u{EC}?" }),
                pick(ctx, { "Good " .. part .. name .. "! I'm Cross, what can I do for you?", "Hey" .. name .. "! How can I help today?", "I'm listening" .. name .. "! What would you like to do?" }),
                "happy", 5)
            return true
        end
        if has(c, "thanks") then
            intent(ctx, "chat.thanks")
            answer(ctx, pick(ctx, { "Kh\u{F4}ng c\u{F3} chi nha!", "D\u{1EA1}, c\u{F3} g\u{EC} c\u{1EE9} g\u{1ECD}i m\u{EC}nh!", "Vui l\u{F2}ng ph\u{1EE5}c v\u{1EE5} b\u{1EA1}n!" }), pick(ctx, { "You're welcome!", "Anytime, just call me!", "Happy to help!" }), "love", 5)
            return true
        end
        if has(c, "sorry") and not has(c, "sad") then
            intent(ctx, "chat.sorry")
            answer(ctx, "Kh\u{F4}ng sao \u{111}\u{E2}u, m\u{EC}nh kh\u{F4}ng \u{111}\u{1EC3} b\u{1EE5}ng. M\u{EC}nh gi\u{FA}p ti\u{1EBF}p nh\u{E9}?", "No worries at all. Shall we carry on?", "happy", 4)
            return true
        end
        if has(c, "bye") then
            intent(ctx, "chat.bye")
            answer(ctx, pick(ctx, { "H\u{1EB9}n g\u{1EB7}p l\u{1EA1}i! Nh\u{1EDB} ngh\u{1EC9} ng\u{1A1}i nha.", "T\u{1EA1}m bi\u{1EC7}t! M\u{EC}nh v\u{1EAB}n \u{1EDF} tr\u{EA}n Dynamic Island n\u{1EBF}u b\u{1EA1}n c\u{1EA7}n.", "Ng\u{1EE7} ngon nh\u{E9}, mai g\u{1EB7}p!" }), pick(ctx, { "See you! Take a rest.", "Bye! I'll be on Dynamic Island if you need me.", "Good night, see you tomorrow!" }), "sleepy", 6)
            return true
        end
        if has(c, "howru") then
            intent(ctx, "chat.howru")
            answer(ctx, "M\u{EC}nh \u{1ED5}n l\u{1EAF}m, \u{111}ang r\u{1EA3}nh \u{111}\u{1EC3} ch\u{1EC9}nh UI cho b\u{1EA1}n n\u{E8}. C\u{F2}n b\u{1EA1}n th\u{EC} sao?", "I'm doing great and ready to tweak your UI. How about you?", "happy", 5)
            return true
        end
        if has(c, "love") then
            intent(ctx, "chat.love")
            answer(ctx, pick(ctx, { "Hihi, m\u{EC}nh c\u{169}ng qu\u{FD} b\u{1EA1}n l\u{1EAF}m \u{111}\u{F3}!", "\u{D4}i ng\u{1EA1}i qu\u{E1}, c\u{1EA3}m \u{1A1}n b\u{1EA1}n nhi\u{1EC1}u!" }), pick(ctx, { "Aww, I like you too!", "You're making me blush, thank you!" }), "love", 6)
            return true
        end
        if has(c, "praise") then
            intent(ctx, "chat.praise")
            answer(ctx, pick(ctx, { "C\u{1EA3}m \u{1A1}n b\u{1EA1}n! M\u{EC}nh s\u{1EBD} c\u{1ED1} g\u{1EAF}ng h\u{1A1}n n\u{1EEF}a.", "H\u{EC}, \u{111}\u{1B0}\u{1EE3}c khen vui gh\u{EA}!" }), pick(ctx, { "Thank you! I'll keep trying my best.", "Hehe, that made my day!" }), "joy", 5)
            return true
        end
        if has(c, "insult") then
            intent(ctx, "chat.insult")
            answer(ctx, pick(ctx, { "Huhu, m\u{EC}nh xin l\u{1ED7}i n\u{1EBF}u l\u{E0}m ch\u{1B0}a t\u{1ED1}t. B\u{1EA1}n ch\u{1EC9} m\u{EC}nh sai ch\u{1ED7} n\u{E0}o \u{111}\u{1EC3} m\u{EC}nh s\u{1EED}a nh\u{E9}?", "Ouch... m\u{EC}nh s\u{1EBD} c\u{1ED1} g\u{1EAF}ng hi\u{1EC3}u b\u{1EA1}n h\u{1A1}n. Th\u{1EED} n\u{F3}i l\u{1EA1}i c\u{E1}ch kh\u{E1}c gi\u{FA}p m\u{EC}nh nha." }), pick(ctx, { "Aw, sorry if I let you down. Tell me what went wrong and I'll fix it.", "Ouch... I'll try to understand you better. Could you rephrase it for me?" }), "sad", 7)
            return true
        end
        if has(c, "tired") then
            intent(ctx, "chat.tired")
            answer(ctx, "M\u{1EC7}t th\u{EC} ngh\u{1EC9} ch\u{FA}t \u{111}i b\u{1EA1}n. M\u{EC}nh \u{111}\u{1ED5}i UI sang t\u{F4}ng t\u{1ED1}i d\u{1ECB}u m\u{1EAF}t nh\u{E9}? N\u{F3}i 'ok' l\u{E0} m\u{EC}nh l\u{E0}m.", "Sounds like you could use a break. Want me to switch to a soft dark theme? Say 'ok' and I'll do it.", "sleepy", 7)
            ctx.PendingSet = { Kind = "grant", Perm = "Ui", Replay = ctx.Lang == "vi" and "doi giao dien nua dem" or "switch to the midnight theme" }
            return true
        end
        if has(c, "bored") then
            intent(ctx, "chat.bored")
            answer(ctx, "Ch\u{E1}n h\u{1EA3}? Th\u{1EED} 't\u{1EF1} ch\u{1A1}i \u{111}i' \u{111}\u{1EC3} m\u{EC}nh \u{111}i d\u{1EA1}o trong game, ho\u{1EB7}c n\u{F3}i 'b\u{1EAD}t nh\u{1EA1}c' cho vui, hay 'k\u{1EC3} chuy\u{1EC7}n c\u{1B0}\u{1EDD}i' n\u{E8}!", "Bored? Try 'play by yourself' and I'll roam the game, say 'play music', or ask for a joke!", "wink", 7)
            return true
        end
        if has(c, "sad") then
            intent(ctx, "chat.sad")
            answer(ctx, "M\u{EC}nh \u{1EDF} \u{111}\u{E2}y nghe b\u{1EA1}n n\u{E8}. C\u{F3} th\u{1EC3} m\u{1EDF} m\u{1ED9}t b\u{1EA3}n nh\u{1EA1}c nh\u{1EB9} ho\u{1EB7}c \u{111}\u{1ED5}i UI sang t\u{F4}ng d\u{1ECB}u m\u{1EAF}t gi\u{FA}p b\u{1EA1}n th\u{1EA5}y tho\u{1EA3}i m\u{E1}i h\u{1A1}n. B\u{1EA1}n mu\u{1ED1}n th\u{1EED} kh\u{F4}ng?", "I'm here for you. A calm track or a softer theme might help a little. Want to try?", "sad", 8)
            return true
        end
        if has(c, "joke") then
            intent(ctx, "chat.joke")
            local jokes = {
                { "V\u{EC} sao l\u{1EAD}p tr\u{EC}nh vi\u{EA}n hay \u{111}\u{F3}i? V\u{EC} h\u{1ECD} to\u{E0}n qu\u{EA}n 'byte' (c\u{1EAF}n)!", "Why do programmers prefer dark mode? Because light attracts bugs!" },
                { "C\u{F3} 10 lo\u{1EA1}i ng\u{1B0}\u{1EDD}i: ng\u{1B0}\u{1EDD}i hi\u{1EC3}u nh\u{1ECB} ph\u{E2}n v\u{E0} ng\u{1B0}\u{1EDD}i kh\u{F4}ng.", "There are 10 kinds of people: those who understand binary and those who don't." },
                { "M\u{EC}nh h\u{1ECF}i bug: sao \u{1EDF} l\u{EC} trong code? Bug b\u{1EA3}o: t\u{1EA1}i b\u{1EA1}n \u{111}\u{E2}u c\u{F3} ch\u{1ECB}u 'debug' m\u{EC}nh \u{111}i!", "A bug moved into my code and refuses to leave. It says I never really 'commit' to anything." },
            }
            local joke = pick(ctx, jokes)
            answer(ctx, joke[1], joke[2], "joy", 6)
            return true
        end
        return false
    end

    local LEVEL_SET = { level = true, lv = true, lvl = true, levels = true, lvls = true, lever = true }
    local KILL_SET = { quai = true, kills = true, kill = true, mobs = true, monsters = true, enemies = true }
    local STAGE_SET = { stage = true, checkpoint = true, chang = true, cp = true, man = true }
    local ITEM_SET = { items = true, item = true, loot = true }
    local TIME_UNIT = { sec = 1, min = 60, hour = 3600 }
    local ON_V = { bat = true, mo = true, enable = true, activate = true, start = true, run = true, chay = true, hien = true, show = true, open = true, canh = true, watch = true, use = true, monitor = true, farm = true, lay = true, nhat = true, collect = true, giu = true, keep = true }
    local OFF_V = { tat = true, off = true, disable = true, hide = true, close = true, ngung = true, stop = true, remove = true, giau = true, dismiss = true, xoa = true, bo = true, deactivate = true }
    local STAT_NAME = {
        level = { "level", "level" },
        kills = { "qu\u{E1}i h\u{1EA1}", "kills" },
        items = { "v\u{1EAD}t ph\u{1EA9}m", "items" },
        stage = { "m\u{E0}n", "stage" },
    }

    local function numberOf(token)
        if not token then
            return nil
        end
        local digits, suffix = string.match(token, "^(%d+_?%d*)(%a*)$")
        if not digits then
            return nil
        end
        local value = tonumber((string.gsub(digits, "_", ".")))
        if not value then
            return nil
        end
        if suffix == "k" then
            value = value * 1000
        elseif suffix == "m" or suffix == "tr" then
            value = value * 1000000
        elseif suffix ~= "" then
            return nil
        end
        return value
    end

    local function statLookup(ctx)
        local set = {}
        local names = ctx.Env.statNames and ctx.Env.statNames() or {}
        for _, name in ipairs(names) do
            set[name] = name
            set[name .. "s"] = name
            if string.sub(name, -1) == "s" and #name > 3 then
                set[string.sub(name, 1, -2)] = name
            end
        end
        return set
    end

    local function statLabel(ctx, stat)
        local pair = STAT_NAME[stat]
        if pair then
            return ctx.Lang == "vi" and pair[1] or pair[2]
        end
        return stat or "level"
    end

    local function parseCond(ctx, tokens)
        local custom = statLookup(ctx)
        for index, token in ipairs(tokens) do
            local prefix, digits = string.match(token, "^(%a+)(%d+)$")
            if prefix and LEVEL_SET[prefix] then
                return { Kind = "stat", Stat = "level", Value = tonumber(digits) }, index
            end
            local stat
            if LEVEL_SET[token] then
                stat = "level"
            elseif KILL_SET[token] then
                stat = "kills"
            elseif STAGE_SET[token] then
                stat = "stage"
            elseif ITEM_SET[token] or (token == "vat" and tokens[index + 1] == "pham") then
                stat = "items"
            elseif custom[token] then
                stat = custom[token]
            end
            if stat then
                local value = numberOf(tokens[index + 1]) or numberOf(tokens[index - 1])
                if token == "vat" then
                    value = numberOf(tokens[index - 1]) or numberOf(tokens[index + 2])
                elseif token == "pham" then
                    value = nil
                end
                if value then
                    return { Kind = "stat", Stat = stat, Value = value }, index
                end
            end
        end
        local value, unit, at = N.number({ tokens = tokens, used = {} })
        if value and unit and TIME_UNIT[unit] then
            return { Kind = "time", Seconds = math.max(1, value * TIME_UNIT[unit]) }, at
        end
        return nil
    end

    local function matchFeatures(ctx, tokens)
        local list = ctx.Env.features and ctx.Env.features() or {}
        local found = {}
        for _, feature in ipairs(list) do
            local total, got, hit, positions, first = 0, 0, 0, {}, 1e9
            for word in pairs(feature.Words) do
                total = total + #word
                for index, token in ipairs(tokens) do
                    if token == word or (#word >= 5 and #token >= 4 and N.close(token, word)) then
                        got = got + #word
                        hit = hit + 1
                        positions[#positions + 1] = index
                        if index < first then
                            first = index
                        end
                        break
                    end
                end
            end
            if hit > 0 and total > 0 then
                local ratio = got / total
                if ratio >= 0.99 or (hit >= 2 and ratio >= 0.6) or (feature.Count == 1 and hit == 1) then
                    found[#found + 1] = { Feature = feature, Ratio = ratio, Got = got, Positions = positions, First = first }
                end
            end
        end
        table.sort(found, function(a, b)
            if a.Ratio ~= b.Ratio then
                return a.Ratio > b.Ratio
            end
            if a.Got ~= b.Got then
                return a.Got > b.Got
            end
            return a.Feature.Key < b.Feature.Key
        end)
        local claimed, result, seenKey = {}, {}, {}
        for _, item in ipairs(found) do
            local clash = seenKey[item.Feature.Key] == true
            for _, position in ipairs(item.Positions) do
                if claimed[position] then
                    clash = true
                end
            end
            if not clash then
                seenKey[item.Feature.Key] = true
                for _, position in ipairs(item.Positions) do
                    claimed[position] = true
                end
                local last = 0
                for _, position in ipairs(item.Positions) do
                    if position > last then
                        last = position
                    end
                end
                item.Last = last
                result[#result + 1] = item
            end
        end
        table.sort(result, function(a, b)
            return a.First < b.First
        end)
        return result
    end

    local function verbNear(tokens, hit, from)
        for index = hit.First - 1, math.max(from, 1), -1 do
            local token = tokens[index]
            if OFF_V[token] then
                return "off"
            elseif ON_V[token] then
                return "on"
            end
        end
        for index = hit.Last + 1, math.min(hit.Last + 2, #tokens) do
            local token = tokens[index]
            if OFF_V[token] then
                return "off"
            elseif ON_V[token] and token ~= "lay" and token ~= "nhat" then
                return "on"
            end
        end
        return nil
    end

    local function formatSeconds(ctx, seconds)
        seconds = math.floor(seconds + 0.5)
        if seconds >= 3600 and seconds % 3600 == 0 then
            return T(ctx, string.format("%d gi\u{1EDD}", seconds / 3600), string.format("%dh", seconds / 3600))
        end
        if seconds >= 60 and seconds % 60 == 0 then
            return T(ctx, string.format("%d ph\u{FA}t", seconds / 60), string.format("%d min", seconds / 60))
        end
        return T(ctx, string.format("%d gi\u{E2}y", seconds), string.format("%ds", seconds))
    end

    local PILOT_TEXT = {
        ["pilot:scan"] = { "qu\u{E9}t map", "scan the map" },
        ["pilot:obby"] = { "ch\u{1A1}i obby", "play the obby" },
        ["pilot:fight"] = { "chi\u{1EBF}n \u{111}\u{1EA5}u v\u{1EDB}i qu\u{E1}i", "fight mobs" },
        ["pilot:collect"] = { "nh\u{1EB7}t v\u{1EAD}t ph\u{1EA9}m", "collect items" },
        ["pilot:auto"] = { "t\u{1EF1} ch\u{1A1}i", "play freely" },
    }

    local function stepText(ctx, item)
        local verb = item.Action == "off" and T(ctx, "t\u{1EAF}t ", "turn off ") or T(ctx, "b\u{1EAD}t ", "turn on ")
        local title = ctx.Lang == "en" and (item.TitleEn or item.Title) or item.Title
        local named = PILOT_TEXT[item.Key]
        if named then
            verb = item.Action == "off" and T(ctx, "ng\u{1EEB}ng ", "stop ") or ""
            title = T(ctx, named[1], named[2])
        end
        local cond = item.Cond
        local tail = ""
        if cond then
            if cond.Kind == "time" then
                tail = T(ctx, " trong " .. formatSeconds(ctx, cond.Seconds), " for " .. formatSeconds(ctx, cond.Seconds))
            elseif cond.Kind == "scan" then
                tail = named and "" or T(ctx, " \u{111}\u{1EBF}n khi qu\u{E9}t xong", " until the scan is done")
            elseif cond.Kind == "finish" then
                tail = T(ctx, " \u{111}\u{1EBF}n v\u{1EA1}ch \u{111}\u{ED}ch", " until the finish line")
            else
                tail = T(ctx, " \u{111}\u{1EBF}n " .. statLabel(ctx, cond.Stat) .. " " .. fmtNumber(cond.Value), " until " .. statLabel(ctx, cond.Stat) .. " " .. fmtNumber(cond.Value))
            end
        end
        return verb .. title .. tail
    end

    local DEFAULT_COND = { ["pilot:scan"] = true, ["pilot:obby"] = true }

    local function needsPilot(steps)
        for _, item in ipairs(steps) do
            if string.sub(item.Key, 1, 6) == "pilot:" then
                return true
            end
        end
        return false
    end

    local function missingIndex(steps)
        for index = 1, #steps - 1 do
            local item = steps[index]
            if item.Action == "on" and not item.Cond and not item.Open and not DEFAULT_COND[item.Key] then
                return index
            end
        end
        return nil
    end

    local function emitTask(ctx, steps)
        local list, args = {}, {}
        for _, item in ipairs(steps) do
            list[#list + 1] = stepText(ctx, item)
            local cond = item.Cond
            local mark = ""
            if cond then
                if cond.Kind == "time" then
                    mark = string.format("(%ds)", cond.Seconds)
                elseif cond.Kind == "stat" then
                    mark = string.format("(%s>=%s)", cond.Stat, fmtNumber(cond.Value))
                else
                    mark = "(" .. cond.Kind .. ")"
                end
            end
            args[#args + 1] = string.format("%s:%s%s", item.Key, item.Action, mark)
        end
        local joined = table.concat(list, ctx.Lang == "vi" and ", r\u{1ED3}i " or ", then ")
        local hasUi = false
        for _, item in ipairs(steps) do
            if string.sub(item.Key, 1, 6) ~= "pilot:" then
                hasUi = true
            end
        end
        intent(ctx, "task.start")
        step(ctx, "task", {
            Do = "start",
            Spec = { Steps = steps },
            Cmd = "Start-Task",
            Args = table.concat(args, " -> "),
            Say = { "b\u{1EAF}t \u{111}\u{1EA7}u nhi\u{1EC7}m v\u{1EE5}: " .. joined, "started the task: " .. joined },
            Perm = hasUi and "Ui" or nil,
        })
        if ctx.Env.discord and ctx.Env.discord() then
            answer(ctx, "M\u{EC}nh s\u{1EBD} b\u{E1}o ti\u{1EBF}n \u{111}\u{1ED9} l\u{EA}n Discord.", "I'll post progress on Discord.", "happy", 6)
        end
        ctx.Mood = ctx.Mood or "joy"
        ctx.Hold = ctx.Hold or 6
    end

    local function askCond(ctx, steps, index)
        local first = steps[index]
        local second = steps[index + 1]
        local a = ctx.Lang == "en" and (first.TitleEn or first.Title) or first.Title
        local b = ctx.Lang == "en" and (second.TitleEn or second.Title) or second.Title
        ctx.PendingSet = { Kind = "taskq", Spec = { Steps = steps }, Missing = index }
        intent(ctx, "task.ask")
        answer(ctx,
            string.format("M\u{EC}nh s\u{1EBD} \u{111}\u{1EC3} '%s' ch\u{1EA1}y r\u{1ED3}i m\u{1EDB}i chuy\u{1EC3}n sang '%s'. \u{110}\u{1EBF}n khi n\u{E0}o th\u{EC} chuy\u{1EC3}n? N\u{F3}i v\u{ED} d\u{1EE5} 'level 50', '10 ph\u{FA}t' hay '20 qu\u{E1}i'; mu\u{1ED1}n b\u{1EAD}t c\u{1EA3} hai ngay th\u{EC} n\u{F3}i 'c\u{1EA3} hai'.", a, b),
            string.format("I'll keep '%s' running before moving to '%s'. When should I switch? Say something like 'level 50', '10 minutes' or '20 kills'; say 'both' to turn them on together.", a, b),
            "think", 10)
    end

    local function finishSteps(ctx, steps)
        if needsPilot(steps) and not needPerm(ctx, "Free") then
            return true
        end
        local missing = missingIndex(steps)
        if missing then
            askCond(ctx, steps, missing)
            return true
        end
        if #steps == 1 and not steps[1].Cond then
            local item = steps[1]
            if string.sub(item.Key, 1, 6) == "pilot:" then
                emitTask(ctx, steps)
            else
                local on = item.Action ~= "off"
                local current = ctx.Env.get(item.Key)
                intent(ctx, "feature.toggle")
                local title = ctx.Lang == "en" and (item.TitleEn or item.Title) or item.Title
                if current ~= nil and (current and true or false) == on then
                    answer(ctx, string.format("'%s' \u{111}\u{E3} %s s\u{1EB5}n r\u{1ED3}i.", title, on and "b\u{1EAD}t" or "t\u{1EAF}t"), string.format("'%s' is already %s.", title, on and "on" or "off"), "wink", 3)
                else
                    setCtl(ctx, item.Key, on, string.format("%s %s", on and "b\u{1EAD}t" or "t\u{1EAF}t", title), string.format("turned %s %s", on and "on" or "off", title), tostring(on))
                end
            end
            return true
        end
        emitTask(ctx, steps)
        return true
    end

    local function planTask(ctx, analysis)
        local features = ctx.Env.features and ctx.Env.features() or {}
        if #features == 0 then
            return false
        end
        local whole = N.whole(analysis)
        if has(whole, "howto") then
            return false
        end
        local taskCue = has(whole, "taskw")
        local chainCue = has(whole, "thenw")
        local steps, taken = {}, {}
        local hitTotal, condTotal = 0, 0
        for index, clause in ipairs(analysis.Clauses) do
            local tokens = clause.tokens
            local hits = matchFeatures(ctx, tokens)
            local cond = parseCond(ctx, tokens)
            if #hits > 0 or cond or has({ tokens = tokens, used = {} }, "taskw") then
                taken[index] = true
            end
            hitTotal = hitTotal + #hits
            if cond then
                condTotal = condTotal + 1
            end
            local from = 1
            for position, hit in ipairs(hits) do
                local feature = hit.Feature
                local act = verbNear(tokens, hit, from) or (position > 1 and steps[#steps] and steps[#steps].Action) or "on"
                from = hit.Last + 1
                local hitCond = position == #hits and cond or nil
                if act == "off" then
                    local previous
                    for back = #steps, 1, -1 do
                        if steps[back].Key == feature.Key and steps[back].Action == "on" then
                            previous = steps[back]
                            break
                        end
                    end
                    if previous then
                        if hitCond and not previous.Cond then
                            previous.Cond = hitCond
                        end
                    elseif hitCond then
                        steps[#steps + 1] = { Key = feature.Key, Title = feature.Title, TitleEn = feature.En, Action = "on", Cond = hitCond, Inferred = true }
                    else
                        steps[#steps + 1] = { Key = feature.Key, Title = feature.Title, TitleEn = feature.En, Action = "off" }
                    end
                else
                    steps[#steps + 1] = { Key = feature.Key, Title = feature.Title, TitleEn = feature.En, Action = "on", Cond = hitCond }
                end
            end
            if #hits == 0 and cond and #steps > 0 then
                local last = steps[#steps]
                if last.Action == "on" and not last.Cond then
                    last.Cond = cond
                end
            end
        end
        if hitTotal == 0 then
            return false
        end
        if not (taskCue or condTotal > 0 or (hitTotal >= 2 and chainCue)) then
            return false
        end
        for index in pairs(taken) do
            analysis.Clauses[index].Taken = true
        end
        if #steps == 0 then
            return false
        end
        ctx.Planned = true
        finishSteps(ctx, steps)
        return true
    end

    local function describeTask(ctx, task)
        local info = task.Desc
        if not info then
            return ""
        end
        return string.format("%s (%d/%d) \u{B7} %s", info.Plan, info.Index, info.Count, info.Detail)
    end

    function I.taskans(ctx, c)
        local pending = ctx.Env.pending()
        if not pending or pending.Kind ~= "taskq" or not pending.Spec then
            return false
        end
        local steps = pending.Spec.Steps
        local index = pending.Missing
        local target = steps[index]
        if not target then
            return false
        end
        if has(c, "no") or has(c, "tcancel") then
            intent(ctx, "task.cancel")
            ctx.Env.clearPending()
            answer(ctx, "Ok, m\u{EC}nh b\u{1ECF} nhi\u{1EC7}m v\u{1EE5} n\u{E0}y.", "Okay, I'll drop that task.", "neutral", 3)
            return true
        end
        local cond = parseCond(ctx, c.tokens)
        if not cond and #c.tokens <= 4 then
            local value, unit = N.number(c)
            if value then
                if unit and TIME_UNIT[unit] then
                    cond = { Kind = "time", Seconds = math.max(1, value * TIME_UNIT[unit]) }
                elseif not unit then
                    cond = { Kind = "stat", Stat = "level", Value = value }
                end
            end
        end
        local both = has(c, "ca hai|both|together|cung luc|luon|same time|cu bat het|bat het|all of them|all at once")
        if not cond and not both then
            return false
        end
        intent(ctx, "task.answer")
        ctx.Env.clearPending()
        if cond then
            target.Cond = cond
        else
            target.Open = true
        end
        local next = missingIndex(steps)
        if next then
            askCond(ctx, steps, next)
            return true
        end
        finishSteps(ctx, steps)
        return true
    end

    function I.taskctl(ctx, c)
        local task = ctx.Env.task and ctx.Env.task()
        local noun = has(c, "taskn")
        local count = #c.tokens
        if not task then
            if noun and has(c, "tstatus") then
                intent(ctx, "task.status")
                answer(ctx, "Hi\u{1EC7}n kh\u{F4}ng c\u{F3} nhi\u{1EC7}m v\u{1EE5} n\u{E0}o \u{111}ang ch\u{1EA1}y. B\u{1EA1}n th\u{1EED}: 'canh Anti AFK 10 ph\u{FA}t'.", "There's no task running right now. Try: 'watch Anti AFK for 10 minutes'.", "wink", 4)
                return true
            end
            return false
        end
        if has(c, "howto") or has(c, "mnoun") or has(c, "timer") or has(c, "watch") then
            return false
        end
        local status = noun and has(c, "tstatus")
        if has(c, "tstatus") and (noun or count <= 4) and not has(c, "bchar") then
            status = true
        end
        if status then
            intent(ctx, "task.status")
            local state = task.Status == "paused" and T(ctx, " (\u{111}ang t\u{1EA1}m d\u{1EEB}ng)", " (paused)") or ""
            answer(ctx, "Nhi\u{1EC7}m v\u{1EE5}" .. state .. ": " .. describeTask(ctx, task) .. ".", "Task" .. state .. ": " .. describeTask(ctx, task) .. ".", "happy", 8)
            return true
        end
        if has(c, "tpause") and (noun or count <= 3) then
            intent(ctx, "task.pause")
            if task.Status == "paused" then
                answer(ctx, "Nhi\u{1EC7}m v\u{1EE5} \u{111}ang t\u{1EA1}m d\u{1EEB}ng s\u{1EB5}n r\u{1ED3}i.", "The task is already paused.", "wink", 3)
            else
                step(ctx, "task", { Do = "pause", Cmd = "Suspend-Task", Args = "", Say = { "t\u{1EA1}m d\u{1EEB}ng nhi\u{1EC7}m v\u{1EE5}", "paused the task" } })
            end
            return true
        end
        if has(c, "tresume") and (noun or task.Status == "paused") and count <= 5 then
            intent(ctx, "task.resume")
            if task.Status ~= "paused" then
                answer(ctx, "Nhi\u{1EC7}m v\u{1EE5} \u{111}ang ch\u{1EA1}y m\u{E0}, kh\u{F4}ng c\u{1EA7}n ti\u{1EBF}p t\u{1EE5}c.", "The task is already running.", "wink", 3)
            else
                step(ctx, "task", { Do = "resume", Cmd = "Resume-Task", Args = "", Say = { "cho nhi\u{1EC7}m v\u{1EE5} ch\u{1EA1}y ti\u{1EBF}p", "resumed the task" } })
            end
            return true
        end
        if (has(c, "tcancel") or (noun and has(c, "bstop|off"))) and (noun or count <= 2) then
            intent(ctx, "task.cancel")
            step(ctx, "task", { Do = "cancel", Cmd = "Stop-Task", Args = "", Say = { "hu\u{1EF7} nhi\u{1EC7}m v\u{1EE5}", "cancelled the task" } })
            return true
        end
        if has(c, "tskip") and task.Status == "running" and (noun or count <= 4) then
            intent(ctx, "task.skip")
            step(ctx, "task", { Do = "skip", Cmd = "Skip-TaskStep", Args = "", Say = { "chuy\u{1EC3}n sang b\u{1B0}\u{1EDB}c ti\u{1EBF}p theo", "moved to the next step" } })
            return true
        end
        return false
    end

    local PLAY_FILLER = { cross = true, e = true, oi = true, di = true, nha = true, nhe = true, ne = true, giup = true, cho = true, minh = true, t = true, tui = true, toi_me = true, please = true, hay = true, la = true, cac = true, nhung = true, con = true, cai = true, the = true, a = true, an = true, some = true, any = true, for_ = true, me = true, my = true, voi = true, lam = true, lai = true, nua = true, luon = true, ["\u{111}i"] = true, tu = true, xung = true, quanh = true, around = true, nearby = true, gan = true, day = true, here = true }

    function I.play(ctx, c)
        if has(c, "howto") then
            return false
        end
        local mode
        if has(c, "pscan") then
            mode = "scan"
        elseif has(c, "pobby") then
            mode = "obby"
        elseif has(c, "pfight") then
            mode = "fight"
        elseif has(c, "pcollect") then
            mode = "collect"
        end
        if not mode then
            return false
        end
        local state = ctx.Env.pilot and ctx.Env.pilot() or {}
        local names = { scan = { "qu\u{E9}t map", "scan the map" }, obby = { "ch\u{1A1}i obby", "play the obby" }, fight = { "chi\u{1EBF}n \u{111}\u{1EA5}u v\u{1EDB}i qu\u{E1}i", "fight mobs" }, collect = { "nh\u{1EB7}t v\u{1EAD}t ph\u{1EA9}m", "collect items" }, auto = { "t\u{1EF1} ch\u{1A1}i", "free play" } }
        if has(c, "off") or has(c, "bstop") or negated(c) then
            intent(ctx, "pilot.stop")
            if state.Active or state.Mode then
                step(ctx, "pilot", { Do = "stop", Cmd = "Stop-Pilot", Args = "", Say = { "ng\u{1EEB}ng " .. names[mode][1], "stopped " .. names[mode][2] }, Perm = "Body" })
            else
                answer(ctx, "M\u{EC}nh \u{111}ang kh\u{F4}ng t\u{1EF1} ch\u{1A1}i m\u{E0}.", "I'm not playing on my own right now.", "wink", 3)
            end
            return true
        end
        intent(ctx, "pilot." .. mode)
        local pendingFree = ctx.Env.pending()
        pendingFree = pendingFree and pendingFree.Kind == "grant" and (pendingFree.Perm == "Free" or pendingFree.Perm == "Body")
        local consent = ctx.NoAsk or has(c, "grantw") or (pendingFree and has(c, "yes"))
        if ctx.NoAsk then
            ctx.NoAskUsed = true
        end
        if consent then
            ctx.Assume = ctx.Assume or {}
            ctx.Assume.Free = true
            ctx.Assume.Body = true
            for _, perm in ipairs({ "Free", "Body" }) do
                if not ctx.Env.perm(perm) then
                    step(ctx, "perm", { Name = perm, Value = true, Cmd = "Grant-Permission", Args = perm, Say = { "b\u{1EAD}t quy\u{1EC1}n " .. PERM_VI[perm], "enabled permission to " .. PERM_EN[perm] } })
                end
            end
        elseif not needPerm(ctx, "Free") then
            return true
        end
        local item
        if mode == "collect" then
            find(c, "pcollect", true)
            local words = {}
            for index, token in ipairs(c.tokens) do
                if not c.used[index] and not PLAY_FILLER[token] and #token >= 2 then
                    words[#words + 1] = token
                end
            end
            if #words > 0 then
                item = table.concat(words, " ")
            end
        end
        local seconds = mode == "scan" and 45 or nil
        local label = names[mode]
        local suffix = item and (" (" .. item .. ")") or ""
        step(ctx, "pilot", {
            Do = "mode",
            Mode = mode,
            Item = item,
            Seconds = seconds,
            Cmd = "Start-Pilot",
            Args = "-Mode " .. mode .. (item and (' -Item "' .. item .. '"') or ""),
            Say = { "b\u{1EAF}t \u{111}\u{1EA7}u " .. label[1] .. suffix, "started " .. label[2] .. suffix },
            Perm = "Free",
        })
        if ctx.Env.discord and ctx.Env.discord() then
            answer(ctx, "M\u{EC}nh s\u{1EBD} b\u{E1}o ti\u{1EBF}n \u{111}\u{1ED9} l\u{EA}n Discord.", "I'll post progress on Discord.", "happy", 6)
        end
        ctx.Mood = "joy"
        return true
    end

    function I.feature(ctx, c)
        if has(c, "howto") then
            return false
        end
        local hits = matchFeatures(ctx, c.tokens)
        if #hits == 0 then
            return false
        end
        local did = false
        local from = 1
        for _, hit in ipairs(hits) do
            local feature = hit.Feature
            local act = verbNear(c.tokens, hit, from)
            from = hit.Last + 1
            if act and not feature.Pseudo then
                local on = act == "on"
                if negated(c) then
                    on = not on
                end
                local current = ctx.Env.get(feature.Key)
                intent(ctx, "feature.toggle")
                local title = ctx.Lang == "en" and (feature.En or feature.Title) or feature.Title
                ctx.Key = feature.Key
                if current ~= nil and (current and true or false) == on then
                    answer(ctx, string.format("'%s' \u{111}\u{E3} %s s\u{1EB5}n r\u{1ED3}i.", title, on and "b\u{1EAD}t" or "t\u{1EAF}t"), string.format("'%s' is already %s.", title, on and "on" or "off"), "wink", 3)
                else
                    setCtl(ctx, feature.Key, on, string.format("%s %s", on and "b\u{1EAD}t" or "t\u{1EAF}t", title), string.format("turned %s %s", on and "on" or "off", title), tostring(on))
                end
                did = true
            end
        end
        return did
    end

    function I.taskmiss(ctx, c)
        if has(c, "howto") then
            return false
        end
        local cue = has(c, "taskw") or (parseCond(ctx, c.tokens) ~= nil and has(c, "levelw"))
        if not cue then
            return false
        end
        local list = ctx.Env.features and ctx.Env.features() or {}
        local names = {}
        for _, feature in ipairs(list) do
            if not feature.Pseudo and #names < 6 then
                names[#names + 1] = ctx.Lang == "en" and (feature.En or feature.Title) or feature.Title
            end
        end
        intent(ctx, "task.unknown")
        answer(ctx,
            "M\u{EC}nh kh\u{F4}ng th\u{1EA5}y ch\u{1EE9}c n\u{103}ng n\u{E0}o trong UI kh\u{1EDB}p v\u{1EDB}i t\u{EA}n b\u{1EA1}n n\u{F3}i n\u{EA}n ch\u{1B0}a canh \u{111}\u{1B0}\u{1EE3}c. M\u{EC}nh \u{111}i\u{1EC1}u khi\u{1EC3}n \u{111}\u{1B0}\u{1EE3}c m\u{1ECD}i c\u{F4}ng t\u{1EAF}c c\u{F3} s\u{1EB5}n, v\u{ED} d\u{1EE5}: " .. table.concat(names, ", ") .. ", c\u{F9}ng c\u{E1}c ki\u{1EC3}u t\u{1EF1} ch\u{1A1}i (obby, chi\u{1EBF}n \u{111}\u{1EA5}u, nh\u{1EB7}t \u{111}\u{1ED3}, qu\u{E9}t map). V\u{ED} d\u{1EE5}: 'b\u{1EAD}t " .. (names[1] or "Anti AFK") .. " \u{111}\u{1EBF}n level 30 r\u{1ED3}i t\u{1EAF}t n\u{F3} v\u{E0} b\u{1EAD}t " .. (names[2] or "nh\u{1EA3}y li\u{EA}n t\u{1EE5}c") .. "'.",
            "I can't find a feature in the UI that matches that name, so I can't watch it. I can drive every toggle that exists, for example: " .. table.concat(names, ", ") .. ", plus the auto-play modes (obby, fight, collect, map scan). Try: 'turn on " .. (names[1] or "Anti AFK") .. " until level 30 then turn it off and turn on " .. (names[2] or "infinite jump") .. "'.",
            "think", 10)
        return true
    end

    function B.plan(text, env)
        if env.features then
            env.features()
        end
        if env.statNames then
            local names = env.statNames()
            if #names > 0 then
                N.learn(table.concat(names, " "))
            end
        end
        local analysis = N.analyze(text, env.lang)
        local ctx = {
            Env = env,
            A = analysis,
            Lang = analysis.Lang,
            Steps = {},
            Intents = {},
            Mood = nil,
            Hold = nil,
            Answer = nil,
            Hist = env.history and env.history() or {},
        }
        if env.carry then
            local copy = {}
            for index, item in ipairs(ctx.Hist) do
                copy[index] = item
            end
            copy[#copy + 1] = { Text = "", Said = "", Did = { "", "" }, Key = env.carry.Key, Topic = env.carry.Topic, Intents = env.carry.Intents or "", Age = 0 }
            ctx.Hist = copy
        end
        local handled = 0
        local addressed = false
        local order = { "taskans", "confirm", "undo", "taskctl", "sys", "recall", "again", "movediag", "who", "capabilities", "status", "howto", "permission", "play", "free", "timer", "body", "music", "setting", "feature", "theme", "window", "tab", "follow", "taskmiss", "chat" }
        local unknown = 0
        local noaskOnly = false
        for _, clause in ipairs(analysis.Clauses) do
            if has({ tokens = clause.tokens, used = {} }, "noask") then
                ctx.NoAsk = true
            end
        end
        local planned = false
        local pending = ctx.Env.pending()
        if not (pending and pending.Kind == "taskq" and #analysis.Tokens <= 5) then
            planned = planTask(ctx, analysis)
        end
        for _, clause in ipairs(analysis.Clauses) do
            strip(clause)
            if clause.addressed then
                addressed = true
            end
            if ctx.NoAsk and find(clause, "noask", true) then
                local left = 0
                for index, token in ipairs(clause.tokens) do
                    if not clause.used[index] and not FILL[token] then
                        left = left + 1
                    end
                end
                clause.Spent = left == 0
            end
            if clause.Taken then
                handled = handled + 1
            elseif clause.Spent then
                handled = handled + 1
                local pending = ctx.Env.pending()
                if pending then
                    intent(ctx, "confirm." .. pending.Kind)
                    ctx.Env.clearPending()
                    accept(ctx, pending)
                else
                    noaskOnly = true
                end
            elseif #clause.tokens == 1 and clause.tokens[1] == "cross" then
                handled = handled + 1
                ctx.Summon = true
            elseif #clause.tokens > 0 then
                local done = false
                for _, name in ipairs(order) do
                    if I[name](ctx, clause) then
                        done = true
                        break
                    end
                end
                if done then
                    handled = handled + 1
                else
                    unknown = unknown + 1
                end
            end
        end
        ctx.Addressed = addressed
        if noaskOnly and not ctx.NoAskUsed and #ctx.Steps == 0 and not ctx.Answer and not ctx.Replay then
            intent(ctx, "chat.noask")
            answer(ctx, "M\u{EC}nh ch\u{1EC9} h\u{1ECF}i khi quy\u{1EC1}n ch\u{1B0}a \u{111}\u{1B0}\u{1EE3}c b\u{1EAD}t. N\u{F3}i 'cho ph\u{E9}p ch\u{1EC9}nh giao di\u{1EC7}n', 'cho ph\u{E9}p \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t' ho\u{1EB7}c 'cho ph\u{E9}p t\u{1EF1} ch\u{1A1}i' th\u{EC} m\u{EC}nh s\u{1EBD} kh\u{F4}ng h\u{1ECF}i n\u{1EEF}a nh\u{E9}.", "I only ask when a permission isn't on yet. Say 'allow editing the interface', 'allow controlling the character' or 'allow free play' and I won't ask again.", "happy", 7)
        end
        do
            local keep = {}
            for _, item in ipairs(ctx.Steps) do
                if item.Perm == "Ui" and not (ctx.Env.perm("Ui") or (ctx.Assume and ctx.Assume.Ui)) then
                    ctx.Denied = ctx.Denied or {}
                    ctx.Denied.Ui = true
                    if not ctx.PendingSet then
                        ctx.PendingSet = { Kind = "grant", Perm = "Ui", Replay = ctx.A.Raw }
                    end
                else
                    keep[#keep + 1] = item
                end
            end
            ctx.Steps = keep
            if ctx.Denied then
                ctx.Mood = ctx.Mood or "think"
                ctx.Hold = ctx.Hold or 7
            end
        end
        if ctx.Summon and #ctx.Steps == 0 and not ctx.Answer then
            intent(ctx, "chat.summon")
            ctx.Answer = T(ctx, "M\u{EC}nh \u{111}\u{E2}y! B\u{1EA1}n c\u{1EA7}n g\u{EC} n\u{E0}o?", "I'm here! What do you need?")
            ctx.Mood = "listen"
            ctx.Hold = 6
        elseif handled == 0 and not ctx.Replay then
            if addressed and unknown == 0 then
                intent(ctx, "chat.summon")
                ctx.Answer = T(ctx, "M\u{EC}nh \u{111}\u{E2}y! B\u{1EA1}n c\u{1EA7}n g\u{EC} n\u{E0}o?", "I'm here! What do you need?")
                ctx.Mood = "listen"
                ctx.Hold = 6
            else
                intent(ctx, "chat.unknown")
                local tips = K.suggestions(ctx.Lang)
                ctx.Answer = T(ctx,
                    "M\u{EC}nh ch\u{1B0}a hi\u{1EC3}u \u{FD} b\u{1EA1}n l\u{1EAF}m. Th\u{1EED} n\u{F3}i ki\u{1EC3}u: '" .. tips[1] .. "', '" .. tips[2] .. "' hay '" .. tips[3] .. "'. Ho\u{1EB7}c h\u{1ECF}i 'b\u{1EA1}n l\u{E0}m \u{111}\u{1B0}\u{1EE3}c g\u{EC}'.",
                    "I didn't quite get that. Try something like: '" .. tips[1] .. "', '" .. tips[2] .. "' or '" .. tips[3] .. "'. Or ask 'what can you do'.")
                ctx.Mood = "confused"
                ctx.Hold = 6
                ctx.Unknown = true
            end
        end
        return ctx
    end

    local function joinSays(ctx, says)
        if #says <= 1 then
            return says[1] or ""
        end
        local last = table.remove(says)
        return table.concat(says, ", ") .. T(ctx, " v\u{E0} ", " and ") .. last
    end

    local function opener(ctx)
        return pick(ctx, ctx.Lang == "vi" and { "Xong r\u{1ED3}i!", "Ok n\u{E8}!", "\u{110}\u{1B0}\u{1EE3}c lu\u{F4}n!" } or { "Done!", "On it!", "All set!" })
    end

    local ASK = {
        Body = {
            "M\u{EC}nh ch\u{1B0}a \u{111}\u{1B0}\u{1EE3}c ph\u{E9}p \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t. B\u{1EA1}n cho ph\u{E9}p kh\u{F4}ng? N\u{F3}i 'ok' \u{111}\u{1EC3} m\u{EC}nh b\u{1EAD}t quy\u{1EC1}n n\u{E0}y nh\u{E9}.",
            "I don't have permission to control your character yet. Allow it? Say 'ok' and I'll enable it.",
        },
        Free = {
            "T\u{1EF1} ch\u{1A1}i t\u{1EF1} do c\u{1EA7}n quy\u{1EC1}n ri\u{EA}ng: m\u{EC}nh s\u{1EBD} t\u{1EF1} \u{111}i l\u{1EA1}i, nh\u{1EA3}y v\u{E0} n\u{E9} v\u{1EAD}t c\u{1EA3}n. N\u{F3}i 'ok' \u{111}\u{1EC3} cho ph\u{E9}p; mu\u{1ED1}n d\u{1EEB}ng l\u{FA}c n\u{E0}o ch\u{1EC9} c\u{1EA7}n n\u{F3}i 'd\u{1EEB}ng' ho\u{1EB7}c b\u{1EA5}m ph\u{ED}m di chuy\u{1EC3}n.",
            "Free play needs its own permission: I'll wander, jump and avoid obstacles by myself. Say 'ok' to allow it; say 'stop' or press a movement key any time to take over.",
        },
        Ui = {
            "M\u{EC}nh ch\u{1B0}a \u{111}\u{1B0}\u{1EE3}c ph\u{E9}p ch\u{1EC9}nh giao di\u{1EC7}n. B\u{1EA1}n cho ph\u{E9}p kh\u{F4}ng? N\u{F3}i 'ok' \u{111}\u{1EC3} m\u{EC}nh b\u{1EAD}t quy\u{1EC1}n n\u{E0}y nh\u{E9}.",
            "I don't have permission to edit the interface yet. Allow it? Say 'ok' and I'll enable it.",
        },
    }

    local function askText(ctx)
        if not ctx.Denied then
            return nil
        end
        for _, name in ipairs({ "Free", "Body", "Ui" }) do
            if ctx.Denied[name] then
                return T(ctx, ASK[name][1], ASK[name][2])
            end
        end
        return nil
    end

    function B.reply(ctx, failures)
        failures = failures or {}
        local ask = askText(ctx)
        if ask then
            local saved = ctx.Denied
            ctx.Denied = nil
            local base = B.reply(ctx, failures)
            ctx.Denied = saved
            return (base ~= "" and (base .. " ") or "") .. ask
        end
        if #ctx.Steps > 0 then
            local says = {}
            for _, item in ipairs(ctx.Steps) do
                if not failures[item] then
                    says[#says + 1] = ctx.Lang == "vi" and item.Say[1] or item.Say[2]
                end
            end
            local text = ""
            if #says > 0 then
                if ctx.Style == "cool" or ctx.Style == "warm" or ctx.Style == "random" then
                    local pair = ctx.LookPair
                    local themeText = themeName(ctx, pair[1])
                    local accentText = accentName(ctx, pair[2])
                    if ctx.Style == "cool" then
                        text = T(ctx,
                            string.format("%s %sM\u{EC}nh \u{111}\u{E3} \u{111}\u{1ED5}i UI sang t\u{F4}ng m\u{E1}t: giao di\u{1EC7}n %s + m\u{E0}u nh\u{1EA5}n %s cho d\u{1ECB}u m\u{1EAF}t. Ch\u{1B0}a \u{111}\u{1EE7} m\u{E1}t th\u{EC} n\u{F3}i 'm\u{E1}t h\u{1A1}n n\u{1EEF}a', mu\u{1ED1}n tr\u{1EA3} l\u{1EA1}i th\u{EC} n\u{F3}i 'ho\u{E0}n t\u{E1}c'.", opener(ctx), ctx.PreMood == "sweat" and "N\u{F3}ng th\u{1EAD}t! " or "", themeText, accentText),
                            string.format("%s %sI made the UI feel cooler: %s theme + %s accent. Want it chillier? Say 'even cooler'. To go back, say 'undo'.", opener(ctx), ctx.PreMood == "sweat" and "Phew, that's hot! " or "", themeText, accentText))
                    elseif ctx.Style == "warm" then
                        text = T(ctx,
                            string.format("%s M\u{EC}nh \u{111}\u{E3} \u{111}\u{1ED5}i UI sang t\u{F4}ng \u{1EA5}m: giao di\u{1EC7}n %s + m\u{E0}u nh\u{1EA5}n %s. Mu\u{1ED1}n tr\u{1EA3} l\u{1EA1}i th\u{EC} n\u{F3}i 'ho\u{E0}n t\u{E1}c'.", opener(ctx), themeText, accentText),
                            string.format("%s I warmed the UI up: %s theme + %s accent. Say 'undo' to go back.", opener(ctx), themeText, accentText))
                    else
                        text = T(ctx,
                            string.format("%s B\u{1EA5}t ng\u{1EDD} ch\u{1B0}a! Giao di\u{1EC7}n %s + m\u{E0}u nh\u{1EA5}n %s.", opener(ctx), themeText, accentText),
                            string.format("%s Surprise! %s theme + %s accent.", opener(ctx), themeText, accentText))
                    end
                else
                    local joined = joinSays(ctx, says)
                    text = T(ctx, opener(ctx) .. " M\u{EC}nh \u{111}\u{E3} " .. joined .. ".", opener(ctx) .. " I " .. joined .. ".")
                end
            end
            if ctx.Answer then
                text = ctx.Answer .. (text ~= "" and (" " .. text) or "")
            end
            return text
        end
        return ctx.Answer or ""
    end

    return B
end)()

