 w_fps w_ping w_rim w_ring w_split walk walked walkspeed warm warmwant watch webhook went what which whichtheme who win window wink xanh xoa xuat yes yourself youw")

local Music = {
    Playing = false,
    Index = 1,
    Volume = 60,
    Tempo = 1,
    Position = 0,
    Clock = 0,
    Phrase = 0,
    Auto = true,
    ShowIsland = true,
    Shuffle = false,
    RepeatOne = false,
    Fails = 0,
    Loading = false,
    Levels = { 0, 0, 0, 0, 0 },
    Listeners = {},
}

do
    local TRACKS = {
        { Name = "Lo-fi Chill A", Mood = "Lo-fi / Chill", Id = 9043887091, A = rgb(88, 86, 214), B = rgb(191, 90, 242) },
        { Name = "Relaxed Scene", Mood = "Relaxing", Id = 1848354536, A = rgb(64, 200, 224), B = rgb(10, 132, 255) },
        { Name = "Chill Jazz", Mood = "Jazz / Lounge", Id = 1845341094, A = rgb(255, 159, 10), B = rgb(255, 55, 95) },
        { Name = "Soft Music", Mood = "Soft / Ambient", Id = 1837429944, A = rgb(64, 200, 224), B = rgb(48, 209, 88) },
        { Name = "Piano Bar Jazz", Mood = "Piano / Jazz", Id = 1841979451, A = rgb(191, 90, 242), B = rgb(88, 86, 214) },
        { Name = "Smooth Vibes", Mood = "Smooth Chill", Id = 9044565954, A = rgb(48, 209, 88), B = rgb(64, 200, 224) },
        { Name = "Sunday In Bed", Mood = "Lo-fi / Relax", Id = 9047104336, A = rgb(255, 159, 10), B = rgb(191, 90, 242) },
        { Name = "Light Dreamer", Mood = "Dreamy", Id = 9047107124, A = rgb(10, 132, 255), B = rgb(191, 90, 242) },
        { Name = "Paradise Falls", Mood = "Cinematic", Id = 1837879082, A = rgb(48, 209, 88), B = rgb(10, 132, 255) },
        { Name = "Upbeat Electronica", Mood = "Electronic", Id = 1837849285, A = rgb(255, 55, 95), B = rgb(255, 159, 10) },
    }

    Music.Tracks = TRACKS

    local group = new("SoundGroup", { Name = "BoncutiPlaylistGroup", Volume = 1, Parent = SoundService })
    Music.Reverb = new("ReverbSoundEffect", {
        DecayTime = 1.5,
        Density = 0.5,
        Diffusion = 0.65,
        DryLevel = -1,
        WetLevel = -12,
        Parent = group,
    })
    Music.Eq = new("EqualizerSoundEffect", { LowGain = 1, MidGain = 0, HighGain = -1, Parent = group })

    local currentSound = new("Sound", {
        Name = "BoncutiPlaylistAudio",
        SoundId = "rbxassetid://" .. TRACKS[1].Id,
        Volume = Music.Volume / 100,
        PlaybackSpeed = Music.Tempo,
        Looped = false,
        SoundGroup = group,
        Parent = SoundService,
    })

    local loadToken = 0
    local function broadcast()
        for _, listener in ipairs(Music.Listeners) do
            pcall(listener)
        end
    end
    Music.Broadcast = broadcast

    Media.Title:SetAttribute("BoncutiRaw", true)
    Media.Sub:SetAttribute("BoncutiRaw", true)

    local function applyMedia(track)
        Media.ArtGradient.Color = ColorSequence.new(track.A, track.B)
        Media.Title.Text = track.Name
        Media.Sub.Text = track.Mood
        for _, bar in ipairs(Media.Bars) do
            bar.BackgroundColor3 = track.B
        end
    end

    function Music.Progress()
        local length = currentSound.TimeLength
        if length <= 0 then
            return 0
        end
        return math.clamp(currentSound.TimePosition / length, 0, 1)
    end

    function Music.Sync()
        local track = TRACKS[Music.Index]
        Music.Position = currentSound.TimePosition
        if Music.Playing and Music.ShowIsland then
            Activities.Music = {
                Title = track.Name,
                Color = track.B,
                Media = true,
                Short = function()
                    return "\u{266A}"
                end,
                Value = function()
                    return track.Name
                end,
                Ring = Music.Progress,
                RingMode = "fill",
            }
        else
            Activities.Music = nil
        end
        applyMedia(track)
        refreshActivity()
    end

    local function waitAndPlay(token, id)
        task.spawn(function()
            local deadline = os.clock() + 12
            while gui.Parent and token == loadToken and currentSound.SoundId == id and not currentSound.IsLoaded and os.clock() < deadline do
                task.wait(0.1)
            end
            if token ~= loadToken or currentSound.SoundId ~= id or not gui.Parent then
                return
            end
            if currentSound.IsLoaded then
                currentSound.Volume = 0
                currentSound.PlaybackSpeed = Music.Tempo
                currentSound:Play()
                tween(currentSound, 0.8, { Volume = Music.Volume / 100 }, Enum.EasingStyle.Sine)
                Music.Playing = true
                Music.Fails = 0
                Music.Sync()
                broadcast()
            else
                Music.Playing = false
                Music.Fails = Music.Fails + 1
                Music.Sync()
                broadcast()
                notify("Kh\u{F4}ng th\u{1EC3} t\u{1EA3}i nh\u{1EA1}c", "\u{C2}m thanh n\u{E0}y c\u{F3} th\u{1EC3} b\u{1ECB} gi\u{1EDB}i h\u{1EA1}n quy\u{1EC1}n truy c\u{1EAD}p trong tr\u{1EA3}i nghi\u{1EC7}m hi\u{1EC7}n t\u{1EA1}i.", "warn", 3)
                if Music.Auto and Music.Fails < 3 then
                    task.wait(0.8)
                    if token == loadToken and gui.Parent then
                        Music.Next(1)
                    end
                end
            end
        end)
    end

    local Remote = {
        Url = "https://pastefy.app/0QU2aU7c/raw",
        Folder = "BoncutiMusic",
        State = "idle",
        Count = 0,
        Busy = false,
        Listeners = {},
    }
    Music.Remote = Remote

    local Http
    pcall(function()
        Http = game:GetService("HttpService")
    end)

    local Covers = {
        { rgb(255, 55, 95), rgb(255, 159, 10) },
        { rgb(10, 132, 255), rgb(191, 90, 242) },
        { rgb(48, 209, 88), rgb(64, 200, 224) },
        { rgb(191, 90, 242), rgb(255, 55, 95) },
        { rgb(255, 159, 10), rgb(255, 214, 10) },
        { rgb(64, 200, 224), rgb(88, 86, 214) },
    }

    function Remote.Supported()
        return type(writefile) == "function" and (type(getcustomasset) == "function" or type(getsynasset) == "function")
    end

    function Remote.Notify()
        for _, listener in ipairs(Remote.Listeners) do
            pcall(listener)
        end
    end

    local function httpGet(url)
        local ok, data = pcall(function()
            return game:HttpGet(url)
        end)
        if ok and type(data) == "string" and #data > 0 then
            return data
        end
        if Http then
            ok, data = pcall(function()
                return Http:GetAsync(url)
            end)
            if ok and type(data) == "string" and #data > 0 then
                return data
            end
        end
        return nil
    end

    local function trim(value)
        local result = string.gsub(value, "^%s+", "")
        result = string.gsub(result, "%s+$", "")
        return result
    end

    local function decodeText(value)
        value = string.gsub(value, "\\u(%x%x%x%x)", function(hex)
            local ok, char = pcall(utf8.char, tonumber(hex, 16))
            return ok and char or ""
        end)
        value = string.gsub(value, "\\([\"\\/])", "%1")
        return value
    end

    local function textField(chunk, key)
        local value = string.match(chunk, '"' .. key .. '"%s*:%s*"(.-)"')
        if value then
            return decodeText(value)
        end
        return nil
    end

    local function stringOf(value)
        if type(value) == "string" then
            return trim(value)
        end
        return ""
    end

    local function collect(node, list)
        if type(node) ~= "table" then
            return
        end
        if type(node.name) == "string" and type(node.download_url) == "string" then
            table.insert(list, {
                Name = trim(node.name),
                Artist = stringOf(node.artist),
                Genre = stringOf(node.genre),
                Year = tonumber(node.release_year) or 0,
                Url = node.download_url,
            })
            return
        end
        if #node > 0 then
            for _, child in ipairs(node) do
                collect(child, list)
            end
        else
            for _, child in pairs(node) do
                collect(child, list)
            end
        end
    end

    local function parse(raw)
        local list = {}
        if Http then
            local ok, decoded = pcall(function()
                return Http:JSONDecode(raw)
            end)
            if ok then
                collect(decoded, list)
            end
        end
        if #list == 0 then
            for chunk in string.gmatch(raw, "%b{}") do
                local name = textField(chunk, "name")
                local url = textField(chunk, "download_url")
                if name and url then
                    table.insert(list, {
                        Name = trim(name),
                        Artist = trim(textField(chunk, "artist") or ""),
                        Genre = trim(textField(chunk, "genre") or ""),
                        Year = tonumber(string.match(chunk, '"release_year"%s*:%s*(%d+)')) or 0,
                        Url = url,
                    })
                end
            end
        end
        return list
    end

    local function cacheName(url)
        local hash = 5381
        for index = 1, #url do
            hash = (hash * 33 + string.byte(url, index)) % 4294967296
        end
        return string.format("%s/%08x.mp3", Remote.Folder, hash)
    end

    local function fetchRemote(token, track)
        task.spawn(function()
            Music.Loading = true
            broadcast()
            local ok, asset = pcall(function()
                local path = cacheName(track.Url)
                if not (type(isfile) == "function" and isfile(path)) then
                    local data = httpGet(track.Url)
                    if not data or #data < 1024 then
                        error("download")
                    end
                    if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder(Remote.Folder) then
                        makefolder(Remote.Folder)
                    end
                    writefile(path, data)
                end
                local getter = getcustomasset or getsynasset
                return getter(path)
            end)
            if token ~= loadToken or not gui.Parent then
                return
            end
            Music.Loading = false
            if ok and type(asset) == "string" and asset ~= "" then
                currentSound.SoundId = asset
                waitAndPlay(token, asset)
            else
                Music.Playing = false
                Music.Fails = Music.Fails + 1
                Music.Sync()
                broadcast()
                notify("Kh\u{F4}ng th\u{1EC3} t\u{1EA3}i b\u{E0}i h\u{E1}t", "Ki\u{1EC3}m tra k\u{1EBF}t n\u{1ED1}i ho\u{1EB7}c executor", "warn", 3)
                if Music.Auto and Music.Fails < 3 then
                    task.wait(0.8)
                    if token == loadToken and gui.Parent then
                        Music.Next(1)
                    end
                end
            end
        end)
    end

    function Remote.Load()
        if Remote.Busy or Remote.State == "ready" then
            return
        end
        if not Remote.Supported() then
            Remote.State = "unsupported"
            Remote.Notify()
            return
        end
        Remote.Busy = true
        Remote.State = "loading"
        Remote.Notify()
        task.spawn(function()
            local raw = httpGet(Remote.Url)
            local list = raw and parse(raw) or {}
            Remote.Busy = false
            if not gui.Parent then
                return
            end
            if #list == 0 then
                Remote.State = raw and "empty" or "failed"
            else
                for index, item in ipairs(list) do
                    local cover = Covers[(index - 1) % #Covers + 1]
                    local mood = item.Artist
                    if item.Genre ~= "" then
                        mood = mood ~= "" and (mood .. " \u{B7} " .. item.Genre) or item.Genre
                    end
                    if item.Year > 0 then
                        mood = mood ~= "" and (mood .. " \u{B7} " .. tostring(item.Year)) or tostring(item.Year)
                    end
                    table.insert(TRACKS, {
                        Name = item.Name,
                        Mood = mood,
                        Remote = true,
                        Url = item.Url,
                        A = cover[1],
                        B = cover[2],
                    })
                end
                Remote.Count = #list
                Remote.State = "ready"
            end
            Remote.Notify()
        end)
    end

    local function startLoad(token, track)
        if track.Remote then
            fetchRemote(token, track)
        else
            waitAndPlay(token, currentSound.SoundId)
        end
    end

    function Music.Select(index, play)
        Music.Index = (index - 1) % #TRACKS + 1
        local track = TRACKS[Music.Index]
        loadToken = loadToken + 1
        currentSound:Stop()
        Music.Playing = play and true or false
        Music.Loading = false
        Music.Position = 0
        Music.Clock = 0
        Music.Phrase = 0
        currentSound.SoundId = track.Remote and "" or ("rbxassetid://" .. track.Id)
        currentSound.TimePosition = 0
        currentSound.PlaybackSpeed = Music.Tempo
        currentSound.Volume = Music.Volume / 100
        Music.Sync()
        broadcast()
        if play then
            startLoad(loadToken, track)
        end
    end

    function Music.Toggle()
        if Music.Playing then
            loadToken = loadToken + 1
            Music.Playing = false
            Music.Loading = false
            tween(currentSound, 0.2, { Volume = 0 })
            task.delay(0.22, function()
                if not Music.Playing then
                    currentSound:Pause()
                end
            end)
            Music.Sync()
            broadcast()
            return
        end
        if currentSound.IsLoaded and currentSound.TimePosition > 0 then
            currentSound.Volume = 0
            currentSound.PlaybackSpeed = Music.Tempo
            currentSound:Resume()
            tween(currentSound, 0.6, { Volume = Music.Volume / 100 }, Enum.EasingStyle.Sine)
            Music.Playing = true
            Music.Sync()
            broadcast()
        else
            loadToken = loadToken + 1
            Music.Playing = true
            Music.Sync()
            startLoad(loadToken, TRACKS[Music.Index])
        end
    end

    function Music.Next(direction)
        if Music.Shuffle and direction > 0 and #TRACKS > 1 then
            local nextIndex = Music.Index
            while nextIndex == Music.Index do
                nextIndex = math.random(1, #TRACKS)
            end
            Music.Select(nextIndex, true)
        else
            Music.Select(Music.Index + direction, true)
        end
    end

    function Music.SetVolume(value)
        Music.Volume = math.clamp(value, 0, 100)
        currentSound.Volume = Music.Volume / 100
    end

    function Music.SetTempo(value)
        Music.Tempo = math.clamp(value, 0.7, 1.4)
        currentSound.PlaybackSpeed = Music.Tempo
    end

    function Music.Seek(alpha)
        local length = currentSound.TimeLength
        if length > 0 then
            currentSound.TimePosition = math.clamp(alpha, 0, 1) * length
            Music.Position = currentSound.TimePosition
        end
    end

    function Music.Duration()
        return math.max(0, currentSound.TimeLength)
    end

    currentSound.Ended:Connect(function()
        if not Music.Playing then
            return
        end
        if Music.RepeatOne then
            Music.Select(Music.Index, true)
        elseif Music.Auto then
            Music.Next(1)
        else
            Music.Playing = false
            Music.Position = 0
            Music.Sync()
            broadcast()
        end
    end)

    Music.Sync()

    table.insert(Hooks.Tasks, function(dt)
        local levels = Music.Levels
        local loudness = Music.Playing and math.clamp(currentSound.PlaybackLoudness / 850, 0, 1) or 0
        for index = 1, 5 do
            local wave = 0.18 + 0.82 * math.abs(math.sin(os.clock() * (3.2 + index * 0.83) + index * 1.4))
            local target = Music.Playing and math.clamp(loudness * wave + 0.04, 0, 1) or 0
            levels[index] = levels[index] + (target - levels[index]) * math.clamp(dt * 10, 0, 1)
        end
        Music.Position = currentSound.TimePosition
        if Music.Playing and Island.Live and Island.Live.Media then
            for index, bar in ipairs(Media.Bars) do
                local level = math.clamp(levels[index] + 0.08, 0, 1)
                bar.Size = UDim2.fromOffset(3, 3 + 15 * level)
            end
        end
    end)

    gui.Destroying:Connect(function()
        pcall(function()
            currentSound:Stop()
            currentSound:Destroy()
            group:Destroy()
        end)
    end)
end

do
    local PAGE_ORDER = { "Home", "Music", "Cross", "Timer", "Stopwatch", "Download" }
    local PAGE_TITLES = { Home = "T\u{1ED5}ng quan", Music = "\u{C2}m nh\u{1EA1}c", Timer = "H\u{1EB9}n gi\u{1EDD}", Stopwatch = "B\u{1EA5}m gi\u{1EDD}", Download = "T\u{1EA3}i xu\u{1ED1}ng", Cross = "Cross" }
    local PAGE_W = ISLAND.ExpandW
    local PAGE_H = ISLAND.ExpandH
    local DOCK_Y = PAGE_H - 40
    local SWIPE = 44
    local IDLE_COLLAPSE = 20
    local View = {
        Pages = {},
        Tabs = {},
        Updaters = {},
        Quick = {},
        Current = "Home",
        Touched = 0,
        Shown = {},
        BubbleText = "",
        BubbleAt = 0,
        Toasts = {},
        ToastBusy = false,
        ToastSkip = false,
        ToastToken = 0,
        Gesture = nil,
        SeekStamp = 0,
        TickAt = 0,
        DockLang = "",
        Inset = 36,
    }
    pcall(function()
        View.Inset = game:GetService("GuiService"):GetGuiInset().Y
    end)

    local function pageIndex(key)
        for index, name in ipairs(PAGE_ORDER) do
            if name == key then
                return index
            end
        end
        return 1
    end

    View.group = new("CanvasGroup", {
        Name = "Expanded",
        AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.fromOffset(PAGE_W / 2, 0),
        Size = UDim2.fromOffset(PAGE_W, PAGE_H),
        BackgroundTransparency = 1,
        GroupTransparency = 1,
        Visible = false,
        Parent = Media.Content,
    })
    View.sink = new("TextButton", {
        Name = "Sink",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutoButtonColor = false,
        Text = "",
        ZIndex = 1,
        Parent = View.group,
    })

    local function fmt(seconds)
        seconds = math.max(0, seconds)
        return string.format("%d:%02d", math.floor(seconds / 60), math.floor(seconds % 60))
    end

    local function put(label, value)
        if label.Text ~= value then
            label.Text = value
        end
    end

    local function label(parent, props)
        props.Parent = parent
        props.TextColor3 = props.TextColor3 or Static.White
        props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
        return text(props)
    end

    local function raw(item)
        item:SetAttribute("BoncutiRaw", true)
        return item
    end

    local function makePage(key)
        local page = new("CanvasGroup", {
            Name = key,
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            GroupTransparency = 1,
            Visible = false,
            ZIndex = 2,
            Parent = View.group,
        })
        View.Pages[key] = page
        return page
    end

    local function pressable(button)
        Glass.Touch(button)
        local scale = new("UIScale", { Parent = button })
        local spring = Spring.new(1, 600, 30, function(value)
            scale.Scale = value
        end, 0.001)
        button.MouseButton1Down:Connect(function()
            spring:Set(0.92)
        end)
        button.MouseButton1Up:Connect(function()
            spring:Set(1)
        end)
        button.MouseLeave:Connect(function()
            spring:Set(1)
        end)
        return spring
    end

    local function touch(callback)
        return function()
            View.Touched = os.clock()
            playSound("click")
            callback()
        end
    end

    local function shine(parent, radius, amount)
        local gloss = box({
            Name = "Shine",
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Static.White,
            ZIndex = 4,
            Parent = parent,
        })
        corner(radius, gloss)
        new("UIGradient", {
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, amount or 0.84),
                NumberSequenceKeypoint.new(0.55, 1),
                NumberSequenceKeypoint.new(1, 1),
            }),
            Rotation = 90,
            Parent = gloss,
        })
        return gloss
    end

    local function action(parent, x, y, w, h, caption, color, callback)
        local radius = math.floor(h / 2.4)
        local button = box({
            Class = "TextButton",
            Position = UDim2.fromOffset(x, y),
            Size = UDim2.fromOffset(w, h),
            BackgroundColor3 = color or Static.White,
            BackgroundTransparency = color and 0 or 0.88,
            AutoButtonColor = false,
            Text = translate(caption),
            FontFace = Fonts.Semibold,
            TextSize = 13,
            TextColor3 = Static.White,
            ZIndex = 5,
            Parent = parent,
        })
        corner(radius, button)
        stroke(button, Static.White, color and 0.8 or 0.9, 1)
        Glass.Pane(button, color and "tint" or "clear")
        shine(button, radius, color and 0.82 or 0.9)
        pressable(button)
        button.MouseButton1Click:Connect(touch(callback))
        return button
    end

    local function icon(parent, kind, x, y, size, color)
        local holder = new("Frame", {
            Name = "Icon",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromOffset(x, y),
            Size = UDim2.fromOffset(size, size),
            BackgroundTransparency = 1,
            ZIndex = 6,
            Parent = parent,
        })
        local function add(px, py, pw, ph, radius)
            local part = new("Frame", {
                Position = UDim2.fromOffset(px, py),
                Size = UDim2.fromOffset(pw, ph),
                BackgroundColor3 = color,
                BorderSizePixel = 0,
                ZIndex = 6,
                Parent = holder,
            })
            if radius then
                new("UICorner", { CornerRadius = UDim.new(0, radius), Parent = part })
            end
        end
        local function wedge(origin, width, height, mirrored)
            local steps = math.max(6, math.floor(width * 1.5 + 0.5))
            local step = width / steps
            for index = 0, steps - 1 do
                local along = (index + 0.5) / steps
                local tall = math.max(height * (mirrored and along or (1 - along)), 1)
                add(origin + index * step, (size - tall) / 2, step + 0.5, tall)
            end
        end
        if kind == "play" then
            wedge(size * 0.24, size * 0.68, size * 0.8, false)
        elseif kind == "pause" then
            local bar = size * 0.22
            add(size * 0.2, size * 0.12, bar, size * 0.76, bar * 0.45)
            add(size * 0.58, size * 0.12, bar, size * 0.76, bar * 0.45)
        elseif kind == "next" then
            wedge(size * 0.1, size * 0.52, size * 0.64, false)
            add(size * 0.68, size * 0.18, size * 0.14, size * 0.64, 1)
        elseif kind == "prev" then
            add(size * 0.18, size * 0.18, size * 0.14, size * 0.64, 1)
            wedge(size * 0.38, size * 0.52, size * 0.64, true)
        end
        return holder
    end

    local function rail(parent, x, y, w, h, color, knob)
        local track_ = box({
            Position = UDim2.fromOffset(x, y),
            Size = UDim2.fromOffset(w, h),
            BackgroundColor3 = Static.White,
            BackgroundTransparency = 0.82,
            Parent = parent,
        })
        corner(h / 2, track_)
        local fill = box({
            Size = UDim2.new(0, 0, 1, 0),
            BackgroundColor3 = color,
            Parent = track_,
        })
        corner(h / 2, fill)
        local dot
        if knob then
            dot = box({
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(1, 0, 0.5, 0),
                Size = UDim2.fromOffset(knob, knob),
                BackgroundColor3 = Static.White,
                ZIndex = 3,
                Parent = fill,
            })
            corner(knob / 2, dot)
        end
        return track_, fill, dot
    end

