        Radius = 14,
        ZIndex = 4,
        Active = function()
            return View.crossSideOpen
        end,
    })

    local function sideApply(open, room)
        View.crossSideOpen = open
        View.crossSideW = open and room or 0
        Isl.setIslandMode("expand", PAGE_W + View.crossSideW, PAGE_H)
        if open then
            View.crossSide.Visible = true
            View.crossSideShell.Refresh(true, true)
            tween(View.crossSide, 0.3, { GroupTransparency = 0 })
        else
            tween(View.crossSide, 0.16, { GroupTransparency = 1 })
            task.delay(0.22, function()
                if not View.crossSideOpen then
                    View.crossSide.Visible = false
                end
            end)
        end
        local pinned = View.crossSidePin
        tween(View.crossShellBtn, 0.2, {
            BackgroundColor3 = pinned and P.Accent or Static.White,
            BackgroundTransparency = pinned and 0.3 or 0.88,
        })
    end

    function View.crossEnter(fromTab)
        if not fromTab and View.crossSideRoom() > 0 then
            View.crossSidePin = true
            View.crossMode("chat", true)
        else
            View.crossMode(fromTab and "chat" or "shell", true)
        end
    end

    local sidePinned = false
    table.insert(Hooks.Tasks, function()
        if not Island.Expanded then
            View.crossSidePin = false
            if View.crossSideOpen then
                View.crossSideOpen = false
                View.crossSideW = 0
                View.crossSide.Visible = false
                View.crossSide.GroupTransparency = 1
            end
            return
        end
        local room = 0
        local want = false
        if View.Current == "Cross" and View.CrossMode == "chat" and not Island.Alerting then
            room = View.crossSideRoom()
            if room > 0 then
                local active = Cross.Busy > 0 or Cross.Thinking or (Cross.Body and Cross.Body.Active) or os.clock() < Cross.ShellHold
                want = View.crossSidePin or active
            end
        end
        if want ~= View.crossSideOpen or (want and room ~= View.crossSideW) then
            sideApply(want, room)
        elseif sidePinned ~= View.crossSidePin then
            sideApply(View.crossSideOpen, View.crossSideW)
        end
        sidePinned = View.crossSidePin
    end)

    function View.crossMode(mode, instant)
        if View.CrossMode == mode and not instant then
            return
        end
        View.CrossMode = mode
        local chat = mode == "chat"
        local keep, show = View.crossTerm, View.crossChat
        if not chat then
            keep, show = View.crossChat, View.crossTerm
        end
        if instant then
            show.Visible = true
            show.GroupTransparency = 0
            keep.GroupTransparency = 1
            keep.Visible = false
        else
            show.Visible = true
            tween(show, 0.26, { GroupTransparency = 0 })
            tween(keep, 0.16, { GroupTransparency = 1 })
            task.delay(0.2, function()
                if View.CrossMode == mode then
                    keep.Visible = false
                end
            end)
        end
        if not chat then
            View.crossShell.Refresh(true, false)
            pcall(function()
                View.crossBox:ReleaseFocus()
            end)
        end
        View.Touched = os.clock()
    end

    View.Updaters.Cross = function()
        local bubble = Cross.Bubble
        local full, visible = bubble.Full, bubble.Entry and bubble.Entry.Visible or -1
        if Cross.Thinking then
            full, visible = string.rep(".", 1 + math.floor(os.clock() * 3) % 3), -1
        elseif full == "" then
            full, visible = Settings.Language == "en" and "I'm Cross. Type something, or ask 'what can you do'!" or "M\u{EC}nh l\u{E0} Cross. Nh\u{1EAF}n g\u{EC} \u{111}\u{F3}, ho\u{1EB7}c h\u{1ECF}i 'b\u{1EA1}n l\u{E0}m \u{111}\u{1B0}\u{1EE3}c g\u{EC}' nh\u{E9}!", -1
        end
        if not Cross.Grapheme then
            if visible >= 0 then
                full = Cross.prefix(full, visible)
            end
            visible = -1
        end
        if View.crossText.Text ~= full or View.crossShownCount ~= visible then
            View.crossText.Text = full
            View.crossShownCount = visible
            if Cross.Grapheme and View.crossText.MaxVisibleGraphemes ~= visible then
                View.crossText.MaxVisibleGraphemes = visible
            end
            local fraction = visible < 0 and 1 or math.clamp(visible / math.max(Cross.length(full), 1), 0, 1)
            local ok, room = pcall(function()
                return View.crossScroll.AbsoluteCanvasSize.Y - View.crossScroll.AbsoluteWindowSize.Y
            end)
            if ok and type(room) == "number" and room > 0 then
                View.crossScroll.CanvasPosition = Vector2.new(0, room * fraction)
            end
        end
        put(View.crossEcho, Cross.Echo ~= "" and ("\u{203A} " .. Cross.Echo) or "")
        local moving = Cross.Body and Cross.Body.Active and true or false
        if View.crossStop.Visible ~= moving then
            View.crossStop.Visible = moving
            View.crossEcho.Size = UDim2.fromOffset(moving and 176 or 238, 20)
        end
        local focused = false
        pcall(function()
            focused = View.crossBox:IsFocused()
        end)
        if focused or Cross.Busy > 0 or os.clock() < Cross.SpeakUntil then
            View.Touched = os.clock()
        end
    end

    Fwd.crossOpen = function(mode, focus)
        task.spawn(function()
            local tries = 0
            while (Island.Alerting or Island.Busy or not State.Ready) and tries < 60 do
                task.wait(0.05)
                tries = tries + 1
            end
            if not Island.Expanded then
                Isl.expand("Cross")
            end
            if Island.Expanded then
                if View.Current ~= "Cross" then
                    View.show("Cross")
                end
                View.crossMode(mode or "chat")
                View.Touched = os.clock()
                if focus then
                    task.wait(0.3)
                    View.crossFocus()
                end
            end
        end)
    end

    Fwd.crossSync = function()
        if Island.Expanded then
            View.refresh()
        end
    end

    do
        local black = Color3.new(0, 0, 0)
        local skin = { T = 1, D = 0.35 }
        local accented = {}

        View.IslandTones = {
            { "Theo giao di\u{1EC7}n", rgb(150, 154, 166) },
            { "\u{110}en", rgb(46, 46, 52) },
            { "Xanh d\u{1B0}\u{1A1}ng", rgb(10, 132, 255) },
            { "T\u{ED}m", rgb(191, 90, 242) },
            { "H\u{1ED3}ng", rgb(255, 55, 95) },
            { "Cam", rgb(255, 159, 10) },
            { "Xanh l\u{E1}", rgb(48, 209, 88) },
            { "Ng\u{1ECD}c", rgb(64, 200, 224) },
        }

        local function luma(color)
            return color.R * 0.299 + color.G * 0.587 + color.B * 0.114
        end

        local function target()
            local custom = Fwd.islandTheme and Fwd.islandTheme.colors()
            if custom then
                return custom[1], custom[2]
            end
            local tone = Settings.IslandTone
            if tone then
                local top = tone:Lerp(black, 0.34)
                local bottom = tone:Lerp(black, 0.9)
                return top, bottom
            end
            local base = luma(P.Window) < 0.3 and P.Card or P.Text
            local top = base:Lerp(P.Accent, 0.07):Lerp(black, 0.2)
            local bottom = base:Lerp(P.Accent, 0.12):Lerp(black, 0.86)
            return top, bottom
        end

        local function apply(top, bottom)
            local sequence = ColorSequence.new(top, bottom)
            Isl.bodyGradient.Color = sequence
            Isl.bubbleGradient.Color = sequence
        end

        local function follow(inst, prop)
            if inst then
                table.insert(accented, { inst, prop })
                inst[prop] = P.Accent
            end
        end

        View.follow = follow

        follow(View.loadFill, "BackgroundColor3")
        for _, child in ipairs(loadPage:GetChildren()) do
            if child:IsA("TextLabel") and child.TextColor3 == Static.Blue then
                follow(child, "TextColor3")
            end
        end
        follow(View.crossSend, "BackgroundColor3")

        skin.Top, skin.Bottom = target()
        skin.FromTop, skin.FromBottom = skin.Top, skin.Bottom
        apply(skin.Top, skin.Bottom)

        local function retarget(duration)
            local top, bottom = target()
            local a = 1 - (1 - skin.T) ^ 3
            skin.FromTop = skin.FromTop:Lerp(skin.Top, a)
            skin.FromBottom = skin.FromBottom:Lerp(skin.Bottom, a)
            skin.Top, skin.Bottom = top, bottom
            skin.D = math.max(duration or 0.35, 0.05)
            skin.T = 0
        end

        function View.islandRecolor(duration)
            retarget(duration or 0.35)
        end
        Fwd.IslandTones = View.IslandTones
        Fwd.islandRecolor = View.islandRecolor

        table.insert(Hooks.Tasks, function(dt)
            if skin.T >= 1 then
                return
            end
            skin.T = math.min(skin.T + dt / skin.D, 1)
            local a = 1 - (1 - skin.T) ^ 3
            apply(skin.FromTop:Lerp(skin.Top, a), skin.FromBottom:Lerp(skin.Bottom, a))
        end)

        table.insert(paletteListeners, function(duration)
            retarget(duration)
            for _, item in ipairs(accented) do
                tween(item[1], skin.D, { [item[2]] = P.Accent })
            end
            for _, entry in ipairs(View.Quick) do
                if entry.Def.Accent and entry.On then
                    tween(entry.Button, skin.D, { BackgroundColor3 = P.Accent })
                end
            end
            if Island.Expanded and not Island.Live then
                tween(Isl.tint, skin.D, { BackgroundColor3 = P.Accent })
            end
        end)
    end

