    View.Updaters.Stopwatch = function()
        local watch = Activities.Stopwatch
        if watch then
            put(View.watchBig, watch.Value())
            local running = watch.Title == "B\u{1EA5}m gi\u{1EDD}"
            put(View.watchTitle, translate(watch.Title))
            put(View.watchToggle, translate(running and "T\u{1EA1}m ng\u{1EEB}ng" or "Ti\u{1EBF}p t\u{1EE5}c"))
            local lap = watch.Lap
            put(View.watchLap, lap and (translate("V\u{F2}ng") .. " " .. lap.Index .. "  \u{B7}  " .. lap.Text) or "")
