function Win.aimIsland()
    local view = camera.ViewportSize
    local scale = math.max(Win.holderScale.Scale, 0.1)
    local centerX = view.X / 2 + Win.winPos.X
    local centerY = view.Y / 2 + Win.winPos.Y
    Win.riseDX = (view.X / 2 - centerX) / scale
    Win.riseDY = (ISLAND.Top + ISLAND.H / 2 - centerY) / scale
end

Spr.springHolderScale = Spring.new(1, 220, 26, function(value)
    Win.holderScale.Scale = value
end, 0.0005)

function Win.fitScale()
    local viewport = camera.ViewportSize
    local curW = currentWinW or WIN_W
    local bound = math.min(viewport.X / (curW + 40), viewport.Y / (WIN_H + 110))
    local base = math.clamp(bound, 0.5, 1)
    return math.clamp(base * ScaleFactors[Settings.Scale], 0.5, math.max(bound, 0.5))
end

function Win.applyScale(animated)
    local target = Win.fitScale()
    if animated then
        Spr.springHolderScale:Set(target)
    else
        Spr.springHolderScale:Snap(target)
    end
    islandState.Base = math.clamp(camera.ViewportSize.X / 430, 0.6, 1)
    Isl.layoutIsland()
end

