    end)

    local drag = { Active = false, Start = nil, X = 0, Y = 0 }

    local function clampPosition(x, y)
        local viewport = camera.ViewportSize
        local scale = Win.holderScale.Scale
        local curW = currentWinW or WIN_W
        local halfW = curW * scale / 2
        local halfH = WIN_H * scale / 2
        local minX = -viewport.X / 2 - halfW + 120
        local maxX = viewport.X / 2 + halfW - 120
        local minY = -viewport.Y / 2 + 10 + halfH
        local maxY = viewport.Y / 2 - 60 + halfH
        return math.max(minX, math.min(maxX, x)), math.max(minY, math.min(maxY, y))
    end

    titlebar.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if Search.Hits and Search.Hits(input.Position) then
                return
            end
            drag.Active = true
            drag.Start = input.Position
            drag.X = Spr.springPosX.Target
            drag.Y = Spr.springPosY.Target
        end
    end)

    track(UserInputService.InputChanged:Connect(function(input)
        if drag.Active and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - drag.Start
            local x, y = clampPosition(drag.X + delta.X, drag.Y + delta.Y)
            Spr.springPosX:Set(x)
            Spr.springPosY:Set(y)
        end
    end))

    track(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            drag.Active = false
        end
    end))
end

Fwd.setWindow = function(open)
    if open and not Auth.Session then
        return
    end
    if State.Open == open then
        return
    end
    State.Open = open
    if not open and Fwd.multitaskMenu then
        Fwd.multitaskMenu.close(true)
    end
    if not open and Cross.releaseFocus then
        Cross.releaseFocus()
    end
    if open then
        local held = Glass.World.grab()
        holder.Visible = true
        Win.aimIsland()
        window.GroupTransparency = 1
        Spr.springWindowScale:Snap(Win.MorphFrom)
        Spr.springWindowScale:Set(1)
        Spr.springWindowRise:Snap(0)
        Spr.springWindowRise:Set(1)
        if held then
            task.delay(0.07, function()
                if State.Open then
                    tween(window, 0.24, { GroupTransparency = 0 })
                end
            end)
        else
            tween(window, 0.24, { GroupTransparency = 0 })
        end
        if Settings.Blur then
            tween(blur, 0.45, { Size = Settings.BlurSize })
        end
        playSound("open")
        if Isl.pop then
            Isl.pop(0.1)
        end
        if Fwd.motion then
            Fwd.motion.open()
        end
    else
        playSound("close")
        Win.aimIsland()
        Spr.springWindowScale:Set(Win.MorphFrom)
        Spr.springWindowRise:Set(0)
        task.delay(0.12, function()
            if not State.Open then
                tween(window, 0.2, { GroupTransparency = 1 })
            end
        end)
        tween(blur, 0.3, { Size = 0 })
        task.delay(0.5, function()
            if not State.Open then
                holder.Visible = false
                Glass.World.hide()
            end
        end)
    end
end

