Spr.springHighlight = Spring.new(0, 360, 30, function(value)
    local spring = Spr.springHighlight
    local velocity = spring and spring.Velocity or 0
    local stretch = math.min(math.abs(velocity) * 0.035, 10)
    local lead = velocity < 0 and stretch or 0
    Win.highlight.Position = UDim2.fromOffset(stretch * 0.17, value - lead)
    Win.highlight.Size = UDim2.new(1, -stretch * 0.34, 0, 36 + stretch)
end, 0.05)

