function Multitask.applyLayout(instant)
    local count = #Multitask.Tabs
    if count == 0 then
        if currentTab and tabs[currentTab] then
            Multitask.Tabs = { currentTab }
            count = 1
        else
            Multitask.Tabs = { "LoopDash" }
            count = 1
        end
    end

    local targetW = WIN_W
    if count == 2 then
        targetW = 880
    elseif count == 3 then
        targetW = 1060
    elseif count >= 4 then
        targetW = 1240
    end
    if Spr.springWindowWidth then
        if instant then
            Spr.springWindowWidth:Snap(targetW)
        else
            Spr.springWindowWidth:Set(targetW)
        end
    end

    for tabName, tab in pairs(tabs) do
        local activeIndex = nil
        for idx, name in ipairs(Multitask.Tabs) do
            if name == tabName then
                activeIndex = idx
                break
            end
        end

        if activeIndex then
            local entering = not tab.page.Visible or tab.page.GroupTransparency > 0.6
            tab.page.Visible = true
            tab.fade = (tab.fade or 0) + 1

            if count > 1 then
                local head = tab.multiHeader or Mk.createMultiHeader(tabName, tab)
                head.Visible = true
                tab.scroll.Position = UDim2.fromOffset(0, 30)
                tab.scroll.Size = UDim2.new(1, 0, 1, -30)
                corner(14, tab.page)
                tab.page.BackgroundTransparency = 0.72
                tab.page.BackgroundColor3 = P.Window or rgb(20, 20, 24)
            else
                if tab.multiHeader then
                    tab.multiHeader.Visible = false
                end
                tab.scroll.Position = UDim2.fromOffset(0, 0)
                tab.scroll.Size = UDim2.fromScale(1, 1)
                tab.page.BackgroundTransparency = 1
            end

            local targetPos, targetSize
            if count == 1 then
                targetPos = UDim2.fromOffset(0, 0)
                targetSize = UDim2.fromScale(1, 1)
            else
                local gap = 8
                targetPos = UDim2.new((activeIndex - 1) / count, (activeIndex - 1) * gap / count, 0, 0)
                targetSize = UDim2.new(1 / count, -(count - 1) * gap / count, 1, 0)
            end

            if instant then
                tab.page.Position = targetPos
                tab.page.Size = targetSize
                tab.page.GroupTransparency = 0
            else
                if entering and count == 1 then
                    tab.page.Position = UDim2.fromOffset(0, 18)
                    tab.page.GroupTransparency = 1
                end
                tween(tab.page, entering and 0.42 or 0.28, {
                    Position = targetPos,
                    Size = targetSize,
                    GroupTransparency = 0,
                })
                if entering and Fwd.motion then
                    Fwd.motion.enter(tab)
                end
            end

            tween(tab.label, 0.25, { TextColor3 = P.Text })
            if activeIndex == 1 then
                if instant then
                    Spr.springHighlight:Snap(tab.y)
                else
                    Spr.springHighlight:Set(tab.y)
                end
            end
            if count > 1 then
                tween(tab.button, 0.2, { BackgroundTransparency = 0.88 })
            else
                tween(tab.button, 0.2, { BackgroundTransparency = 1 })
            end
        else
            tween(tab.label, 0.25, { TextColor3 = P.Sub })
            tween(tab.button, 0.2, { BackgroundTransparency = 1 })
            if tab.page.Visible then
                tab.fade = (tab.fade or 0) + 1
                local token = tab.fade
                if not instant then
                    tween(tab.page, 0.16, { GroupTransparency = 1 })
                    task.delay(0.18, function()
                        if tab.fade == token and not Multitask.isTabActive(tabName) then
                            tab.page.Visible = false
                        end
                    end)
                else
                    tab.page.Visible = false
                end
            end
        end
    end

    if MultiTaskBtn and MultiTaskBtn.update then
        MultiTaskBtn.update()
    end
end

function Multitask.toggleTab(name, quiet)
    if not tabs[name] or (name == "Test" and not testTabVisible) or Fwd.isSynth() then
        return
    end
    playSound("tick")
    local foundIdx = nil
    for idx, tName in ipairs(Multitask.Tabs) do
        if tName == name then
            foundIdx = idx
            break
        end
    end

    if foundIdx then
        if #Multitask.Tabs > 1 then
            table.remove(Multitask.Tabs, foundIdx)
            currentTab = Multitask.Tabs[1]
            if not quiet then
                notify("\u{110}a nhi\u{1EC7}m", translate("\u{110}\u{E3} \u{111}\u{F3}ng tab ") .. translate(tabs[name].labelKey), "info", 1.8)
            end
        else
            notify("\u{110}a nhi\u{1EC7}m", translate("C\u{1EA7}n gi\u{1EEF} \u{ED}t nh\u{1EA5}t m\u{1ED9}t tab \u{111}ang m\u{1EDF}"), "info", 1.8)
            return
        end
    else
        if #Multitask.Tabs >= Multitask.Max then
            table.remove(Multitask.Tabs)
            notify("\u{110}a nhi\u{1EC7}m", translate("\u{110}\u{E3} \u{111}\u{1EA1}t t\u{1ED1}i \u{111}a s\u{1ED1} tab, \u{111}\u{E3} thay tab cu\u{1ED1}i"), "info", 1.8)
        elseif not quiet then
            notify("\u{110}a nhi\u{1EC7}m", translate("\u{110}\u{E3} m\u{1EDF} song song tab ") .. translate(tabs[name].labelKey), "success", 1.8)
        end
        table.insert(Multitask.Tabs, name)
        currentTab = name
    end
    Multitask.applyLayout(false)
end

function Multitask.addTab(name)
    if not tabs[name] or (name == "Test" and not testTabVisible) or Fwd.isSynth() then
        return
    end
    if Multitask.isTabActive(name) then
        return
    end
    if #Multitask.Tabs >= Multitask.Max then
        table.remove(Multitask.Tabs)
    end
    table.insert(Multitask.Tabs, name)
    currentTab = name
    Multitask.applyLayout(false)
end

function Multitask.remove(name)
    local foundIdx = nil
    for idx, tName in ipairs(Multitask.Tabs) do
        if tName == name then
            foundIdx = idx
            break
        end
    end
    if foundIdx and #Multitask.Tabs > 1 then
        playSound("tick")
        table.remove(Multitask.Tabs, foundIdx)
        currentTab = Multitask.Tabs[1]
        Multitask.applyLayout(false)
    end
end

function Mk.createPage(name)
    local group = new("CanvasGroup", {
        Name = name,
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Visible = false,
        Parent = Win.contentArea,
    })
    local scroll = new("ScrollingFrame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageTransparency = 0.7,
        CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        Parent = group,
    })
    paint(scroll, "ScrollBarImageColor3", "Text")
    new("UIListLayout", {
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = scroll,
    })
    new("UIPadding", {
        PaddingRight = UDim.new(0, 8),
        PaddingBottom = UDim.new(0, 10),
        Parent = scroll,
    })
    return group, scroll
end

local function addTab(name, label, color, glyph, hidden)
    if hidden then
        local _, hiddenScroll = Mk.createPage(name)
        return hiddenScroll
    end
    tabCount = tabCount + 1
    local y = (tabCount - 1) * 40

    local button = box({
        Class = "TextButton",
        Name = name,
        Position = UDim2.fromOffset(0, y),
        Size = UDim2.new(1, 0, 0, 36),
        BackgroundColor3 = Static.White,
        BackgroundTransparency = 1,
        AutoButtonColor = false,
        Text = "",
        Parent = sidebar,
    })
    corner(10, button)
    Glass.Touch(button)

    local icon = box({
        Position = UDim2.fromOffset(9, 7),
        Size = UDim2.fromOffset(22, 22),
        BackgroundColor3 = color,
        Parent = button,
    })
    corner(6, icon)
    Glass.Pane(icon, "tint")
    text({
        Size = UDim2.fromScale(1, 1),
        Text = glyph,
        FontFace = Fonts.Bold,
        TextSize = 15,
        TextColor3 = Static.White,
        Parent = icon,
    })

    local title = text({
        Position = UDim2.fromOffset(42, 0),
        Size = UDim2.new(1, -48, 1, 0),
        Text = label,
        FontFace = Fonts.Medium,
        TextSize = 14,
        TextColor3 = P.Sub,
        TextXAlignment = Enum.TextXAlignment.Left,
        Parent = button,
    })

    local page, scroll = Mk.createPage(name)
    tabs[name] = {
        y = y,
        button = button,
        label = title,
        page = page,
        scroll = scroll,
        color = color,
        glyph = glyph,
        labelKey = label,
    }

    table.insert(paletteListeners, function(duration)
        tween(title, duration, { TextColor3 = (currentTab == name or Multitask.isTabActive(name)) and P.Text or P.Sub })
    end)

    button.MouseEnter:Connect(function()
        if currentTab ~= name then
            tween(button, 0.15, { BackgroundTransparency = 0.94 })
        end
    end)
    button.MouseLeave:Connect(function()
        tween(button, 0.2, { BackgroundTransparency = 1 })
    end)
    button.MouseButton1Click:Connect(function()
        playSound("tick")

        if name == "Settings" then
            local now = os.clock()
            if now - settingsClickTime <= 0.36 then
                settingsClickTime = 0
                if Fwd.toggleTestTab then
                    Fwd.toggleTestTab()
                end
                return
            end
            settingsClickTime = now
        end

        selectTab(name)
    end)
    local rightAt = 0
    button.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton2 and not Fwd.isSynth() then
            rightAt = os.clock()
        end
    end)
    button.MouseButton2Click:Connect(function()
        if Fwd.isSynth() or not State.Open or os.clock() - rightAt > 1.5 then
            return
        end
        rightAt = 0
        Multitask.toggleTab(name)
    end)

    return scroll
end

selectTab = function(name, instant)
    if not tabs[name] then
        return
    end
    if #Multitask.Tabs == 1 and currentTab == name then
        return
    end

    if name == "Test" and not testTabVisible then
        return
    end

    currentTab = name
    Multitask.Tabs = { name }
    Multitask.applyLayout(instant)
end

Fwd.uiSet = function(open)
    Fwd.setWindow(open and true or false)
end

Fwd.openApp = function(name)
    if not State.Open then
        Fwd.setWindow(true)
    end
    selectTab(name)
end

