        ZIndex = 3,
        Parent = overlay,
    })
    local function order()
        local list = {}
        for _, name in ipairs(Switch.Recents) do
            if tabs[name] and (name ~= "Test" or testTabVisible) then
                list[#list + 1] = name
            end
        end
        return list
    end

    local function slotX(index, total)
        local width = total * CARD_W + (total - 1) * GAP
        local left = math.max(24, (VIEW_W - width) / 2)
        return left + (index - 1) * (CARD_W + GAP) + CARD_W / 2
    end

    local function canvas(total)
        local width = total * CARD_W + (total - 1) * GAP
        scroller.CanvasSize = UDim2.fromOffset(math.max(VIEW_W, width + 48), 0)
    end

    local function layoutCards(animated)
        local list = order()
        local total = #list
        canvas(total)
        for index, name in ipairs(list) do
            local card = Switch.Cards[name]
            if card and not card.Gone then
                card.Index = index
                if animated then
                    card.SpringX:Set(slotX(index, total))
                else
                    card.SpringX:Snap(slotX(index, total))
                end
            end
        end
        empty.Visible = total == 0
        tween(empty, 0.3, { TextTransparency = total == 0 and 0.2 or 1 })
    end

    local function destroyCards()
        for name, card in pairs(Switch.Cards) do
            card.Gone = true
            card.Disconnect()
            card.Frame:Destroy()
            Switch.Cards[name] = nil
        end
    end

    local function removeCard(name, direction)
        local card = Switch.Cards[name]
        for index, value in ipairs(Switch.Recents) do
            if value == name then
                table.remove(Switch.Recents, index)
                break
            end
        end
        if card and not card.Gone then
            card.Gone = true
            card.Disconnect()
            card.SpringY:Set(card.BaseY + (direction or -1) * 260)
            tween(card.Group, 0.28, { GroupTransparency = 1 })
            task.delay(0.34, function()
                card.Frame:Destroy()
            end)
            Switch.Cards[name] = nil
        end
        playSound("slide")
        layoutCards(true)
    end

    local function buildCard(name, delay, animated)
        local tab = tabs[name]
        local frame = new("Frame", {
            Name = "SwitchCard",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromOffset(0, VIEW_H / 2),
            Size = UDim2.fromOffset(CARD_W, CARD_H + HEAD),
            BackgroundTransparency = 1,
            Parent = scroller,
        })
        local group = new("CanvasGroup", {
            Name = "Body",
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            GroupTransparency = animated and 1 or 0,
            Parent = frame,
        })
        local scale = new("UIScale", { Scale = animated and 0.74 or 1, Parent = frame })
        local icon = box({
            Position = UDim2.fromOffset(2, 4),
            Size = UDim2.fromOffset(24, 24),
            BackgroundColor3 = tab.color,
            Parent = group,
        })
        corner(7, icon)
        text({
            Size = UDim2.fromScale(1, 1),
            Text = tab.glyph,
            FontFace = Fonts.Bold,
            TextSize = 15,
            TextColor3 = Static.White,
            Parent = icon,
        })
        local label = text({
            Position = UDim2.fromOffset(34, 0),
            Size = UDim2.new(1, -62, 0, HEAD - 2),
            Text = tab.labelKey,
            FontFace = Fonts.Semibold,
            TextSize = 13,
            TextColor3 = Static.White,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = group,
        })
        label:SetAttribute("BoncutiTranslationKey", tab.labelKey)
        local body = box({
            Name = "Preview",
            Position = UDim2.fromOffset(0, HEAD),
            Size = UDim2.new(1, 0, 1, -HEAD),
            BackgroundColor3 = tab.color,
            Parent = group,
        })
        corner(20, body)
        new("UIGradient", {
            Color = ColorSequence.new(Static.White, rgb(150, 150, 170)),
            Rotation = 60,
            Parent = body,
        })
        local ring = new("UIStroke", {
            Color = Static.White,
            Thickness = 1.2,
            Transparency = 0.55,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Parent = body,
        })
        local shine = box({
            Size = UDim2.new(1, 0, 0.5, 0),
            BackgroundColor3 = Static.White,
            Parent = body,
        })
        corner(20, shine)
        new("UIGradient", { Transparency = NumberSequence.new(0.62, 1), Rotation = 90, Parent = shine })
        text({
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.46),
            Size = UDim2.fromOffset(100, 80),
            Text = tab.glyph,
            FontFace = Fonts.Bold,
            TextSize = 62,
            TextColor3 = Static.White,
            TextTransparency = 0.08,
            Parent = body,
        })
        local caption = text({
            AnchorPoint = Vector2.new(0.5, 1),
            Position = UDim2.new(0.5, 0, 1, -14),
            Size = UDim2.new(1, -20, 0, 20),
            Text = currentTab == name and "\u{110}ang d\u{F9}ng" or "M\u{1EDF}",
            FontFace = Fonts.Medium,
            TextSize = 12,
            TextColor3 = Static.White,
            TextTransparency = 0.12,
            Parent = body,
        })
        local closeDot = new("TextButton", {
            Name = "CardClose",
            AnchorPoint = Vector2.new(1, 0),
            Position = UDim2.new(1, -2, 0, 3),
            Size = UDim2.fromOffset(22, 22),
            BackgroundColor3 = Static.Black,
            BackgroundTransparency = 0.45,
            AutoButtonColor = false,
            Text = "\u{D7}",
            FontFace = Fonts.Bold,
            TextSize = 15,
            TextColor3 = Static.White,
            ZIndex = 4,
            Parent = group,
        })
        corner(11, closeDot)
        local hit = new("TextButton", {
            Name = "CardHit",
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 3,
            Parent = group,
        })
        local card = {
            Name = name,
            Frame = frame,
            Group = group,
            Moved = false,
            BaseY = VIEW_H / 2 - 4,
            X = 0,
            Y = animated and VIEW_H / 2 + 60 or VIEW_H / 2 - 4,
        }
        card.SpringX = Spring.new(0, 230, 22, function(value)
            card.X = value
            frame.Position = UDim2.fromOffset(value, card.Y)
        end, 0.05)
        card.SpringY = Spring.new(card.Y, 230, 21, function(value)
            card.Y = value
            frame.Position = UDim2.fromOffset(card.X, value)
        end, 0.05)
        card.SpringScale = Spring.new(scale.Scale, 260, 20, function(value)
            scale.Scale = value
        end, 0.0005)
        card.SpringX:Snap(slotX(1, 1))
        if currentTab == name then
            ring.Color = Static.White
            ring.Transparency = 0.1
            ring.Thickness = 2.4
        end

        local drag = { Active = false, Start = nil, Y = 0 }
        hit.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                drag.Active = true
                drag.Start = input.Position
                card.Moved = false
                card.SpringScale:Set(0.97)
            end
        end)
        local moved = UserInputService.InputChanged:Connect(function(input)
            if card.Gone or not drag.Active then
                return
            end
            if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                local dy = input.Position.Y - drag.Start.Y
                local dx = input.Position.X - drag.Start.X
                if math.abs(dy) > 8 or math.abs(dx) > 8 then
                    card.Moved = true
                end
                if dy < 0 and math.abs(dy) > math.abs(dx) * 0.8 then
                    drag.Y = dy
                    card.SpringY:Snap(card.BaseY + dy)
                    group.GroupTransparency = math.clamp(-dy / 320, 0, 0.7)
                end
            end
        end)
        local ended = UserInputService.InputEnded:Connect(function(input)
            if card.Gone or not drag.Active then
                return
            end
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                drag.Active = false
                card.SpringScale:Set(1)
                if drag.Y < -70 then
                    drag.Y = 0
                    removeCard(name, -1)
                else
                    drag.Y = 0
                    card.SpringY:Set(card.BaseY)
                    tween(group, 0.25, { GroupTransparency = 0 })
                end
            end
        end)
        card.Disconnect = function()
            moved:Disconnect()
            ended:Disconnect()
        end
        hit.MouseButton1Click:Connect(function()
            if card.Moved or card.Gone then
                card.Moved = false
                return
            end
            Switch.choose(name)
        end)
        hit.MouseLeave:Connect(function()
            if not drag.Active then
                card.SpringScale:Set(1)
            end
        end)
        closeDot.MouseButton1Click:Connect(function()
            if not card.Gone then
                removeCard(name, -1)
            end
        end)

        Switch.Cards[name] = card
        if animated then
            task.delay(delay, function()
                if card.Gone then
                    return
                end
                card.SpringY:Set(card.BaseY)
                card.SpringScale:Set(1)
                tween(group, 0.34, { GroupTransparency = 0 })
            end)
        end
        return card
    end

    function Switch.open()
        if Switch.Open or not State.Open or Fwd.isSynth() then
            return
        end
        if Fwd.multitaskMenu then
            Fwd.multitaskMenu.close()
        end
        Switch.Open = true
        Switch.Busy = Switch.Busy + 1
        destroyCards()
        overlay.Visible = true
        tween(scrim, 0.35, { BackgroundTransparency = 0.38 })
        local list = order()
        canvas(#list)
        scroller.CanvasPosition = Vector2.new(0, 0)
        for index, name in ipairs(list) do
            local card = buildCard(name, 0.05 + (index - 1) * 0.045, true)
            card.SpringX:Snap(slotX(index, #list))
            card.Index = index
        end
        layoutCards(false)
        Spr.springWindowScale:Set(0.97)
        task.delay(0.02, function()
            if Switch.Open then
                Spr.springWindowScale:Set(1)
            end
        end)
        pill.Spring:Set(150)
        playSound("open")
    end

    function Switch.close(instant)
        if not Switch.Open then
            return
        end
        Switch.Open = false
        Switch.Busy = Switch.Busy + 1
        local ticket = Switch.Busy
        tween(scrim, instant and 0 or 0.28, { BackgroundTransparency = 1 })
        tween(empty, 0.2, { TextTransparency = 1 })
        for _, card in pairs(Switch.Cards) do
            card.SpringScale:Set(0.86)
            tween(card.Group, instant and 0 or 0.22, { GroupTransparency = 1 })
            card.SpringY:Set(card.BaseY + 40)
        end
        pill.Spring:Set(110)
        task.delay(instant and 0 or 0.3, function()
            if Switch.Busy == ticket and not Switch.Open then
                destroyCards()
                overlay.Visible = false
            end
        end)
    end

    function Switch.choose(name)
        if not Switch.Open then
            return
        end
        playSound("tick")
        local card = Switch.Cards[name]
        if card then
            card.SpringScale:Set(1.12)
            card.SpringY:Set(card.BaseY - 10)
            for other, value in pairs(Switch.Cards) do
                if other ~= name then
                    value.SpringScale:Set(0.88)
                    tween(value.Group, 0.2, { GroupTransparency = 1 })
                end
            end
        end
        Switch.Open = false
        Switch.Busy = Switch.Busy + 1
        local ticket = Switch.Busy
        tween(scrim, 0.3, { BackgroundTransparency = 1 })
        pill.Spring:Set(110)
        task.delay(0.12, function()
            if currentTab ~= name then
                selectTab(name)
            end
            if card then
                tween(card.Group, 0.26, { GroupTransparency = 1 })
            end
        end)
        task.delay(0.4, function()
            if Switch.Busy == ticket and not Switch.Open then
                destroyCards()
                overlay.Visible = false
            end
        end)
    end

    function Switch.toggle()
        if Switch.Open then
            Switch.close()
        else
            Switch.open()
        end
    end

    scrim.MouseButton1Click:Connect(function()
        Switch.close()
    end)

    local baseSelect = selectTab
    selectTab = function(name, instant)
        if tabs[name] and (name ~= "Test" or testTabVisible) then
            for index, value in ipairs(Switch.Recents) do
                if value == name then
                    table.remove(Switch.Recents, index)
                    break
                end
            end
            table.insert(Switch.Recents, 1, name)
            while #Switch.Recents > 8 do
                table.remove(Switch.Recents)
            end
        end
        return baseSelect(name, instant)
    end

    local baseWindow = Fwd.setWindow
    Fwd.setWindow = function(open)
        if not open and Switch.Open then
            Switch.close(true)
        end
        return baseWindow(open)
    end

    local pillHit = new("TextButton", {
        Name = "SwitcherPillHit",
        AnchorPoint = Vector2.new(0.5, 1),
        Position = UDim2.new(0.5, 0, 1, -2),
        Size = UDim2.fromOffset(190, 16),
        BackgroundTransparency = 1,
        AutoButtonColor = false,
        Text = "",
        ZIndex = 26,
        Parent = window,
    })
    local pillBar = box({
        Name = "SwitcherPill",
        AnchorPoint = Vector2.new(0.5, 1),
        Position = UDim2.new(0.5, 0, 1, -6),
        Size = UDim2.fromOffset(110, 5),
        Role = "Text",
        BackgroundTransparency = 0.7,
        ZIndex = 27,
        Parent = window,
    })
    corner(3, pillBar)
    pill.Spring = Spring.new(110, 320, 22, function(value)
        pillBar.Size = UDim2.fromOffset(value, 5)
    end, 0.05)
    local start
    Fwd.cursorInWindow = function()
        local ok, point = pcall(function()
            return UserInputService:GetMouseLocation()
        end)
        if not ok or not point then
            return false
        end
        local pos, size = window.AbsolutePosition, window.AbsoluteSize
        return point.X >= pos.X and point.X <= pos.X + size.X and point.Y >= pos.Y and point.Y <= pos.Y + size.Y
    end
    pillHit.MouseEnter:Connect(function()
        if not Switch.Open then
            pill.Spring:Set(132)
        end
        tween(pillBar, 0.2, { BackgroundTransparency = 0.45 })
    end)
    pillHit.MouseLeave:Connect(function()
        if not Switch.Open then
            pill.Spring:Set(110)
        end
        tween(pillBar, 0.25, { BackgroundTransparency = 0.7 })
        start = nil
    end)
    local press
    pillHit.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            if Fwd.isSynth() or not State.Open then
                start = nil
                press = { Input = input, From = input.Position, At = os.clock(), Moved = math.huge }
                return
            end
            start = input.Position
            press = { Input = input, From = input.Position, At = os.clock(), Moved = 0 }
        end
    end)
    track(UserInputService.InputChanged:Connect(function(input)
        if not press then
            return
        end
        local touch = input.UserInputType == Enum.UserInputType.Touch
        if touch then
            if input ~= press.Input then
                return
            end
        elseif input.UserInputType ~= Enum.UserInputType.MouseMovement then
            return
        end
        local dx, dy = input.Position.X - press.From.X, input.Position.Y - press.From.Y
        local moved = math.sqrt(dx * dx + dy * dy)
        if moved > press.Moved and press.Moved ~= math.huge then
            press.Moved = moved
        end
        if not start then
            return
        end
        if not State.Open or Switch.Open or Ux.Dialog.Open or Fwd.isSynth() then
            start = nil
            return
        end
        if not touch and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
            start = nil
            return
        end
        local rise = start.Y - input.Position.Y
        if os.clock() - press.At > 1.6 then
            start = nil
            return
        end
        if rise > 46 and math.abs(start.X - input.Position.X) < rise * 0.6 then
            start = nil
            Switch.open()
        end
    end))
    track(UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            start = nil
            local mine = press
            if mine then
                task.delay(0.3, function()
                    if press == mine then
                        press = nil
                    end
                end)
            end
        end
    end))
    pillHit.MouseButton1Click:Connect(function()
        if Fwd.isSynth() or not State.Open then
            return
        end
        if press and (press.Moved > 14 or os.clock() - press.At > 0.9) then
            return
        end
        playSound("tick")
        Switch.toggle()
    end)
    track(UserInputService.InputBegan:Connect(function(input, processed)
        if processed or not State.Open or Ux.Capture.Active or Ux.Dialog.Open or Search.Open or Fwd.isSynth() then
            return
        end
        if input.KeyCode == Enum.KeyCode.Tab and (UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)) and Fwd.cursorInWindow() then
            Switch.toggle()
        elseif input.KeyCode == Enum.KeyCode.Escape and Switch.Open then
            Switch.close()
        end
    end))
end

function Mk.reflowSidebar()
    local order = { "LoopDash", "AutoBlock", "ChangeVFX" }
    local y = 0

    for _, name in ipairs(order) do
        local tab = tabs[name]
        if tab then
            local visible = name ~= "Test" or testTabVisible
            tab.button.Visible = visible

            if visible then
                if name == "Test" then
                    tab.button.Position = UDim2.fromOffset(8, y)
                    tab.button.Size = UDim2.new(1, -8, 0, 36)
                    tab.label.Position = UDim2.fromOffset(38, 0)
                    tab.label.Size = UDim2.new(1, -44, 1, 0)
                    tab.button.BackgroundTransparency = 0.94
                else
                    tab.button.Position = UDim2.fromOffset(0, y)
                    tab.button.Size = UDim2.new(1, 0, 0, 36)
                    tab.label.Position = UDim2.fromOffset(42, 0)
                    tab.label.Size = UDim2.new(1, -48, 1, 0)
                end

                tab.y = y
                y = y + 40
            end
        end
    end

    if currentTab and tabs[currentTab] then
        Spr.springHighlight:Set(tabs[currentTab].y)
    end
end

Fwd.toggleTestTab = function()
    if testTabVisible then
        if currentTab == "Test" then
            selectTab("Settings")
        end
        testTabVisible = false
    else
        testTabVisible = true
    end

    Mk.reflowSidebar()
end

local controls = {}

local function register(control, default, key)
    control.Default = default
    control.Key = key
    table.insert(controls, control)
    return control
end

local function slot(scroll)
    local index = (scroll:GetAttribute("slot") or 0) + 1
    scroll:SetAttribute("slot", index)
    return index
end

local function section(scroll, title)
    local header = text({
        Name = "Header",
        Text = Fwd.upper(translate(title)),
        FontFace = Fonts.Semibold,
        TextSize = 11,
        Role = "Sub",
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Bottom,
        Size = UDim2.new(1, 0, 0, 26),
        LayoutOrder = slot(scroll),
        Parent = scroll,
    })
    header:SetAttribute("BoncutiTranslationKey", title)
    new("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingBottom = UDim.new(0, 2), Parent = header })
    local card = box({
        Name = "Card",
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        LayoutOrder = slot(scroll),
        Role = "Card",
        Parent = scroll,
    })
    corner(14, card)
    Glass.Skin(card, 0.42)
    new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = card })
    return card
end

local function addRow(card, height)
    local index = (card:GetAttribute("rows") or 0) + 1
    card:SetAttribute("rows", index)
    local row = new("Frame", {
        Name = "Row",
        Size = UDim2.new(1, 0, 0, height),
        BackgroundTransparency = 1,
        LayoutOrder = index,
        Parent = card,
    })
    if index > 1 then
        box({
            Name = "Separator",
            Position = UDim2.fromOffset(16, 0),
            Size = UDim2.new(1, -16, 0, 1),
            BackgroundTransparency = 0.92,
            Role = "Line",
            Parent = row,
        })
    end
    return row
end

function Mk.rowTitle(row, title, desc, inset)
    inset = inset or 100
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, desc and 9 or 0),
        Size = UDim2.new(1, -inset, desc and 0 or 1, desc and 20 or 0),
        Parent = row,
    })
    if desc then
        text({
            Text = desc,
            FontFace = Fonts.Regular,
            TextSize = 12,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Position = UDim2.fromOffset(16, 29),
            Size = UDim2.new(1, -inset, 0, 16),
            Parent = row,
        })
    end
end

function Mk.createToggle(card, title, desc, default, callback)
    local row = addRow(card, desc and 58 or 50)
    Mk.rowTitle(row, title, desc, 90)
    Search.Add(row, "C\u{F4}ng t\u{1EAF}c", title, desc)

    local state = default and true or false
    local track_ = box({
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.fromOffset(51, 31),
        BackgroundColor3 = state and Static.Green or P.Off,
        Parent = row,
    })
    corner(16, track_)
    local knob = box({
        Size = UDim2.fromOffset(27, 27),
        BackgroundColor3 = Static.White,
        Parent = track_,
    })
    corner(14, knob)
    stroke(knob, Static.Black, 0.9, 1)
    local hit = new("TextButton", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = "",
        Parent = track_,
    })

    local progress = state and 1 or 0
    local width = 27

    local function layout()
        knob.Size = UDim2.fromOffset(width, 27)
        knob.Position = UDim2.fromOffset(2 + (47 - width) * progress, 2)
    end

    local progressSpring = Spring.new(progress, 380, 24, function(value)
        progress = value
        layout()
    end, 0.001)

    local widthSpring = Spring.new(27, 520, 30, function(value)
        width = value
        layout()
    end, 0.02)

    local function paintTrack(duration)
        tween(track_, duration, { BackgroundColor3 = state and Static.Green or P.Off })
    end

    table.insert(paletteListeners, function(duration)
        if not state then
            paintTrack(duration)
        end
    end)

    local function apply(value, user)
        state = value
        progressSpring:Set(state and 1 or 0)
        paintTrack(0.3)
        if callback then
            callback(state, user)
        end
    end

    hit.MouseButton1Down:Connect(function()
        widthSpring:Set(33)
    end)
    hit.MouseButton1Up:Connect(function()
        widthSpring:Set(27)
    end)
    hit.MouseLeave:Connect(function()
        widthSpring:Set(27)
    end)
    hit.MouseButton1Click:Connect(function()
        playSound(state and "off" or "on")
        apply(not state, true)
    end)

    return {
        Set = function(value)
            apply(value and true or false, false)
        end,
        Get = function()
            return state
        end,
        Toggle = true,
        Title = title,
        Desc = desc,
    }
end

function Mk.createSlider(card, title, min, max, default, step, suffix, callback)
    local row = addRow(card, 68)
    Search.Add(row, "Thanh tr\u{1B0}\u{1EE3}t", title)
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, 10),
        Size = UDim2.new(1, -110, 0, 20),
        Parent = row,
    })
    local valueLabel = text({
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -16, 0, 10),
        Size = UDim2.fromOffset(80, 20),
        TextXAlignment = Enum.TextXAlignment.Right,
        Role = "Sub",
        TextSize = 14,
        Parent = row,
    })

    local rail = box({
        Position = UDim2.new(0, 16, 0, 47),
        Size = UDim2.new(1, -32, 0, 6),
        Role = "Off",
        Parent = row,
    })
    corner(3, rail)
    local fill = box({
        Size = UDim2.fromScale(0, 1),
        Role = "Accent",
        Parent = rail,
    })
    corner(3, fill)
    local knob = box({
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0, 0.5),
        Size = UDim2.fromOffset(22, 22),
        BackgroundColor3 = Static.White,
        ZIndex = 2,
        Parent = rail,
    })
    corner(11, knob)
    stroke(knob, Static.Black, 0.85, 1)
    local hit = new("TextButton", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.new(1, 20, 0, 34),
        BackgroundTransparency = 1,
        Text = "",
        ZIndex = 3,
        Parent = rail,
    })

    local value = default
    local alpha = (default - min) / (max - min)
    local knobSize = 22

    local function format(number)
        if step < 1 then
            return string.format("%.1f", number) .. suffix
        end
        return string.format("%d", number) .. suffix
    end

    local function layout()
        local shown = math.clamp(alpha, 0, 1)
        fill.Size = UDim2.fromScale(shown, 1)
        knob.Position = UDim2.fromScale(shown, 0.5)
        knob.Size = UDim2.fromOffset(knobSize, knobSize)
    end

    local alphaSpring = Spring.new(alpha, 520, 46, function(current)
        alpha = current
        layout()
    end, 0.0005)

    local sizeSpring = Spring.new(22, 560, 30, function(current)
        knobSize = current
        layout()
    end, 0.02)

    valueLabel.Text = format(default)

    local function setValue(number, user)
        number = math.clamp(number, min, max)
        if number == value then
            return
        end
        value = number
        alphaSpring:Set((number - min) / (max - min))
        valueLabel.Text = format(number)
        if user then
            playSound("slide", 0.75 + (number - min) / (max - min) * 0.9)
        end
        if callback then
            callback(number, user)
        end
    end

    local function fromX(x)
        local ratio = math.clamp((x - rail.AbsolutePosition.X) / rail.AbsoluteSize.X, 0, 1)
        local raw = min + (max - min) * ratio
        setValue(math.floor(raw / step + 0.5) * step, true)
    end

    local sliding = false

    local function lockScroll(locked)
        local scroller = row:FindFirstAncestorOfClass("ScrollingFrame")
        if scroller then
            scroller.ScrollingEnabled = not locked
        end
    end

    hit.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            sliding = true
            lockScroll(true)
            sizeSpring:Set(28)
            fromX(input.Position.X)
        end
    end)
    track(UserInputService.InputChanged:Connect(function(input)
        if sliding and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            fromX(input.Position.X)
        end
    end))
    track(UserInputService.InputEnded:Connect(function(input)
        if sliding and (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) then
            sliding = false
            lockScroll(false)
            sizeSpring:Set(22)
        end
    end))

    return {
        Set = function(number)
            setValue(number, false)
        end,
        Get = function()
            return value
        end,
    }
end

function Mk.createSegmented(card, title, options, default, segWidth, callback)
    local row = addRow(card, 56)
    Search.Add(row, "Tu\u{1EF3} ch\u{1ECD}n", title)
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, 0),
        Size = UDim2.new(0, 140, 1, 0),
        Parent = row,
    })

    local count = #options
    local frame = box({
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.fromOffset(count * segWidth + 4, 32),
        Role = "Field",
        Parent = row,
    })
    corner(9, frame)
    local pill = box({
        Position = UDim2.fromOffset(2, 2),
        Size = UDim2.fromOffset(segWidth, 28),
        Role = "Seg",
        Parent = frame,
    })
    corner(7, pill)
    stroke(pill, Static.Black, 0.85, 1)

    local index = default
    local labels = {}

    local pillSpring = Spring.new((default - 1) * segWidth, 420, 32, function(value)
        pill.Position = UDim2.fromOffset(2 + value, 2)
    end, 0.05)

    local function refreshLabels(duration)
        for i, label in ipairs(labels) do
            tween(label, duration, { TextColor3 = i == index and P.Text or P.Sub })
        end
    end

    table.insert(paletteListeners, refreshLabels)

    local function choose(i, user)
        index = i
        pillSpring:Set((i - 1) * segWidth)
        refreshLabels(0.2)
        if callback then
            callback(i, user)
        end
    end

    for i, name in ipairs(options) do
        local button = new("TextButton", {
            Position = UDim2.fromOffset(2 + (i - 1) * segWidth, 2),
            Size = UDim2.fromOffset(segWidth, 28),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 2,
            Parent = frame,
        })
        labels[i] = text({
            Size = UDim2.fromScale(1, 1),
            Text = name,
            FontFace = Fonts.Medium,
            TextSize = 12,
            TextColor3 = i == default and P.Text or P.Sub,
            ZIndex = 3,
            Parent = button,
        })
        button.MouseButton1Click:Connect(function()
            if index ~= i then
                playSound("tick")
                choose(i, true)
            end
        end)
    end

    return {
        Set = function(i)
            if index ~= i then
                choose(i, false)
            end
        end,
        Get = function()
            return index
        end,
    }
end

function Mk.createThemes(card, title, names, default, callback)
    local columns = 4
    local tileHeight = 62
    local gap = 8
    local lines = math.ceil(#names / columns)
    local row = addRow(card, 44 + lines * (tileHeight + gap))
    Search.Add(row, "Tu\u{1EF3} ch\u{1ECD}n", title)
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, 0),
        Size = UDim2.new(0, 160, 0, 44),
        Parent = row,
    })
    local grid = new("Frame", {
        Position = UDim2.fromOffset(16, 44),
        Size = UDim2.new(1, -32, 0, lines * (tileHeight + gap) - gap),
        BackgroundTransparency = 1,
        Parent = row,
    })

    local index = default
    local rings = {}
    local labels = {}

    local function refreshLabels(duration)
        for i, label in ipairs(labels) do
            tween(label, duration, { TextColor3 = i == index and P.Text or P.Sub })
        end
    end

    table.insert(paletteListeners, refreshLabels)

    local function choose(i, user)
        index = i
        for n, ring in ipairs(rings) do
            tween(ring, 0.25, { Transparency = n == i and 0 or 1 })
        end
        refreshLabels(0.2)
        if callback then
            callback(i, user)
        end
    end

    for i, name in ipairs(names) do
        local palette = Palettes[i]
        local column = (i - 1) % columns
        local line = math.floor((i - 1) / columns)
        local cell = new("TextButton", {
            Name = "ThemeTile",
            Position = UDim2.new(column * 0.25, column * 2, 0, line * (tileHeight + gap)),
            Size = UDim2.new(0.25, -6, 0, tileHeight),
            BackgroundTransparency = 1,
            AutoButtonColor = false,
            Text = "",
            Parent = grid,
        })
        local preview = new("Frame", {
            Size = UDim2.new(1, 0, 0, 42),
            BackgroundColor3 = palette.Window,
            BorderSizePixel = 0,
            Parent = cell,
        })
        corner(10, preview)
        local liveTheme = Fwd.ThemeLive[i]
        if liveTheme or i == Fwd.ThemeImage then
            local colors = liveTheme and liveTheme.Colors or { rgb(255, 154, 98), rgb(214, 92, 190), rgb(86, 120, 255) }
            preview.BackgroundColor3 = Static.White
            local stops = {}
            for n, color in ipairs(colors) do
                stops[n] = ColorSequenceKeypoint.new((n - 1) / (#colors - 1), palette.Window:Lerp(color, 0.55))
            end
            local gradient = new("UIGradient", { Color = ColorSequence.new(stops), Rotation = 35, Parent = preview })
            if liveTheme then
                table.insert(Fwd.ThemeSpin, gradient)
            end
        end
        local mini = new("Frame", {
            Position = UDim2.fromOffset(7, 7),
            Size = UDim2.new(1, -14, 0, 15),
            BackgroundColor3 = palette.Card,
            BorderSizePixel = 0,
            Parent = preview,
        })
        corner(5, mini)
        local lineA = new("Frame", {
            Position = UDim2.fromOffset(6, 3),
            Size = UDim2.new(0.55, 0, 0, 3),
            BackgroundColor3 = palette.Text,
            BorderSizePixel = 0,
            Parent = mini,
        })
        corner(2, lineA)
        local lineB = new("Frame", {
            Position = UDim2.fromOffset(6, 9),
            Size = UDim2.new(0.34, 0, 0, 3),
            BackgroundColor3 = palette.Sub,
            BorderSizePixel = 0,
            Parent = mini,
        })
        corner(2, lineB)
        local dot = box({
            AnchorPoint = Vector2.new(1, 1),
            Position = UDim2.new(1, -8, 1, -7),
            Size = UDim2.fromOffset(11, 11),
            Role = "Accent",
            Parent = preview,
        })
        corner(6, dot)
        local track_ = new("Frame", {
            Position = UDim2.fromOffset(7, 28),
            Size = UDim2.new(0.5, 0, 0, 7),
            BackgroundColor3 = palette.Off,
            BorderSizePixel = 0,
            Parent = preview,
        })
        corner(4, track_)
        local outline = new("Frame", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 2,
            Parent = preview,
        })
        corner(10, outline)
        stroke(outline, Static.Black, 0.88, 1)
        local selection = new("Frame", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 3,
            Parent = preview,
        })
        corner(10, selection)
        rings[i] = stroke(selection, "Accent", i == default and 0 or 1, 2)
        labels[i] = text({
            Position = UDim2.fromOffset(0, 45),
            Size = UDim2.new(1, 0, 0, 16),
            Text = name,
            FontFace = Fonts.Medium,
            TextSize = 12,
            TextColor3 = i == default and P.Text or P.Sub,
            Parent = cell,
        })
        cell.MouseButton1Click:Connect(function()
            if index ~= i then
                playSound("tick")
                choose(i, true)
            end
        end)
    end

    return {
        Set = function(i)
            if index ~= i and Palettes[i] then
                choose(i, false)
            end
        end,
        Get = function()
            return index
        end,
    }
end

Ux.Capture = { Active = nil }

function Mk.createKeybind(card, title, desc, default, callback)
    local row = addRow(card, desc and 58 or 50)
    Mk.rowTitle(row, title, desc, 150)
    Search.Add(row, "Ph\u{ED}m t\u{1EAF}t", title, desc)

    local key = default
    local button = box({
        Class = "TextButton",
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.fromOffset(110, 30),
        AutoButtonColor = false,
        Text = "",
        Role = "Field",
        Parent = row,
    })
    corner(8, button)
    stroke(button, "Line", 0.9, 1)
    Glass.Pane(button, "clear")
    local label = text({
        Size = UDim2.fromScale(1, 1),
        Text = key.Name,
        FontFace = Fonts.Semibold,
        TextSize = 13,
        Parent = button,
    })

    local function finish(newKey)
        Ux.Capture.Active = nil
        if newKey then
            key = newKey
            if callback then
                callback(key, true)
            end
        end
        label.Text = key.Name
        tween(label, 0.2, { TextColor3 = P.Text })
    end

    button.MouseButton1Click:Connect(function()
        playSound("click")
        Ux.Capture.Active = finish
        label.Text = "Nh\u{1EA5}n ph\u{ED}m\u{2026}"
        tween(label, 0.2, { TextColor3 = P.Accent })
    end)

    return {
        Set = function(value)
            key = value
            label.Text = key.Name
            if callback then
                callback(key, false)
            end
        end,
        Get = function()
            return key
        end,
    }
end

function Mk.createSwatches(card, title, list, default, callback)
    local row = addRow(card, 62)
    Search.Add(row, "M\u{E0}u s\u{1EAF}c", title)
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, 0),
        Size = UDim2.new(0, 140, 1, 0),
        Parent = row,
    })
    local inner = new("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.fromOffset(#list * 32 - 6, 28),
        BackgroundTransparency = 1,
        Parent = row,
    })
    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Parent = inner,
    })

    local index = default
    local rings = {}
    local scaleSprings = {}

    local function choose(i, user)
        index = i
        for n, ring in ipairs(rings) do
            tween(ring, 0.25, { Transparency = n == i and 0 or 1 })
            scaleSprings[n]:Set(n == i and 1.12 or 1)
        end
        if callback then
            callback(i, user)
        end
    end

    for i, item in ipairs(list) do
        local swatch = box({
            Class = "TextButton",
            Size = UDim2.fromOffset(26, 26),
            BackgroundColor3 = item[2],
            AutoButtonColor = false,
            Text = "",
            LayoutOrder = i,
            Parent = inner,
        })
        corner(13, swatch)
        local scale = new("UIScale", { Parent = swatch })
        rings[i] = stroke(swatch, "Text", i == default and 0 or 1, 2)
        scaleSprings[i] = Spring.new(i == default and 1.12 or 1, 500, 26, function(value)
            scale.Scale = value
        end, 0.001)
        swatch.MouseButton1Click:Connect(function()
            if index ~= i then
                playSound("tick")
                scaleSprings[i]:Snap(0.82)
                choose(i, true)
            end
        end)
    end

    return {
        Set = function(i)
            if index ~= i then
                choose(i, false)
            end
        end,
        Get = function()
            return index
        end,
    }
end

function Mk.createTextBox(card, title, placeholder, callback)
    local row = addRow(card, 56)
    Search.Add(row, "Nh\u{1EAD}p li\u{1EC7}u", title)
    text({
        Text = title,
        FontFace = Fonts.Medium,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(16, 0),
        Size = UDim2.new(0, 110, 1, 0),
        Parent = row,
    })
    local field = new("TextBox", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.new(1, -150, 0, 34),
        BorderSizePixel = 0,
        ClearTextOnFocus = false,
        Text = "",
        PlaceholderText = placeholder,
        FontFace = Fonts.Regular,
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = row,
    })
    paint(field, "BackgroundColor3", "Field")
    paint(field, "TextColor3", "Text")
    paint(field, "PlaceholderColor3", "Sub")
    corner(9, field)
    new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = field })
    local line = stroke(field, "Line", 0.9, 1)

    field.Focused:Connect(function()
        tween(line, 0.2, { Color = P.Accent, Transparency = 0 })
    end)
    field.FocusLost:Connect(function(enterPressed)
        tween(line, 0.2, { Color = P.Line, Transparency = 0.9 })
        if enterPressed and field.Text ~= "" then
            local value = field.Text
            field.Text = ""
            playSound("click")
            if callback then
                callback(value)
            end
        end
    end)
end

function Mk.createButtons(card, list)
    local row = addRow(card, 58)
    local inner = new("Frame", {
        Position = UDim2.fromOffset(12, 11),
        Size = UDim2.new(1, -24, 1, -22),
        BackgroundTransparency = 1,
        Parent = row,
    })
    new("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = inner,
    })

    local count = #list
    local made = {}
    for i, def in ipairs(list) do
        local role = def.Color and nil or (def.Role or "Accent")
        local button = box({
            Class = "TextButton",
            Size = UDim2.new(1 / count, -(8 * (count - 1)) / count, 1, 0),
            BackgroundColor3 = def.Color,
            AutoButtonColor = false,
            Text = def.Text,
            FontFace = Fonts.Semibold,
            TextSize = 14,
            LayoutOrder = i,
            Role = role,
            Parent = inner,
        })
        if def.Role == "Field" then
            paint(button, "TextColor3", "Text")
        else
            button.TextColor3 = Static.White
        end
        corner(10, button)
        made[i] = button
        Glass.Pane(button, def.Role == "Field" and "clear" or "tint")
        Search.Add(row, "N\u{FA}t", def.Text)
        local pressScale = new("UIScale", { Parent = button })
        local pressSpring = Spring.new(1, 600, 30, function(value)
            pressScale.Scale = value
        end, 0.001)

        local function base()
            return def.Color or P[def.Role or "Accent"]
        end

        button.MouseEnter:Connect(function()
            local target = def.Role == "Field" and base():Lerp(P.Text, 0.08) or base():Lerp(Static.White, 0.14)
            tween(button, 0.15, { BackgroundColor3 = target })
        end)
        button.MouseLeave:Connect(function()
            tween(button, 0.2, { BackgroundColor3 = base() })
            pressSpring:Set(1)
        end)
        button.MouseButton1Down:Connect(function()
            pressSpring:Set(0.94)
        end)
        button.MouseButton1Up:Connect(function()
            pressSpring:Set(1)
        end)
        button.MouseButton1Click:Connect(function()
            playSound("click")
            if def.Callback then
                def.Callback()
            end
        end)
    end
    return made
end

