        FontFace = Fonts.Regular,
        TextSize = 13,
        Role = "Sub",
        TextWrapped = true,
        LayoutOrder = 2,
        Parent = dialog,
    })
    new("Frame", {
        Size = UDim2.new(1, 0, 0, 6),
        BackgroundTransparency = 1,
        LayoutOrder = 3,
        Parent = dialog,
    })
    local dialogButtons = new("Frame", {
        Size = UDim2.new(1, 0, 0, 40),
        BackgroundTransparency = 1,
        LayoutOrder = 4,
        Parent = dialog,
    })

    local cancelButton = box({
        Class = "TextButton",
        Size = UDim2.new(0.5, -4, 1, 0),
        AutoButtonColor = false,
        Text = "Hu\u{1EF7}",
        FontFace = Fonts.Semibold,
        TextSize = 14,
        Role = "Field",
        Parent = dialogButtons,
    })
    paint(cancelButton, "TextColor3", "Text")
    corner(10, cancelButton)
    Glass.Pane(cancelButton, "clear")

    local confirmButton = box({
        Class = "TextButton",
        Position = UDim2.new(0.5, 4, 0, 0),
        Size = UDim2.new(0.5, -4, 1, 0),
        BackgroundColor3 = Static.Blue,
        AutoButtonColor = false,
        Text = "OK",
        FontFace = Fonts.Semibold,
        TextSize = 14,
        TextColor3 = Static.White,
        Parent = dialogButtons,
    })
    corner(10, confirmButton)
    Glass.Pane(confirmButton, "tint")

    local function closeDialog()
        if not Ux.Dialog.Open then
            return
        end
        Ux.Dialog.Open = false
        tween(overlay, 0.25, { BackgroundTransparency = 1 })
        tween(dialog, 0.2, { GroupTransparency = 1 })
        springDialog:Set(0.94)
        task.delay(0.28, function()
            if not Ux.Dialog.Open then
                overlay.Visible = false
            end
        end)
    end

    function Ux.confirm(title, message, confirmText, destructive, action)
        Ux.Dialog.Open = true
        Ux.Dialog.Action = action
        dialogTitle.Text = title
        dialogMessage.Text = message
        confirmButton.Text = confirmText
        confirmButton.BackgroundColor3 = destructive and Static.Red or P.Accent
        overlay.Visible = true
        springDialog:Snap(0.88)
        springDialog:Set(1)
        tween(overlay, 0.3, { BackgroundTransparency = 0.45 })
        tween(dialog, 0.25, { GroupTransparency = 0 })
        playSound("info")
    end

    overlay.MouseButton1Click:Connect(closeDialog)
    cancelButton.MouseButton1Click:Connect(function()
        playSound("click")
        closeDialog()
    end)
    confirmButton.MouseButton1Click:Connect(function()
        playSound("click")
        local action = Ux.Dialog.Action
        closeDialog()
        if action then
            action()
        end
    end)
end

function Ux.resetAll()
    for _, control in ipairs(controls) do
        if not control.Keep then
            control.Set(control.Default)
        end
    end
    Activities.Timer = nil
    refreshActivity()
end

function Ux.unload()
    Auth.save()
    Fwd.setWindow(false)
    if Cross.shutdown then
        Cross.shutdown()
    end
    Activities.Timer = nil
    Activities.Download = nil
    Activities.Fps = nil
    Activities.Ping = nil
    Activities.Clock = nil
    Island.Live = nil
    Island.Pin = nil
    if Isl.collapse then
        Isl.collapse(true, true)
    end
    Isl.bubbleTo(0)
    task.spawn(function()
        Isl.showGroup(Isl.liveGroup, false, 0.15)
        Isl.showGroup(Isl.alertGroup, false, 0.15)
        Isl.setIslandMode("idle")
        task.wait(0.4)
        Spr.springIslandY:Set(-70)
        task.wait(0.7)
        gui:Destroy()
    end)
end

function Ux.greeting()
    local hour = tonumber(os.date("%H")) or 12
    if hour < 11 then
        return "Ch\u{E0}o bu\u{1ED5}i s\u{E1}ng"
    elseif hour < 14 then
        return "Ch\u{E0}o bu\u{1ED5}i tr\u{1B0}a"
    elseif hour < 18 then
        return "Ch\u{E0}o bu\u{1ED5}i chi\u{1EC1}u"
    end
    return "Ch\u{E0}o bu\u{1ED5}i t\u{1ED1}i"
end

