Mk.reflowSidebar()

do
    local HttpService = game:GetService("HttpService")
    local StatsService = game:GetService("Stats")
    local genv = (getgenv and getgenv()) or _G

    local function setClipboardText(value)
        local fn = setclipboard or toclipboard
        if fn then
            return pcall(fn, value)
        end
        return false
    end

    local function flashButton(button, message, original)
        if not button then
            return
        end
        button.Text = message
        task.delay(1.5, function()
            if button.Parent then
                button.Text = original
            end
        end)
    end

    local function configBox(card, title, placeholder)
        local row = addRow(card, 56)
        Search.Add(row, "Config", title)
        local field = new("TextBox", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.new(1, -32, 0, 34),
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Text = "",
            PlaceholderText = placeholder,
            FontFace = Fonts.Regular,
            TextSize = 13,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = row,
        })
        paint(field, "BackgroundColor3", "Field")
        paint(field, "TextColor3", "Text")
        paint(field, "PlaceholderColor3", "Sub")
        corner(9, field)
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = field })
        local line = stroke(field, "Line", 0.9, 1)
        field.Focused:Connect(function()
            tween(line, 0.2, { Color = P.Accent, Transparency = 0 })
        end)
        field.FocusLost:Connect(function()
            tween(line, 0.2, { Color = P.Line, Transparency = 0.9 })
        end)
        return field
    end

    local function valueRow(card, title, initial, onCommit)
        local row = addRow(card, 50)
        Mk.rowTitle(row, title, nil, 160)
        Search.Add(row, "Setting", title)
        local field = new("TextBox", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -16, 0.5, 0),
            Size = UDim2.fromOffset(120, 32),
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Text = tostring(initial),
            FontFace = Fonts.Regular,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Center,
            Parent = row,
        })
        paint(field, "BackgroundColor3", "Field")
        paint(field, "TextColor3", "Text")
        corner(9, field)
        local line = stroke(field, "Line", 0.9, 1)
        field.Focused:Connect(function()
            tween(line, 0.2, { Color = P.Accent, Transparency = 0 })
        end)
        field.FocusLost:Connect(function()
            tween(line, 0.2, { Color = P.Line, Transparency = 0.9 })
            local shown = onCommit(field.Text)
            if shown ~= nil then
                field.Text = tostring(shown)
            end
        end)
        return field
    end

    do
        local LocalPlayer = player
        local scriptId = math.random(1, 1000000)
        _G.ThanhDuyHubLoopDashV4Id = scriptId

        local function isCurrent()
            return _G.ThanhDuyHubLoopDashV4Id == scriptId
        end

        local connections = {}

        local Config = {
            Enabled = true,
            ThanhDuyHubLoopDashV4Enabled = true,
            ThanhDuyHubLoopDashV4Anim = "rbxassetid://10503381238",
            ThanhDuyHubLoopDashV4Delay = 0.26,
            ThanhDuyHubLoopDashV4Jump = 55,
            ThanhDuyHubLoopDashV4Accuracy = 12,
            ThanhDuyHubLoopDashV4CancelDelay = 0.35,
            CancelEnabled = true,
            CooldownActive = true,
            NoClipEnabled = false,
            DashRange = 170,
            TouchMode = true,
            Platform = "PC",
            Keybind = "E",
            CamDistance = 20,
            CamHeight = 5,
            CamSmooth = 0.35,
            FlickEnabled = false,
            FlickDelay = 0.22,
            AutoPingComp = true,
            Smoothness = 50,
            MagnetEnabled = false,
            MagnetDelay = 0.3,
            MagnetMaxAnimWait = 5.0,
            MagnetDuration = 0.21,
            AutoJumpEnabled = false,
            JumpCount = 1,
            JumpPower = 50,
            StrengthDash = false,
            StrengthPower = 35,
            LockDuration = 0.65,
            Floater = true,
            FlingUpPower = 55,
            CooldownAnims = { ["10491993682"] = true, ["10479335397"] = true, ["13380255751"] = true },
        }

        local SAVE_FILE = "ThanhDuyHubLoopDashLegit_Config.json"
        pcall(function()
            if readfile and isfile and isfile(SAVE_FILE) then
                local data = HttpService:JSONDecode(readfile(SAVE_FILE))
                if type(data) == "table" then
                    for k, v in pairs(data) do
                        Config[k] = v
                    end
                end
            end
        end)

        local function saveConfig()
            pcall(function()
                if writefile then
                    writefile(SAVE_FILE, HttpService:JSONEncode(Config))
                end
            end)
        end

        local isLoopActive = false
        local isCooldown = false
        local isExecuting = false
        local camera = workspace.CurrentCamera

        table.insert(connections, RunService.RenderStepped:Connect(function()
            if not isCurrent() or not isLoopActive then
                return
            end
            local character = LocalPlayer.Character
            if not character then
                return
            end
            local rootPart = character:FindFirstChild("HumanoidRootPart")
            if not rootPart then
                return
            end
            local _, yaw, _ = rootPart.CFrame:ToEulerAnglesYXZ()
            local _, _, roll = camera.CFrame:ToEulerAnglesYXZ()
            local pitch = math.asin(camera.CFrame.LookVector.Y)
            local newLookCFrame = CFrame.fromEulerAnglesYXZ(pitch, yaw, roll)
            local camPos = rootPart.Position + Vector3.new(0, Config.CamHeight, 0) - (newLookCFrame.LookVector * Config.CamDistance)
            local focusPos = rootPart.Position + Vector3.new(0, 3, 0)
            local targetCF = CFrame.lookAt(camPos, focusPos)
            camera.CFrame = camera.CFrame:Lerp(targetCF, Config.CamSmooth)
        end))

        local function fireDash()
            local character = LocalPlayer.Character
            if not character then
                return
            end
            local remote = character:FindFirstChild("Communicate")
            if remote then
                local args = { {
                    Dash = Enum.KeyCode.W,
                    Key = Enum.KeyCode.Q,
                    Goal = "KeyPress",
                } }
                remote:FireServer(unpack(args))
            end
        end

        local function applyFloater(root)
            if not Config.Floater or not root or not root.Parent then
                return
            end
            local initialY = root.Position.Y
            local upPower = Config.FlingUpPower or 55
            root.AssemblyLinearVelocity = Vector3.new(0, upPower, 0)
            local bodyVelocity = Instance.new("BodyVelocity")
            bodyVelocity.Name = "FloaterVelocity"
            bodyVelocity.MaxForce = Vector3.new(0, math.huge, 0)
            bodyVelocity.Velocity = Vector3.new(0, upPower, 0)
            bodyVelocity.Parent = root
            local trackConnection
            trackConnection = RunService.Heartbeat:Connect(function()
                if not root or not root.Parent or not bodyVelocity or bodyVelocity.Parent ~= root then
                    if trackConnection then
                        trackConnection:Disconnect()
                    end
                    return
                end
                if (root.Position.Y - initialY) >= 4 then
                    trackConnection:Disconnect()
                    bodyVelocity:Destroy()
                end
            end)
            task.delay(0.5, function()
                if trackConnection then
                    trackConnection:Disconnect()
                end
                if bodyVelocity and bodyVelocity.Parent == root then
                    bodyVelocity:Destroy()
                end
            end)
        end

        local function applyStrengthDash(root, targetPos)
            if not Config.StrengthDash or not root or not root.Parent then
                return
            end
            local strength = Config.StrengthPower or 35
            local dir = (targetPos and (Vector3.new(targetPos.X, root.Position.Y, targetPos.Z) - root.Position).Unit) or root.CFrame.LookVector
            root.AssemblyLinearVelocity = Vector3.new(dir.X * strength * 1.5, root.AssemblyLinearVelocity.Y, dir.Z * strength * 1.5)
        end

        local function executeAutoJump(root, hum)
            if not Config.AutoJumpEnabled or not root or not root.Parent or not hum then
                return
            end
            local count = Config.JumpCount or 1
            local power = Config.JumpPower or 50
            task.spawn(function()
                for i = 1, count do
                    if not root or not root.Parent or not hum or hum.Health <= 0 then
                        break
                    end
                    root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, power, root.AssemblyLinearVelocity.Z)
                    task.wait(0.15)
                end
            end)
        end

        local function getClosestTarget()
            local character = LocalPlayer.Character
            if not character or not character:FindFirstChild("HumanoidRootPart") then
                return nil
            end
            local rootPart = character.HumanoidRootPart
            local liveFolder = workspace:FindFirstChild("Live")
            local closestTarget, maxDistance = nil, Config.DashRange
            if liveFolder then
                for _, obj in pairs(liveFolder:GetChildren()) do
                    if obj:IsA("Model") and obj ~= character then
                        if obj.Name == "Weakest Dummy" or Players:GetPlayerFromCharacter(obj) then
                            local tRoot = obj:FindFirstChild("HumanoidRootPart") or obj:FindFirstChild("Torso") or obj:FindFirstChild("UpperTorso")
                            if tRoot then
                                local dist = (rootPart.Position - tRoot.Position).Magnitude
                                if dist < maxDistance then
                                    maxDistance = dist
                                    closestTarget = obj
                                end
                            end
                        end
                    end
                end
            end
            if not closestTarget then
                local params = OverlapParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = { character }
                local parts = workspace:GetPartBoundsInRadius(rootPart.Position, Config.DashRange, params)
                for _, part in pairs(parts) do
                    local model = part:FindFirstAncestorOfClass("Model")
                    if model and model ~= character and (model:FindFirstChild("Humanoid") or model:FindFirstChildOfClass("Humanoid")) then
                        local tRoot = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso")
                        if tRoot then
                            local dist = (rootPart.Position - tRoot.Position).Magnitude
                            if dist < maxDistance then
                                maxDistance = dist
                                closestTarget = model
                            end
                        end
                    end
                end
            end
            return closestTarget
        end

        local CoreButton = new("TextButton", {
            Name = "LoopDashDashButton",
            Size = UDim2.fromOffset(56, 56),
            Position = UDim2.fromScale(0.7, 0.5),
            BackgroundColor3 = Color3.fromRGB(20, 20, 20),
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "Dash",
            TextColor3 = Color3.fromRGB(255, 255, 255),
            FontFace = Fonts.Semibold,
            TextSize = 13,
            Visible = Config.TouchMode,
            Active = true,
            ZIndex = 50,
            Parent = gui,
        })
        pcall(function()
            CoreButton.Draggable = true
        end)
        corner(28, CoreButton)
        local coreStroke = new("UIStroke", {
            Color = Color3.fromRGB(255, 50, 100),
            Thickness = 1.5,
            Parent = CoreButton,
        })

        local CooldownBar = new("Frame", {
            Name = "CooldownBar",
            Size = UDim2.new(1, -8, 0, 4),
            Position = UDim2.new(0, 4, 1, 4),
            BackgroundColor3 = Color3.fromRGB(0, 0, 0),
            BackgroundTransparency = 0.5,
            BorderSizePixel = 0,
            Visible = false,
            ZIndex = 51,
            Parent = CoreButton,
        })
        corner(2, CooldownBar)
        local CooldownFill = new("Frame", {
            Name = "Fill",
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.fromRGB(255, 100, 150),
            BorderSizePixel = 0,
            ZIndex = 52,
            Parent = CooldownBar,
        })
        corner(2, CooldownFill)

        local function startCooldown(duration)
            if not isCurrent() or isCooldown then
                return
            end
            isCooldown = true
            CooldownBar.Visible = true
            CooldownFill.Size = UDim2.fromScale(1, 1)
            local cooldownTween = TweenService:Create(CooldownFill, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(0, 1) })
            cooldownTween:Play()
            task.delay(duration, function()
                isCooldown = false
                CooldownBar.Visible = false
            end)
        end

        local function resetState()
            isLoopActive = false
            local character = LocalPlayer.Character
            if character then
                local hum = character:FindFirstChild("Humanoid")
                if hum then
                    hum.AutoRotate = true
                end
                local root = character:FindFirstChild("HumanoidRootPart")
                if root then
                    for _, obj in pairs(root:GetChildren()) do
                        if obj:IsA("BodyVelocity") or obj:IsA("LinearVelocity") or obj:IsA("Attachment") or obj:IsA("BodyAngularVelocity") then
                            obj:Destroy()
                        end
                    end
                end
            end
        end

        local function executeMagnetTech(targetRoot, root, hum)
            if not Config.MagnetEnabled or not targetRoot or not root then
                return
            end
            task.wait(Config.MagnetDelay or 0.3)
            if not root.Parent or not targetRoot.Parent then
                return
            end
            root.CFrame = CFrame.new(targetRoot.Position + Vector3.new(0, 2, 0))
            local velocity = root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(0, velocity.Y, 0)
            local startTime = os.clock()
            local duration = Config.MagnetDuration or 0.21
            local connPull
            connPull = RunService.Heartbeat:Connect(function()
                if not root or not root.Parent or not targetRoot or not targetRoot.Parent or (os.clock() - startTime >= duration) then
                    if connPull then
                        connPull:Disconnect()
                    end
                    return
                end
                local currentPosition = root.Position
                local targetHorizontal = Vector3.new(targetRoot.Position.X, currentPosition.Y, targetRoot.Position.Z)
                local direction = targetHorizontal - currentPosition
                if direction.Magnitude > 1 then
                    local desiredVelocity = direction.Unit * 50
                    local currentVelocity = root.AssemblyLinearVelocity
                    local newVelocity = currentVelocity:Lerp(desiredVelocity, 0.65)
                    root.AssemblyLinearVelocity = Vector3.new(newVelocity.X * 0.85, currentVelocity.Y, newVelocity.Z * 0.85)
                end
            end)
            if connPull then
                while connPull.Connected and root and root.Parent do
                    task.wait(0.05)
                end
            end
            if Config.AutoJumpEnabled then
                executeAutoJump(root, hum)
            end
        end

        local function executeLoopDash()
            if not isCurrent() or isExecuting or isCooldown then
                return
            end
            if not Config.Enabled or not Config.ThanhDuyHubLoopDashV4Enabled then
                return
            end
            local character = LocalPlayer.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local hum = character and character:FindFirstChild("Humanoid")
            if not root or not hum then
                return
            end
            local targetModel = getClosestTarget()
            if not targetModel then
                return
            end
            local targetRoot = targetModel:FindFirstChild("HumanoidRootPart") or targetModel:FindFirstChild("Torso") or targetModel:FindFirstChild("UpperTorso")
            if not targetRoot then
                return
            end

            isExecuting = true

            if not Config.TouchMode then
                task.wait(Config.ThanhDuyHubLoopDashV4Delay)
            end

            if not isCurrent() then
                isExecuting = false
                return
            end

            isLoopActive = true
            local prevCameraType = camera.CameraType
            camera.CameraType = Enum.CameraType.Scriptable

            root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, Config.ThanhDuyHubLoopDashV4Jump, root.AssemblyLinearVelocity.Z)
            fireDash()
            applyStrengthDash(root, targetRoot.Position)

            local startT = tick()
            local bav = Instance.new("BodyAngularVelocity")
            bav.MaxTorque = Vector3.new(0, 1000000, 0)
            bav.P = 15000
            bav.Parent = root

            local conn
            conn = RunService.Heartbeat:Connect(function()
                if not isCurrent() or not targetRoot or not targetRoot.Parent or not root or not root.Parent then
                    if bav then
                        bav:Destroy()
                    end
                    resetState()
                    applyFloater(root)
                    isExecuting = false
                    if conn then
                        conn:Disconnect()
                    end
                    camera.CameraType = prevCameraType
                    return
                end

                local elapsed = tick() - startT
                local torsoPos, rootPos = targetRoot.Position, root.Position
                hum.AutoRotate = false

                for _, p in pairs(character:GetChildren()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = false
                    end
                end

                local forwardDir = (torsoPos - rootPos).Unit
                local sideVec = Vector3.new(-forwardDir.Z, 0, forwardDir.X)

                if Config.FlickEnabled then
                    local fDelay = Config.FlickDelay or 0.22
                    local smoothVal = math.clamp((1000 - (Config.Smoothness or 50)) / 1000, 0.01, 1)
                    smoothVal = math.clamp(smoothVal * 0.75, 0.01, 1)
                    if fDelay <= elapsed then
                        local lookPos = Vector3.new(torsoPos.X, rootPos.Y, torsoPos.Z)
                        root.CFrame = root.CFrame:Lerp(CFrame.lookAt(rootPos, lookPos), 1 - math.pow(1 - smoothVal, 0.016 * 60))
                    end
                else
                    local progress = math.clamp(elapsed / 0.38, 0, 1)
                    local loopyenDrift = math.sin(progress * math.pi * 1.6) * (Config.ThanhDuyHubLoopDashV4Accuracy * 0.3)
                    local targetLookPos = torsoPos + (forwardDir * -0.4) + (sideVec * loopyenDrift)
                    local lookAtCF = CFrame.lookAt(rootPos, Vector3.new(targetLookPos.X, rootPos.Y, targetLookPos.Z))
                    local relativeCF = root.CFrame:Inverse() * lookAtCF
                    local _, y, _ = relativeCF:ToEulerAnglesXYZ()
                    if bav and bav.Parent then
                        bav.AngularVelocity = Vector3.new(0, y * 45, 0)
                    end
                end

                local distXZ = (Vector2.new(rootPos.X, rootPos.Z) - Vector2.new(torsoPos.X, torsoPos.Z)).Magnitude
                if Config.CancelEnabled and elapsed > Config.ThanhDuyHubLoopDashV4CancelDelay and distXZ < 2.2 then
                    if bav then
                        bav:Destroy()
                    end
                    resetState()
                    applyFloater(root)
                    isExecuting = false
                    conn:Disconnect()
                    local savedCF = camera.CFrame
                    camera.CameraType = prevCameraType
                    RunService.RenderStepped:Wait()
                    camera.CFrame = savedCF
                    if Config.MagnetEnabled then
                        task.spawn(function()
                            executeMagnetTech(targetRoot, root, hum)
                        end)
                    elseif Config.AutoJumpEnabled then
                        executeAutoJump(root, hum)
                    end
                    return
                end

                if not Config.Enabled or elapsed > (Config.LockDuration or 1.5) then
                    if bav then
                        bav:Destroy()
                    end
                    resetState()
                    applyFloater(root)
                    isExecuting = false
                    conn:Disconnect()
                    local savedCF = camera.CFrame
                    camera.CameraType = prevCameraType
                    RunService.RenderStepped:Wait()
                    camera.CFrame = savedCF
                    if Config.MagnetEnabled then
                        task.spawn(function()
                            executeMagnetTech(targetRoot, root, hum)
                        end)
                    elseif Config.AutoJumpEnabled then
                        executeAutoJump(root, hum)
                    end
                    return
                end
            end)
        end

        CoreButton.MouseButton1Click:Connect(function()
            executeLoopDash()
        end)

        table.insert(connections, UserInputService.InputBegan:Connect(function(input, gpe)
            if not isCurrent() or gpe then
                return
            end
            if Config.Platform == "PC" then
                local okKey, keyCode = pcall(function()
                    return Enum.KeyCode[string.upper(tostring(Config.Keybind))]
                end)
                if okKey and keyCode and input.KeyCode == keyCode then
                    executeLoopDash()
                end
            end
        end))

        local function setupCharacter(char)
            if not isCurrent() then
                return
            end
            local hum = char:WaitForChild("Humanoid")
            table.insert(connections, hum.AnimationPlayed:Connect(function(track)
                if not isCurrent() then
                    return
                end
                local anim = track.Animation
                if not anim then
                    return
                end
                local animId = tostring(anim.AnimationId):match("%d+")
                if Config.CooldownActive and Config.CooldownAnims[animId] then
                    startCooldown(5)
                end

                local isDashAnim = anim.AnimationId:find("10479335397") or anim.AnimationId:find("13380255751")
                local isUppercut = (anim.AnimationId == Config.ThanhDuyHubLoopDashV4Anim)

                if Config.Enabled and not Config.TouchMode then
                    if isUppercut or isDashAnim then
                        if isDashAnim then
                            local maxWait = Config.MagnetMaxAnimWait or 5.0
                            local waitStart = tick()
                            while tick() - waitStart < maxWait do
                                local closest = getClosestTarget()
                                if closest then
                                    break
                                end
                                task.wait(0.05)
                            end
                        end
                        executeLoopDash()
                    end
                end
            end))
        end

        table.insert(connections, RunService.Stepped:Connect(function()
            if not isCurrent() or not Config.NoClipEnabled then
                return
            end
            local character = LocalPlayer.Character
            if character then
                for _, part in pairs(character:GetChildren()) do
                    if part:IsA("BasePart") then
                        part.CanCollide = false
                    end
                end
            end
        end))

        if LocalPlayer.Character then
            task.spawn(setupCharacter, LocalPlayer.Character)
        end
        table.insert(connections, LocalPlayer.CharacterAdded:Connect(function(char)
            task.spawn(setupCharacter, char)
        end))

        gui.Destroying:Connect(function()
            saveConfig()
            if _G.ThanhDuyHubLoopDashV4Id == scriptId then
                _G.ThanhDuyHubLoopDashV4Id = nil
            end
            for _, conn in pairs(connections) do
                pcall(function()
                    conn:Disconnect()
                end)
            end
            table.clear(connections)
        end)

        Players.PlayerRemoving:Connect(function(removed)
            if removed == LocalPlayer then
                saveConfig()
            end
        end)

        local scroll = Pg.loopScroll
        local toggles = {}
        local inputs = {}

        local function addToggle(card, title, desc, key, after)
            local control = Mk.createToggle(card, title, desc, Config[key], function(state)
                Config[key] = state
                if after then
                    after(state)
                end
                saveConfig()
            end)
            toggles[key] = control
            return control
        end

        local function addNumber(card, title, key, clampMax, clampMin)
            local field = valueRow(card, title, Config[key], function(raw)
                local val = tonumber(raw)
                if val then
                    if clampMin and val < clampMin then
                        val = clampMin
                    end
                    if clampMax and val > clampMax then
                        val = clampMax
                    end
                    Config[key] = val
                    saveConfig()
                end
                return Config[key]
            end)
            inputs[key] = field
            return field
        end

        local statusCard = section(scroll, "LoopDash")
        addToggle(statusCard, "LoopDash", "Turn the dash loop on or off", "Enabled", nil)
        addToggle(statusCard, "Touch Mode", "Show the on screen Dash button", "TouchMode", function(state)
            CoreButton.Visible = state
        end)
        addToggle(statusCard, "Noclip", "Pass through parts while active", "NoClipEnabled", nil)
        addToggle(statusCard, "Flick", "Flick toward the target", "FlickEnabled", nil)
        addToggle(statusCard, "Magnet", "Pull toward the target after the dash", "MagnetEnabled", nil)
        addToggle(statusCard, "Auto Jump", "Jump after the dash ends", "AutoJumpEnabled", nil)
        addToggle(statusCard, "Strength Dash", "Add extra dash strength", "StrengthDash", nil)
        addToggle(statusCard, "Floater", "Float up after the dash", "Floater", nil)
        addToggle(statusCard, "Auto Compa", "Start the cooldown bar after dash animations", "CooldownActive", nil)

        local settingsCard = section(scroll, "Settings")
        addNumber(settingsCard, "Delay", "ThanhDuyHubLoopDashV4Delay", nil, 0.26)
        addNumber(settingsCard, "Jump Power", "ThanhDuyHubLoopDashV4Jump", 55, nil)
        addNumber(settingsCard, "Accuracy", "ThanhDuyHubLoopDashV4Accuracy", nil, nil)
        addNumber(settingsCard, "Dash Range", "DashRange", 170, nil)
        addNumber(settingsCard, "Cancel Delay", "ThanhDuyHubLoopDashV4CancelDelay", nil, nil)
        addNumber(settingsCard, "Lock Duration", "LockDuration", nil, nil)
        addNumber(settingsCard, "Fling Power", "FlingUpPower", nil, nil)
        addNumber(settingsCard, "Flick Delay", "FlickDelay", nil, nil)
        addNumber(settingsCard, "Smoothness", "Smoothness", nil, nil)
        addNumber(settingsCard, "Magnet Delay", "MagnetDelay", nil, nil)
        addNumber(settingsCard, "Magnet Max Wait", "MagnetMaxAnimWait", nil, nil)
        addNumber(settingsCard, "Jump Count", "JumpCount", nil, nil)
        addNumber(settingsCard, "Jump Height", "JumpPower", nil, nil)
        addNumber(settingsCard, "Strength Power", "StrengthPower", nil, nil)
        addNumber(settingsCard, "Cam Distance", "CamDistance", nil, nil)
        addNumber(settingsCard, "Cam Height", "CamHeight", nil, nil)
        addNumber(settingsCard, "Cam Smooth", "CamSmooth", nil, nil)
        inputs.Keybind = valueRow(settingsCard, "Keybind", Config.Keybind, function(raw)
            local value = string.gsub(tostring(raw), "%s", "")
            if value ~= "" then
                Config.Keybind = value
                saveConfig()
            end
            return Config.Keybind
        end)

        local configCard = section(scroll, "Config")
        local configField = configBox(configCard, "Config JSON", "Paste config JSON here")
        local configButtons
        configButtons = Mk.createButtons(configCard, {
            {
                Text = "Copy Config",
                Role = "Field",
                Callback = function()
                    local ok = setClipboardText(HttpService:JSONEncode(Config))
                    if ok then
                        flashButton(configButtons[1], "Copied", "Copy Config")
                    else
                        notify("LoopDash", "Clipboard is not available", "error", 2.2, true)
                    end
                end,
            },
            {
                Text = "Apply",
                Callback = function()
                    local ok, decoded = pcall(function()
                        return HttpService:JSONDecode(configField.Text)
                    end)
                    if ok and type(decoded) == "table" then
                        for k, v in pairs(decoded) do
                            Config[k] = v
                        end
                        saveConfig()
                        for key, field in pairs(inputs) do
                            if Config[key] ~= nil then
                                field.Text = tostring(Config[key])
                            end
                        end
                        for key, control in pairs(toggles) do
                            if Config[key] ~= nil then
                                control.Set(Config[key] and true or false)
                            end
                        end
                        CoreButton.Visible = Config.TouchMode and true or false
                        flashButton(configButtons[2], "Applied", "Apply")
                        notify("LoopDash", "Config applied", "success", 2, true)
                    else
                        notify("LoopDash", "Invalid config JSON", "error", 2.2, true)
                    end
                end,
            },
            {
                Text = "Save",
                Role = "Field",
                Callback = function()
                    saveConfig()
                    flashButton(configButtons[3], "Saved", "Save")
                end,
            },
        })
    end

    do
        local plr = player
        local alive = true

        local AB = {
            Enabled = false,
            AutoM1 = false,
            AutoCounter = false,
            DashPredict = false,
            FOV = 180,
            RotateChar = false,
            RotateCam = false,
            CamEasing = 0,
            CharEasing = 100,
            FriendCheck = false,
        }

        local interuptableMoves = {
            "Shove", "Normal Punch", "Uppercut", "Flowing Water", "Lethal Whirlwind Stream", "Hunter's Grasp", "Doom Dive", "Crowd Buster", "Hammer Heel", "Binding Cloth",
            "Jet Dive", "Blitz Shot", "Ignition Burst", "Flash Strike", "Scatter", "Explosive Shuriken", "Homerun", "Beatdown", "Four Ball",
            "Quick Slice", "Atmos Cleave", "Pinpoint Cut", "Crushing Pull", "Windstorm Fury", "Stone Coffin", "Expulsive Push", "GoPush",
            "Vanishing Kick", "Whirlwind Drop", "Head First", "Weboom", "Plasma Cannon", "Trinity Tear", "Twin Burst", "TornadoBind",
        }
        local barrageMoves = { "Consecutive Punches", "Machine Gun Blows", "Bullet Barrage" }
        local ignoreM1 = { "Counter", "AbsoluteImmortal", "AtomicCounter", "HunterCounter", "UpFrames", "Ragdoll", "ForceField", "CanBringUp" }
        local ignoreEnemy = { "DoingEmote", "CancelEmote", "CancelEmote2", "BeingLaunched", "Freeze" }
        local ignoreLocal = { "Counter", "HunterCounter", "DoingEmote", "CancelEmote", "CancelEmote2", "BeingLaunched", "Ragdoll", "Freeze", "BarrageBind" }

        local function makeLookupSet(list)
            local lookup = {}
            for _, value in ipairs(list) do
                lookup[value] = true
            end
            return lookup
        end

        local ignoreEnemySet = makeLookupSet(ignoreEnemy)
        local ignoreLocalSet = makeLookupSet(ignoreLocal)
        local interruptMovesSet = makeLookupSet(interuptableMoves)
        local barrageMovesSet = makeLookupSet(barrageMoves)

        local activeConnections = {}
        local playersConnections = {}
        local charConnections = {}
        local playersList = {}

        local blocking = false
        local pcharacter, phumanoid, phumanoidRootPart, premote, panimator, counterTool

        local FarDashDistance = 28
        local barrageDistance = 18
        local movingM1Distance = 15
        local m1Distance = 9

        local lsideDashAnim = "10480796021"
        local rsideDashAnim = "10480793962"

        local holdM1Args = { Goal = "LeftClick" }
        local releaseM1Args = { Goal = "LeftClickRelease" }
        local holdBlockArgs = { Goal = "KeyPress", Key = Enum.KeyCode.F }
        local releaseBlockArgs = { Goal = "KeyRelease", Key = Enum.KeyCode.F }

        local function destroyConnection(conn)
            if conn then
                conn:Disconnect()
            end
        end

        local function clearConnectionsTable(list)
            if list then
                for _, conn in ipairs(list) do
                    destroyConnection(conn)
                end
            end
        end

        local function newConnection(list, parent, signal, callback)
            local conn = parent[signal]:Connect(callback)
            table.insert(list, conn)
            return conn
        end

        local function getPing(divide)
            divide = divide or 1
            local ok, value = pcall(function()
                return StatsService.Network.ServerStatsItem["Data Ping"]:GetValue()
            end)
            return (ok and value or 50) / divide
        end

        local function getDelay(baseTiming)
            local timing = baseTiming + (getPing() - 50) * -0.0003846
            return { timing, baseTiming - timing }
        end

        local function filter(char, ignoreList)
            if not char then
                return false
            end
            local lookup = ignoreList or {}
            for _, ignore in pairs(char:GetChildren()) do
                if lookup[ignore.Name] then
                    return false
                end
            end
            return true
        end

        local function isAnimationRunning(animationId, thuman)
            local tanimator
            if not thuman then
                tanimator = panimator
            else
                tanimator = thuman:FindFirstChildOfClass("Animator")
            end
            if not tanimator then
                return false
            end
            for _, track in ipairs(tanimator:GetPlayingAnimationTracks()) do
                if track.Animation and track.Animation.AnimationId == "rbxassetid://" .. tostring(animationId) then
                    return true
                end
            end
            return false
        end

        local function isFriend(otherPlayer, checkToggle)
            if playersList[otherPlayer.Name] == "Friend" then
                if checkToggle then
                    return AB.FriendCheck and true or false
                end
                return true
            end
            return false
        end

        local function updateFriends(otherPlayer)
            local ok, result = pcall(function()
                return otherPlayer:IsFriendsWithAsync(plr.UserId)
            end)
            if ok and result then
                playersList[otherPlayer.Name] = "Friend"
                return
            end
            playersList[otherPlayer.Name] = "Neutral"
        end

        local function newCamPosition(camPos, newYaw, pitch)
            local cam = workspace.CurrentCamera
            cam.CFrame = CFrame.new(camPos) * CFrame.Angles(0, newYaw, 0) * CFrame.Angles(pitch, 0, 0)
        end

        local function smoothRotateCamToPos(targetPosition, duration)
            local cam = workspace.CurrentCamera
            local startTime = tick()
            local startCFrame = cam.CFrame
            local camPos = startCFrame.Position
            local startLook = startCFrame.LookVector
            local startYaw = math.atan2(-startLook.X, -startLook.Z)
            local pitch = math.asin(startLook.Y)
            local direction = (targetPosition - camPos).Unit
            local targetYaw = math.atan2(-direction.X, -direction.Z)
            local delta = math.atan2(math.sin(targetYaw - startYaw), math.cos(targetYaw - startYaw))
            local connection
            connection = RunService.RenderStepped:Connect(function()
                local elapsed = tick() - startTime
                local alpha = math.clamp(elapsed / math.max(duration, 0.0001), 0, 1)
                local smoothAlpha = alpha * alpha * (3 - 2 * alpha)
                local currentCamPos = cam.CFrame.Position
                local newYaw = startYaw + delta * smoothAlpha
                newCamPosition(currentCamPos, newYaw, pitch)
                if alpha >= 1 then
                    destroyConnection(connection)
                end
            end)
        end

        local function GetAngleToTarget(targetRoot)
            if not phumanoidRootPart or not targetRoot then
                return nil
            end
            local lookVector = phumanoidRootPart.CFrame.LookVector
            lookVector = Vector3.new(lookVector.X, 0, lookVector.Z).Unit
            local toTarget = targetRoot.Position - phumanoidRootPart.Position
            toTarget = Vector3.new(toTarget.X, 0, toTarget.Z)
            if toTarget.Magnitude == 0 then
                return 0
            end
            toTarget = toTarget.Unit
            local dot = math.clamp(lookVector:Dot(toTarget), -1, 1)
            return math.deg(math.acos(dot))
        end

        local function IsInFOV(targetHrp, fovDegrees)
            local angle = GetAngleToTarget(targetHrp)
            if angle == nil then
                return false
            end
            return angle <= fovDegrees / 2
        end

        local function getCooldownsGui()
            local hotbar = playerGui:WaitForChild("Hotbar")
            return hotbar:WaitForChild("Backpack"):WaitForChild("Hotbar")
        end

        local function LookAt(enemyHrp, enemyHuman, easingTime)
            easingTime = easingTime or 0
            local tweenConn
            tweenConn = RunService.Heartbeat:Connect(function(dt)
                if not enemyHrp.Parent or not phumanoidRootPart.Parent or enemyHuman.Health <= 0 or phumanoid.Health <= 0 then
                    destroyConnection(tweenConn)
                elseif filter(phumanoidRootPart.Parent, ignoreLocal) then
                    phumanoid.AutoRotate = false
                    local currentCFrame = phumanoidRootPart.CFrame
                    local targetPosition = Vector3.new(enemyHrp.Position.X, currentCFrame.Position.Y, enemyHrp.Position.Z)
                    local targetCFrame = CFrame.new(currentCFrame.Position, targetPosition)
                    if easingTime <= 0 then
                        phumanoidRootPart.CFrame = targetCFrame
                    else
                        local alpha = math.clamp(dt / easingTime, 0, 1)
                        phumanoidRootPart.CFrame = currentCFrame:Lerp(targetCFrame, alpha)
                    end
                end
            end)
            table.insert(activeConnections, tweenConn)
            return tweenConn
        end

        local function holdblock()
            if not blocking then
                blocking = true
                premote:FireServer(holdBlockArgs)
            end
        end

        local function releaseblock()
            if blocking then
                blocking = false
                premote:FireServer(releaseBlockArgs)
            end
        end

        local function block(holdDuration, enemyHrp, enemyHuman)
            if pcharacter:FindFirstChild("Counter") then
                return
            end
            holdblock()
            local tweenConn
            if AB.RotateChar then
                tweenConn = LookAt(enemyHrp, enemyHuman, AB.CharEasing / 1000)
            end
            if AB.RotateCam then
                smoothRotateCamToPos(enemyHrp.Position, AB.CamEasing / 100)
            end
            task.wait(holdDuration)
            destroyConnection(tweenConn)
            releaseblock()
        end

        local function justM1()
            task.wait()
            premote:FireServer(holdM1Args)
            task.wait()
            premote:FireServer(releaseM1Args)
            task.wait()
        end

        local function m1(enemyHrp, enemyHuman)
            if enemyHrp.Parent and filter(enemyHrp.Parent, ignoreM1) and not pcharacter:FindFirstChild("CanBringUp") then
                local m1Tween
                if AB.RotateChar then
                    m1Tween = LookAt(enemyHrp, enemyHuman, AB.CharEasing / 1000)
                end
                if AB.RotateCam then
                    smoothRotateCamToPos(enemyHrp.Position, AB.CamEasing / 100)
                end
                justM1()
                task.wait(0.1)
                destroyConnection(m1Tween)
            end
        end

        local function isMovingTowards(targetHRP)
            local velocity = targetHRP.AssemblyLinearVelocity
            if velocity.Magnitude < 0.1 then
                return false
            end
            local directionToLocal = (phumanoidRootPart.Position - targetHRP.Position).Unit
            local moveDirection = velocity.Unit
            return moveDirection:Dot(directionToLocal) > 0.7
        end

        local function perfectBlock(enemyHrp, enemyHuman, ignoreDistance)
            local magnitude = (phumanoidRootPart.Position - enemyHrp.Position).Magnitude
            block(getDelay(0.25)[1], enemyHrp, enemyHuman)
            if ((not AB.AutoM1) or ((magnitude > m1Distance) and not (magnitude <= movingM1Distance and isMovingTowards(enemyHrp)))) and not ignoreDistance then
                return
            end
            m1(enemyHrp, enemyHuman)
        end

        local function barrage(HRP, enemyHuman, enemyChar)
            local lookTween = LookAt(HRP, enemyHuman, AB.CharEasing / 1000)
            local blockTween
            local startTime = tick()
            blockTween = RunService.Heartbeat:Connect(function()
                holdblock()
                local elapsed = tick() - startTime
                local alpha = math.clamp(elapsed / 0.1, 0, 1)
                if enemyChar:FindFirstChild("NoBlock") or (phumanoidRootPart.Position - HRP.Position).Magnitude >= barrageDistance + 5 then
                    destroyConnection(lookTween)
                    destroyConnection(blockTween)
                    releaseblock()
                    if AB.AutoM1 and (phumanoidRootPart.Position - HRP.Position).Magnitude <= m1Distance then
                        m1(HRP, enemyHuman)
                    end
                end
                if alpha >= 1 and not enemyChar:FindFirstChild("Slowed") then
                    destroyConnection(lookTween)
                    destroyConnection(blockTween)
                    releaseblock()
                end
            end)
        end

        local function autocounter(enemyHrp, enemyHuman, ignore)
            if ignore or not counterTool or not AB.AutoCounter then
                return true
            end
            local cooldowns = getCooldownsGui()
            if cooldowns:WaitForChild(4):WaitForChild("Base"):FindFirstChild("Cooldown") then
                return true
            end
            premote:FireServer({
                IsAutoActivate = true,
                Goal = "Console Move",
                Tool = counterTool,
                ToolName = counterTool.Name,
            })
            return false
        end

        local function checkEvent(event)
            if not alive or not AB.Enabled or not event then
                return
            end
            if isrbxactive and not isrbxactive() then
                return
            end
            if not pcharacter or not phumanoid or not phumanoidRootPart or not premote or not panimator then
                return
            end

            local eventName = event.Name
            local enemyChar = event:FindFirstAncestorWhichIsA("Model")
            if not enemyChar and event.Parent then
                enemyChar = event.Parent:FindFirstAncestorWhichIsA("Model")
            end
            if not enemyChar then
                return
            end

            local enemy = Players:FindFirstChild(enemyChar.Name)
            if not enemy or enemy == plr then
                return
            end

            local enemyHrp = enemyChar:FindFirstChild("HumanoidRootPart")
            local enemyHuman = enemyChar:FindFirstChild("Humanoid")
            if not enemyHuman or not enemyHrp or phumanoid.Health <= 0 or enemyHuman.Health <= 0 then
                return
            end

            if eventName == "Counter" or isFriend(enemy, true) then
                return
            end

            local magnitude = (phumanoidRootPart.Position - enemyHrp.Position).Magnitude

            local filter1 = filter(pcharacter, ignoreLocalSet)
            local filter2 = filter(enemyChar, ignoreEnemySet)

            local m1Danger = magnitude <= m1Distance
            local movingm1 = magnitude <= movingM1Distance and isMovingTowards(enemyHrp)
            local dashed = AB.DashPredict and (isAnimationRunning(lsideDashAnim, enemyHuman) or isAnimationRunning(rsideDashAnim, enemyHuman)) and magnitude <= FarDashDistance

            if (m1Danger or movingm1 or dashed) and filter1 and filter2 then
                local isM1 = eventName == "M1ing"
                local isInterrupt = interruptMovesSet[eventName]
                local isBarrage = barrageMovesSet[eventName]

                if (isM1 or isInterrupt or isBarrage) and IsInFOV(enemyHrp, AB.FOV) then
                    local toContinue = autocounter(enemyHrp, enemyHuman, movingm1)
                    if toContinue then
                        if isM1 then
                            perfectBlock(enemyHrp, enemyHuman, dashed)
                        elseif isInterrupt then
                            m1(enemyHrp, enemyHuman)
                        elseif isBarrage then
                            barrage(enemyHrp, enemyHuman, enemyChar)
                        end
                    end
                end
            end
        end

        local function checkPlayer(otherPlayer)
            if otherPlayer == plr then
                return
            end
            clearConnectionsTable(playersConnections[otherPlayer])
            clearConnectionsTable(charConnections[otherPlayer])
            playersConnections[otherPlayer] = {}
            charConnections[otherPlayer] = {}

            task.spawn(updateFriends, otherPlayer)

            local char = otherPlayer.Character
            if char then
                newConnection(charConnections[otherPlayer], char, "DescendantAdded", checkEvent)
            end

            newConnection(playersConnections[otherPlayer], otherPlayer, "CharacterAdded", function(newChar)
                clearConnectionsTable(charConnections[otherPlayer])
                charConnections[otherPlayer] = {}
                newConnection(charConnections[otherPlayer], newChar, "DescendantAdded", checkEvent)
            end)

            newConnection(playersConnections[otherPlayer], otherPlayer, "CharacterRemoving", function()
                clearConnectionsTable(charConnections[otherPlayer])
                charConnections[otherPlayer] = {}
            end)
        end

        local function onChar(char)
            pcharacter = char
            phumanoid = char:WaitForChild("Humanoid")
            phumanoidRootPart = char:WaitForChild("HumanoidRootPart")
            premote = char:WaitForChild("Communicate")
            panimator = phumanoid:WaitForChild("Animator")
            task.wait(0.5)
            counterTool = plr.Backpack:FindFirstChild("Prey's Peril") or plr.Backpack:FindFirstChild("Split Second Counter")
        end

        for _, otherPlayer in pairs(Players:GetPlayers()) do
            checkPlayer(otherPlayer)
        end
        table.insert(activeConnections, Players.PlayerAdded:Connect(checkPlayer))
        table.insert(activeConnections, Players.PlayerRemoving:Connect(function(removed)
            clearConnectionsTable(charConnections[removed])
            clearConnectionsTable(playersConnections[removed])
            charConnections[removed] = nil
            playersConnections[removed] = nil
            playersList[removed.Name] = nil
        end))

        if plr.Character then
            task.spawn(onChar, plr.Character)
        end
        table.insert(activeConnections, plr.CharacterAdded:Connect(function(char)
            task.spawn(onChar, char)
        end))

        gui.Destroying:Connect(function()
            alive = false
            clearConnectionsTable(activeConnections)
            for _, list in pairs(playersConnections) do
                clearConnectionsTable(list)
            end
            for _, list in pairs(charConnections) do
                clearConnectionsTable(list)
            end
        end)

        local scroll = Pg.blockScroll
        local toggles = {}
        local sliders = {}

        local function addToggle(card, title, desc, key)
            local control = Mk.createToggle(card, title, desc, AB[key], function(state)
                AB[key] = state
            end)
            toggles[key] = control
            return control
        end

        local function addSlider(card, title, key, min, max, suffix)
            local control = Mk.createSlider(card, title, min, max, AB[key], 1, suffix, function(value)
                AB[key] = value
            end)
            sliders[key] = control
            return control
        end

        local blockCard = section(scroll, "Auto Block")
        addToggle(blockCard, "Auto Block", "Block incoming attacks automatically", "Enabled")
        addToggle(blockCard, "Auto m1 Punish", "Punch back after a perfect block", "AutoM1")
        addToggle(blockCard, "Auto Counter", "Use your counter move when it is ready", "AutoCounter")
        addToggle(blockCard, "Dash Prediction", "React to side dashes before they land", "DashPredict")
        addToggle(blockCard, "Friend Check", "Do not block attacks from friends", "FriendCheck")
        addSlider(blockCard, "Autoblock FOV", "FOV", 0, 360, " deg")
        addToggle(blockCard, "Rotate Character", "Face the attacker while blocking", "RotateChar")
        addToggle(blockCard, "Rotate Camera", "Turn the camera toward the attacker", "RotateCam")
        addSlider(blockCard, "Camera Easing", "CamEasing", 0, 100, "")
        addSlider(blockCard, "Character Easing", "CharEasing", 0, 100, "")

        local configCard = section(scroll, "Config")
        local configField = configBox(configCard, "Config JSON", "Paste config JSON here")
        local configButtons
        configButtons = Mk.createButtons(configCard, {
            {
                Text = "Copy Config",
                Role = "Field",
                Callback = function()
                    local ok = setClipboardText(HttpService:JSONEncode(AB))
                    if ok then
                        flashButton(configButtons[1], "Copied", "Copy Config")
                    else
                        notify("Auto Block", "Clipboard is not available", "error", 2.2, true)
                    end
                end,
            },
            {
                Text = "Apply",
                Callback = function()
                    local ok, decoded = pcall(function()
                        return HttpService:JSONDecode(configField.Text)
                    end)
                    if ok and type(decoded) == "table" then
                        for key, current in pairs(AB) do
                            local incoming = decoded[key]
                            if type(incoming) == type(current) then
                                if type(incoming) == "number" then
                                    local limit = key == "FOV" and 360 or 100
                                    incoming = math.clamp(math.floor(incoming + 0.5), 0, limit)
                                    AB[key] = incoming
                                    if sliders[key] then
                                        sliders[key].Set(incoming)
                                    end
                                else
                                    AB[key] = incoming
                                    if toggles[key] then
                                        toggles[key].Set(incoming)
                                    end
                                end
                            end
                        end
                        flashButton(configButtons[2], "Applied", "Apply")
                        notify("Auto Block", "Config applied", "success", 2, true)
                    else
                        notify("Auto Block", "Invalid config JSON", "error", 2.2, true)
                    end
                end,
            },
        })
    end

    do
        local vfxColor = Color3.fromRGB(128, 0, 200)
        genv.VFXEnabled = false

        local vfxChar = player.Character
        local hooked = setmetatable({}, { __mode = "k" })

        local function applyColor(instance)
            if instance:IsA("ParticleEmitter") or instance:IsA("Trail") or instance:IsA("Beam") then
                instance.Color = ColorSequence.new(vfxColor)
            end
        end

        local function processCharacter(char)
            if not char then
                return
            end
            for _, descendant in ipairs(char:GetDescendants()) do
                if genv.VFXEnabled then
                    applyColor(descendant)
                end
            end
            if not hooked[char] then
                hooked[char] = char.DescendantAdded:Connect(function(descendant)
                    if genv.VFXEnabled then
                        applyColor(descendant)
                    end
                end)
            end
        end

        if vfxChar then
            processCharacter(vfxChar)
        end

        local charConn = player.CharacterAdded:Connect(function(newCharacter)
            vfxChar = newCharacter
            processCharacter(newCharacter)
        end)

        gui.Destroying:Connect(function()
            charConn:Disconnect()
            genv.VFXEnabled = false
            for _, conn in pairs(hooked) do
                pcall(function()
                    conn:Disconnect()
                end)
            end
        end)

        local pendingApply = false
        local function scheduleApply()
            if pendingApply then
                return
            end
            pendingApply = true
            task.delay(0.12, function()
                pendingApply = false
                if genv.VFXEnabled then
                    processCharacter(vfxChar)
                end
            end)
        end

        local scroll = Pg.vfxScroll
        local vfxCard = section(scroll, "Change VFX")

        local swatchRow = addRow(vfxCard, 58)
        Mk.rowTitle(swatchRow, "VFX Color", "Tap the color to open the palette", 120)
        Search.Add(swatchRow, "Color", "VFX Color", "Tap the color to open the palette")
        local swatch = new("TextButton", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -16, 0.5, 0),
            Size = UDim2.fromOffset(64, 32),
            BackgroundColor3 = vfxColor,
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "",
            Parent = swatchRow,
        })
        corner(10, swatch)
        stroke(swatch, "Line", 0.6, 1)

        local vfxToggle = Mk.createToggle(vfxCard, "Change The Selected VFX Color", "Apply the selected color to your VFX", false, function(state)
            genv.VFXEnabled = state
            if state then
                processCharacter(vfxChar)
            end
        end)

        local hue, sat, val = vfxColor:ToHSV()

        local picker = box({
            Name = "VfxColorPicker",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            Size = UDim2.fromOffset(280, 300),
            Role = "Card",
            Visible = false,
            Active = true,
            ZIndex = 200,
            Parent = window,
        })
        corner(16, picker)
        stroke(picker, "Line", 0.8, 1)

        text({
            Text = "VFX Color",
            FontFace = Fonts.Semibold,
            TextSize = 15,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(16, 10),
            Size = UDim2.new(1, -32, 0, 22),
            ZIndex = 201,
            Parent = picker,
        })

        local svBox = new("Frame", {
            Position = UDim2.fromOffset(16, 40),
            Size = UDim2.fromOffset(248, 150),
            BackgroundColor3 = Color3.fromHSV(hue, 1, 1),
            BorderSizePixel = 0,
            ZIndex = 201,
            Parent = picker,
        })
        corner(10, svBox)
        local whiteLayer = new("Frame", {
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            ZIndex = 202,
            Parent = svBox,
        })
        corner(10, whiteLayer)
        new("UIGradient", {
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) }),
            Parent = whiteLayer,
        })
        local blackLayer = new("Frame", {
            Size = UDim2.fromScale(1, 1),
            BackgroundColor3 = Color3.new(0, 0, 0),
            BorderSizePixel = 0,
            ZIndex = 203,
            Parent = svBox,
        })
        corner(10, blackLayer)
        new("UIGradient", {
            Rotation = 90,
            Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) }),
            Parent = blackLayer,
        })
        local svCursor = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.fromOffset(16, 16),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = 205,
            Parent = svBox,
        })
        corner(8, svCursor)
        new("UIStroke", { Color = Color3.new(1, 1, 1), Thickness = 2, Parent = svCursor })
        local svHit = new("TextButton", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 206,
            Parent = svBox,
        })

        local hueBar = new("Frame", {
            Position = UDim2.fromOffset(16, 202),
            Size = UDim2.fromOffset(248, 16),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            ZIndex = 201,
            Parent = picker,
        })
        corner(8, hueBar)
        new("UIGradient", {
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
                ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
                ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)),
                ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
                ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)),
                ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
                ColorSequenceKeypoint.new(1, Color3.fromHSV(0, 1, 1)),
            }),
            Parent = hueBar,
        })
        local hueCursor = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            Size = UDim2.fromOffset(8, 24),
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            ZIndex = 205,
            Parent = hueBar,
        })
        corner(4, hueCursor)
        new("UIStroke", { Color = Color3.new(0, 0, 0), Transparency = 0.5, Thickness = 1, Parent = hueCursor })
        local hueHit = new("TextButton", {
            Size = UDim2.new(1, 0, 1, 12),
            Position = UDim2.fromOffset(0, -6),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 206,
            Parent = hueBar,
        })

        local hexField = new("TextBox", {
            Position = UDim2.fromOffset(16, 240),
            Size = UDim2.fromOffset(120, 34),
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Text = "",
            PlaceholderText = "#RRGGBB",
            FontFace = Fonts.Regular,
            TextSize = 14,
            ZIndex = 201,
            Parent = picker,
        })
        paint(hexField, "BackgroundColor3", "Field")
        paint(hexField, "TextColor3", "Text")
        paint(hexField, "PlaceholderColor3", "Sub")
        corner(9, hexField)
        stroke(hexField, "Line", 0.9, 1)

        local preview = new("Frame", {
            Position = UDim2.fromOffset(146, 240),
            Size = UDim2.fromOffset(34, 34),
            BackgroundColor3 = vfxColor,
            BorderSizePixel = 0,
            ZIndex = 201,
            Parent = picker,
        })
        corner(9, preview)
        stroke(preview, "Line", 0.7, 1)

        local doneButton = new("TextButton", {
            Position = UDim2.fromOffset(190, 240),
            Size = UDim2.fromOffset(74, 34),
            BorderSizePixel = 0,
            AutoButtonColor = false,
            Text = "Done",
            FontFace = Fonts.Semibold,
            TextSize = 14,
            TextColor3 = Static.White,
            ZIndex = 201,
            Parent = picker,
        })
        paint(doneButton, "BackgroundColor3", "Accent")
        corner(10, doneButton)

        local function refreshPicker(fromHex)
            vfxColor = Color3.fromHSV(hue, sat, val)
            svBox.BackgroundColor3 = Color3.fromHSV(hue, 1, 1)
            svCursor.Position = UDim2.fromScale(sat, 1 - val)
            hueCursor.Position = UDim2.fromScale(hue, 0.5)
            preview.BackgroundColor3 = vfxColor
            swatch.BackgroundColor3 = vfxColor
            if not fromHex then
                hexField.Text = string.format("#%02X%02X%02X", math.floor(vfxColor.R * 255 + 0.5), math.floor(vfxColor.G * 255 + 0.5), math.floor(vfxColor.B * 255 + 0.5))
            end
            scheduleApply()
        end
        refreshPicker(false)

        local dragging = nil

        local function updateFromInput(position)
            if dragging == "sv" then
                sat = math.clamp((position.X - svBox.AbsolutePosition.X) / svBox.AbsoluteSize.X, 0, 1)
                val = 1 - math.clamp((position.Y - svBox.AbsolutePosition.Y) / svBox.AbsoluteSize.Y, 0, 1)
                refreshPicker(false)
            elseif dragging == "hue" then
                hue = math.clamp((position.X - hueBar.AbsolutePosition.X) / hueBar.AbsoluteSize.X, 0, 1)
                refreshPicker(false)
            end
        end

        svHit.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = "sv"
                updateFromInput(input.Position)
            end
        end)
        hueHit.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = "hue"
                updateFromInput(input.Position)
            end
        end)
        track(UserInputService.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                updateFromInput(input.Position)
            end
        end))
        track(UserInputService.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = nil
            end
        end))

        hexField.FocusLost:Connect(function()
            local hex = string.gsub(hexField.Text, "#", "")
            if #hex == 6 and string.match(hex, "^%x+$") then
                local r = tonumber(string.sub(hex, 1, 2), 16)
                local g = tonumber(string.sub(hex, 3, 4), 16)
                local b = tonumber(string.sub(hex, 5, 6), 16)
                hue, sat, val = Color3.fromRGB(r, g, b):ToHSV()
                refreshPicker(false)
            else
                refreshPicker(false)
            end
        end)

        local function setPickerOpen(open)
            picker.Visible = open
        end

        swatch.MouseButton1Click:Connect(function()
            setPickerOpen(not picker.Visible)
        end)
        doneButton.MouseButton1Click:Connect(function()
            setPickerOpen(false)
        end)

        local baseSelectTab = selectTab
        selectTab = function(name, instant)
            setPickerOpen(false)
            baseSelectTab(name, instant)
        end
    end
end
do
    local Menu = { Open = false, Busy = 0, Rows = {} }
    Fwd.multitaskMenu = Menu
    local Multi = Fwd.multitask
    local MENU_W, ROW_H, HEAD, FOOT = 240, 36, 58, 50
    local ORDER = { "LoopDash", "AutoBlock", "ChangeVFX" }

    local scrim = new("TextButton", {
        Name = "MultitaskScrim",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        AutoButtonColor = false,
        Text = "",
        Visible = false,
        ZIndex = 40,
        Parent = window,
    })
    local menu = box({
        Class = "CanvasGroup",
        Name = "MultitaskMenu",
        Position = UDim2.fromOffset(80, 40),
        Size = UDim2.fromOffset(MENU_W, 240),
        BackgroundTransparency = 0.1,
        GroupTransparency = 1,
        Visible = false,
        ZIndex = 41,
        Role = "Window",
        Parent = window,
    })
    corner(18, menu)
    Glass.Pane(menu, "tint")
    menu.BackgroundTransparency = 0.1
    local pop = new("UIScale", { Scale = 0.9, Parent = menu })

    text({
        Position = UDim2.fromOffset(16, 10),
        Size = UDim2.new(1, -80, 0, 20),
        Text = "\u{110}a nhi\u{1EC7}m",
        FontFace = Fonts.Bold,
        TextSize = 14,
        Role = "Text",
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 43,
        Parent = menu,
    })
    local counter = text({
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -16, 0, 10),
        Size = UDim2.fromOffset(60, 20),
        Text = "",
        FontFace = Fonts.Semibold,
        TextSize = 12,
        Role = "Sub",
        TextXAlignment = Enum.TextXAlignment.Right,
        ZIndex = 43,
        Parent = menu,
    })
    text({
        Position = UDim2.fromOffset(16, 30),
        Size = UDim2.new(1, -32, 0, 18),
        Text = "Ch\u{1EA1}m \u{111}\u{1EC3} b\u{1EAD}t ho\u{1EB7}c t\u{1EAF}t t\u{1EEB}ng tab",
        FontFace = Fonts.Regular,
        TextSize = 11,
        Role = "Sub",
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 43,
        Parent = menu,
    })
    local collapse = box({
        Class = "TextButton",
        Name = "MultiCollapse",
        Position = UDim2.fromOffset(12, 200),
        Size = UDim2.new(1, -24, 0, 32),
        BackgroundTransparency = 0.9,
        AutoButtonColor = false,
        Text = translate("Thu v\u{1EC1} 1 tab"),
        FontFace = Fonts.Semibold,
        TextSize = 12,
        Role = "Line",
        ZIndex = 43,
        Parent = menu,
    })
    corner(12, collapse)
    paint(collapse, "TextColor3", "Text")
    Glass.Pane(collapse, "clear")

    function Menu.refresh()
        local count = #Multi.Tabs
        counter.Text = count .. "/" .. Multi.Max
        for _, item in ipairs(Menu.Rows) do
            local index
            for position, name in ipairs(Multi.Tabs) do
                if name == item.Name then
                    index = position
                    break
                end
            end
            item.On = index ~= nil
            item.Num.Text = index and tostring(index) or ""
            tween(item.Frame, 0.22, { BackgroundTransparency = index and 0.9 or 1 })
            tween(item.Badge, 0.22, { BackgroundTransparency = index and 0 or 1 })
            tween(item.Ring, 0.22, { Transparency = index and 1 or 0.6 })
        end
        tween(collapse, 0.2, { TextTransparency = count > 1 and 0 or 0.55 })
    end

    local function build()
        for _, item in ipairs(Menu.Rows) do
            item.Frame:Destroy()
        end
        Menu.Rows = {}
        local list = {}
        for _, name in ipairs(ORDER) do
            if tabs[name] and (name ~= "Test" or testTabVisible) then
                list[#list + 1] = name
            end
        end
        local height = HEAD + #list * ROW_H + FOOT
        menu.Size = UDim2.fromOffset(MENU_W, height)
        collapse.Position = UDim2.fromOffset(12, height - FOOT + 8)
        collapse.Text = translate("Thu v\u{1EC1} 1 tab")
        for index, name in ipairs(list) do
            local tab = tabs[name]
            local row = box({
                Class = "TextButton",
                Name = "MultiRow",
                Position = UDim2.fromOffset(8, HEAD + (index - 1) * ROW_H + 10),
                Size = UDim2.new(1, -16, 0, ROW_H - 4),
                BackgroundTransparency = 1,
                AutoButtonColor = false,
                Text = "",
                Role = "Line",
                ZIndex = 43,
                Parent = menu,
            })
            corner(10, row)
            Glass.Touch(row)
            local icon = box({
                Position = UDim2.fromOffset(8, 5),
                Size = UDim2.fromOffset(22, 22),
                BackgroundColor3 = tab.color,
                Parent = row,
            })
            corner(6, icon)
            text({
                Size = UDim2.fromScale(1, 1),
                Text = tab.glyph,
                FontFace = Fonts.Bold,
                TextSize = 14,
                TextColor3 = Static.White,
                Parent = icon,
            })
            local label = text({
                Position = UDim2.fromOffset(40, 0),
                Size = UDim2.new(1, -84, 1, 0),
                Text = tab.labelKey,
                FontFace = Fonts.Medium,
                TextSize = 13,
                Role = "Text",
                TextXAlignment = Enum.TextXAlignment.Left,
                TextTruncate = Enum.TextTruncate.AtEnd,
                Parent = row,
            })
            label.Text = translate(tab.labelKey)
            local badge = box({
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(1, -20, 0.5, 0),
                Size = UDim2.fromOffset(22, 22),
                BackgroundTransparency = 1,
                Parent = row,
            })
            paint(badge, "BackgroundColor3", "Accent")
            corner(11, badge)
            local ring = stroke(badge, "Line", 0.6, 1.2)
            local num = text({
                Size = UDim2.fromScale(1, 1),
                Text = "",
                FontFace = Fonts.Bold,
                TextSize = 12,
                TextColor3 = Static.White,
                Parent = badge,
            })
            local item = { Name = name, Frame = row, Badge = badge, Ring = ring, Num = num, On = false, Y = HEAD + (index - 1) * ROW_H }
            Menu.Rows[#Menu.Rows + 1] = item
            row.MouseEnter:Connect(function()
                if not item.On then
                    tween(row, 0.15, { BackgroundTransparency = 0.94 })
                end
            end)
            row.MouseLeave:Connect(function()
                tween(row, 0.2, { BackgroundTransparency = item.On and 0.9 or 1 })
            end)
            row.MouseButton1Click:Connect(function()
                Multi.toggleTab(name, true)
                tween(badge, 0.1, { Size = UDim2.fromOffset(28, 28) })
                task.delay(0.1, function()
                    tween(badge, 0.32, { Size = UDim2.fromOffset(22, 22) }, Enum.EasingStyle.Back)
                end)
            end)
        end
    end

    function Menu.open()
        if Menu.Open or not State.Open or Fwd.isSynth() then
            return
        end
        Menu.Open = true
        Menu.Busy = Menu.Busy + 1
        build()
        Menu.refresh()
        scrim.Visible = true
        menu.Visible = true
        menu.GroupTransparency = 1
        pop.Scale = 0.88
        tween(menu, 0.22, { GroupTransparency = 0 })
        tween(pop, 0.38, { Scale = 1 }, Enum.EasingStyle.Back)
        for index, item in ipairs(Menu.Rows) do
            task.delay((index - 1) * 0.025, function()
                if Menu.Open and item.Frame.Parent then
                    tween(item.Frame, 0.34, { Position = UDim2.fromOffset(8, item.Y) })
                end
            end)
        end
    end

    function Menu.close(instant)
        if not Menu.Open then
            return
        end
        Menu.Open = false
        Menu.Busy = Menu.Busy + 1
        local ticket = Menu.Busy
        scrim.Visible = false
        tween(menu, instant and 0 or 0.16, { GroupTransparency = 1 })
        tween(pop, instant and 0 or 0.2, { Scale = 0.92 })
        task.delay(instant and 0 or 0.2, function()
            if Menu.Busy == ticket and not Menu.Open then
                menu.Visible = false
            end
        end)
    end

    function Menu.toggle()
        if Menu.Open then
            Menu.close()
        else
            Menu.open()
        end
    end

    scrim.MouseButton1Click:Connect(function()
        Menu.close()
    end)
    collapse.MouseButton1Click:Connect(function()
        if #Multi.Tabs > 1 then
            playSound("tick")
            selectTab(Multi.Tabs[1] or "LoopDash")
            Menu.close()
        end
    end)
    track(UserInputService.InputBegan:Connect(function(input)
        if input.KeyCode == Enum.KeyCode.Escape and Menu.Open then
            Menu.close()
        end
    end))
    Menu.refresh()
end



function Ux.refreshKeyHints()
    Win.sidebarHint.Text = "v" .. VERSION .. "  \u{B7}  " .. Settings.ToggleKey.Name
    if Fwd.aboutKeyLabel then
        Fwd.aboutKeyLabel.Text = Settings.ToggleKey.Name
    end
end


