    local function tile(caption, order)
        local frame = box({
            Size = UDim2.new(1 / 3, -16 / 3, 1, 0),
            LayoutOrder = order,
            Role = "Card",
            Parent = tiles,
        })
        corner(14, frame)
        Glass.Skin(frame, 0.42)
        local value = text({
            Position = UDim2.fromOffset(14, 14),
            Size = UDim2.new(1, -28, 0, 34),
            Text = "\u{2014}",
            FontFace = Fonts.Bold,
            TextSize = 24,
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = frame,
        })
        text({
            Position = UDim2.fromOffset(14, 52),
            Size = UDim2.new(1, -28, 0, 18),
            Text = caption,
            FontFace = Fonts.Medium,
            TextSize = 12,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Left,
            Parent = frame,
        })
        return value
    end

    Ux.fpsValue = tile("FPS", 1)
    Ux.pingValue = tile("\u{110}\u{1ED9} tr\u{1EC5}", 2)
    Ux.playersValue = tile("Ng\u{1B0}\u{1EDD}i ch\u{1A1}i", 3)

    local perf = section(Pg.homeScroll, "Hi\u{1EC7}u n\u{103}ng")
    local perfRow = addRow(perf, 124)
    local barArea = new("Frame", {
        Position = UDim2.fromOffset(16, 14),
        Size = UDim2.new(1, -32, 0, 80),
        BackgroundTransparency = 1,
        Parent = perfRow,
    })
    for i = 1, BAR_COUNT do
        local bar = box({
            AnchorPoint = Vector2.new(0, 1),
            Position = UDim2.new((i - 1) / BAR_COUNT, 0, 1, 0),
            Size = UDim2.new(1 / BAR_COUNT, -3, 0.04, 0),
            BackgroundTransparency = 0.75 - 0.75 * (i / BAR_COUNT),
            Role = "Accent",
            Parent = barArea,
        })
        corner(3, bar)
        Ux.graphBars[i] = bar
    end
    text({
        Position = UDim2.fromOffset(16, 98),
        Size = UDim2.new(1, -32, 0, 18),
        Text = "FPS trong 15 gi\u{E2}y g\u{1EA7}n nh\u{1EA5}t",
        FontFace = Fonts.Regular,
        TextSize = 12,
        Role = "Sub",
        TextXAlignment = Enum.TextXAlignment.Left,
        Parent = perfRow,
    })
end

