do
    local Http = game:GetService("HttpService")
    local Dc = { Id = "", Hook = "", Forward = true, Report = true, Cross = false }
    local Net = { Queue = {}, Busy = false, Recent = {}, TestAt = 0, Working = false }
    local View = {}
    local COLORS = {
        success = 0x30D158,
        info = 0x0A84FF,
        warn = 0xFF9F0A,
        error = 0xFF453A,
        login = 0x30D158,
        resume = 0x0A84FF,
        logout = 0x8E8E93,
        expired = 0xFF9F0A,
        linked = 0x5865F2,
        unlinked = 0x8E8E93,
        test = 0x5865F2,
    }
    local TITLES = {
        login = "T\u{E0}i kho\u{1EA3}n \u{111}\u{E3} \u{111}\u{103}ng nh\u{1EAD}p",
        resume = "Phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p \u{111}\u{1B0}\u{1EE3}c kh\u{F4}i ph\u{1EE5}c",
        logout = "T\u{E0}i kho\u{1EA3}n \u{111}\u{E3} \u{111}\u{103}ng xu\u{1EA5}t",
        expired = "Phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p \u{111}\u{E3} h\u{1EBF}t h\u{1EA1}n",
        linked = "\u{110}\u{E3} li\u{EA}n k\u{1EBF}t Discord",
        unlinked = "\u{110}\u{E3} h\u{1EE7}y li\u{EA}n k\u{1EBF}t Discord",
        test = "Tin nh\u{1EAF}n th\u{1EED} t\u{1EEB} boncuti",
    }
    local DETAILS = {
        linked = "Th\u{F4}ng b\u{E1}o c\u{1EE7}a boncuti s\u{1EBD} \u{111}\u{1B0}\u{1EE3}c g\u{1EED}i t\u{1EDB}i k\u{EA}nh n\u{E0}y",
        test = "K\u{1EBF}t n\u{1ED1}i Discord ho\u{1EA1}t \u{111}\u{1ED9}ng b\u{EC}nh th\u{1B0}\u{1EDD}ng",
    }
    local GATED = { login = true, resume = true, logout = true, expired = true }
    local HOSTS = {
        ["discord.com"] = true,
        ["discordapp.com"] = true,
        ["canary.discord.com"] = true,
        ["ptb.discord.com"] = true,
    }

    local function transport()
        local ok, send = pcall(function()
            if type(request) == "function" then
                return request
            end
            if type(http_request) == "function" then
                return http_request
            end
            if type(syn) == "table" and type(syn.request) == "function" then
                return syn.request
            end
            if type(http) == "table" and type(http.request) == "function" then
                return http.request
            end
            if type(fluxus) == "table" and type(fluxus.request) == "function" then
                return fluxus.request
            end
            return nil
        end)
        if ok then
            return send
        end
        return nil
    end

    local function validId(value)
        return type(value) == "string" and string.match(value, "^%d+$") ~= nil and #value >= 17 and #value <= 20
    end

    local function cleanHook(value)
        if type(value) ~= "string" then
            return nil
        end
        local url = string.gsub(value, "%s", "")
        url = string.gsub(url, "[?#].*$", "")
        url = string.gsub(url, "/+$", "")
        local host, path = string.match(url, "^https://([%w%.%-]+)(/.+)$")
        if not host or not HOSTS[string.lower(host)] then
            return nil
        end
        local id, token = string.match(path, "^/api/webhooks/(%d+)/([%w_%-]+)$")
        if not id then
            id, token = string.match(path, "^/api/v%d+/webhooks/(%d+)/([%w_%-]+)$")
        end
        if not id or #id < 17 or #id > 20 or #token < 20 then
            return nil
        end
        return "https://discord.com/api/webhooks/" .. id .. "/" .. token
    end

    local function maskHook(hook)
        local id = string.match(hook, "/webhooks/(%d+)/") or ""
        return "discord.com/api/webhooks/" .. id .. "/\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}\u{2022}"
    end

    local function clip(value, limit)
        value = tostring(value or "")
        local length = utf8.len(value)
        if not length then
            return (string.gsub(string.sub(value, 1, limit), "[\128-\255]", "?"))
        end
        if length <= limit then
            return value
        end
        return string.sub(value, 1, utf8.offset(value, limit) - 1) .. "\u{2026}"
    end

    local function statusOf(res)
        if type(res) ~= "table" then
            return 0
        end
        local code = tonumber(res.StatusCode) or tonumber(res.status_code) or tonumber(res.Status) or 0
        if code == 0 and res.Success == true then
            code = 200
        end
        return code
    end

    local function post(hook, payload)
        local send = transport()
        if not send then
            return false, 0
        end
        local encoded, body = pcall(Http.JSONEncode, Http, payload)
        if not encoded then
            return false, 0
        end
        for attempt = 1, 3 do
            local done, res = pcall(send, {
                Url = hook,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = body,
            })
            if not done then
                return false, 0
            end
            local code = statusOf(res)
            if code >= 200 and code < 300 then
                return true, code
            end
            if code == 429 and attempt < 3 then
                local delay = 1
                local parsed, data = pcall(Http.JSONDecode, Http, tostring(res.Body or ""))
                if parsed and type(data) == "table" and tonumber(data.retry_after) then
                    delay = tonumber(data.retry_after)
                end
                task.wait(math.clamp(delay, 0.5, 8))
            else
                return false, code
            end
        end
        return false, 429
    end

    local function verify(hook)
        local send = transport()
        if not send then
            return false
        end
        local done, res = pcall(send, { Url = hook, Method = "GET" })
        if not done or statusOf(res) ~= 200 then
            return false
        end
        local parsed, data = pcall(Http.JSONDecode, Http, tostring(res.Body or ""))
        return parsed and type(data) == "table" and data.id ~= nil
    end

    local function pump()
        if Net.Busy then
            return
        end
        Net.Busy = true
        task.spawn(function()
            while #Net.Queue > 0 and gui.Parent do
                local item = table.remove(Net.Queue, 1)
                local ok, code = post(item.Hook, item.Payload)
                if item.Done then
                    pcall(item.Done, ok, code)
                end
                task.wait(0.7)
            end
            Net.Busy = false
        end)
    end

    local function enqueue(hook, payload, done)
        if #Net.Queue >= 12 then
            local dropped = table.remove(Net.Queue, 1)
            if dropped and dropped.Done then
                pcall(dropped.Done, false, 0)
            end
        end
        table.insert(Net.Queue, { Hook = hook, Payload = payload, Done = done })
        pump()
    end

    local function ready()
        return Dc.Hook ~= "" and transport() ~= nil
    end

    local function deliver(title, description, color, fields, mention, done)
        local id = Dc.Id
        local ping = mention and id ~= ""
        local payload = {
            username = "boncuti",
            embeds = {
                {
                    title = clip(title, 250),
                    description = clip(description, 1500),
                    color = color,
                    fields = fields,
                    footer = { text = "boncuti \u{B7} @" .. player.Name },
                    timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
                },
            },
            allowed_mentions = { parse = {}, users = ping and { id } or {} },
        }
        if ping then
            payload.content = "<@" .. id .. ">"
        end
        enqueue(Dc.Hook, payload, done)
    end

    Fwd.discordForward = function(title, message, kind)
        if not Dc.Forward or not ready() then
            return
        end
        local key = tostring(title) .. "|" .. tostring(message)
        local stamp = os.clock()
        for known, at in pairs(Net.Recent) do
            if stamp - at > 5 then
                Net.Recent[known] = nil
            end
        end
        if Net.Recent[key] then
            return
        end
        Net.Recent[key] = stamp
        deliver(translate(tostring(title)), translate(tostring(message or "")), COLORS[kind] or COLORS.info, nil, kind == "warn" or kind == "error")
    end

    Fwd.discordEvent = function(kind, name, expires, done)
        if not ready() then
            if done then
                pcall(done, false, 0)
            end
            return
        end
        if GATED[kind] and not Dc.Report then
            return
        end
        local fields = {
            { name = translate("T\u{E0}i kho\u{1EA3}n"), value = clip(name or "\u{2014}", 200), inline = true },
            { name = "Roblox", value = "@" .. player.Name, inline = true },
        }
        if Dc.Id ~= "" then
            table.insert(fields, { name = "Discord", value = "<@" .. Dc.Id .. ">", inline = true })
        end
        if type(expires) == "number" and (kind == "login" or kind == "resume") then
            table.insert(fields, {
                name = translate("Phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p"),
                value = "<t:" .. math.floor(expires) .. ":R>",
                inline = false,
            })
        end
        deliver(translate(TITLES[kind]), translate(DETAILS[kind] or ""), COLORS[kind], fields, kind == "expired", done)
    end

    Fwd.crossEnabled = function()
        return Dc.Cross and ready()
    end

    Fwd.crossReport = function(title, text, kind, fields)
        if not Dc.Cross or not ready() then
            return false
        end
        local list = {}
        for _, field in ipairs(fields or {}) do
            list[#list + 1] = { name = clip(field.name, 100), value = clip(field.value, 200), inline = field.inline and true or false }
        end
        if Dc.Id ~= "" then
            list[#list + 1] = { name = "Discord", value = "<@" .. Dc.Id .. ">", inline = true }
        end
        enqueue(Dc.Hook, {
            username = "Cross.OS",
            embeds = {
                {
                    title = clip(title, 250),
                    description = clip(text, 1500),
                    color = COLORS[kind] or COLORS.info,
                    fields = #list > 0 and list or nil,
                    footer = { text = "Powered by Cross.OS \u{B7} @" .. player.Name },
                    timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
                },
            },
            allowed_mentions = { parse = {}, users = {} },
        })
        return true
    end

    local card = section(Pg.settingsScroll, "Li\u{EA}n k\u{1EBF}t Discord")

    local statusRow = addRow(card, 76)
    Search.Add(statusRow, "Th\u{F4}ng tin", "Li\u{EA}n k\u{1EBF}t Discord")
    local badge = box({
        Position = UDim2.fromOffset(16, 16),
        Size = UDim2.fromOffset(44, 44),
        BackgroundColor3 = rgb(88, 101, 242),
        Parent = statusRow,
    })
    corner(22, badge)
    local badgeMark = text({
        Size = UDim2.fromScale(1, 1),
        Text = "@",
        FontFace = Fonts.Bold,
        TextSize = 21,
        TextColor3 = Static.White,
        Parent = badge,
    })
    View.title = text({
        Position = UDim2.fromOffset(74, 16),
        Size = UDim2.new(1, -90, 0, 22),
        Text = "\u{2014}",
        FontFace = Fonts.Bold,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = statusRow,
    })
    View.meta = text({
        Position = UDim2.fromOffset(74, 40),
        Size = UDim2.new(1, -90, 0, 18),
        Text = "\u{2014}",
        FontFace = Fonts.Regular,
        TextSize = 12,
        Role = "Sub",
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = statusRow,
    })
    badgeMark:SetAttribute("BoncutiRaw", true)
    View.title:SetAttribute("BoncutiRaw", true)
    View.meta:SetAttribute("BoncutiRaw", true)

    local function inputField(title, placeholder)
        local row = addRow(card, 56)
        Search.Add(row, "Nh\u{1EAD}p li\u{1EC7}u", title)
        text({
            Text = title,
            FontFace = Fonts.Medium,
            TextSize = 15,
            TextXAlignment = Enum.TextXAlignment.Left,
            Position = UDim2.fromOffset(16, 0),
            Size = UDim2.new(0, 110, 1, 0),
            Parent = row,
        })
        local input = new("TextBox", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -16, 0.5, 0),
            Size = UDim2.new(1, -150, 0, 34),
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Text = "",
            PlaceholderText = placeholder,
            FontFace = Fonts.Regular,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = row,
        })
        paint(input, "BackgroundColor3", "Field")
        paint(input, "TextColor3", "Text")
        paint(input, "PlaceholderColor3", "Sub")
        corner(9, input)
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = input })
        local line = stroke(input, "Line", 0.9, 1)
        input.Focused:Connect(function()
            tween(line, 0.2, { Color = P.Accent, Transparency = 0 })
        end)
        input.FocusLost:Connect(function(enterPressed)
            tween(line, 0.2, { Color = P.Line, Transparency = 0.9 })
            if enterPressed and input.Text ~= "" and View.link then
                View.link()
            end
        end)
        return input
    end

    View.idField = inputField("ID Discord", "ID ng\u{1B0}\u{1EDD}i d\u{F9}ng, 17\u{2013}20 ch\u{1EEF} s\u{1ED1}")
    View.hookField = inputField("Webhook", "D\u{E1}n URL webhook c\u{1EE7}a k\u{EA}nh Discord")

    function View.refresh()
        local linked = Dc.Id ~= ""
        View.title.Text = translate(linked and "\u{110}\u{E3} li\u{EA}n k\u{1EBF}t" or "Ch\u{1B0}a li\u{EA}n k\u{1EBF}t")
        if linked then
            local caption = "ID %s \u{B7} ch\u{1B0}a c\u{F3} webhook"
            if Dc.Hook ~= "" then
                caption = transport() and "ID %s \u{B7} webhook s\u{1EB5}n s\u{E0}ng" or "ID %s \u{B7} executor thi\u{1EBF}u h\u{E0}m request"
            end
            View.meta.Text = string.format(translate(caption), Dc.Id)
            View.idField.PlaceholderText = Dc.Id
        else
            View.meta.Text = translate("Ch\u{1B0}a li\u{EA}n k\u{1EBF}t t\u{E0}i kho\u{1EA3}n Discord")
            View.idField.PlaceholderText = translate("ID ng\u{1B0}\u{1EDD}i d\u{F9}ng, 17\u{2013}20 ch\u{1EEF} s\u{1ED1}")
        end
        if Dc.Hook ~= "" then
            View.hookField.PlaceholderText = maskHook(Dc.Hook)
        else
            View.hookField.PlaceholderText = translate("D\u{E1}n URL webhook c\u{1EE7}a k\u{EA}nh Discord")
        end
    end

    Fwd.discordLanguage = View.refresh

    local function run()
        local typedId = (string.gsub(View.idField.Text, "%s", ""))
        local typedHook = (string.gsub(View.hookField.Text, "%s", ""))
        local id = typedId ~= "" and typedId or Dc.Id
        if not validId(id) then
            notify("ID Discord kh\u{F4}ng h\u{1EE3}p l\u{1EC7}", "C\u{1EA7}n 17\u{2013}20 ch\u{1EEF} s\u{1ED1}", "error", nil, true)
            return
        end
        local hook = Dc.Hook
        local skipped = false
        if typedHook ~= "" then
            local clean = cleanHook(typedHook)
            if not clean then
                notify("Webhook Discord kh\u{F4}ng h\u{1EE3}p l\u{1EC7}", "D\u{E1}n URL d\u{1EA1}ng discord.com/api/webhooks/\u{2026}", "error", nil, true)
                return
            end
            if not transport() then
                notify("Executor kh\u{F4}ng h\u{1ED7} tr\u{1EE3} g\u{1EED}i t\u{1EDB}i Discord", "Thi\u{1EBF}u h\u{E0}m request n\u{EA}n ch\u{1EC9} l\u{1B0}u ID", "warn", nil, true)
                skipped = true
            elseif verify(clean) then
                hook = clean
            else
                notify("Kh\u{F4}ng x\u{E1}c th\u{1EF1}c \u{111}\u{1B0}\u{1EE3}c webhook", "Ki\u{1EC3}m tra URL ho\u{1EB7}c k\u{1EBF}t n\u{1ED1}i m\u{1EA1}ng", "error", nil, true)
                return
            end
        end
        Dc.Id = id
        Dc.Hook = hook
        View.idField.Text = ""
        View.hookField.Text = ""
        View.refresh()
        Auth.save()
        if skipped then
            return
        end
        if hook ~= "" then
            notify("\u{110}\u{E3} li\u{EA}n k\u{1EBF}t Discord", "Th\u{F4}ng b\u{E1}o c\u{1EE7}a boncuti s\u{1EBD} \u{111}\u{1B0}\u{1EE3}c g\u{1EED}i t\u{1EDB}i k\u{EA}nh n\u{E0}y", "success", nil, true)
            Fwd.discordEvent("linked", Auth.Display)
        else
            notify("\u{110}\u{E3} l\u{1B0}u ID Discord", "Ch\u{1B0}a c\u{F3} webhook n\u{EA}n ch\u{1B0}a g\u{1EED}i \u{111}\u{1B0}\u{1EE3}c tin", "info", nil, true)
        end
    end

    function View.link()
        if Net.Working then
            return
        end
        Net.Working = true
        task.spawn(function()
            pcall(run)
            Net.Working = false
        end)
    end

    function View.test()
        if Dc.Id == "" and Dc.Hook == "" then
            notify("Ch\u{1B0}a li\u{EA}n k\u{1EBF}t", "Ch\u{1B0}a li\u{EA}n k\u{1EBF}t t\u{E0}i kho\u{1EA3}n Discord", "info", nil, true)
            return
        end
        if Dc.Hook == "" then
            notify("Ch\u{1B0}a c\u{F3} webhook \u{111}\u{1EC3} g\u{1EED}i", "Ch\u{1B0}a c\u{F3} webhook n\u{EA}n ch\u{1B0}a g\u{1EED}i \u{111}\u{1B0}\u{1EE3}c tin", "warn", nil, true)
            return
        end
        if not transport() then
            notify("Executor kh\u{F4}ng h\u{1ED7} tr\u{1EE3} g\u{1EED}i t\u{1EDB}i Discord", "C\u{1EA7}n h\u{E0}m request, http_request ho\u{1EB7}c syn.request", "warn", nil, true)
            return
        end
        if os.clock() - Net.TestAt < 3 then
            return
        end
        Net.TestAt = os.clock()
        Fwd.discordEvent("test", Auth.Display, nil, function(ok)
            if ok then
                notify("\u{110}\u{E3} g\u{1EED}i t\u{1EDB}i Discord", "K\u{1EBF}t n\u{1ED1}i Discord ho\u{1EA1}t \u{111}\u{1ED9}ng b\u{EC}nh th\u{1B0}\u{1EDD}ng", "success", nil, true)
            else
                notify("Kh\u{F4}ng g\u{1EED}i \u{111}\u{1B0}\u{1EE3}c t\u{1EDB}i Discord", "Ki\u{1EC3}m tra URL ho\u{1EB7}c k\u{1EBF}t n\u{1ED1}i m\u{1EA1}ng", "error", nil, true)
            end
        end)
    end

    function View.unlink()
        if Dc.Id == "" and Dc.Hook == "" then
            notify("Ch\u{1B0}a li\u{EA}n k\u{1EBF}t", "Ch\u{1B0}a li\u{EA}n k\u{1EBF}t t\u{E0}i kho\u{1EA3}n Discord", "info", nil, true)
            return
        end
        Ux.confirm(
            translate("H\u{1EE7}y li\u{EA}n k\u{1EBF}t Discord?"),
            translate("T\u{E0}i kho\u{1EA3}n n\u{E0}y s\u{1EBD} kh\u{F4}ng c\u{F2}n nh\u{1EAD}n th\u{F4}ng b\u{E1}o qua Discord."),
            translate("H\u{1EE7}y li\u{EA}n k\u{1EBF}t"),
            true,
            function()
                Fwd.discordEvent("unlinked", Auth.Display)
                Dc.Id = ""
                Dc.Hook = ""
                View.refresh()
                Auth.save()
                notify("\u{110}\u{E3} h\u{1EE7}y li\u{EA}n k\u{1EBF}t Discord", "Ch\u{1B0}a li\u{EA}n k\u{1EBF}t t\u{E0}i kho\u{1EA3}n Discord", "info", nil, true)
            end
        )
    end

    Mk.createButtons(card, {
        { Text = "Li\u{EA}n k\u{1EBF}t", Callback = View.link },
        { Text = "G\u{1EED}i th\u{1EED}", Role = "Field", Callback = View.test },
        { Text = "H\u{1EE7}y li\u{EA}n k\u{1EBF}t", Color = Static.Red, Callback = View.unlink },
    })

    local idControl = register({
        Keep = true,
        Get = function()
            return Dc.Id
        end,
        Set = function(value)
            Dc.Id = validId(value) and value or ""
            View.refresh()
        end,
    }, "", "discordId")
    local hookControl = register({
        Keep = true,
        Get = function()
            return Dc.Hook
        end,
        Set = function(value)
            Dc.Hook = cleanHook(value) or ""
            View.refresh()
        end,
    }, "", "discordHook")
    local forwardControl = register(
        Mk.createToggle(card, "Chuy\u{1EC3}n th\u{F4}ng b\u{E1}o", "G\u{1EED}i th\u{F4}ng b\u{E1}o c\u{1EE7}a boncuti sang k\u{EA}nh Discord", true, function(on)
            Dc.Forward = on
        end),
        true,
        "discordForward"
    )
    local reportControl = register(
        Mk.createToggle(card, "B\u{E1}o phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p", "G\u{1EED}i tin khi \u{111}\u{103}ng nh\u{1EAD}p, \u{111}\u{103}ng xu\u{1EA5}t ho\u{1EB7}c h\u{1EBF}t h\u{1EA1}n", true, function(on)
            Dc.Report = on
        end),
        true,
        "discordReport"
    )
    local crossControl = register(
        Mk.createToggle(card, "Cross b\u{E1}o Discord", "Cross g\u{1EED}i ti\u{1EBF}n \u{111}\u{1ED9} nhi\u{1EC7}m v\u{1EE5} v\u{E0} ho\u{1EA1}t \u{111}\u{1ED9}ng t\u{1EF1} ch\u{1A1}i l\u{EA}n k\u{EA}nh Discord", false, function(on)
            Dc.Cross = on
        end),
        false,
        "crossDiscord"
    )
    idControl.Keep = true
    hookControl.Keep = true
    forwardControl.Keep = true
    reportControl.Keep = true
    crossControl.Keep = true
    View.refresh()
end

