        if user then
            notify("C\u{F4}ng t\u{1EAF}c th\u{1EED}", on and "\u{110}\u{E3} b\u{1EAD}t" or "\u{110}\u{E3} t\u{1EAF}t", on and "success" or "info", 1.6)
        end
    end), false)

    local download = section(Pg.testScroll, "Ho\u{1EA1}t \u{111}\u{1ED9}ng tr\u{EA}n \u{111}\u{1EA3}o")
    local progress = Mk.createProgress(download, "T\u{1EA3}i xu\u{1ED1}ng th\u{1EED}")

    local function runDownload()
        if Activities.Download then
            return
        end
        downloadValue = 0
        progress.Set(0)
        Activities.Download = {
            Title = "T\u{1EA3}i xu\u{1ED1}ng",
            Color = Static.Blue,
            Value = function()
                return string.format("%d%%", math.floor(downloadValue * 100 + 0.5))
            end,
            Short = function()
                return string.format("%d%%", math.floor(downloadValue * 100 + 0.5))
            end,
            Ring = function()
                return downloadValue
            end,
            RingMode = "fill",
        }
        refreshActivity()
        task.spawn(function()
            local duration = 4.5
            local started = os.clock()
            while gui.Parent do
                local alpha = math.clamp((os.clock() - started) / duration, 0, 1)
                downloadValue = alpha * alpha * (3 - 2 * alpha)
                progress.Set(downloadValue)
                if alpha >= 1 then
                    break
                end
                task.wait(0.05)
            end
            Activities.Download = nil
            refreshActivity()
            notify("T\u{1EA3}i xu\u{1ED1}ng ho\u{E0}n t\u{1EA5}t", "boncuti_demo.zip", "success")
        end)
    end

    Mk.createButtons(download, {
        {
            Text = "T\u{1EA3}i th\u{1EED}",
            Callback = runDownload,
        },
    })

    local inputs = section(Pg.testScroll, "Nh\u{1EAD}p li\u{1EC7}u")
    register(Mk.createSegmented(inputs, "Lo\u{1EA1}i th\u{F4}ng b\u{E1}o", { "Th\u{E0}nh c\u{F4}ng", "Th\u{F4}ng tin", "C\u{1EA3}nh b\u{E1}o", "L\u{1ED7}i" }, 1, 78, function(index)
