            Text = "Th\u{E0}nh c\u{F4}ng",
            Color = Static.Green,
            Callback = function()
                notify("Th\u{E0}nh c\u{F4}ng", "M\u{1ECD}i th\u{1EE9} \u{111}\u{E3} s\u{1EB5}n s\u{E0}ng", "success")
            end,
