            Callback = function()
                notify("Th\u{F4}ng tin", "\u{110}\u{E2}y l\u{E0} m\u{1ED9}t th\u{F4}ng b\u{E1}o th\u{1EED}", "info")
            end,
        },
        {
            Text = "C\u{1EA3}nh b\u{E1}o",
            Color = Static.Orange,
            Callback = function()
                notify("C\u{1EA3}nh b\u{E1}o", "C\u{F3} \u{111}i\u{1EC1}u g\u{EC} \u{111}\u{F3} c\u{1EA7}n ch\u{FA} \u{FD}", "warn")
            end,
        },
        {
            Text = "L\u{1ED7}i",
            Color = Static.Red,
            Callback = function()
                notify("\u{110}\u{E3} x\u{1EA3}y ra l\u{1ED7}i", "Kh\u{F4}ng th\u{1EC3} ho\u{E0}n t\u{1EA5}t thao t\u{E1}c", "error")
