    end), 1, "accent")

    local mode = section(Pg.settingsScroll, "Ch\u{1EBF} \u{111}\u{1ED9}")
    Fwd.themeControl = register(Mk.createThemes(mode, "Giao di\u{1EC7}n", ThemeNames, 1, function(index, user)
        applyTheme(index)
        if user and index == Fwd.ThemeImage and Fwd.themeImage and not Fwd.themeImage.Asset then
            notify("Ch\u{1B0}a c\u{F3} \u{1EA3}nh n\u{1EC1}n", "D\u{E1}n link ho\u{1EB7}c t\u{EA}n file \u{1EDF} m\u{1EE5}c \u{1EA2}nh n\u{1EC1}n", "info", 3)
        end
    end), 1, "theme")

    do
        local Back = Fwd.themeBackdrop
        local Img = { Source = "", Asset = nil, Ticket = 0, Busy = false }
        Fwd.themeImage = Img
        local card = section(Pg.settingsScroll, "\u{1EA2}nh n\u{1EC1}n")

        local fieldRow = addRow(card, 100)
        Search.Add(fieldRow, "Tu\u{1EF3} ch\u{1ECD}n", "\u{1EA2}nh n\u{1EC1}n")
        Mk.rowTitle(fieldRow, "D\u{F9}ng \u{1EA3}nh l\u{E0}m giao di\u{1EC7}n", "D\u{E1}n link \u{1EA3}nh, GIF ho\u{1EB7}c t\u{EA}n file trong workspace (h\u{1ED7} tr\u{1EE3} 4K)", 32)
        local field = new("TextBox", {
