            PlaceholderText = translate("https://\u{2026} ho\u{1EB7}c boncuti/anh.png"),
            FontFace = Fonts.Regular,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = fieldRow,
        })
        paint(field, "BackgroundColor3", "Field")
        paint(field, "TextColor3", "Text")
        paint(field, "PlaceholderColor3", "Sub")
        corner(9, field)
        new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = field })
        local fieldLine = stroke(field, "Line", 0.9, 1)
        field.Focused:Connect(function()
            tween(fieldLine, 0.2, { Color = P.Accent, Transparency = 0 })
        end)

        local buttons
        buttons = Mk.createButtons(card, {
            {
                Text = "\u{C1}p d\u{1EE5}ng",
                Callback = function()
                    Img.apply(field.Text, false)
                end,
            },
            {
                Text = "G\u{1EE1} \u{1EA3}nh",
                Role = "Field",
                Callback = function()
                    field.Text = ""
                    Img.apply("", false)
                end,
            },
            {
                Text = "Qu\u{E9}t \u{1EA3}nh trong m\u{E1}y",
                Role = "Field",
                Callback = function()
                    Img.scan()
                end,
            },
        })
        for _, button in ipairs(buttons) do
            button.Name = "ThemeImageButton"
        end
        local status = Mk.createInfo(card, "Tr\u{1EA1}ng th\u{E1}i", "Ch\u{1B0}a c\u{F3} \u{1EA3}nh")
        status.Name = "ThemeImageStatus"
        status.Position = UDim2.new(0.25, 0, 0, 0)
        status.Size = UDim2.new(0.75, -16, 1, 0)

        local filesRow = addRow(card, 0)
        filesRow.Name = "ThemeFiles"
        filesRow.Visible = false
        filesRow.ClipsDescendants = true
        local grid = new("Frame", {
            Position = UDim2.fromOffset(12, 8),
            Size = UDim2.new(1, -24, 1, -12),
            BackgroundTransparency = 1,
            Parent = filesRow,
        })

        register(Mk.createSlider(card, "\u{110}\u{1ED9} \u{111}\u{1EAD}m \u{1EA3}nh", 10, 100, 100, 1, "%", function(value)
            Back.setStrength(value)
        end), 100, "themeImageStrength")
        register(Mk.createSlider(card, "\u{110}\u{1ED9} t\u{1ED1}i \u{1EA3}nh", 0, 85, 18, 1, "%", function(value)
            Back.setDim(value)
        end), 18, "themeImageDim")
        register(Mk.createToggle(card, "Chuy\u{1EC3}n \u{111}\u{1ED9}ng n\u{1EC1}n", "Theme \u{111}\u{1ED9}ng t\u{1EF1} tr\u{F4}i m\u{E0}u v\u{E0} \u{E1}nh s\u{E1}ng", true, function(on)
            Back.Motion = on
        end), true, "themeMotion")

        local function setStatus(message, tone)
            status.Text = translate(message)
            local color = P.Sub
            if tone == "ok" then
                color = Static.Green
            elseif tone == "warn" then
                color = Static.Orange
            end
            status.TextTransparency = 0
            tween(status, 0.2, { TextColor3 = color })
        end

        local function trimText(value)
            local result = string.gsub(value, "^%s+", "")
            result = string.gsub(result, "%s+$", "")
            return result
        end

        local function fetch(url)
            local why
            local send
            pcall(function()
                if type(request) == "function" then
                    send = request
                elseif type(http_request) == "function" then
                    send = http_request
                elseif type(syn) == "table" and type(syn.request) == "function" then
                    send = syn.request
                end
            end)
            if send then
                local origin = string.match(url, "^(https?://[^/%?#]+)")
                local sent, response = pcall(send, {
                    Url = url,
                    Method = "GET",
                    Headers = {
                        ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36",
                        ["Accept"] = "image/png,image/jpeg,image/gif,image/*;q=0.8,text/html;q=0.5,*/*;q=0.3",
                        ["Referer"] = origin and (origin .. "/") or nil,
                    },
                })
                if sent and type(response) == "table" then
                    local body = response.Body
                    if response.Success ~= false and type(body) == "string" and #body > 0 then
                        return body
                    end
                    local code = tonumber(response.StatusCode)
                    if code then
                        why = "http" .. code
                        if code == 404 or code == 410 then
                            return nil, why
                        end
                    end
                end
            end
            local ok, data = pcall(function()
                return game:HttpGet(url)
            end)
            if ok and type(data) == "string" and #data > 0 then
                return data
            end
            return nil, why
        end

        local function findFile(source)
            if type(isfile) ~= "function" or type(readfile) ~= "function" then
                return nil
            end
            local clean = string.gsub(source, "\\", "/")
            clean = string.gsub(clean, "^[Ff][Ii][Ll][Ee]:///?", "")
            clean = string.gsub(clean, "%%(%x%x)", function(hex)
                return string.char(tonumber(hex, 16))
            end)
            clean = trimText(clean)
            local name = string.match(clean, "([^/]+)$") or clean
            local stripped = string.gsub(clean, "^%./", "")
            stripped = string.gsub(stripped, "^workspace/", "")
            local tries = { clean, stripped, "boncuti/" .. stripped, "images/" .. stripped, name, "boncuti/" .. name }
            for _, ext in ipairs({ "", ".png", ".jpg", ".jpeg", ".gif" }) do
                for _, path in ipairs(tries) do
                    local ok, found = pcall(isfile, path .. ext)
                    if ok and found then
                        return path .. ext
                    end
                end
            end
            if type(listfiles) == "function" and name ~= "" then
                local lowerName = string.lower(name)
                for _, folder in ipairs({ "", "boncuti", "images", "Images", "pictures", "Pictures", "wallpapers" }) do
                    local ok, list = pcall(listfiles, folder)
                    if ok and type(list) == "table" then
                        for _, path in ipairs(list) do
                            local candidate = string.gsub(tostring(path), "\\", "/")
                            local tail = string.lower(string.match(candidate, "([^/]+)$") or "")
                            if tail == lowerName or tail == lowerName .. ".png" or tail == lowerName .. ".jpg" or tail == lowerName .. ".jpeg" or tail == lowerName .. ".gif" then
                                return candidate
                            end
                        end
                    end
                end
            end
            return nil
        end

        function Img.resolve(source)
            return Fwd.pic.load(source, {
                Slot = "ui",
                Fetch = fetch,
                Find = findFile,
                Status = function(message)
                    setStatus(Img.localize(message), "idle")
                end,
            })
        end

        function Img.localize(message)
            local label, percent = string.match(message, "^(.-)%s(%d+%%)$")
            if label then
                return translate(label) .. " " .. percent
            end
            return message
        end

        Img.Fetch, Img.Find = fetch, findFile

        function Img.describe(desc)
            if desc.Degraded then
                return "\u{110}\u{E3} \u{E1}p d\u{1EE5}ng \u{1EA3}nh g\u{1ED1}c (Roblox c\u{F3} th\u{1EC3} gi\u{1EA3}m \u{111}\u{1ED9} n\u{E9}t)"
            end
            local size = (desc.W or 0) > 0 and string.format(" %d\u{D7}%d", desc.W, desc.H) or ""
            if math.max(desc.W or 0, desc.H or 0) >= 3800 then
                size = size .. " \u{B7} 4K"
            end
            if desc.Kind == "gif" then
                return translate("\u{110}\u{E3} \u{E1}p d\u{1EE5}ng \u{1EA3}nh \u{111}\u{1ED9}ng") .. size .. ", " .. #desc.Frames .. " " .. translate("khung h\u{EC}nh")
            end
            return translate("\u{110}\u{E3} \u{E1}p d\u{1EE5}ng \u{1EA3}nh n\u{1EC1}n") .. size
        end

        function Img.apply(source, quiet)
            source = trimText(tostring(source or ""))
            source = string.match(source, "^[\"']*(.-)[\"']*$") or source
            Img.Ticket = Img.Ticket + 1
            local ticket = Img.Ticket
            Fwd.pic.cancel("ui")
            if source == "" then
                Img.Busy = false
                Img.Source = ""
                Img.Asset = nil
                Back.setImage(nil)
                if field.Text ~= "" and not field:IsFocused() then
                    field.Text = ""
                end
                setStatus("Ch\u{1B0}a c\u{F3} \u{1EA3}nh", "idle")
                if not quiet then
                    notify("\u{110}\u{E3} g\u{1EE1} \u{1EA3}nh n\u{1EC1}n", "Giao di\u{1EC7}n \u{1EA2}nh kh\u{F4}ng c\u{F2}n \u{1EA3}nh", "info", 2)
                end
                return
            end
            local previous = Img.Source
            Img.Source = source
            if field.Text ~= source and not field:IsFocused() then
                field.Text = source
            end
            Img.Busy = true
            setStatus("\u{110}ang x\u{1EED} l\u{FD}\u{2026}", "idle")
            task.spawn(function()
                local flip = false
                while Img.Busy and ticket == Img.Ticket and gui.Parent do
                    flip = not flip
                    tween(status, 0.4, { TextTransparency = flip and 0.6 or 0 })
                    task.wait(0.4)
                end
                if ticket == Img.Ticket then
                    status.TextTransparency = 0
                end
            end)
            task.spawn(function()
                local ok, asset, failure = pcall(Img.resolve, source)
                if ticket ~= Img.Ticket or not gui.Parent then
                    return
                end
                Img.Busy = false
                if ok and type(asset) == "table" then
                    Img.Asset = asset
                    Back.setImage(asset)
                    setStatus(Img.describe(asset), "ok")
                    if not quiet then
                        notify("\u{110}\u{E3} \u{111}\u{1EB7}t \u{1EA3}nh n\u{1EC1}n", "Giao di\u{1EC7}n \u{1EA2}nh \u{111}ang b\u{1EAD}t", "success", 2.5)
                        if Fwd.themeControl then
                            Fwd.themeControl.Set(Fwd.ThemeImage)
                        end
                    end
                else
                    Img.Source = previous
                    local message = ok and failure or "Kh\u{F4}ng t\u{1EA3}i \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh t\u{1EEB} link"
                    setStatus(message, "warn")
                    if not quiet then
                        notify("Kh\u{F4}ng \u{111}\u{1EB7}t \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh n\u{1EC1}n", message, "warn", 3)
                    end
                end
            end)
        end

        local chips = {}
        function Img.showFiles(list)
            for _, chip in ipairs(chips) do
                chip:Destroy()
            end
            chips = {}
            if #list == 0 then
                tween(filesRow, 0.25, { Size = UDim2.new(1, 0, 0, 0) })
                task.delay(0.28, function()
                    if #chips == 0 then
                        filesRow.Visible = false
                    end
                end)
                return
            end
            local lines = math.ceil(#list / 2)
            filesRow.Size = UDim2.new(1, 0, 0, 0)
            filesRow.Visible = true
            tween(filesRow, 0.4, { Size = UDim2.new(1, 0, 0, 14 + lines * 36) }, Enum.EasingStyle.Quint)
            for n, path in ipairs(list) do
                local column = (n - 1) % 2
                local line = math.floor((n - 1) / 2)
                local chip = box({
                    Class = "TextButton",
                    Name = "ThemeFile",
                    Position = UDim2.new(column * 0.5, column * 3, 0, line * 36),
                    Size = UDim2.new(0.5, -3, 0, 30),
                    AutoButtonColor = false,
                    Text = string.match(path, "([^/]+)$") or path,
                    FontFace = Fonts.Medium,
                    TextSize = 12,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    BackgroundTransparency = 1,
                    Role = "Field",
                    Parent = grid,
                })
                paint(chip, "TextColor3", "Text")
                corner(9, chip)
                new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = chip })
                Glass.Pane(chip, "clear")
                local pop = new("UIScale", { Scale = 0.85, Parent = chip })
                task.delay(0.04 * n, function()
                    if chip.Parent then
                        tween(pop, 0.4, { Scale = 1 }, Enum.EasingStyle.Back)
                    end
                end)
                chip.MouseButton1Click:Connect(function()
                    playSound("click")
                    field.Text = path
                    Img.apply(path, false)
                end)
                chips[#chips + 1] = chip
            end
        end

        function Img.scan()
            if type(listfiles) ~= "function" then
                setStatus("Executor kh\u{F4}ng h\u{1ED7} tr\u{1EE3} qu\u{E9}t file", "warn")
                return
            end
            local found, seen = {}, {}
            for _, folder in ipairs({ "", "boncuti", "images", "Images", "pictures", "Pictures", "wallpapers" }) do
                local ok, list = pcall(listfiles, folder)
                if not ok and folder == "" then
                    ok, list = pcall(listfiles, ".")
                end
                if ok and type(list) == "table" then
                    for _, path in ipairs(list) do
                        if type(path) == "string" and #found < 12 then
                            local clean = string.gsub(path, "\\", "/")
                            clean = string.gsub(clean, "^%./", "")
                            local lower = string.lower(clean)
                            local ext = string.match(lower, "%.(%w+)$")
                            if (ext == "png" or ext == "jpg" or ext == "jpeg" or ext == "gif")
                                and not string.find(lower, "boncuti/themes/", 1, true)
                                and not string.find(lower, "boncuti/media/", 1, true)
                                and not seen[clean] then
                                seen[clean] = true
                                found[#found + 1] = clean
                            end
                        end
                    end
                end
            end
            Img.showFiles(found)
            if #found > 0 then
                setStatus("\u{110}\u{E3} t\u{EC}m th\u{1EA5}y \u{1EA3}nh, ch\u{1ECD}n m\u{1ED9}t \u{1EA3}nh b\u{EA}n d\u{1B0}\u{1EDB}i", "ok")
            else
                setStatus("Kh\u{F4}ng th\u{1EA5}y \u{1EA3}nh PNG, JPG ho\u{1EB7}c GIF trong workspace", "warn")
            end
        end

        field.FocusLost:Connect(function(enterPressed)
            tween(fieldLine, 0.2, { Color = P.Line, Transparency = 0.9 })
            if enterPressed and trimText(field.Text) ~= "" then
                playSound("click")
                Img.apply(field.Text, false)
            end
        end)

        register({
            Get = function()
                return Img.Source
            end,
            Set = function(value)
                Img.apply(value, true)
            end,
        }, "", "themeImage")
    end

    local windowCard = section(Pg.settingsScroll, "C\u{1EED}a s\u{1ED5}")
    register(Mk.createToggle(windowCard, "L\u{E0}m m\u{1EDD} n\u{1EC1}n", "Hi\u{1EC7}u \u{1EE9}ng blur ph\u{ED}a sau c\u{1EED}a s\u{1ED5}", true, function(on)
        Settings.Blur = on
        if State.Open then
            tween(blur, 0.35, { Size = on and Settings.BlurSize or 0 })
        end
    end), true, "blur")
    register(Mk.createSlider(windowCard, "\u{110}\u{1ED9} m\u{1EDD}", 0, 32, 16, 1, "", function(value)
        Settings.BlurSize = value
        if State.Open and Settings.Blur then
            tween(blur, 0.15, { Size = value })
        end
    end), 16, "blurSize")
    Fwd.scaleControl = register(Mk.createSegmented(windowCard, "K\u{ED}ch th\u{1B0}\u{1EDB}c", { "Nh\u{1ECF}", "V\u{1EEB}a", "L\u{1EDB}n" }, 2, 62, function(index)
        Settings.Scale = index
        Win.applyScale(true)
    end), 2, "scale")

    local islandCard = section(Pg.settingsScroll, "Dynamic Island")
    register(Mk.createToggle(islandCard, "Hi\u{1EC7}n FPS tr\u{EA}n \u{111}\u{1EA3}o", "Hi\u{1EC3}n th\u{1ECB} hi\u{1EC7}u n\u{103}ng ngay tr\u{EA}n \u{111}\u{1EA3}o", false, function(on)
        setFpsActivity(on)
    end), false, "islandFps")
    register(Mk.createToggle(islandCard, "Hi\u{1EC7}n ping tr\u{EA}n \u{111}\u{1EA3}o", "Hi\u{1EC3}n th\u{1ECB} \u{111}\u{1ED9} tr\u{1EC5} m\u{1EA1}ng ngay tr\u{EA}n \u{111}\u{1EA3}o", false, function(on)
        setPingActivity(on)
    end), false, "islandPing")
    register(Mk.createToggle(islandCard, "Hi\u{1EC7}n \u{111}\u{1ED3}ng h\u{1ED3} tr\u{EA}n \u{111}\u{1EA3}o", "Hi\u{1EC3}n th\u{1ECB} gi\u{1EDD} hi\u{1EC7}n t\u{1EA1}i ngay tr\u{EA}n \u{111}\u{1EA3}o", false, function(on)
        setClockActivity(on)
    end), false, "islandClock")
    register(Mk.createToggle(islandCard, "M\u{1EDF} r\u{1ED9}ng \u{111}\u{1EA3}o", "Nh\u{1EA5}n gi\u{1EEF} ho\u{1EB7}c chu\u{1ED9}t ph\u{1EA3}i v\u{E0}o \u{111}\u{1EA3}o \u{111}\u{1EC3} m\u{1EDF} b\u{1EA3}ng \u{111}i\u{1EC1}u khi\u{1EC3}n", true, function(on)
        Settings.Expand = on
        if not on and Isl.collapse then
            Isl.collapse()
        end
    end), true, "islandExpand")
    register(Mk.createToggle(islandCard, "\u{110}\u{1EA3}o t\u{E1}ch \u{111}\u{F4}i", "Ho\u{1EA1}t \u{111}\u{1ED9}ng th\u{1EE9} hai hi\u{1EC7}n th\u{E0}nh bong b\u{F3}ng c\u{1EA1}nh \u{111}\u{1EA3}o", true, function(on)
        Settings.Split = on
        if Fwd.islandSync then
            Fwd.islandSync()
        end
    end), true, "islandSplit")
    register(Mk.createToggle(islandCard, "\u{C1}nh s\u{E1}ng vi\u{1EC1}n", "V\u{1EC7}t s\u{E1}ng ch\u{1EA1}y quanh vi\u{1EC1}n \u{111}\u{1EA3}o", false, function(on)
        Settings.RimLight = on
    end), false, "islandRim")
    register(Mk.createToggle(islandCard, "Ch\u{1EA5}m nh\u{1ECB}p th\u{1EDF}", "Ch\u{1EA5}m xanh nh\u{1EA5}p nh\u{E1}y khi \u{111}\u{1EA3}o ngh\u{1EC9}", true, function(on)
        Settings.Breathe = on
    end), true, "breathe")
    register(Mk.createToggle(islandCard, "Vi\u{1EC1}n \u{111}\u{1EBF}m ng\u{1B0}\u{1EE3}c", "V\u{F2}ng s\u{E1}ng ch\u{1EA1}y quanh \u{111}\u{1EA3}o khi c\u{F3} th\u{F4}ng b\u{E1}o", true, function(on)
        Settings.Ring = on
        if on then
            Isl.settleIsland()
        else
            Ring.ringHide()
        end
    end), true, "ring")
    register(Mk.createSwatches(islandCard, "M\u{E0}u \u{111}\u{1EA3}o", Fwd.IslandTones, 1, function(index)
        Settings.IslandTone = index > 1 and Fwd.IslandTones[index][2] or nil
        if Fwd.islandRecolor then
            Fwd.islandRecolor(0.35)
        end
    end), 1, "islandColor")
end

do
    local IT = {
        Mode = 1, A = 210, B = 280, Sat = 70, ValA = 55, ValB = 30, Angle = 90, Spin = false, Speed = 30, Phase = 0,
        Strength = 100, Dim = 25, Motion = true, Source = "", Desc = nil, Ticket = 0, Bulk = false, Reset = false,
    }
    Fwd.islandTheme = IT

    local wrap = new("CanvasGroup", {
        Name = "IslandTheme",
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 0,
        Visible = false,
        Parent = Isl.islandFrame,
    })
    Fwd.islandThemeCorner = corner(15, wrap)
    Fwd.islandThemeCorner.CornerRadius = Isl.islandCorner.CornerRadius
    local pic = Fwd.surface(wrap, "IslandPicture")
    pic.Root.ZIndex = 1
    pic.Gate = function()
        return IT.Motion
    end
    local dim = new("Frame", {
        Name = "IslandDim",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Static.Black,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 2,
        Parent = wrap,
    })
    local modeControl

    function IT.colors()
        if IT.Mode ~= 2 then
            return nil
        end
        return {
            Color3.fromHSV(IT.A / 360, IT.Sat / 100, IT.ValA / 100),
            Color3.fromHSV(IT.B / 360, IT.Sat / 100, IT.ValB / 100),
        }
    end

    function IT.refresh(duration)
        if IT.Bulk then
            return
        end
        duration = duration or 0.35
        if IT.Mode == 3 and IT.Desc ~= nil then
            pic:Set(IT.Desc)
            wrap.Visible = true
            pic.Root.Visible = true
            tween(pic.Root, duration, { GroupTransparency = 1 - IT.Strength / 100 })
            tween(dim, duration, { BackgroundTransparency = 1 - IT.Dim / 100 })
        else
            tween(pic.Root, duration, { GroupTransparency = 1 })
            tween(dim, duration, { BackgroundTransparency = 1 })
            task.delay(duration + 0.05, function()
                if not (IT.Mode == 3 and IT.Desc ~= nil) then
                    wrap.Visible = false
                    pic.Root.Visible = false
                end
            end)
        end
        if Fwd.islandRecolor then
            Fwd.islandRecolor(math.max(duration, 0.05))
        end
    end

    table.insert(Hooks.Tasks, function(dt)
        if IT.Mode == 2 then
            local rotation = IT.Angle
            if IT.Spin then
                IT.Phase = (IT.Phase + dt * IT.Speed * 1.2) % 360
                rotation = rotation + IT.Phase
            end
            if Isl.bodyGradient.Rotation ~= rotation then
                Isl.bodyGradient.Rotation = rotation
                Isl.bubbleGradient.Rotation = rotation
            end
            IT.Reset = true
        elseif IT.Reset then
            IT.Reset = false
            Isl.bodyGradient.Rotation = 90
            Isl.bubbleGradient.Rotation = 90
        end
    end)

    local card = section(Pg.settingsScroll, "Theme Dynamic Island")
    modeControl = register(Mk.createSegmented(card, "Ki\u{1EC3}u n\u{1EC1}n \u{111}\u{1EA3}o", { "M\u{1EB7}c \u{111}\u{1ECB}nh", "M\u{E0}u t\u{1EF1} do", "\u{1EA2}nh / GIF" }, 1, 78, function(index, user)
        IT.Mode = index
        IT.refresh()
        if user and index == 3 and IT.Desc == nil then
            notify("Ch\u{1B0}a c\u{F3} \u{1EA3}nh n\u{1EC1}n \u{111}\u{1EA3}o", "D\u{E1}n link ho\u{1EB7}c t\u{EA}n file \u{1EDF} m\u{1EE5}c \u{1EA2}nh n\u{1EC1}n \u{111}\u{1EA3}o", "info", 3)
        end
    end), 1, "islandMode")

    local PRESETS = {
        { "Aurora", 160, 270, 70, 60, 30 },
        { "Ho\u{E0}ng h\u{F4}n", 18, 335, 85, 75, 35 },
        { "\u{110}\u{1EA1}i d\u{1B0}\u{1A1}ng", 200, 245, 80, 65, 28 },
        { "K\u{1EB9}o ng\u{1ECD}t", 325, 190, 55, 85, 55 },
        { "V\u{E0}ng kim", 45, 22, 80, 70, 32 },
        { "R\u{1EEB}ng", 135, 170, 75, 48, 22 },
        { "Neon", 290, 170, 95, 85, 40 },
        { "Than \u{111}\u{E1}", 225, 260, 18, 34, 14 },
    }
    local swatchList = {}
    for n, item in ipairs(PRESETS) do
        swatchList[n] = { item[1], Color3.fromHSV(item[2] / 360, item[4] / 100, math.max(item[5], 60) / 100) }
    end
    local ctl = {}
    Mk.createSwatches(card, "B\u{1ED9} m\u{E0}u c\u{F3} s\u{1EB5}n", swatchList, 0, function(index, user)
        if not user then
            return
        end
        local preset = PRESETS[index]
        IT.Bulk = true
        IT.A, IT.B, IT.Sat, IT.ValA, IT.ValB = preset[2], preset[3], preset[4], preset[5], preset[6]
        ctl.A.Set(preset[2])
        ctl.B.Set(preset[3])
        ctl.Sat.Set(preset[4])
        ctl.ValA.Set(preset[5])
        ctl.ValB.Set(preset[6])
        IT.A, IT.B, IT.Sat, IT.ValA, IT.ValB = preset[2], preset[3], preset[4], preset[5], preset[6]
        IT.Bulk = false
        if IT.Mode ~= 2 then
            modeControl.Set(2)
        else
            IT.refresh()
        end
    end)

    local function slider(field, key, title, min, max, default, suffix)
        ctl[field] = register(Mk.createSlider(card, title, min, max, default, 1, suffix, function(value, user)
            IT[field] = value
            if user and IT.Mode ~= 2 and field ~= "Speed" then
                modeControl.Set(2)
            else
                IT.refresh(0.12)
            end
        end), default, key)
    end
    slider("A", "islandHueA", "S\u{1EAF}c \u{111}\u{1ED9} m\u{E0}u A", 0, 360, 210, "\u{B0}")
    slider("B", "islandHueB", "S\u{1EAF}c \u{111}\u{1ED9} m\u{E0}u B", 0, 360, 280, "\u{B0}")
    slider("Sat", "islandSat", "\u{110}\u{1ED9} r\u{1EF1}c m\u{E0}u", 0, 100, 70, "%")
    slider("ValA", "islandValA", "\u{110}\u{1ED9} s\u{E1}ng m\u{E0}u A", 5, 100, 55, "%")
    slider("ValB", "islandValB", "\u{110}\u{1ED9} s\u{E1}ng m\u{E0}u B", 5, 100, 30, "%")
    slider("Angle", "islandAngle", "G\u{F3}c chuy\u{1EC3}n m\u{E0}u", 0, 360, 90, "\u{B0}")
    register(Mk.createToggle(card, "Xoay m\u{E0}u li\u{EA}n t\u{1EE5}c", "Gradient xoay quanh \u{111}\u{1EA3}o", false, function(on)
        IT.Spin = on
    end), false, "islandSpin")
    slider("Speed", "islandSpinSpeed", "T\u{1ED1}c \u{111}\u{1ED9} xoay", 5, 100, 30, "%")

    local imgCard = section(Pg.settingsScroll, "\u{1EA2}nh n\u{1EC1}n \u{111}\u{1EA3}o")
    local fieldRow = addRow(imgCard, 100)
    Search.Add(fieldRow, "Tu\u{1EF3} ch\u{1ECD}n", "\u{1EA2}nh n\u{1EC1}n \u{111}\u{1EA3}o")
    Mk.rowTitle(fieldRow, "D\u{F9}ng \u{1EA3}nh ho\u{1EB7}c GIF cho \u{111}\u{1EA3}o", "D\u{E1}n link \u{1EA3}nh, GIF ho\u{1EB7}c t\u{EA}n file trong workspace", 32)
    local field = new("TextBox", {
        Name = "IslandImageField",
        Position = UDim2.fromOffset(16, 54),
        Size = UDim2.new(1, -32, 0, 34),
        BorderSizePixel = 0,
        ClearTextOnFocus = false,
        Text = "",
        PlaceholderText = translate("https://\u{2026} ho\u{1EB7}c boncuti/anh.gif"),
        FontFace = Fonts.Regular,
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Parent = fieldRow,
    })
    paint(field, "BackgroundColor3", "Field")
    paint(field, "TextColor3", "Text")
    paint(field, "PlaceholderColor3", "Sub")
    corner(9, field)
    new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = field })
    local fieldLine = stroke(field, "Line", 0.9, 1)
    field.Focused:Connect(function()
        tween(fieldLine, 0.2, { Color = P.Accent, Transparency = 0 })
    end)
    local status = Mk.createInfo(imgCard, "Tr\u{1EA1}ng th\u{E1}i", "Ch\u{1B0}a c\u{F3} \u{1EA3}nh")
    status.Name = "IslandImageStatus"
    status.Position = UDim2.new(0.25, 0, 0, 0)
    status.Size = UDim2.new(0.75, -16, 1, 0)

    local function setStatus(message, tone)
        status.Text = translate(message)
        local color = P.Sub
        if tone == "ok" then
            color = Static.Green
        elseif tone == "warn" then
            color = Static.Orange
        end
        tween(status, 0.2, { TextColor3 = color })
    end

    function IT.apply(source, quiet)
        source = tostring(source or "")
        source = string.match(source, "^%s*[\"']*(.-)[\"']*%s*$") or source
        IT.Ticket = IT.Ticket + 1
        local ticket = IT.Ticket
        Fwd.pic.cancel("island")
        if source == "" then
            IT.Source = ""
            IT.Desc = nil
            if field.Text ~= "" and not field:IsFocused() then
                field.Text = ""
            end
            setStatus("Ch\u{1B0}a c\u{F3} \u{1EA3}nh", "idle")
            IT.refresh()
            if not quiet then
                notify("\u{110}\u{E3} g\u{1EE1} \u{1EA3}nh n\u{1EC1}n \u{111}\u{1EA3}o", "Dynamic Island kh\u{F4}ng c\u{F2}n \u{1EA3}nh", "info", 2)
            end
            return
        end
        local previous = IT.Source
        IT.Source = source
        if field.Text ~= source and not field:IsFocused() then
            field.Text = source
        end
        setStatus("\u{110}ang x\u{1EED} l\u{FD}\u{2026}", "idle")
        task.spawn(function()
            local ok, desc, failure = pcall(function()
                return Fwd.pic.load(source, {
                    Slot = "island",
                    Light = true,
                    Side = 512,
                    Pixels = 10000000,
                    Fetch = Fwd.themeImage.Fetch,
                    Find = Fwd.themeImage.Find,
                    Status = function(message)
                        if ticket == IT.Ticket then
                            setStatus(Fwd.themeImage.localize(message), "idle")
                        end
                    end,
                })
            end)
            if ticket ~= IT.Ticket or not gui.Parent then
                return
            end
            if ok and type(desc) == "table" then
                IT.Desc = desc
                setStatus(Fwd.themeImage.describe(desc), "ok")
                if not quiet and IT.Mode ~= 3 then
                    modeControl.Set(3)
                else
                    IT.refresh()
                end
                if not quiet then
                    notify("\u{110}\u{E3} \u{111}\u{1EB7}t \u{1EA3}nh n\u{1EC1}n \u{111}\u{1EA3}o", "Dynamic Island \u{111}ang d\u{F9}ng \u{1EA3}nh m\u{1EDB}i", "success", 2.5)
                end
            else
                IT.Source = previous
                local message = ok and failure or "Kh\u{F4}ng t\u{1EA3}i \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh t\u{1EEB} link"
                setStatus(message, "warn")
                if not quiet then
                    notify("Kh\u{F4}ng \u{111}\u{1EB7}t \u{111}\u{1B0}\u{1EE3}c \u{1EA3}nh \u{111}\u{1EA3}o", message, "warn", 3)
                end
            end
        end)
    end

    local buttons = Mk.createButtons(imgCard, {
        {
            Text = "\u{C1}p d\u{1EE5}ng",
            Callback = function()
                IT.apply(field.Text, false)
            end,
        },
        {
            Text = "G\u{1EE1} \u{1EA3}nh",
            Role = "Field",
            Callback = function()
                field.Text = ""
                IT.apply("", false)
            end,
        },
    })
    for _, button in ipairs(buttons) do
        button.Name = "IslandImageButton"
    end
    field.FocusLost:Connect(function(enterPressed)
        tween(fieldLine, 0.2, { Color = P.Line, Transparency = 0.9 })
        if enterPressed and string.match(field.Text, "%S") then
            playSound("click")
            IT.apply(field.Text, false)
        end
    end)

    register(Mk.createSlider(imgCard, "\u{110}\u{1ED9} \u{111}\u{1EAD}m \u{1EA3}nh \u{111}\u{1EA3}o", 10, 100, 100, 1, "%", function(value)
        IT.Strength = value
        if wrap.Visible then
            tween(pic.Root, 0.15, { GroupTransparency = 1 - value / 100 })
        end
    end), 100, "islandImageStrength")
    register(Mk.createSlider(imgCard, "\u{110}\u{1ED9} t\u{1ED1}i \u{1EA3}nh \u{111}\u{1EA3}o", 0, 85, 25, 1, "%", function(value)
        IT.Dim = value
        if wrap.Visible then
            tween(dim, 0.15, { BackgroundTransparency = 1 - value / 100 })
        end
    end), 25, "islandImageDim")
    register(Mk.createToggle(imgCard, "Chuy\u{1EC3}n \u{111}\u{1ED9}ng \u{1EA3}nh \u{111}\u{1EA3}o", "Cho \u{1EA3}nh GIF tr\u{EA}n \u{111}\u{1EA3}o ch\u{1EA1}y li\u{EA}n t\u{1EE5}c", true, function(on)
        IT.Motion = on
    end), true, "islandImageMotion")
    register({
        Get = function()
            return IT.Source
        end,
        Set = function(value)
            IT.apply(value, true)
        end,
    }, "", "islandImage")
end

