    local keys = section(Pg.settingsScroll, "Ph\u{ED}m t\u{1EAF}t")
    register(Mk.createKeybind(keys, "\u{1EA8}n / hi\u{1EC7}n c\u{1EED}a s\u{1ED5}", "B\u{1EA5}m r\u{1ED3}i nh\u{1EA5}n ph\u{ED}m m\u{1EDB}i, Esc \u{111}\u{1EC3} hu\u{1EF7}", Enum.KeyCode.RightShift, function(key, user)
        Settings.ToggleKey = key
        Ux.refreshKeyHints()
        if user then
            notify("\u{110}\u{E3} \u{111}\u{1ED5}i ph\u{ED}m t\u{1EAF}t", key.Name, "success", 1.8)
        end
