    local manage = section(Pg.settingsScroll, "Qu\u{1EA3}n l\u{FD}")
    Mk.createButtons(manage, {
        {
            Text = "\u{110}\u{1EB7}t l\u{1EA1}i c\u{E0}i \u{111}\u{1EB7}t",
            Role = "Field",
            Callback = function()
                Ux.confirm("\u{110}\u{1EB7}t l\u{1EA1}i c\u{E0}i \u{111}\u{1EB7}t?", "M\u{1ECD}i tu\u{1EF3} ch\u{1ECD}n s\u{1EBD} tr\u{1EDF} v\u{1EC1} m\u{1EB7}c \u{111}\u{1ECB}nh.", "\u{110}\u{1EB7}t l\u{1EA1}i", false, function()
                    Ux.resetAll()
                    notify("\u{110}\u{E3} \u{111}\u{1EB7}t l\u{1EA1}i", "C\u{E0}i \u{111}\u{1EB7}t \u{111}\u{E3} v\u{1EC1} m\u{1EB7}c \u{111}\u{1ECB}nh", "success")
                end)
            end,
        },
        {
            Text = "G\u{1EE1} boncuti",
            Color = Static.Red,
            Callback = function()
                Ux.confirm("G\u{1EE1} boncuti?", "Giao di\u{1EC7}n s\u{1EBD} b\u{1ECB} xo\u{E1} kh\u{1ECF}i phi\u{EA}n ch\u{1A1}i n\u{E0}y.", "G\u{1EE1}", true, Ux.unload)
