            Size = UDim2.fromOffset(9, 9),
            BackgroundColor3 = Static.White,
            ZIndex = 5,
            Visible = false,
            Parent = canvas,
        })
        corner(5, marker)
        stroke(marker, Static.Black, 0.4, 1.5)
        local pool = {}
        local MAP_COLORS = {
            walk = Color3.fromRGB(52, 168, 110),
            void = Color3.fromRGB(18, 22, 40),
            hz = Color3.fromRGB(235, 72, 60),
            wall = Color3.fromRGB(112, 114, 130),
        }

        local function rect(index, x, y, w, h, color, transparency, layer)
            local frame = pool[index]
            if not frame then
                frame = new("Frame", { BorderSizePixel = 0, Parent = canvas })
                pool[index] = frame
            end
            frame.Visible = true
            frame.Position = UDim2.fromOffset(x, y)
            frame.Size = UDim2.fromOffset(w, h)
            frame.BackgroundColor3 = color
            frame.BackgroundTransparency = transparency or 0
            frame.ZIndex = layer or 1
        end

        local function drawMap()
            local World = Cross.World
            local character = player.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            if not root then
                return
            end
            local size = canvas.AbsoluteSize
            local side = math.min(size.X, size.Y)
            if side < 24 then
                return
            end
            local px, pz = root.Position.X, root.Position.Z
            local cix, ciz = World.cellIndex(px, pz)
            local range = World.Range
            local span = range * 2 + 1
            local unit = side / span
            local ox, oz = (size.X - side) / 2, (size.Y - side) / 2
            local used = 0
            local anyCell = false
            for dz = -range, range do
                local runClass, runStart
                for dx = -range, range + 1 do
                    local class
                    if dx <= range then
                        local cell = World.cell(cix + dx, ciz + dz)
                        if cell then
                            anyCell = true
                            if cell.Void then
                                class = "void"
                            elseif cell.Hz then
                                class = "hz"
                            elseif cell.Walk then
                                class = "walk"
                            else
                                class = "wall"
                            end
                        end
                    end
                    if class ~= runClass then
                        if runClass and used < 700 then
                            used = used + 1
                            rect(used, ox + (runStart + range) * unit, oz + (dz + range) * unit, (dx - runStart) * unit + 0.6, unit + 0.6, MAP_COLORS[runClass], 0, 1)
                        end
                        runClass, runStart = class, dx
                    end
                end
            end
            local act = Cross.Pilot.Act
            local nav = act and act.Nav
            if nav and nav.Path then
                local last
                local shown = 0
                for index = nav.PI or 1, #nav.Path do
                    local node = nav.Path[index]
                    if node.Ix and shown < 80 and math.abs(node.Ix - cix) <= range and math.abs(node.Iz - ciz) <= range then
                        shown = shown + 1
                        used = used + 1
                        local cx = ox + (node.Ix - cix + range + 0.5) * unit
                        local cz = oz + (node.Iz - ciz + range + 0.5) * unit
                        rect(used, cx - unit * 0.28, cz - unit * 0.28, unit * 0.56, unit * 0.56, P.Accent, 0, 3)
                        last = { cx, cz }
                    end
                end
                if last then
                    used = used + 1
                    rect(used, last[1] - unit * 0.7, last[2] - unit * 0.7, unit * 1.4, unit * 1.4, Static.Orange, 0.1, 4)
                end
            end
            for index = used + 1, #pool do
                pool[index].Visible = false
            end
            local fx = (px / World.Cell) - cix
            local fz = (pz / World.Cell) - ciz
            marker.Position = UDim2.fromOffset(ox + (range + fx) * unit, oz + (range + fz) * unit)
            marker.Visible = true
            mapEmpty.Visible = not anyCell
        end

        local function playLine(info)
            local bits = {}
            local name = PLAY_NAMES[info.Mode or ""]
            if name then
                bits[#bits + 1] = lang2(name[1], name[2])
            else
                bits[#bits + 1] = lang2("\u{110}ang ngh\u{1EC9}", "Idle")
            end
            if info.Active then
                bits[#bits + 1] = tostring(info.Phase or "")
            end
            bits[#bits + 1] = string.format("%s %d", lang2("\u{F4}", "cells"), info.Cells or 0)
            bits[#bits + 1] = string.format("%s %d", lang2("qu\u{E1}i", "kills"), info.Kills or 0)
            bits[#bits + 1] = string.format("%s %d", lang2("\u{111}\u{1ED3}", "items"), info.Items or 0)
            if info.Level then
                bits[#bits + 1] = "lv " .. tostring(info.Level)
            end
            if info.Stage then
                bits[#bits + 1] = "stage " .. tostring(info.Stage)
            end
            return table.concat(bits, " \u{B7} ")
        end

        local mapClock = 0
        table.insert(Hooks.Tasks, function(dt)
            if not visibleTab() then
                return
            end
            mapClock = mapClock + dt
            if mapClock < 0.25 then
                return
            end
            mapClock = 0
            local info = Cross.Pilot.info()
            local line = playLine(info)
            if playStatus.Text ~= line then
                playStatus.Text = line
            end
            local desc = Cross.Tasks.describe()
            local planText = desc and desc.Plan or lang2("Ch\u{1B0}a c\u{F3} nhi\u{1EC7}m v\u{1EE5}. Th\u{1EED}: 'b\u{1EAD}t Anti AFK 10 ph\u{FA}t'", "No task. Try: 'turn on Anti AFK for 10 minutes'")
            local detailText = desc and ((desc.Status == "paused" and (lang2("T\u{1EA1}m d\u{1EEB}ng \u{B7} ", "Paused \u{B7} "))) or "") .. desc.Detail or "\u{2014}"
            if desc == nil and Cross.Tasks.Last then
                detailText = lang2("Nhi\u{1EC7}m v\u{1EE5} tr\u{1B0}\u{1EDB}c: ", "Last task: ") .. (Cross.Tasks.Last.Status == "done" and lang2("ho\u{E0}n th\u{E0}nh", "complete") or lang2("\u{111}\u{E3} hu\u{1EF7}", "cancelled"))
            end
            if taskPlan.Text ~= planText then
                taskPlan.Text = planText
            end
            if taskDetail.Text ~= detailText then
                taskDetail.Text = detailText
            end
            local sum = Cross.Pilot.summary()
            local obby = sum.Obby and lang2("c\u{F3}", "yes") or lang2("kh\u{F4}ng", "no")
            local info2 = string.format("%d %s \u{B7} %d %s \u{B7} %d %s \u{B7} %d %s \u{B7} obby: %s", sum.Cells, lang2("\u{F4}", "cells"), sum.Walk, lang2("\u{111}i \u{111}\u{1B0}\u{1EE3}c", "walkable"), sum.Voids, lang2("kho\u{1EA3}ng tr\u{1ED1}ng", "gaps"), sum.Hazards, lang2("nguy hi\u{1EC3}m", "hazards"), obby)
            if mapInfo.Text ~= info2 then
                mapInfo.Text = info2
            end
            drawMap()
        end)
    end

