            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            TextColor3 = mine and Static.White or nil,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            Parent = bubble,
        })
        body:SetAttribute("BoncutiRaw", true)
        return { Holder = holder, Body = body }
    end

    local function syncRows()
        local list = Cross.Chat
        local alive = {}
        for _, entry in ipairs(list) do
            alive[entry] = true
            local item = rows[entry]
            if not item then
                item = makeRow(entry)
                rows[entry] = item
            end
            if Cross.Grapheme then
                if item.Body.Text ~= entry.Text then
                    item.Body.Text = entry.Text
                end
                local visible = entry.Visible or -1
                if item.Body.MaxVisibleGraphemes ~= visible then
                    item.Body.MaxVisibleGraphemes = visible
                end
                item.Holder.Visible = visible ~= 0
            else
                if item.Body.Text ~= entry.Shown then
                    item.Body.Text = entry.Shown
                end
                item.Holder.Visible = entry.Shown ~= ""
            end
        end
        for entry, item in pairs(rows) do
            if not alive[entry] then
                item.Holder:Destroy()
                rows[entry] = nil
            end
        end
        emptyLabel.Visible = #list == 0
        emptyLabel.Text = translate(Cross.Enabled and "Ch\u{1B0}a c\u{F3} tin nh\u{1EAF}n. Th\u{1EED} n\u{F3}i: \u{EA} Cross, tr\u{1EDD}i n\u{F3}ng qu\u{E1} l\u{E0}m UI m\u{E1}t x\u{ED}u coi" or "Cross \u{111}ang ng\u{1EE7}. N\u{F3}i 'b\u{1EAD}t cross' \u{111}\u{1EC3} \u{111}\u{E1}nh th\u{1EE9}c m\u{EC}nh.")
        stick = 3
    end

    function Cross.clearChat()
        Cross.Memory.clear()
        Cross.Chat = {}
        Cross.ChatVersion = Cross.ChatVersion + 1
        Cross.Bubble.Full = ""
        Cross.Bubble.Shown = ""
        Cross.Bubble.Entry = nil
        Cross.Echo = ""
    end

    function Cross.CardsSync()
        shown = -1
    end

    table.insert(Hooks.Tasks, function()
        if not visibleTab() then
            return
        end
        if shown ~= Cross.ChatVersion then
            shown = Cross.ChatVersion
            syncRows()
        end
        if stick > 0 then
            stick = stick - 1
            log.CanvasPosition = Vector2.new(0, 100000)
        end
        local state
        local en = Settings.Language == "en"
        if not Cross.Enabled then
            state = en and "Asleep \u{B7} say 'turn on cross'" or "\u{110}ang ng\u{1EE7} \u{B7} n\u{F3}i 'b\u{1EAD}t cross'"
        elseif Cross.Thinking then
            state = en and "Thinking\u{2026}" or "\u{110}ang ngh\u{129}\u{2026}"
        elseif Cross.Body.Active then
            state = Cross.Body.Free and (en and "Playing on its own \u{B7} say 'stop'" or "\u{110}ang t\u{1EF1} ch\u{1A1}i \u{B7} n\u{F3}i 'd\u{1EEB}ng'") or (en and "Controlling your character \u{B7} say 'stop'" or "\u{110}ang \u{111}i\u{1EC1}u khi\u{1EC3}n nh\u{E2}n v\u{1EAD}t \u{B7} n\u{F3}i 'd\u{1EEB}ng'")
        elseif Cross.Busy > 0 then
            state = en and "Working\u{2026}" or "\u{110}ang th\u{1EF1}c hi\u{1EC7}n\u{2026}"
        else
            state = en and "Ready" or "S\u{1EB5}n s\u{E0}ng"
        end
        if statusLabel.Text ~= state then
            statusLabel.Text = state
        end
    end)
end

