    local actions = section(Pg.inboxScroll, "Thao t\u{E1}c")
    local feed = section(Pg.inboxScroll, "G\u{1EA7}n \u{111}\u{E2}y")
    feed.Visible = false
    local empty = text({
        Name = "Empty",
        Size = UDim2.new(1, 0, 0, 80),
        Text = "Ch\u{1B0}a c\u{F3} th\u{F4}ng b\u{E1}o n\u{E0}o",
        FontFace = Fonts.Regular,
