    })

    local rows = {}
    local counter = 0
    local top

    local function refreshEmpty()
        feed.Visible = #rows > 0
        empty.Visible = #rows == 0
    end

    local function addEntry(title, message, kind)
        counter = counter + 1
        local style = KINDS[kind] or KINDS.info
        local row = new("Frame", {
            Name = "Entry",
