            Size = UDim2.fromOffset(50, 16),
            Text = os.date("%H:%M"),
            FontFace = Fonts.Regular,
            TextSize = 12,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Right,
            Parent = row,
        })
        if top then
            top.Visible = true
        end
        top = separator
        table.insert(rows, row)
        if #rows > 30 then
            table.remove(rows, 1):Destroy()
        end
        refreshEmpty()
    end

    local function clearEntries()
        for _, row in ipairs(rows) do
            row:Destroy()
        end
        table.clear(rows)
        top = nil
        refreshEmpty()
    end

    History.Add = addEntry

    Mk.createButtons(actions, {
        {
            Text = "Xo\u{E1} t\u{1EA5}t c\u{1EA3}",
            Role = "Field",
            Callback = clearEntries,
        },
    })
end

do
    local Tools = { Speed = nil, Jump = nil, InfiniteJump = false }

    local function humanoid()
        local character = player.Character
        return character and character:FindFirstChildOfClass("Humanoid")
    end

    local function applyCharacter()
        local hum = humanoid()
        if not hum then
            return
        end
        if Tools.Speed then
            hum.WalkSpeed = Tools.Speed
        end
        if Tools.Jump then
            hum.UseJumpPower = true
            hum.JumpPower = Tools.Jump
        end
    end

    track(player.CharacterAdded:Connect(function()
        task.wait(0.6)
        applyCharacter()
    end))

    track(UserInputService.JumpRequest:Connect(function()
        if Tools.InfiniteJump then
            local hum = humanoid()
            if hum then
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
            end
        end
    end))

    local cameraCard = section(Pg.toolsScroll, "M\u{E1}y \u{1EA3}nh")
    local startFov = math.floor(camera.FieldOfView + 0.5)
    register(Mk.createSlider(cameraCard, "G\u{F3}c nh\u{EC}n (FOV)", 40, 120, startFov, 1, "\u{B0}", function(value)
        camera.FieldOfView = value
    end), startFov, "fov")

    local envCard = section(Pg.toolsScroll, "M\u{F4}i tr\u{1B0}\u{1EDD}ng")
    local baseLighting = {
        Brightness = Lighting.Brightness,
        Ambient = Lighting.Ambient,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        GlobalShadows = Lighting.GlobalShadows,
    }
    local startClock = math.floor(Lighting.ClockTime + 0.5)
    register(Mk.createSlider(envCard, "Gi\u{1EDD} trong ng\u{E0}y", 0, 24, startClock, 1, "h", function(value)
        Lighting.ClockTime = value
    end), startClock, "clock")
    register(Mk.createToggle(envCard, "S\u{E1}ng to\u{E0}n c\u{1EA3}nh", "Xo\u{E1} c\u{E1}c v\u{F9}ng t\u{1ED1}i tr\u{EA}n b\u{1EA3}n \u{111}\u{1ED3}", false, function(on)
        if on then
            Lighting.Brightness = 3
            Lighting.Ambient = rgb(190, 190, 190)
            Lighting.OutdoorAmbient = rgb(190, 190, 190)
        else
            Lighting.Brightness = baseLighting.Brightness
            Lighting.Ambient = baseLighting.Ambient
            Lighting.OutdoorAmbient = baseLighting.OutdoorAmbient
        end
    end), false, "fullbright")
    register(Mk.createToggle(envCard, "T\u{1EAF}t b\u{F3}ng \u{111}\u{1ED5}", "T\u{103}ng FPS tr\u{EA}n m\u{E1}y y\u{1EBF}u", false, function(on)
        Lighting.GlobalShadows = (not on) and baseLighting.GlobalShadows
    end), false, "noShadows")

    local charCard = section(Pg.toolsScroll, "Nh\u{E2}n v\u{1EAD}t")
    local hum0 = humanoid()
    local startSpeed = hum0 and math.floor(hum0.WalkSpeed + 0.5) or 16
    local startJump = hum0 and math.floor(hum0.JumpPower + 0.5) or 50
    register(Mk.createSlider(charCard, "T\u{1ED1}c \u{111}\u{1ED9} ch\u{1EA1}y", 8, 100, startSpeed, 1, "", function(value)
        Tools.Speed = value
        applyCharacter()
    end), startSpeed, "speed")
    register(Mk.createSlider(charCard, "L\u{1EF1}c nh\u{1EA3}y", 20, 150, startJump, 1, "", function(value)
        Tools.Jump = value
        applyCharacter()
    end), startJump, "jump")
    register(Mk.createToggle(charCard, "Nh\u{1EA3}y li\u{EA}n t\u{1EE5}c", "Cho ph\u{E9}p nh\u{1EA3}y khi \u{111}ang \u{1EDF} tr\u{EA}n kh\u{F4}ng", false, function(on)
        Tools.InfiniteJump = on
    end), false, "infiniteJump")

    local Afk = { Enabled = true, Blocked = 0, Since = os.clock(), Service = nil }
    pcall(function()
        Afk.Service = game:GetService("VirtualUser")
    end)

    local function afkPulse()
        local service = Afk.Service
        if not service then
            return false
        end
        Fwd.synth(1.5)
        return (pcall(function()
            service:CaptureController()
            service:ClickButton2(Vector2.new(0, 0))
        end))
    end

    track(player.Idled:Connect(function()
        if Afk.Enabled and afkPulse() then
            Afk.Blocked = Afk.Blocked + 1
            notify("Anti AFK", "\u{110}\u{E3} gi\u{1EEF} b\u{1EA1}n ho\u{1EA1}t \u{111}\u{1ED9}ng, kh\u{F4}ng b\u{1ECB} kick", "success")
        end
    end))

    task.spawn(function()
        while gui.Parent do
            task.wait(45)
            if Afk.Enabled and gui.Parent then
                afkPulse()
            end
        end
    end)

    local afkCard = section(Pg.toolsScroll, "Anti AFK")
    register(Mk.createToggle(afkCard, "Anti AFK", "Gi\u{1EEF} nh\u{E2}n v\u{1EAD}t ho\u{1EA1}t \u{111}\u{1ED9}ng \u{111}\u{1EC3} kh\u{F4}ng b\u{1ECB} kick khi \u{111}\u{1EE9}ng y\u{EA}n", true, function(on)
        Afk.Enabled = on
        if on then
            Afk.Since = os.clock()
        end
    end), true, "antiAfk")
    local afkStatus = Mk.createInfo(afkCard, "Tr\u{1EA1}ng th\u{E1}i", "\u{110}ang b\u{1EA3}o v\u{1EC7}")
    local afkCount = Mk.createInfo(afkCard, "L\u{1EA7}n ch\u{1EB7}n kick", "0")

    local function refreshAfk()
        local status
        if Afk.Enabled then
            local elapsed = math.floor(os.clock() - Afk.Since)
            status = string.format(
                "%s \u{B7} %02d:%02d:%02d",
                translate("\u{110}ang b\u{1EA3}o v\u{1EC7}"),
                math.floor(elapsed / 3600),
                math.floor(elapsed / 60) % 60,
                elapsed % 60
            )
        else
            status = translate("\u{110}ang t\u{1EAF}t")
        end
        if afkStatus.Text ~= status then
            afkStatus.Text = status
        end
        local count = tostring(Afk.Blocked)
        if afkCount.Text ~= count then
            afkCount.Text = count
        end
    end

    Fwd.afkLanguage = refreshAfk
    local afkClock = 0
    table.insert(Hooks.Tasks, function(dt)
        afkClock = afkClock + dt
        if afkClock >= 0.5 then
            afkClock = 0
            if State.Open and (currentTab == "Tools" or (Multitask and Multitask.isTabActive("Tools"))) then
                refreshAfk()
            end
        end
    end)
end

