    })

    local pills = {}
    local shuffleControl
    local repeatControl

    local function pillPalette(item)
        local on = item.Kind == "accent" or (item.Kind == "toggle" and item.State())
        if on then
            return P.Accent, Static.White
        end
        return P.Field, P.Text
    end

    local function makePill(label, kind, stateFn, onClick)
        local order = #pills + 1
        local button = box({
            Class = "TextButton",
            Size = UDim2.new(0.2, -6, 1, 0),
            BackgroundColor3 = P.Field,
            AutoButtonColor = false,
            Text = translate(label),
            FontFace = Fonts.Semibold,
            TextSize = 13,
            TextColor3 = P.Text,
            LayoutOrder = order,
            Parent = pillRow,
        })
        corner(10, button)
        Glass.Pane(button, "clear")
        local item = { Button = button, Kind = kind, State = stateFn }
        pills[order] = item
        local pressScale = new("UIScale", { Parent = button })
        local pressSpring = Spring.new(1, 600, 30, function(value)
            pressScale.Scale = value
        end, 0.001)
        button.MouseEnter:Connect(function()
            local bg = pillPalette(item)
            tween(button, 0.15, { BackgroundColor3 = bg:Lerp(Static.White, 0.14) })
        end)
        button.MouseLeave:Connect(function()
            local bg = pillPalette(item)
            tween(button, 0.2, { BackgroundColor3 = bg })
            pressSpring:Set(1)
        end)
        button.MouseButton1Down:Connect(function()
            pressSpring:Set(0.94)
        end)
        button.MouseButton1Up:Connect(function()
            pressSpring:Set(1)
        end)
        button.MouseButton1Click:Connect(function()
            playSound("click")
            onClick()
        end)
        return button
    end

