    local pool = {}
    local slots = {}
    local entries = {}
    local totalH = 0
    local filterText = ""
    local lastY = -1
    local lastActive = nil
    local touchedAt = -100
    local selfUntil = 0
    local seen = false
    local shownCount = 0
    local layout

    local function makeRow()
        local frame = new("Frame", {
            Name = "TrackRow",
            Size = UDim2.new(1, -8, 0, ROW_H),
            BackgroundTransparency = 1,
            Visible = false,
            Parent = scroller,
        })
        local body = new("CanvasGroup", {
            Name = "Body",
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Parent = frame,
        })
        local bodyScale = new("UIScale", { Parent = body })
        local pressSpring = Spring.new(1, 560, 30, function(value)
            bodyScale.Scale = value
        end, 0.0005)
        local hi = box({
            Position = UDim2.fromOffset(4, 3),
            Size = UDim2.new(1, -8, 1, -6),
            BackgroundColor3 = P.Text,
            BackgroundTransparency = 1,
            Parent = body,
        })
        corner(14, hi)
        local icon = box({
            Position = UDim2.fromOffset(14, 10),
            Size = UDim2.fromOffset(38, 38),
            BackgroundColor3 = Static.White,
            Parent = body,
        })
        corner(11, icon)
        local iconGradient = new("UIGradient", { Rotation = 45, Parent = icon })
        local iconScale = new("UIScale", { Parent = icon })
        local iconSpring = Spring.new(1, 520, 15, function(value)
            iconScale.Scale = value
        end, 0.001)
        local number = text({
            Size = UDim2.fromScale(1, 1),
            Text = "",
            FontFace = Fonts.Bold,
            TextSize = 14,
            TextColor3 = Static.White,
            Parent = icon,
        })
        number:SetAttribute("BoncutiRaw", true)
        local name = text({
            Position = UDim2.fromOffset(66, 11),
            Size = UDim2.new(1, -196, 0, 18),
            Text = "",
            FontFace = Fonts.Semibold,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = body,
        })
        name:SetAttribute("BoncutiRaw", true)
        local mood = text({
            Position = UDim2.fromOffset(66, 30),
            Size = UDim2.new(1, -196, 0, 16),
            Text = "",
            FontFace = Fonts.Regular,
            TextSize = 12,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = body,
        })
        mood:SetAttribute("BoncutiRaw", true)
        local badge = text({
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -18, 0.5, 0),
            Size = UDim2.fromOffset(80, 16),
            Text = "",
            FontFace = Fonts.Medium,
            TextSize = 12,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Right,
            Parent = body,
        })
        badge:SetAttribute("BoncutiRaw", true)
        local eq = new("Frame", {
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -106, 0.5, 0),
            Size = UDim2.fromOffset(15, 14),
            BackgroundTransparency = 1,
            Visible = false,
            Parent = body,
        })
        local eqBars = {}
        for barIndex = 1, 3 do
            local eqBar = box({
                AnchorPoint = Vector2.new(0, 1),
                Position = UDim2.new(0, (barIndex - 1) * 6, 1, 0),
                Size = UDim2.fromOffset(3, 4),
                Role = "Accent",
                Parent = eq,
            })
            corner(2, eqBar)
            eqBars[barIndex] = eqBar
        end
        local hit = new("TextButton", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Text = "",
            Parent = body,
        })
        local row = {
            Frame = frame,
            Body = body,
            Hi = hi,
            Icon = icon,
            IconGradient = iconGradient,
            IconSpring = iconSpring,
            Number = number,
            Name = name,
            Mood = mood,
            Badge = badge,
            Eq = eq,
            EqBars = eqBars,
            Track = nil,
        }
        local function pressed(state)
            pressSpring:Set(state and 0.965 or 1)
            if row.Track then
                local active = row.Track == Music.Index
                tween(hi, state and 0.08 or 0.3, {
                    BackgroundTransparency = state and (active and 0.76 or 0.9) or (active and 0.86 or 1),
                })
            end
        end
        hit.MouseButton1Down:Connect(function()
            pressed(true)
        end)
        hit.MouseButton1Up:Connect(function()
            pressed(false)
        end)
        hit.MouseLeave:Connect(function()
            pressed(false)
        end)
        hit.MouseButton1Click:Connect(function()
            if not row.Track then
                return
            end
            playSound("tick")
            touchedAt = os.clock()
            row.IconSpring:Set(1.22)
            task.delay(0.14, function()
                row.IconSpring:Set(1)
            end)
            Music.Select(row.Track, true)
        end)
        return row
    end

    local function paintRow(row, animate)
        local active = row.Track == Music.Index
        local goal = active and P.Accent or P.Text
        row.Hi.BackgroundColor3 = active and P.Accent or P.Text
        if animate then
            tween(row.Name, 0.25, { TextColor3 = goal })
            tween(row.Hi, 0.32, { BackgroundTransparency = active and 0.86 or 1 })
        else
            row.Name.TextColor3 = goal
            row.Hi.BackgroundTransparency = active and 0.86 or 1
        end
        row.Badge.Text = active and translate(Music.Loading and "\u{110}ang t\u{1EA3}i" or Music.Playing and "\u{110}ang ph\u{E1}t" or "T\u{1EA1}m d\u{1EEB}ng") or ""
        row.Eq.Visible = active and Music.Playing and true or false
    end

    local function bind(row, trackIndex)
        local item = tracks[trackIndex]
        row.Track = trackIndex
        row.IconGradient.Color = ColorSequence.new(item.A, item.B)
        row.Number.Text = tostring(trackIndex)
        row.Name.Text = item.Remote and item.Name or translate(item.Name)
        row.Mood.Text = item.Remote and item.Mood or translate(item.Mood)
        paintRow(row, false)
    end

    local function enterRow(row, delay)
        row.Body.GroupTransparency = 1
        row.Body.Position = UDim2.fromOffset(0, 20)
        local token = row.Track
        task.delay(delay, function()
            if row.Track ~= token then
                return
            end
            tween(row.Body, 0.5, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
            tween(row.Body, 0.38, { GroupTransparency = 0 })
        end)
    end

    local function matches(item, query)
        if not item.Fold then
            item.Fold = fold(item.Name .. " " .. item.Mood)
        end
        for token in string.gmatch(query, "%S+") do
            if not string.find(item.Fold, token, 1, true) then
                return false
            end
        end
        return true
    end

    local function updateCount()
        local text_ = ""
        if filterText ~= "" then
            text_ = string.format(translate("%d k\u{1EBF}t qu\u{1EA3}"), shownCount)
        else
            text_ = string.format(translate("%d b\u{E0}i"), #tracks)
        end
        countLabel.Text = text_
        emptyList.Visible = shownCount == 0
        for _, head in pairs(heads) do
            head.Label.Text = translate(head.Title)
        end
    end

    local function rebuild()
        entries = {}
        local y = 0
        shownCount = 0
        local query = fold(filterText)
        if query == "" then
            for _, key in ipairs({ "builtin", "remote" }) do
                local list = {}
                for index, item in ipairs(tracks) do
                    if (item.Remote and key == "remote") or (not item.Remote and key == "builtin") then
                        list[#list + 1] = index
                    end
                end
                if #list > 0 then
                    entries[#entries + 1] = { Head = key, Y = y, H = HEAD_H }
                    y = y + HEAD_H
                    for _, index in ipairs(list) do
                        entries[#entries + 1] = { Track = index, Y = y, H = ROW_H }
                        y = y + ROW_H
                        shownCount = shownCount + 1
                    end
                end
            end
        else
            for index, item in ipairs(tracks) do
                if matches(item, query) then
                    entries[#entries + 1] = { Track = index, Y = y, H = ROW_H }
                    y = y + ROW_H
                    shownCount = shownCount + 1
                end
            end
        end
        totalH = y
        scroller.CanvasSize = UDim2.fromOffset(0, y + 8)
        updateCount()
    end

    layout = function(entering)
        local top = scroller.CanvasPosition.Y
        lastY = top
        local from, to = top - ROW_H * OVER, top + VIEW_H + ROW_H * OVER
        local want = {}
        local ordered = {}
        local headShown = {}
        for _, entry in ipairs(entries) do
            if entry.Y + entry.H >= from and entry.Y <= to then
                if entry.Track then
                    want[entry.Track] = entry
                    ordered[#ordered + 1] = entry
                else
                    local head = heads[entry.Head]
                    head.Label.Position = UDim2.fromOffset(0, entry.Y)
                    head.Label.Visible = true
                    headShown[entry.Head] = true
                end
            end
        end
        for key, head in pairs(heads) do
            if not headShown[key] and head.Label.Visible then
                head.Label.Visible = false
            end
        end
        for track, row in pairs(slots) do
            if not want[track] then
                slots[track] = nil
                row.Track = nil
                row.Frame.Visible = false
            end
        end
        local step = 0
        for _, entry in ipairs(ordered) do
            local row = slots[entry.Track]
            local fresh = false
            if not row then
                for _, candidate in ipairs(pool) do
                    if candidate.Track == nil then
                        row = candidate
                        break
                    end
                end
                if not row then
                    row = makeRow()
                    pool[#pool + 1] = row
                end
                slots[entry.Track] = row
                bind(row, entry.Track)
                row.Frame.Visible = true
                fresh = true
            end
            row.Frame.Position = UDim2.fromOffset(0, entry.Y)
            if entering then
                step = step + 1
                enterRow(row, math.min(step, 9) * 0.04)
            elseif fresh then
                row.Body.GroupTransparency = 0
                row.Body.Position = UDim2.fromOffset(0, 0)
            end
        end
    end

    local function replay()
        local step = 0
        for _, entry in ipairs(entries) do
            local row = entry.Track and slots[entry.Track]
            if row then
                step = step + 1
                enterRow(row, math.min(step, 9) * 0.04)
            end
        end
    end

    local function reveal(animated)
        local target
        for _, entry in ipairs(entries) do
            if entry.Track == Music.Index then
                target = entry.Y - (VIEW_H - ROW_H) / 2
                break
            end
        end
        if not target then
            return
        end
        target = math.clamp(target, 0, math.max(0, totalH + 8 - VIEW_H))
        selfUntil = os.clock() + 0.9
        if animated then
            tween(scroller, 0.6, { CanvasPosition = Vector2.new(0, target) }, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        else
            scroller.CanvasPosition = Vector2.new(0, target)
            layout(false)
        end
    end

    local function indexSearch()
        local done = Music.Indexed or 0
        for index = done + 1, #tracks do
            local item = tracks[index]
            Search.Add(listRow, "B\u{E0}i h\u{E1}t", item.Name, item.Mood, function()
                Music.Select(index, true)
            end)
        end
        Music.Indexed = #tracks
    end

    searchInput.Focused:Connect(function()
        tween(searchLine, 0.2, { Color = P.Accent, Transparency = 0 })
    end)
    searchInput.FocusLost:Connect(function()
        tween(searchLine, 0.2, { Color = P.Line, Transparency = 0.9 })
    end)
    searchInput:GetPropertyChangedSignal("Text"):Connect(function()
        local value = searchInput.Text
        if value == filterText then
            return
        end
        filterText = value
        local has = value ~= ""
        if has then
            clearHit.Visible = true
        end
        tween(clearHit, 0.2, { TextTransparency = has and 0 or 1 })
        if not has then
            task.delay(0.22, function()
                if searchInput.Text == "" then
                    clearHit.Visible = false
                end
            end)
        end
        touchedAt = os.clock()
        rebuild()
        scroller.CanvasPosition = Vector2.new(0, 0)
        layout(true)
    end)
    clearHit.MouseButton1Click:Connect(function()
        playSound("tick")
        searchInput.Text = ""
    end)

    rebuild()
    indexSearch()
    layout(false)

    do
        Drop.Is = false
        Drop.Page = Pg.musicScroll
        Drop.From, Drop.To = 0, 0
        local function mix(from, to, t)
            return from + (to - from) * t
        end
        local function soft(x)
            x = math.clamp(x, 0, 1)
            return x * x * (3 - 2 * x)
        end
        Drop.Spring = Spring.new(0, 150, 19, function(value)
            local amount = math.max(value, 0)
            if Drop.Is and Drop.To > Drop.From then
                Drop.Page.CanvasPosition = Vector2.new(0, Drop.From + (Drop.To - Drop.From) * math.min(amount, 1))
            end
            local over = math.max(amount - 1, 0)
            local factor = Drop.Page.AbsoluteSize.Y / (WIN_H - 64)
            if factor < 0.01 then
                factor = 1
            end
            local rowWidth = Drop.Row.AbsoluteSize.X / factor
            local fullW = (rowWidth > 80 and rowWidth or 492) - 24
            local fullH = 56 + VIEW_H
            local lift = soft(amount / 0.5)
            local wide = soft((amount - 0.16) / 0.84)
            local tall = soft((amount - 0.08) / 0.92)
            local stretch = math.sin(math.pi * math.clamp(amount / 0.5, 0, 1))
            local width = mix(32 - 5 * stretch, fullW, wide) + over * 18
            local height = mix(32 + 12 * stretch, fullH, tall) + over * 14
            local top = mix(-44, 8, lift)
            local right = mix(-14, -12, wide)
            local radius = math.min(mix(16, 24, wide), width / 2, height / 2)
            local visible = amount > 0.004
            local position = UDim2.new(1, right, 0, top)
            local size = UDim2.fromOffset(width, height)
            Drop.Glass.Position = position
            Drop.Glass.Size = size
            Drop.Blob.Position = position
            Drop.Blob.Size = size
            Drop.GlassCorner.CornerRadius = UDim.new(0, radius)
            Drop.BlobCorner.CornerRadius = UDim.new(0, radius)
            Drop.Content.Size = UDim2.fromOffset(fullW, fullH)
            Drop.Blob.GroupTransparency = 1 - soft((amount - 0.34) / 0.4)
            Drop.Glass.Visible = visible
            Drop.Blob.Visible = visible
            Drop.Row.Size = UDim2.new(1, 0, 0, visible and math.max(math.floor(top + height + 10), 0) or 0)
            Drop.Arrow.Rotation = 180 * math.min(value, 1.15)
        end, 0.001)

        function Drop.set(open)
            if Drop.Is == open then
                return
            end
            Drop.Is = open
            if open then
                Drop.From = Drop.Page.CanvasPosition.Y
                Drop.To = Drop.From
                local factor = Drop.Page.AbsoluteSize.Y / (WIN_H - 64)
                if factor > 0.01 then
                    local rowTop = (statusRow.AbsolutePosition.Y - Drop.Page.AbsolutePosition.Y) / factor + Drop.From
                    Drop.To = math.max(Drop.From, rowTop - 38)
                end
            end
            Drop.Spring:Set(open and 1 or 0)
            for _, arm in ipairs(Drop.Arms) do
                tween(arm, 0.3, { BackgroundColor3 = open and P.Accent or P.Sub })
            end
            tween(Drop.Chevron, 0.3, { BackgroundTransparency = open and 0.78 or 0.86 })
            if open then
                reveal(false)
                task.delay(0.12, function()
                    if Drop.Is then
                        replay()
                    end
                end)
            else
                searchInput:ReleaseFocus()
            end
        end

        function Drop.pressed(state)
            Drop.Press:Set(state and 0.88 or 1)
            tween(Drop.Hi, state and 0.08 or 0.35, { BackgroundTransparency = state and 0.9 or 1 })
        end
        Drop.Hit.MouseButton1Down:Connect(function()
            Drop.pressed(true)
        end)
        Drop.Hit.MouseButton1Up:Connect(function()
            Drop.pressed(false)
        end)
        Drop.Hit.MouseLeave:Connect(function()
            Drop.pressed(false)
        end)
        Drop.Hit.MouseButton1Click:Connect(function()
            playSound("tick")
            Drop.set(not Drop.Is)
        end)
        Fwd.musicDrop = function(open)
            Drop.set(open and true or false)
        end
        table.insert(paletteListeners, function()
            for _, arm in ipairs(Drop.Arms) do
                arm.BackgroundColor3 = Drop.Is and P.Accent or P.Sub
            end
        end)
    end

    local optionsCard = section(Pg.musicScroll, "Tu\u{1EF3} ch\u{1EC9}nh")
    register(Mk.createSlider(optionsCard, "\u{C2}m l\u{1B0}\u{1EE3}ng nh\u{1EA1}c", 0, 100, 60, 1, "%", function(value)
        Music.SetVolume(value)
    end), 60, "musicVolume")
    register(Mk.createSlider(optionsCard, "T\u{1ED1}c \u{111}\u{1ED9}", 0.7, 1.4, 1, 0.1, "x", function(value)
        Music.SetTempo(value)
    end), 1, "tempo")
    register(Mk.createSlider(optionsCard, "Bass", -10, 10, 1, 1, " dB", function(value)
        Music.Eq.LowGain = value
    end), 1, "bass")
    shuffleControl = register(Mk.createToggle(optionsCard, "X\u{E1}o tr\u{1ED9}n", "Ph\u{E1}t ng\u{1EAB}u nhi\u{EA}n khi chuy\u{1EC3}n b\u{E0}i", false, function(on)
        Music.Shuffle = on
        Music.Broadcast()
    end), false, "shuffle")
    repeatControl = register(Mk.createToggle(optionsCard, "L\u{1EB7}p m\u{1ED9}t b\u{E0}i", "Ph\u{E1}t l\u{1EA1}i b\u{E0}i hi\u{1EC7}n t\u{1EA1}i khi k\u{1EBF}t th\u{FA}c", false, function(on)
        Music.RepeatOne = on
        Music.Broadcast()
    end), false, "repeatOne")
    register(Mk.createToggle(optionsCard, "T\u{1EF1} chuy\u{1EC3}n b\u{E0}i", "Chuy\u{1EC3}n b\u{E0}i sau khi ph\u{E1}t xong", true, function(on)
        Music.Auto = on
    end), true, "autoNext")
    register(Mk.createToggle(optionsCard, "Hi\u{1EC7}n tr\u{EA}n \u{111}\u{1EA3}o", "Hi\u{1EC3}n th\u{1ECB} b\u{E0}i \u{111}ang ph\u{E1}t tr\u{EA}n Dynamic Island", true, function(on)
        Music.ShowIsland = on
        Music.Sync()
    end), true, "musicIsland")
    register(Mk.createToggle(optionsCard, "Kh\u{F4}ng gian", "Th\u{EA}m hi\u{1EC7}u \u{1EE9}ng vang cho nh\u{1EA1}c", true, function(on)
        Music.Reverb.Enabled = on
    end), true, "spatial")

    local function refresh()
        local current = tracks[Music.Index]
        artGradient.Color = ColorSequence.new(current.A, current.B)
        titleLabel.Text = current.Name
        moodLabel.Text = Music.Loading and translate("\u{110}ang t\u{1EA3}i b\u{E0}i h\u{E1}t\u{2026}") or current.Mood
        counterLabel.Text = string.format("%d / %d", Music.Index, #tracks)
        playButton.Text = translate(Music.Playing and "D\u{1EEB}ng" or "Ph\u{E1}t")
        for index, bar in ipairs(spectrum) do
            bar.BackgroundColor3 = current.A:Lerp(current.B, (index - 1) / (BAR_N - 1))
        end
        for _, item in ipairs(pills) do
            local bg, fg = pillPalette(item)
            tween(item.Button, 0.25, { BackgroundColor3 = bg, TextColor3 = fg })
        end
        for _, row in pairs(slots) do
            paintRow(row, true)
        end
        if lastActive ~= Music.Index then
            lastActive = Music.Index
            if os.clock() - touchedAt > 4 then
                reveal(seen)
            end
        end
    end

    table.insert(Music.Listeners, refresh)
    table.insert(paletteListeners, function()
        refresh()
    end)
    refresh()

    table.insert(Music.Remote.Listeners, function()
        rebuild()
        layout(false)
        indexSearch()
        refreshStatus()
        refresh()
    end)
    Fwd.musicLanguage = function()
        for _, row in pairs(slots) do
            bind(row, row.Track)
        end
        searchInput.PlaceholderText = translate("T\u{EC}m b\u{E0}i h\u{E1}t\u{2026}")
        reload.Text = translate("T\u{1EA3}i l\u{1EA1}i")
        updateCount()
        refreshStatus()
        refresh()
    end
    task.spawn(Music.Remote.Load)

    table.insert(Hooks.Tasks, function(dt)
        if not State.Open or (currentTab ~= "Music" and not (Multitask and Multitask.isTabActive("Music"))) then
            return
        end
        local clock = os.clock()
        if not seen then
            seen = true
            replay()
        end
        local scrollY = scroller.CanvasPosition.Y
        if scrollY ~= lastY then
            if clock > selfUntil then
                touchedAt = clock
            end
            layout(false)
        end
        local levels = Music.Levels
        local loud = 0
        if Music.Playing then
            loud = math.clamp((levels[1] + levels[2] + levels[3] + levels[4] + levels[5]) / 5 * 2.5 + 0.1, 0, 1)
        end
        for index, bar in ipairs(artBars) do
            local level = levels[(index - 1) % 5 + 1]
            local wobble = Music.Playing and 0.12 * (1 + math.sin(clock * 5 + index * 1.7)) or 0
            bar.Size = UDim2.fromOffset(7, 6 + 50 * math.clamp(level + wobble, 0, 1))
        end
        if Music.Playing then
            artGradient.Rotation = (clock * 24) % 360
        end
        local blend = math.clamp(dt * 12, 0, 1)
        for index, bar in ipairs(spectrum) do
            local waveA = 0.5 + 0.5 * math.sin(clock * (2.1 + index * 0.31) + index * 0.9)
            local waveB = 0.5 + 0.5 * math.sin(clock * (1.3 + index * 0.17) - index * 1.7)
            local target = 0.05
            if Music.Playing then
                target = 0.1 + 0.9 * (waveA * 0.55 + waveB * 0.45) * loud
            end
            specValues[index] = specValues[index] + (target - specValues[index]) * blend
            bar.Size = UDim2.new(1 / BAR_N, -3, math.clamp(specValues[index], 0.05, 1), 0)
        end
        local progress = Music.Progress()
        railFill.Size = UDim2.fromScale(progress, 1)
        railKnob.Position = UDim2.fromScale(progress, 0.5)
        local duration = Music.Duration()
        elapsedLabel.Text = fmt(math.max(0, Music.Position))
        durationLabel.Text = duration > 0 and fmt(duration) or "0:00"
        local active = slots[Music.Index]
        if active and Music.Playing then
            for index, bar in ipairs(active.EqBars) do
                local level = levels[index]
                local wobble = 0.25 * (0.5 + 0.5 * math.sin(clock * 6 + index * 2))
                bar.Size = UDim2.fromOffset(3, 3 + 11 * math.clamp(level * 1.6 + wobble, 0, 1))
            end
        end
    end)
end

do
    local BAR_W = 300
    local PANEL_W = 300
    local ROW_H = 46
    local GAP = 4
    local FOOTER_H = 28
    local MAX_RESULTS = 6

    local FOLD = {}
    for base, chars in pairs({
        a = "\u{E0}\u{E1}\u{1EA1}\u{1EA3}\u{E3}\u{E2}\u{1EA7}\u{1EA5}\u{1EAD}\u{1EA9}\u{1EAB}\u{103}\u{1EB1}\u{1EAF}\u{1EB7}\u{1EB3}\u{1EB5}\u{C0}\u{C1}\u{1EA0}\u{1EA2}\u{C3}\u{C2}\u{1EA6}\u{1EA4}\u{1EAC}\u{1EA8}\u{1EAA}\u{102}\u{1EB0}\u{1EAE}\u{1EB6}\u{1EB2}\u{1EB4}",
        e = "\u{E8}\u{E9}\u{1EB9}\u{1EBB}\u{1EBD}\u{EA}\u{1EC1}\u{1EBF}\u{1EC7}\u{1EC3}\u{1EC5}\u{C8}\u{C9}\u{1EB8}\u{1EBA}\u{1EBC}\u{CA}\u{1EC0}\u{1EBE}\u{1EC6}\u{1EC2}\u{1EC4}",
        i = "\u{EC}\u{ED}\u{1ECB}\u{1EC9}\u{129}\u{CC}\u{CD}\u{1ECA}\u{1EC8}\u{128}",
        o = "\u{F2}\u{F3}\u{1ECD}\u{1ECF}\u{F5}\u{F4}\u{1ED3}\u{1ED1}\u{1ED9}\u{1ED5}\u{1ED7}\u{1A1}\u{1EDD}\u{1EDB}\u{1EE3}\u{1EDF}\u{1EE1}\u{D2}\u{D3}\u{1ECC}\u{1ECE}\u{D5}\u{D4}\u{1ED2}\u{1ED0}\u{1ED8}\u{1ED4}\u{1ED6}\u{1A0}\u{1EDC}\u{1EDA}\u{1EE2}\u{1EDE}\u{1EE0}",
        u = "\u{F9}\u{FA}\u{1EE5}\u{1EE7}\u{169}\u{1B0}\u{1EEB}\u{1EE9}\u{1EF1}\u{1EED}\u{1EEF}\u{D9}\u{DA}\u{1EE4}\u{1EE6}\u{168}\u{1AF}\u{1EEA}\u{1EE8}\u{1EF0}\u{1EEC}\u{1EEE}",
        y = "\u{1EF3}\u{FD}\u{1EF5}\u{1EF7}\u{1EF9}\u{1EF2}\u{DD}\u{1EF4}\u{1EF6}\u{1EF8}",
        d = "\u{111}\u{110}",
    }) do
        for _, code in utf8.codes(chars) do
            FOLD[utf8.char(code)] = base
        end
    end

    local function fold(value)
        local ok, result = pcall(function()
            local out = {}
            for _, code in utf8.codes(value) do
                if code < 0x300 or code > 0x36F then
                    local char = utf8.char(code)
                    out[#out + 1] = FOLD[char] or string.lower(char)
                end
            end
            return table.concat(out)
        end)
        if ok then
            return result
        end
        return string.lower(value)
    end

    local function english(value)
        if not value then
            return ""
        end
        return VI_EN[value] or Extra.En[value] or value
    end

    local tabOrder = { "LoopDash", "AutoBlock", "ChangeVFX" }

    local function tabOf(entry)
        if entry.Tab then
            return entry.Tab
        end
        local scroller = entry.Row and entry.Row:FindFirstAncestorOfClass("ScrollingFrame")
        for name, tab in pairs(tabs) do
            if tab.scroll == scroller then
                entry.Tab = name
                return name
            end
        end
        return nil
    end

    local function candidates()
        local list = {}
        for _, name in ipairs(tabOrder) do
            local tab = tabs[name]
            if tab and (name ~= "Test" or testTabVisible) then
                table.insert(list, { Type = "tab", Tab = name, Title = tab.labelKey, Kind = "M\u{1EDF} tab", Order = 0 })
            end
        end
        for _, entry in ipairs(Search.Index) do
            local name = tabOf(entry)
            if name and (name ~= "Test" or testTabVisible) and entry.Row.Parent then
                table.insert(list, {
                    Type = "control",
                    Tab = name,
                    Row = entry.Row,
                    Title = entry.Title,
                    Desc = entry.Desc,
                    Kind = entry.Kind,
                    Action = entry.Action,
                    Order = entry.Order,
                })
            end
        end
        return list
    end

    local function scoreOf(item, tokens)
        local tab = tabs[item.Tab]
        local title = fold(translate(item.Title)) .. " " .. fold(english(item.Title))
        local rest = fold(translate(item.Desc or "")) .. " " .. fold(english(item.Desc))
            .. " " .. fold(translate(item.Kind)) .. " " .. fold(english(item.Kind))
            .. " " .. fold(translate(tab.labelKey)) .. " " .. fold(english(tab.labelKey))
        local total = 0
        for _, token in ipairs(tokens) do
            local at = string.find(title, token, 1, true)
            local points
            if at then
                if at == 1 then
                    points = 30
                elseif string.sub(title, at - 1, at - 1) == " " then
                    points = 24
                else
                    points = 16
                end
            elseif string.find(rest, token, 1, true) then
                points = 6
            else
                return 0
            end
            total = total + points
        end
        return total
    end

    local function collect(query)
        local tokens = {}
        for token in string.gmatch(fold(query), "%S+") do
            table.insert(tokens, token)
        end
        local list = candidates()
        if #tokens == 0 then
            local only = {}
            for _, item in ipairs(list) do
                if item.Type == "tab" then
                    table.insert(only, item)
                end
            end
            return only
        end
        local scored = {}
        for _, item in ipairs(list) do
            local value = scoreOf(item, tokens)
            if value > 0 then
                item.Score = value
                table.insert(scored, item)
            end
        end
        table.sort(scored, function(a, b)
            if a.Score ~= b.Score then
                return a.Score > b.Score
            end
            return a.Order < b.Order
        end)
        return scored
    end

    local bar = box({
        Name = "SearchBar",
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -14, 0.5, 0),
        Size = UDim2.fromOffset(30, 30),
        BackgroundTransparency = 0.9,
        ClipsDescendants = true,
        ZIndex = 6,
        Role = "Line",
        Parent = titlebar,
    })
    corner(15, bar)
    stroke(bar, "Line", 0.86, 1)

    local glyph = new("Frame", {
        Size = UDim2.fromOffset(30, 30),
        BackgroundTransparency = 1,
        Parent = bar,
    })
    local lens = new("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromOffset(14, 14),
        Size = UDim2.fromOffset(11, 11),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Parent = glyph,
    })
    new("UICorner", { CornerRadius = UDim.new(1, 0), Parent = lens })
    stroke(lens, "Text", 0.1, 2)
    local handle = box({
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromOffset(20.5, 20.5),
        Size = UDim2.fromOffset(2.5, 7),
        Rotation = -45,
        Role = "Text",
        Parent = glyph,
    })
    corner(2, handle)
    local hit = new("TextButton", {
        Size = UDim2.fromOffset(30, 30),
        BackgroundTransparency = 1,
        Text = "",
        ZIndex = 4,
        Parent = bar,
    })

    local field = new("TextBox", {
        Position = UDim2.fromOffset(34, 0),
        Size = UDim2.new(1, -66, 1, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClearTextOnFocus = false,
        Text = "",
        PlaceholderText = translate("T\u{EC}m ch\u{1EE9}c n\u{103}ng\u{2026}"),
        FontFace = Fonts.Medium,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        Visible = false,
        ZIndex = 3,
        Parent = bar,
    })
    paint(field, "TextColor3", "Text")
    paint(field, "PlaceholderColor3", "Sub")

    local clearButton = new("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -4, 0.5, 0),
        Size = UDim2.fromOffset(22, 22),
        BackgroundTransparency = 1,
        Text = "\u{D7}",
        FontFace = Fonts.Bold,
        TextSize = 17,
        Visible = false,
        ZIndex = 4,
        Parent = bar,
    })
    paint(clearButton, "TextColor3", "Sub")

    local springBar = Spring.new(30, 300, 26, function(value)
        bar.Size = UDim2.fromOffset(value, 30)
    end, 0.05)

    local dim = new("TextButton", {
        Name = "SearchDim",
        Position = UDim2.fromOffset(0, 44),
        Size = UDim2.new(1, 0, 1, -44),
        BackgroundColor3 = Static.Black,
        BackgroundTransparency = 1,
        Text = "",
        AutoButtonColor = false,
        Visible = false,
        ZIndex = 15,
        Parent = window,
    })

    local panel = box({
        Class = "CanvasGroup",
        Name = "SearchPanel",
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.new(1, -14, 0, 50),
        Size = UDim2.fromOffset(PANEL_W, 54),
        GroupTransparency = 1,
        BackgroundTransparency = 0.04,
        Active = true,
        Visible = false,
        ZIndex = 20,
        Role = "Card",
        Parent = window,
    })
    corner(18, panel)
    stroke(panel, "Line", 0.86, 1)
    local panelScale = new("UIScale", { Scale = 0.94, Parent = panel })
    local springPanel = Spring.new(0.94, 320, 26, function(value)
        panelScale.Scale = value
    end, 0.0005)
    Glass.Band(panel, 70)
    Glass.Rim(panel, 18)

    local list = new("Frame", {
        Name = "Results",
        Size = UDim2.new(1, 0, 1, -FOOTER_H),
        BackgroundTransparency = 1,
        Parent = panel,
    })
    new("UIPadding", {
        PaddingTop = UDim.new(0, 8),
        PaddingLeft = UDim.new(0, 8),
        PaddingRight = UDim.new(0, 8),
        Parent = list,
    })
    new("UIListLayout", {
        Padding = UDim.new(0, GAP),
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = list,
    })

    local empty = new("Frame", {
        Name = "Empty",
        Size = UDim2.new(1, 0, 0, 62),
        BackgroundTransparency = 1,
        LayoutOrder = 100,
        Visible = false,
        Parent = list,
    })
    text({
        Position = UDim2.fromOffset(0, 8),
        Size = UDim2.new(1, 0, 0, 22),
        Text = "Kh\u{F4}ng t\u{EC}m th\u{1EA5}y ch\u{1EE9}c n\u{103}ng",
        FontFace = Fonts.Semibold,
        TextSize = 14,
        Parent = empty,
    })
    text({
        Position = UDim2.fromOffset(0, 32),
        Size = UDim2.new(1, 0, 0, 18),
        Text = "Th\u{1EED} m\u{1ED9}t t\u{1EEB} kho\u{E1} kh\u{E1}c",
        FontFace = Fonts.Regular,
        TextSize = 12,
        Role = "Sub",
        Parent = empty,
    })

    text({
        AnchorPoint = Vector2.new(0, 1),
        Position = UDim2.new(0, 0, 1, -2),
        Size = UDim2.new(1, 0, 0, FOOTER_H - 6),
        Text = "Enter \u{111}\u{1EC3} m\u{1EDF}  \u{B7}  Esc \u{111}\u{1EC3} \u{111}\u{F3}ng",
        FontFace = Fonts.Regular,
        TextSize = 11,
        Role = "Sub",
        Parent = panel,
    })

    local current = {}
    local selected = 1
    local rows = {}
    local setSelected
    local pick

    for index = 1, MAX_RESULTS do
        local frame = box({
            Class = "CanvasGroup",
            Name = "Result",
            Size = UDim2.new(1, 0, 0, ROW_H),
            BackgroundTransparency = 1,
            GroupTransparency = 1,
            LayoutOrder = index,
            Visible = false,
            Role = "Accent",
            Parent = list,
        })
        corner(12, frame)
        local icon = box({
            Position = UDim2.fromOffset(9, 9),
            Size = UDim2.fromOffset(28, 28),
            BackgroundColor3 = Static.Blue,
            Parent = frame,
        })
        corner(9, icon)
        local iconGlyph = text({
            Size = UDim2.fromScale(1, 1),
            Text = "",
            FontFace = Fonts.Bold,
            TextSize = 14,
            TextColor3 = Static.White,
            Parent = icon,
        })
        local title = text({
            Position = UDim2.fromOffset(48, 6),
            Size = UDim2.new(1, -132, 0, 18),
            Text = "",
            FontFace = Fonts.Semibold,
            TextSize = 13,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = frame,
        })
        local sub = text({
            Position = UDim2.fromOffset(48, 24),
            Size = UDim2.new(1, -132, 0, 16),
            Text = "",
            FontFace = Fonts.Regular,
            TextSize = 11,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = frame,
        })
        local kind = text({
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, -12, 0.5, 0),
            Size = UDim2.fromOffset(78, 16),
            Text = "",
            FontFace = Fonts.Medium,
            TextSize = 11,
            Role = "Sub",
            TextXAlignment = Enum.TextXAlignment.Right,
            TextTruncate = Enum.TextTruncate.AtEnd,
            Parent = frame,
        })
        local rowHit = new("TextButton", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            Text = "",
            ZIndex = 5,
            Parent = frame,
        })
        rows[index] = { Frame = frame, Icon = icon, Glyph = iconGlyph, Title = title, Sub = sub, Kind = kind }
        rowHit.MouseEnter:Connect(function()
            setSelected(index)
        end)
        rowHit.MouseButton1Click:Connect(function()
            pick(current[index])
        end)
    end

    setSelected = function(index)
        selected = index
        local count = math.min(#current, MAX_RESULTS)
        for i, row in ipairs(rows) do
            tween(row.Frame, 0.15, { BackgroundTransparency = (i == selected and i <= count) and 0.84 or 1 })
        end
    end

    local function render()
        current = collect(field.Text)
        local count = math.min(#current, MAX_RESULTS)
        for index = 1, MAX_RESULTS do
            local row = rows[index]
            local item = current[index]
            if item and index <= count then
                local tab = tabs[item.Tab]
                row.Icon.BackgroundColor3 = tab.color
                row.Glyph.Text = tab.glyph
                row.Title.Text = translate(item.Title)
                if item.Type == "tab" then
                    row.Sub.Text = translate("M\u{1EDF} tab")
                    row.Kind.Text = ""
                else
                    local detail = translate(tab.labelKey)
                    if item.Desc then
                        detail = detail .. "  \u{B7}  " .. translate(item.Desc)
                    end
                    row.Sub.Text = detail
                    row.Kind.Text = translate(item.Kind)
                end
                if not row.Frame.Visible then
                    row.Frame.GroupTransparency = 1
                    row.Frame.Visible = true
                    task.delay((index - 1) * 0.035, function()
                        if row.Frame.Visible then
                            tween(row.Frame, 0.28, { GroupTransparency = 0 })
                        end
                    end)
                end
            else
                row.Frame.Visible = false
                row.Frame.GroupTransparency = 1
            end
        end
        empty.Visible = count == 0
        local height
        if count == 0 then
            height = 8 + 62 + 6 + FOOTER_H
        else
            height = 8 + count * ROW_H + (count - 1) * GAP + 6 + FOOTER_H
        end
        tween(panel, 0.32, { Size = UDim2.fromOffset(PANEL_W, height) }, Enum.EasingStyle.Quint)
        setSelected(1)
    end

    local function setOpen(open)
        if Search.Open == open then
            return
        end
        Search.Open = open
        if open then
            springBar:Set(BAR_W)
            tween(bar, 0.25, { BackgroundTransparency = 0.82 })
            field.Visible = true
            field.TextTransparency = 1
            tween(field, 0.35, { TextTransparency = 0 })
            dim.Visible = true
            panel.Visible = true
            panel.GroupTransparency = 1
            panel.Size = UDim2.fromOffset(PANEL_W, 54)
            springPanel:Snap(0.94)
            springPanel:Set(1)
            tween(dim, 0.35, { BackgroundTransparency = 0.6 })
            tween(panel, 0.3, { GroupTransparency = 0 })
            render()
            playSound("tick")
            task.delay(0.14, function()
                if Search.Open then
                    field:CaptureFocus()
                end
            end)
        else
            field:ReleaseFocus()
            springBar:Set(30)
            tween(bar, 0.25, { BackgroundTransparency = 0.9 })
            tween(field, 0.15, { TextTransparency = 1 })
            tween(dim, 0.25, { BackgroundTransparency = 1 })
            tween(panel, 0.2, { GroupTransparency = 1 })
            springPanel:Set(0.96)
            task.delay(0.32, function()
                if not Search.Open then
                    field.Visible = false
                    dim.Visible = false
                    panel.Visible = false
                    field.Text = ""
                    for _, row in ipairs(rows) do
                        row.Frame.Visible = false
                        row.Frame.GroupTransparency = 1
                    end
                end
            end)
        end
    end

    local function reveal(row)
        task.wait(0.18)
        if not row.Parent then
            return
        end
        local scroller = row:FindFirstAncestorOfClass("ScrollingFrame")
        if scroller then
            local factor = row.AbsoluteSize.Y / math.max(row.Size.Y.Offset, 1)
            if factor <= 0 then
                factor = 1
            end
            local offset = (row.AbsolutePosition.Y - scroller.AbsolutePosition.Y) / factor
            local limit = math.max(0, (scroller.AbsoluteCanvasSize.Y - scroller.AbsoluteSize.Y) / factor)
            local target = math.clamp(offset + scroller.CanvasPosition.Y - 52, 0, limit)
            tween(scroller, 0.5, { CanvasPosition = Vector2.new(0, target) })
        end
        local glow = row:FindFirstChild("SearchGlow")
        if not glow then
            glow = box({
                Name = "SearchGlow",
                Position = UDim2.fromOffset(6, 3),
                Size = UDim2.new(1, -12, 1, -6),
                BackgroundTransparency = 1,
                ZIndex = 0,
                Role = "Accent",
                Parent = row,
            })
            corner(10, glow)
        end
        for _ = 1, 2 do
            tween(glow, 0.25, { BackgroundTransparency = 0.72 })
            task.wait(0.3)
            tween(glow, 0.5, { BackgroundTransparency = 1 })
            task.wait(0.55)
        end
    end

    pick = function(item)
        if not item then
            return
        end
        setOpen(false)
        playSound("click")
        if item.Tab == "Test" and not testTabVisible then
            return
        end
        selectTab(item.Tab)
        if item.Row then
            task.spawn(reveal, item.Row)
        end
        if item.Action then
            item.Action()
        end
    end

    local function move(step)
        local count = math.min(#current, MAX_RESULTS)
        if count == 0 then
            return
        end
        setSelected((selected - 1 + step) % count + 1)
        playSound("tick")
    end

    function Search.SetOpen(open)
        setOpen(open)
    end

    function Search.Hits(position)
        if not Search.Open then
            return false
        end
        local left = bar.AbsolutePosition.X
        return position.X >= left - 4 and position.X <= left + bar.AbsoluteSize.X + 4
    end

    hit.MouseButton1Click:Connect(function()
        setOpen(not Search.Open)
    end)
    hit.MouseEnter:Connect(function()
        if not Search.Open then
            tween(bar, 0.15, { BackgroundTransparency = 0.82 })
        end
    end)
    hit.MouseLeave:Connect(function()
        if not Search.Open then
            tween(bar, 0.2, { BackgroundTransparency = 0.9 })
        end
    end)
    clearButton.MouseButton1Click:Connect(function()
        field.Text = ""
        field:CaptureFocus()
    end)
    dim.MouseButton1Click:Connect(function()
        setOpen(false)
    end)
    field:GetPropertyChangedSignal("Text"):Connect(function()
        clearButton.Visible = field.Text ~= ""
        if Search.Open then
            render()
        end
    end)
    field.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            pick(current[selected])
        end
    end)

    track(UserInputService.InputBegan:Connect(function(input)
        if not Search.Open then
            return
        end
        if input.KeyCode == Enum.KeyCode.Escape then
            setOpen(false)
        elseif input.KeyCode == Enum.KeyCode.Down then
            move(1)
        elseif input.KeyCode == Enum.KeyCode.Up then
            move(-1)
        end
    end))

    table.insert(Hooks.Tasks, function()
        if Search.Open and not State.Open then
            setOpen(false)
        end
    end)
end

Ux.refreshKeyHints()
selectTab("LoopDash", true)

local metricsList = {}
for i = 1, BAR_COUNT do
    metricsList[i] = 0
end

task.spawn(function()
    while gui.Parent do
        if State.Open then
            local fps = math.floor(Metrics.Fps + 0.5)
            Ux.fpsValue.Text = tostring(fps)
            local ok, ping = pcall(function()
                return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
            end)
            Ux.pingValue.Text = ok and string.format("%d ms", math.floor(ping + 0.5)) or "\u{2014}"
            Ux.playersValue.Text = tostring(#Players:GetPlayers())
            Ux.timeLabel.Text = os.date("%H:%M")
            table.remove(metricsList, 1)
            table.insert(metricsList, fps)
            for i, bar in ipairs(Ux.graphBars) do
                local height = math.clamp(metricsList[i] / 120, 0.04, 1)
                tween(bar, 0.45, { Size = UDim2.new(1 / BAR_COUNT, -3, height, 0) })
            end
        end
        task.wait(0.5)
    end
end)

track(UserInputService.InputBegan:Connect(function(input, processed)
    if Ux.Capture.Active and input.UserInputType == Enum.UserInputType.Keyboard then
        local finish = Ux.Capture.Active
        if input.KeyCode == Enum.KeyCode.Escape then
            finish(nil)
        else
            finish(input.KeyCode)
        end
        return
    end
    if processed or not State.Ready or Ux.Dialog.Open then
        return
    end
    if input.KeyCode == Settings.ToggleKey then
        Fwd.setWindow(not State.Open)
    end
end))

do
    local Http = game:GetService("HttpService")
    local FOLDER = "boncuti"
    local ACCOUNTS = FOLDER .. "/accounts.json"
    local SESSIONS = FOLDER .. "/sessions.json"
    local ROUNDS = 2400
    local MAX_FAILS = 5
    local LOCK_SECONDS = 30
    local uid = tostring(player.UserId)

    local Memory = {}
    local okEnv, genv = pcall(function()
        return getgenv()
    end)
    if okEnv and type(genv) == "table" then
        genv.BoncutiStore = genv.BoncutiStore or {}
        Memory = genv.BoncutiStore
    end

    local Files = type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
    Auth.Persistent = Files
    if Files then
        pcall(function()
            if type(isfolder) == "function" and isfolder(FOLDER) then
                return
            end
            makefolder(FOLDER)
        end)
    end

    local function readRaw(path)
        if Auth.Persistent then
            local ok, content = pcall(function()
                if isfile(path) then
                    return readfile(path)
                end
                return nil
            end)
            if ok and type(content) == "string" and content ~= "" then
                return content
            end
            return nil
        end
        return Memory[path]
    end

    local function writeRaw(path, content)
        if Auth.Persistent then
            local ok = pcall(writefile, path, content)
            if ok then
                return
            end
            Auth.Persistent = false
        end
        Memory[path] = content
    end

    local function decode(raw)
        if type(raw) ~= "string" or raw == "" then
            return nil
        end
        local ok, data = pcall(function()
            return Http:JSONDecode(raw)
        end)
        if ok and type(data) == "table" then
            return data
        end
        return nil
    end

    local function encode(data)
        local ok, raw = pcall(function()
            return Http:JSONEncode(data)
        end)
        if ok then
            return raw
        end
        return nil
    end

    local K = {
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    }
    local MOD = 4294967296
    local band, bxor, bnot = bit32.band, bit32.bxor, bit32.bnot
    local rrotate, rshift = bit32.rrotate, bit32.rshift

    local function wordBytes(value)
        return string.char(
            math.floor(value / 16777216) % 256,
            math.floor(value / 65536) % 256,
            math.floor(value / 256) % 256,
            value % 256
        )
    end

    local function sha256(message)
        local length = #message
        local padded = message .. "\128" .. string.rep("\0", (55 - length) % 64)
            .. wordBytes(math.floor(length * 8 / MOD)) .. wordBytes(length * 8 % MOD)
        local h0, h1, h2, h3 = 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a
        local h4, h5, h6, h7 = 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
        local w = {}
        for chunk = 1, #padded, 64 do
            for i = 0, 15 do
                local b1, b2, b3, b4 = string.byte(padded, chunk + i * 4, chunk + i * 4 + 3)
                w[i] = b1 * 16777216 + b2 * 65536 + b3 * 256 + b4
            end
            for i = 16, 63 do
                local x, y = w[i - 15], w[i - 2]
                local s0 = bxor(rrotate(x, 7), rrotate(x, 18), rshift(x, 3))
                local s1 = bxor(rrotate(y, 17), rrotate(y, 19), rshift(y, 10))
                w[i] = (w[i - 16] + s0 + w[i - 7] + s1) % MOD
            end
            local a, b, c, d, e, f, g, h = h0, h1, h2, h3, h4, h5, h6, h7
            for i = 0, 63 do
                local big1 = bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
                local choose = bxor(band(e, f), band(bnot(e), g))
                local temp1 = (h + big1 + choose + K[i + 1] + w[i]) % MOD
                local big0 = bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
                local majority = bxor(band(a, b), band(a, c), band(b, c))
                local temp2 = (big0 + majority) % MOD
                h, g, f, e, d, c, b, a = g, f, e, (d + temp1) % MOD, c, b, a, (temp1 + temp2) % MOD
            end
            h0 = (h0 + a) % MOD
            h1 = (h1 + b) % MOD
            h2 = (h2 + c) % MOD
            h3 = (h3 + d) % MOD
            h4 = (h4 + e) % MOD
            h5 = (h5 + f) % MOD
            h6 = (h6 + g) % MOD
            h7 = (h7 + h) % MOD
        end
        return wordBytes(h0) .. wordBytes(h1) .. wordBytes(h2) .. wordBytes(h3)
            .. wordBytes(h4) .. wordBytes(h5) .. wordBytes(h6) .. wordBytes(h7)
    end

    local function toHex(raw)
        return (string.gsub(raw, ".", function(char)
            return string.format("%02x", string.byte(char))
        end))
    end

    local Accounts = decode(readRaw(ACCOUNTS)) or {}
    if type(Accounts.Users) ~= "table" then
        Accounts.Users = {}
    end
    local Sessions = decode(readRaw(SESSIONS)) or {}
    Auth.Last = type(Accounts.Last) == "string" and Accounts.Last or nil

    local function saveAccounts()
        local raw = encode(Accounts)
        if raw then
            writeRaw(ACCOUNTS, raw)
        end
    end

    local function saveSessions()
        local raw = encode(Sessions)
        if raw then
            writeRaw(SESSIONS, raw)
        end
    end

    local function settingsPath(key)
        return FOLDER .. "/settings_" .. key .. ".json"
    end

    local function newSalt()
        local ok, guid = pcall(function()
            return Http:GenerateGUID(false)
        end)
        local seed = ok and guid or (tostring(os.clock()) .. tostring(math.random()) .. tostring(os.time()))
        local salt = string.sub((string.gsub(seed, "[^%w]", "")), 1, 16)
        while #salt < 16 do
            salt = salt .. string.format("%x", math.random(0, 15))
        end
        return salt
    end

    local function derive(password, salt, rounds)
        local digest = sha256(salt .. "|" .. password)
        for round = 1, rounds do
            digest = sha256(digest .. salt)
            if round % 300 == 0 then
                task.wait()
            end
        end
        return toHex(digest)
    end

    local failures, lockedUntil = 0, 0

    function Auth.checkName(name)
        if name == "" then
            return "Nh\u{1EAD}p t\u{EA}n t\u{E0}i kho\u{1EA3}n"
        end
        if #name < 3 or #name > 20 then
            return "T\u{EA}n t\u{E0}i kho\u{1EA3}n c\u{1EA7}n t\u{1EEB} 3 \u{111}\u{1EBF}n 20 k\u{FD} t\u{1EF1}"
        end
        if string.find(name, "[^%w_]") then
            return "Ch\u{1EC9} d\u{F9}ng ch\u{1EEF}, s\u{1ED1} v\u{E0} d\u{1EA5}u g\u{1EA1}ch d\u{1B0}\u{1EDB}i"
        end
        return nil
    end

    function Auth.checkPassword(password)
        if password == "" then
            return "Nh\u{1EAD}p m\u{1EAD}t kh\u{1EA9}u"
        end
        if #password < 6 then
            return "M\u{1EAD}t kh\u{1EA9}u c\u{1EA7}n t\u{1EEB} 6 k\u{FD} t\u{1EF1}"
        end
        return nil
    end

    function Auth.control(key)
        for _, control in ipairs(controls) do
            if control.Key == key then
                return control
            end
        end
        return nil
    end

    function Auth.pack(control)
        local value = control.Get()
        if typeof(value) == "EnumItem" then
            return value.Name
        end
        return value
    end

    function Auth.unpack(control, saved)
        if control.Key == "islandRim" then
            return nil
        end
        if typeof(control.Default) == "EnumItem" then
            if type(saved) ~= "string" then
                return nil
            end
            local ok, item = pcall(function()
                return Enum.KeyCode[saved]
            end)
            if ok and item then
                return item
            end
            return nil
        end
        if type(saved) == type(control.Default) then
            return saved
        end
        return nil
    end

    function Auth.signature()
        local parts = {}
        for _, control in ipairs(controls) do
            if control.Key then
                table.insert(parts, control.Key .. "=" .. tostring(Auth.pack(control)))
            end
        end
        return table.concat(parts, ";")
    end

    local function same(a, b)
        if type(a) == "number" and type(b) == "number" then
            return math.abs(a - b) < 0.000001
        end
        return a == b
    end

    function Auth.restore(values, keepLanguage)
        for _, control in ipairs(controls) do
            local key = control.Key
            if key and not (keepLanguage and key == "language") then
                local target = control.Default
                if type(values) == "table" and values[key] ~= nil then
                    local decoded = Auth.unpack(control, values[key])
                    if decoded ~= nil then
                        target = decoded
                    end
                end
                if not same(control.Get(), target) then
                    pcall(control.Set, target)
                end
            end
        end
    end

    function Auth.save()
        if not Auth.Session or not Auth.Applied then
            return
        end
        local values = {}
        for _, control in ipairs(controls) do
            if control.Key then
                values[control.Key] = Auth.pack(control)
            end
        end
        local raw = encode({ Version = 1, Saved = os.time(), Values = values })
        if raw then
            writeRaw(settingsPath(Auth.Name), raw)
        end
        Auth.Sig = Auth.signature()
    end

    function Auth.remaining()
        if not Auth.Session then
            return 0
        end
        return math.max(0, Auth.Session.Expires - os.time())
    end

    function Auth.timeText(seconds)
        local days = math.floor(seconds / 86400)
        local hours = math.floor(seconds % 86400 / 3600)
        local minutes = math.floor(seconds % 3600 / 60)
        if days > 0 then
            return string.format(translate("%d ng\u{E0}y %d gi\u{1EDD}"), days, hours)
        end
        if hours > 0 then
            return string.format(translate("%d gi\u{1EDD} %d ph\u{FA}t"), hours, minutes)
        end
        return string.format(translate("%d ph\u{FA}t"), math.max(minutes, 1))
    end

    function Auth.begin(key, record, fresh)
        local account = Accounts.Users[key]
        Auth.Session = record
        Auth.Name = key
        Auth.Display = account.Name
        local data = decode(readRaw(settingsPath(key)))
        Auth.restore(data and data.Values, false)
        Auth.Sig = Auth.signature()
        Auth.Applied = true
        Accounts.Last = account.Name
        Auth.Last = account.Name
        saveAccounts()
        if Auth.Ui.refresh then
            Auth.Ui.refresh()
        end
        if Fwd.discordEvent then
            pcall(Fwd.discordEvent, fresh and "login" or "resume", account.Name, record.Expires)
        end
    end

    function Auth.open(key)
        local now = os.time()
        local record = { Account = key, At = now, Expires = now + Auth.Lifetime }
        Sessions[uid] = record
        saveSessions()
        Auth.begin(key, record, true)
    end

    function Auth.resume()
        local record = Sessions[uid]
        if type(record) ~= "table" then
            return false
        end
        local now = os.time()
        local valid = type(record.Account) == "string"
            and Accounts.Users[record.Account] ~= nil
            and type(record.At) == "number"
            and type(record.Expires) == "number"
            and now < record.Expires
            and now >= record.At - 300
        if not valid then
            Sessions[uid] = nil
            saveSessions()
            return false
        end
        Auth.begin(record.Account, record)
        return true
    end

    function Auth.login(name, password)
        local waiting = math.ceil(lockedUntil - os.clock())
        if waiting > 0 then
            return false, "Th\u{1EED} l\u{1EA1}i sau %d gi\u{E2}y", waiting
        end
        local key = string.lower(name)
        local account = Accounts.Users[key]
        local hash = derive(password, account and account.Salt or newSalt(), account and account.Rounds or ROUNDS)
        if not account or hash ~= account.Hash then
            failures = failures + 1
            if failures >= MAX_FAILS then
                failures = 0
                lockedUntil = os.clock() + LOCK_SECONDS
            end
            return false, "Sai t\u{EA}n t\u{E0}i kho\u{1EA3}n ho\u{1EB7}c m\u{1EAD}t kh\u{1EA9}u"
        end
        failures = 0
        Auth.open(key)
        return true
    end

    function Auth.create(name, password)
        local key = string.lower(name)
        if Accounts.Users[key] then
            return false, "T\u{EA}n t\u{E0}i kho\u{1EA3}n \u{111}\u{E3} t\u{1ED3}n t\u{1EA1}i"
        end
        local salt = newSalt()
        local hash = derive(password, salt, ROUNDS)
        if Accounts.Users[key] then
            return false, "T\u{EA}n t\u{E0}i kho\u{1EA3}n \u{111}\u{E3} t\u{1ED3}n t\u{1EA1}i"
        end
        Accounts.Users[key] = { Name = name, Salt = salt, Hash = hash, Rounds = ROUNDS, Created = os.time() }
        saveAccounts()
        Auth.open(key)
        return true
    end

    function Auth.lock(message)
        if not Auth.Session then
            return
        end
        Auth.save()
        if Fwd.discordEvent then
            pcall(Fwd.discordEvent, message == "Phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p \u{111}\u{E3} h\u{1EBF}t h\u{1EA1}n" and "expired" or "logout", Auth.Display)
        end
        if Cross.shutdownPlay then
            Cross.shutdownPlay("logout")
        end
        Auth.Applied = false
        Sessions[uid] = nil
        saveSessions()
        Auth.Session = nil
        Auth.Name = nil
        Auth.Display = nil
        State.Ready = false
        Fwd.setWindow(false)
        if Music.Playing then
            Music.Toggle()
        end
        Activities.Timer = nil
        Activities.Download = nil
        refreshActivity()
        Auth.restore(nil, true)
        Island.Pin = nil
        if Isl.collapse then
            Isl.collapse(true, true)
        end
        task.spawn(function()
            if Auth.Ui.prompt(message) then
                State.Ready = true
                Fwd.setWindow(true)
                notify(translate("\u{110}\u{E3} \u{111}\u{103}ng nh\u{1EAD}p"), Auth.Display or "", "success", 2.4, true)
                task.delay(2.6, function()
                    if Fwd.crossPowered then
                        Fwd.crossPowered(Auth.Display)
                    end
                end)
            end
        end)
    end

    local lastLanguage = Settings.Language

    task.spawn(function()
        while gui.Parent do
            task.wait(1)
            if Settings.Language ~= lastLanguage then
                lastLanguage = Settings.Language
                Accounts.Lang = Settings.Language
                saveAccounts()
            end
            if Auth.Session and Auth.Applied and Auth.signature() ~= Auth.Sig then
                Auth.save()
            end
        end
    end)

    task.spawn(function()
        local ticks = 0
        while gui.Parent do
            task.wait(5)
            ticks = ticks + 1
            local session = Auth.Session
            if session then
                local now = os.time()
                if now >= session.Expires or now < session.At - 300 then
                    Auth.lock("Phi\u{EA}n \u{111}\u{103}ng nh\u{1EAD}p \u{111}\u{E3} h\u{1EBF}t h\u{1EA1}n")
                elseif ticks % 6 == 0 and Auth.Ui.refresh then
                    Auth.Ui.refresh()
                end
            end
        end
    end)

    if Accounts.Lang == "en" then
        local control = Auth.control("language")
        if control then
            control.Set(2)
        end
        lastLanguage = Settings.Language
    end
end

do
    local U = Auth.Ui
    local dim = rgb(183, 188, 204)
    local tabDim = rgb(206, 211, 228)
    local focusColor = rgb(106, 187, 255)
    local failColor = rgb(255, 112, 104)
    local okColor = rgb(84, 222, 124)
    local mode = "login"
    local busy = false

    local function textButton(props)
        props.BackgroundTransparency = props.BackgroundTransparency or 1
        props.BorderSizePixel = 0
        props.AutoButtonColor = false
        props.FontFace = props.FontFace or Fonts.Medium
        props.TextSize = props.TextSize or 13
        return new("TextButton", props)
    end

    local overlay = new("Frame", {
        Name = "SignIn",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = rgb(7, 9, 18),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Active = true,
        Visible = false,
        ZIndex = 110,
        Parent = gui,
