    local function makeField(order, placeholder, secret)
        local frame = new("Frame", {
            Size = UDim2.new(1, 0, 0, 46),
            BackgroundColor3 = Static.White,
            BackgroundTransparency = 0.9,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            LayoutOrder = order,
            Parent = body,
        })
        corner(14, frame)
        local line = stroke(frame, Static.White, 0.86, 1)
        local input = new("TextBox", {
            Position = UDim2.fromOffset(16, 0),
            Size = UDim2.new(1, secret and -76 or -32, 1, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Text = "",
            PlaceholderText = translate(placeholder),
            PlaceholderColor3 = rgb(138, 144, 166),
            TextColor3 = Static.White,
            FontFace = Fonts.Medium,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            ClipsDescendants = true,
            Parent = frame,
        })
        input:SetAttribute("BoncutiRaw", true)
        local field = { Frame = frame, Input = input, Line = line, Reveal = false }

        input.Focused:Connect(function()
            tween(line, 0.2, { Color = focusColor, Transparency = 0.1 })
            tween(frame, 0.2, { BackgroundTransparency = 0.84 })
        end)
        input.FocusLost:Connect(function(enter)
            tween(line, 0.2, { Color = Static.White, Transparency = 0.86 })
            tween(frame, 0.2, { BackgroundTransparency = 0.9 })
            if enter and field.OnEnter then
                field.OnEnter()
            end
        end)

        if secret then
            input.Font = Enum.Font.Code
            input.TextSize = 15
            input.TextTransparency = 1
            local mask = new("TextLabel", {
                Position = UDim2.fromOffset(16, 0),
                Size = UDim2.new(1, -76, 1, 0),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Text = "",
                Font = Enum.Font.Code,
                TextSize = 15,
                TextColor3 = Static.White,
                TextXAlignment = Enum.TextXAlignment.Left,
                ClipsDescendants = true,
                Parent = frame,
            })
            mask:SetAttribute("BoncutiRaw", true)
            input:GetPropertyChangedSignal("Text"):Connect(function()
                mask.Text = string.rep("*", utf8.len(input.Text) or #input.Text)
            end)
            local eye = textButton({
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -10, 0.5, 0),
                Size = UDim2.fromOffset(46, 28),
                Text = "Hi\u{1EC7}n",
                TextSize = 12,
                TextColor3 = focusColor,
                Parent = frame,
            })
            eye.MouseButton1Click:Connect(function()
                field.Reveal = not field.Reveal
                input.TextTransparency = field.Reveal and 0 or 1
                mask.Visible = not field.Reveal
                eye.Text = translate(field.Reveal and "\u{1EA8}n" or "Hi\u{1EC7}n")
                playSound("tick")
            end)
            field.Eye = eye
            field.Mask = mask
        end
        return field
    end

