    local function limit(field, pattern, count)
        field.Input:GetPropertyChangedSignal("Text"):Connect(function()
            local current = field.Input.Text
            local clean = string.sub((string.gsub(current, pattern, "")), 1, count)
            if clean ~= current then
                field.Input.Text = clean
            end
        end)
    end
    limit(userField, "[^%w_]", 20)
    limit(passField, "[^\33-\126]", 40)
    limit(confirmField, "[^\33-\126]", 40)

