    local function say(kind, key, extra)
        local value = translate(key)
        if extra then
            value = string.format(value, extra)
        end
        message.Text = value
        message.TextColor3 = kind == "error" and failColor or (kind == "ok" and okColor or dim)
        message.TextTransparency = 1
        tween(message, 0.25, { TextTransparency = 0 })
    end

    local function shake()
        task.spawn(function()
            for _, offset in ipairs({ 9, -9, 6, -6, 3, 0 }) do
                tween(card, 0.05, { Position = UDim2.new(0.5, offset, 0.5, 0) }, Enum.EasingStyle.Sine)
                task.wait(0.05)
            end
        end)
    end

    local function flag(field)
        tween(field.Line, 0.15, { Color = failColor, Transparency = 0 })
        task.delay(1.2, function()
            tween(field.Line, 0.3, { Color = Static.White, Transparency = 0.86 })
        end)
    end

    local function fail(field, key, extra)
        if field then
            flag(field)
        end
        say("error", key, extra)
        shake()
        playSound("error")
    end

    local function refreshSubmit()
        if busy then
            submitButton.Text = translate("\u{110}ang x\u{E1}c th\u{1EF1}c\u{2026}")
        else
            submitButton.Text = translate(mode == "login" and "\u{110}\u{103}ng nh\u{1EAD}p" or "T\u{1EA1}o t\u{E0}i kho\u{1EA3}n")
        end
        tween(submitFill, 0.2, { BackgroundTransparency = busy and 0.45 or 0 })
    end

    local function refit()
        local viewport = camera.ViewportSize
        local height = mode == "signup" and 574 or 518
        fit = math.min(1, (viewport.Y - 32) / height, (viewport.X - 24) / 344)
        cardScale.Scale = cardSpring.Value * fit
    end
    track(camera:GetPropertyChangedSignal("ViewportSize"):Connect(refit))

    local function setMode(target, instant)
        mode = target
        local signup = target == "signup"
        local goal = signup and UDim2.new(0.5, 0, 0, 4) or UDim2.new(0, 4, 0, 4)
        local frame = confirmField.Frame
        if instant then
            pill.Position = goal
            loginTab.TextColor3 = signup and tabDim or Static.White
            signupTab.TextColor3 = signup and Static.White or tabDim
            frame.Size = UDim2.new(1, 0, 0, signup and 46 or 0)
            frame.Visible = signup
        else
            tween(pill, 0.3, { Position = goal })
            tween(loginTab, 0.25, { TextColor3 = signup and tabDim or Static.White })
            tween(signupTab, 0.25, { TextColor3 = signup and Static.White or tabDim })
            if signup then
                frame.Visible = true
                tween(frame, 0.3, { Size = UDim2.new(1, 0, 0, 46) })
            else
                tween(frame, 0.25, { Size = UDim2.new(1, 0, 0, 0) })
                task.delay(0.28, function()
                    if mode ~= "signup" then
                        frame.Visible = false
                    end
                end)
            end
        end
        confirmField.Input.Text = ""
        message.Text = ""
        subtitle.Text = translate(signup and "T\u{1EA1}o t\u{E0}i kho\u{1EA3}n m\u{1EDB}i" or "\u{110}\u{103}ng nh\u{1EAD}p \u{111}\u{1EC3} ti\u{1EBF}p t\u{1EE5}c")
        refreshSubmit()
        refit()
    end

    local function submit()
        if busy then
            return
        end
        local name = userField.Input.Text
        local password = passField.Input.Text
        local problem = Auth.checkName(name)
        if problem then
            fail(userField, problem)
            return
        end
        if mode == "signup" then
            problem = Auth.checkPassword(password)
        elseif password == "" then
            problem = "Nh\u{1EAD}p m\u{1EAD}t kh\u{1EA9}u"
        end
        if problem then
            fail(passField, problem)
            return
        end
        if mode == "signup" and confirmField.Input.Text ~= password then
            fail(confirmField, "M\u{1EAD}t kh\u{1EA9}u nh\u{1EAD}p l\u{1EA1}i kh\u{F4}ng kh\u{1EDB}p")
            return
        end
        busy = true
        refreshSubmit()
        task.spawn(function()
            local ok, reason, extra
            if mode == "login" then
                ok, reason, extra = Auth.login(name, password)
            else
                ok, reason, extra = Auth.create(name, password)
            end
            busy = false
            refreshSubmit()
            if ok then
                say("ok", mode == "login" and "\u{110}\u{103}ng nh\u{1EAD}p th\u{E0}nh c\u{F4}ng" or "\u{110}\u{E3} t\u{1EA1}o t\u{E0}i kho\u{1EA3}n")
                playSound("success")
            else
                fail(reason == "T\u{EA}n t\u{E0}i kho\u{1EA3}n \u{111}\u{E3} t\u{1ED3}n t\u{1EA1}i" and userField or passField, reason, extra)
            end
        end)
    end

    userField.OnEnter = function()
        task.defer(function()
            passField.Input:CaptureFocus()
        end)
    end
    passField.OnEnter = function()
        if mode == "signup" then
            task.defer(function()
                confirmField.Input:CaptureFocus()
            end)
        else
            submit()
        end
    end
    confirmField.OnEnter = submit

    loginTab.MouseButton1Click:Connect(function()
        if busy or mode == "login" then
            return
        end
        playSound("tick")
        setMode("login")
    end)
    signupTab.MouseButton1Click:Connect(function()
        if busy or mode == "signup" then
            return
        end
        playSound("tick")
        setMode("signup")
    end)

    submitButton.MouseButton1Down:Connect(function()
