    end)

    U.lang.MouseButton1Click:Connect(function()
        playSound("tick")
        local control = Auth.control("language")
        if control then
            control.Set(Settings.Language == "en" and 1 or 2)
        end
    end)

    function U.refresh()
        U.lang.Text = Settings.Language == "en" and "EN" or "VI"
        subtitle.Text = translate(mode == "signup" and "T\u{1EA1}o t\u{E0}i kho\u{1EA3}n m\u{1EDB}i" or "\u{110}\u{103}ng nh\u{1EAD}p \u{111}\u{1EC3} ti\u{1EBF}p t\u{1EE5}c")
        loginTab.Text = translate("\u{110}\u{103}ng nh\u{1EAD}p")
        signupTab.Text = translate("\u{110}\u{103}ng k\u{FD}")
        passField.Eye.Text = translate(passField.Reveal and "\u{1EA8}n" or "Hi\u{1EC7}n")
        confirmField.Eye.Text = translate(confirmField.Reveal and "\u{1EA8}n" or "Hi\u{1EC7}n")
        refreshSubmit()
        if U.nameLabel then
            local display = Auth.Display or "\u{2014}"
            U.nameLabel.Text = display
            U.initial.Text = Fwd.upper(Fwd.firstChar(display))
            U.metaLabel.Text = "@" .. player.Name
            U.expiryLabel.Text = Auth.Session and Auth.timeText(Auth.remaining()) or "\u{2014}"
        end
    end

    function U.show()
        U.Open = true
        overlay.Visible = true
        card.Position = UDim2.fromScale(0.5, 0.5)
        refit()
        cardSpring:Snap(0.92)
        cardSpring:Set(1)
        tween(overlay, 0.35, { BackgroundTransparency = 0.5 })
        tween(card, 0.35, { GroupTransparency = 0 })
        tween(blur, 0.45, { Size = 22 })
    end

    function U.hide()
        U.Open = false
        tween(overlay, 0.3, { BackgroundTransparency = 1 })
        tween(card, 0.25, { GroupTransparency = 1 })
        cardSpring:Set(1.05)
        task.delay(0.35, function()
            if not U.Open then
                overlay.Visible = false
            end
        end)
    end

    function U.prompt(reason)
        if not gui.Parent then
            return false
        end
        busy = false
        setMode("login", true)
        passField.Input.Text = ""
        userField.Input.Text = Auth.Last or ""
        if reason then
            say("info", reason)
        end
        U.refresh()
        U.show()
        while not Auth.Session and gui.Parent do
            task.wait(0.1)
        end
        if not gui.Parent then
            return false
        end
        task.wait(0.6)
        passField.Input.Text = ""
        U.hide()
        return true
    end

    U.refresh()
end

    do
        local Motion = { Counts = {} }
        Fwd.motion = Motion
        local RISE = { TrackRow = true, Result = true, Message = true, Entry = true }

        function Motion.pop(item, delay)
            local scale = item:FindFirstChild("EnterScale")
            if not scale then
                scale = new("UIScale", { Name = "EnterScale", Parent = item })
            end
            scale.Scale = 0.92
            task.delay(delay or 0, function()
                if scale.Parent then
                    tween(scale, 0.5, { Scale = 1 }, Enum.EasingStyle.Back)
                end
            end)
        end

        function Motion.enter(tab)
            local index = 0
            for _, child in ipairs(tab.scroll:GetChildren()) do
                if child:IsA("GuiObject") and child.Visible then
                    index = index + 1
                    if index > 14 then
                        break
                    end
                    Motion.pop(child, 0.04 + (index - 1) * 0.04)
                end
            end
        end

        function Motion.open()
            local index = 0
            for _, child in ipairs(sidebar:GetChildren()) do
                if child:IsA("TextButton") and child.Visible then
                    index = index + 1
                    Motion.pop(child, 0.12 + (index - 1) * 0.04)
                end
            end
            for _, name in ipairs(Multitask.Tabs) do
                local tab = tabs[name]
                if tab then
                    task.delay(0.1, function()
                        if State.Open then
                            Motion.enter(tab)
                        end
                    end)
                end
            end
        end

        function Motion.press(button)
            if button:GetAttribute("BoncutiPress") then
                return
            end
            button:SetAttribute("BoncutiPress", true)
            if button:FindFirstChildOfClass("UIScale") then
                return
            end
            if button.BackgroundTransparency >= 1 and button.Text == "" and #button:GetChildren() == 0 then
                return
            end
            local scale = new("UIScale", { Name = "PressScale", Parent = button })
            button.MouseButton1Down:Connect(function()
                tween(scale, 0.12, { Scale = 0.95 })
            end)
            local function release()
                tween(scale, 0.38, { Scale = 1 }, Enum.EasingStyle.Back)
            end
            button.MouseButton1Up:Connect(release)
            button.MouseLeave:Connect(release)
        end

        for _, inst in ipairs(window:GetDescendants()) do
            if inst:IsA("TextButton") then
                Motion.press(inst)
            end
        end
        window.DescendantAdded:Connect(function(inst)
            if inst:IsA("TextButton") then
                task.defer(function()
                    if inst.Parent then
                        Motion.press(inst)
                    end
                end)
            end
            if RISE[inst.Name] and State.Open and inst:IsA("GuiObject") then
                local now = os.clock()
                local parent = inst.Parent
                local entry = Motion.Counts[parent]
                if not entry or now - entry.At > 0.25 then
                    entry = { At = now, N = 0 }
                    Motion.Counts[parent] = entry
                end
                entry.At = now
                entry.N = entry.N + 1
                Motion.pop(inst, math.min(entry.N - 1, 10) * 0.03)
            end
        end)
    end

