            { 172.3, 42.6 }, { 175.3, 43.1 }, { 177.4, 45.5 }, { 179.1, 51.8 }, { 179.4, 58.0 }, { 177.1, 72.1 },
            { 173.6, 85.6 }, { 171.0, 92.6 }, { 166.7, 98.7 }, { 165.7, 109.1 }, { 169.5, 125.2 }, { 173.0, 129.9 },
            { 178.0, 130.4 }, { 183.4, 127.7 }, { 186.4, 124.7 }, { 195.4, 112.0 }, { 196.6, 98.6 }, { 195.0, 94.1 },
            { 194.5, 89.3 }, { 195.0, 57.5 }, { 197.6, 47.0 }, { 199.2, 44.3 }, { 201.5, 42.8 }, { 204.6, 42.8 },
            { 206.6, 44.4 }, { 208.1, 48.2 }, { 208.8, 53.9 }, { 208.4, 63.6 }, { 205.9, 77.1 }, { 201.7, 91.9 },
            { 197.1, 97.9 }, { 196.1, 102.5 }, { 195.7, 112.9 }, { 197.8, 117.3 }, { 199.3, 125.7 }, { 202.2, 129.7 },
            { 208.4, 130.9 }, { 214.4, 128.7 }, { 224.7, 118.3 }, { 227.1, 112.4 }, { 230.0, 108.7 },
            { 235.8, 104.6 }, { 240.8, 103.3 }, { 247.7, 104.6 }, { 249.2, 106.7 }, { 249.7, 110.0 },
            { 249.9, 116.9 }, { 248.9, 121.4 }, { 246.3, 125.3 }, { 242.1, 128.3 }, { 237.9, 129.0 },
            { 233.8, 128.5 }, { 230.6, 126.6 }, { 228.2, 123.7 }, { 225.8, 116.1 }, { 227.2, 112.2 },
            { 230.9, 107.9 }, { 235.5, 104.7 }, { 240.0, 103.4 }, { 245.3, 103.6 }, { 250.4, 105.4 },
            { 261.0, 105.2 }, { 267.6, 103.0 }, { 277.0, 98.2 },
        }
        local PER_SEGMENT = 6
        local STEP = 2.0
        local LAYERS = {
            { Scale = 1.8, Color = rgb(235, 240, 250), Alpha = 0.94 },
            { Scale = 1.2, Color = rgb(232, 237, 247), Alpha = 0.72 },
            { Scale = 1, Color = rgb(226, 231, 241), Alpha = 0 },
        }

        local function smoothPoints(pts, iterations)
            local res = {}
            for i, p in ipairs(pts) do
                res[i] = { p[1], p[2] }
            end
            for _ = 1, (iterations or 2) do
                local nextPts = { { res[1][1], res[1][2] } }
                for i = 2, #res - 1 do
                    local prev, cur, nxt = res[i - 1], res[i], res[i + 1]
                    nextPts[i] = {
                        prev[1] * 0.22 + cur[1] * 0.56 + nxt[1] * 0.22,
                        prev[2] * 0.22 + cur[2] * 0.56 + nxt[2] * 0.22,
                    }
                end
                nextPts[#res] = { res[#res][1], res[#res][2] }
                res = nextPts
            end
            return res
        end
        local DESIGN_W = 360
        local PAD = 28
        local INK = 6.2
        local DRAW_TIME = 3.1
        local WIDTH_FRACTION = 0.09

        local function knot(a, b, t)
            return t + math.max(math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2), 1e-6) ^ 0.5
        end

        local function interpolate(a, b, ta, tb, t)
            if tb == ta then
                return { a[1], a[2] }
            end
            local w = (t - ta) / (tb - ta)
            return { a[1] * (1 - w) + b[1] * w, a[2] * (1 - w) + b[2] * w }
        end

        local function sample(points)
            local count = #points
            local padded = { points[1] }
            for _, point in ipairs(points) do
                padded[#padded + 1] = point
            end
            padded[#padded + 1] = points[count]
            local line = {}
            for index = 2, #padded - 2 do
                local p0, p1, p2, p3 = padded[index - 1], padded[index], padded[index + 1], padded[index + 2]
                local t0 = 0
                local t1 = knot(p0, p1, t0)
                local t2 = knot(p1, p2, t1)
                local t3 = knot(p2, p3, t2)
                for step = 0, PER_SEGMENT - 1 do
                    local t = t1 + (t2 - t1) * step / PER_SEGMENT
                    local a1 = interpolate(p0, p1, t0, t1, t)
                    local a2 = interpolate(p1, p2, t1, t2, t)
                    local a3 = interpolate(p2, p3, t2, t3, t)
                    local b1 = interpolate(a1, a2, t0, t2, t)
                    local b2 = interpolate(a2, a3, t1, t3, t)
                    line[#line + 1] = interpolate(b1, b2, t1, t2, t)
                end
            end
            line[#line + 1] = { points[count][1], points[count][2] }
            return line
        end

        local function ease(t)
            t = math.clamp(t, 0, 1)
            local smooth = t * t * (3 - 2 * t)
            return smooth * 0.62 + t * 0.38
        end

        function Hello.skip()
            if Hello.Active then
                Hello.Skipping = true
            end
        end

        function Hello.play(done, keepBlur)
            if Hello.Active then
                return
            end
            Hello.Active = true
            Hello.Skipping = false
            Hello.Plays = Hello.Plays + 1
            local view = camera.ViewportSize
            local overlay = new("Frame", {
                Name = "HelloOverlay",
                Size = UDim2.fromScale(1, 1),
                BackgroundColor3 = rgb(4, 6, 12),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Active = true,
                ZIndex = 140,
                Parent = gui,
            })
            local ink = new("CanvasGroup", {
                Name = "HelloInk",
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(DESIGN_W + PAD * 2, DESIGN_W * 0.4 + PAD * 2),
                BackgroundTransparency = 1,
                GroupTransparency = 0.1,
                ZIndex = 141,
                Parent = overlay,
            })
            local inkScale = new("UIScale", {
                Scale = math.clamp(view.X * WIDTH_FRACTION / DESIGN_W, 0.42, 1.4),
                Parent = ink,
            })
            local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
            for _, point in ipairs(POINTS) do
                minX, minY = math.min(minX, point[1]), math.min(minY, point[2])
                maxX, maxY = math.max(maxX, point[1]), math.max(maxY, point[2])
            end
            local factor = DESIGN_W / (maxX - minX)
            local canvasW = DESIGN_W + PAD * 2
            local canvasH = (maxY - minY) * factor + PAD * 2
            ink.Size = UDim2.fromOffset(canvasW, canvasH)
            local scaled = {}
            for index, point in ipairs(POINTS) do
                scaled[index] = { (point[1] - minX) * factor + PAD, (point[2] - minY) * factor + PAD }
            end
            scaled = smoothPoints(scaled, 2)
            local line = sample(scaled)

            local cumulative = { 0 }
            for index = 1, #line - 1 do
                local a, b = line[index], line[index + 1]
                cumulative[index + 1] = cumulative[index] + math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2)
            end
            local length = cumulative[#cumulative]

            local function pointAt(distance, from)
                local index = from
                while index < #line - 1 and cumulative[index + 1] < distance do
                    index = index + 1
                end
                local a, b = line[index], line[index + 1]
                local span = cumulative[index + 1] - cumulative[index]
                local weight = span > 1e-6 and math.clamp((distance - cumulative[index]) / span, 0, 1) or 0
                return a[1] + (b[1] - a[1]) * weight, a[2] + (b[2] - a[2]) * weight, index
            end

            local steps = math.max(math.ceil(length / STEP), 1)
            local placed = 0
            local buildWalk = 1
            local function place(distance)
                local x, y
                x, y, buildWalk = pointAt(distance, buildWalk)
                for _, layer in ipairs(LAYERS) do
                    local size = INK * layer.Scale
                    local dot = new("Frame", {
                        Name = "HelloDot",
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromOffset(x, y),
                        Size = UDim2.fromOffset(size, size),
                        BackgroundColor3 = layer.Color,
                        BackgroundTransparency = layer.Alpha,
                        BorderSizePixel = 0,
                        Parent = ink,
                    })
                    new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = dot })
                end
            end
            local tip = new("Frame", {
                Name = "HelloTip",
                AnchorPoint = Vector2.new(0.5, 0.5),
                Size = UDim2.fromOffset(INK * 2.5, INK * 1.15),
                BackgroundColor3 = Static.White,
                BorderSizePixel = 0,
                Visible = false,
                ZIndex = 142,
                Parent = ink,
            })
            new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = tip })

            local clock = 0
            local startAt = 0.4
            local writeEnd = startAt + DRAW_TIME
            local holdEnd = writeEnd + 0.55
            local fade = 0.7
            local finished = false
            local opened = false
            local connection
            local skipper

            local function cleanup()
                if connection then
                    connection:Disconnect()
                end
                if skipper then
                    skipper:Disconnect()
                end
                overlay:Destroy()
                Hello.Active = false
            end

            local function release()
                if opened then
                    return
                end
                opened = true
                if done then
                    task.spawn(done)
                end
            end

            skipper = UserInputService.InputBegan:Connect(function(input)
                if clock < 0.6 then
                    return
                end
                local kind = input.UserInputType
                if kind == Enum.UserInputType.MouseButton1 or kind == Enum.UserInputType.Touch or kind == Enum.UserInputType.Keyboard then
                    Hello.Skipping = true
                end
            end)

            local tipWalk = 1
            local function reveal(travelled)
                while placed <= steps and math.min(placed * STEP, length) <= travelled do
                    place(math.min(placed * STEP, length))
                    placed = placed + 1
                end
                if placed <= steps then
                    local x, y
                    x, y, tipWalk = pointAt(math.min(travelled, length), tipWalk)
                    local nx, ny = pointAt(math.min(travelled + 8, length), tipWalk)
                    tip.Position = UDim2.fromOffset(x, y)
                    tip.Rotation = math.deg(math.atan2(ny - y, nx - x))
                    tip.Visible = travelled > 0
                end
            end

            tween(overlay, 0.5, { BackgroundTransparency = 0.86 })
            tween(blur, 0.7, { Size = 30 })
            connection = RunService.RenderStepped:Connect(function(dt)
                dt = math.min(dt, 1 / 20)
                local speed = Hello.Skipping and 6 or 1
                clock = clock + dt * speed
                if clock >= startAt and placed <= steps then
                    reveal(clock >= startAt + DRAW_TIME and length + 1 or ease((clock - startAt) / DRAW_TIME) * length)
                end
                if placed > steps and tip.Visible then
                    tip.Visible = false
                end
                if clock >= holdEnd and not finished then
                    finished = true
                    release()
                    tween(ink, fade, { GroupTransparency = 1 })
                    tween(overlay, fade, { BackgroundTransparency = 1 })
                    tween(inkScale, fade, { Scale = inkScale.Scale * 1.05 })
                    if not keepBlur then
                        tween(blur, fade, { Size = Settings.Blur and Settings.BlurSize or 0 })
                    end
                    task.delay(fade + 0.05, cleanup)
                end
            end)
            Hello.Cleanup = cleanup
        end

        do
            local baseSetWindow = Fwd.setWindow
            Fwd.setWindow = function(open)
                if not Auth.Session and not Hello.Suppress then
                    Hello.Pending = true
                end
                if open and Hello.Active then
                    return
                end
                if open and Hello.Pending and Settings.Hello and Auth.Session and not State.Open then
                    Hello.Pending = false
                    Hello.play(function()
                        baseSetWindow(true)
                    end)
                    return
                end
                baseSetWindow(open)
            end
        end
    end

local function runLoader()
    local backdrop = new("Frame", {
        Name = "Backdrop",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = rgb(7, 9, 18),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 100,
        Parent = gui,
    })

    task.spawn(function()
        task.wait(0.2)
        Auth.Session = { Account = "local", At = os.time(), Expires = os.time() + 31536000 }
        Auth.Name = "thanhduyhub"
        Auth.Display = "ThanhDuyHub"
        State.Ready = true
        tween(backdrop, 0.55, { BackgroundTransparency = 1 })
        tween(blur, 0.6, { Size = Settings.Blur and Settings.BlurSize or 0 })
        task.wait(0.55)

        backdrop:Destroy()
        Spr.springIslandY:Set(ISLAND.Top)
        task.wait(0.2)
        Fwd.setWindow(true)
        notify("ThanhDuyHub", "Press " .. Settings.ToggleKey.Name .. " to hide or show", "success", 2.8, true)
    end)
end

runLoader()